package shortestpath;

import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.io.InputStream;

/**
 * General utility helpers for I/O and primitive array manipulation used by the
 * shortest path plugin.
 */
public class Util
{
	/**
	 * Reads all bytes from the provided {@link InputStream} until EOF.
	 * This method does not close the stream; the caller retains responsibility for
	 * resource management.
	 *
	 * @param in the input stream to read from.
	 * @return a newly allocated byte array containing all bytes read (may be empty,
	 * never {@code null}).
	 * @throws IOException if an I/O error occurs while reading.
	 */
	public static byte[] readAllBytes(InputStream in) throws IOException
	{
		ByteArrayOutputStream result = new ByteArrayOutputStream();
		byte[] buffer = new byte[1024];

		while (true)
		{
			int read = in.read(buffer, 0, buffer.length);

			if (read == -1)
			{
				return result.toByteArray();
			}

			result.write(buffer, 0, read);
		}
	}

	/**
	 * Concatenates the contents of multiple {@code int[]} arrays into one
	 * contiguous array.
	 * {@code null} elements in {@code arrays} are skipped. If all arrays are
	 * {@code null} or empty, {@code null}
	 * is returned (this mirrors the existing behavior relied upon by callers).
	 *
	 * @param arrays an array of {@code int[]} segments to concatenate (may contain
	 *               {@code null}).
	 * @return a new combined array, or {@code null} if there are no elements to
	 * copy.
	 */
	public static int[] concatenate(int[][] arrays)
	{
		int n = 0;
		for (int[] value : arrays)
		{
			n += (value == null) ? 0 : value.length;
		}
		if (n == 0)
		{
			return null;
		}
		int[] array = new int[n];
		int k = 0;
		for (int[] ints : arrays)
		{
			if (ints != null)
			{
				for (int anInt : ints)
				{
					array[k++] = anInt;
				}
			}
		}
		return array;
	}
}

package shortestpath;

import net.runelite.api.Client;
import static net.runelite.api.Constants.CHUNK_SIZE;
import static net.runelite.api.Perspective.LOCAL_COORD_BITS;
import net.runelite.api.Player;
import net.runelite.api.WorldEntity;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;

/**
 * Utility functions for packing, unpacking, and transforming {@link WorldPoint}
 * coordinates as compact {@code int} values.
 * <p>
 * A packed world point encodes {@code x}, {@code y}, and {@code plane} into a
 * single 32-bit integer using:
 *
 * <pre>
 * bits 0..14   : x (15 bits)
 * bits 15..29  : y (15 bits)
 * bits 30..31  : plane (2 bits)
 * </pre>
 * <p>
 * This representation allows efficient storage and hashing of coordinates
 * within the pathfinding data structures.
 */
public class WorldPointUtil
{
	public static final int CHEBYSHEV_DISTANCE_METRIC = 1;
	public static final int EUCLIDEAN_SQUARED_DISTANCE_METRIC = 1414213562;
	public static final int MANHATTAN_DISTANCE_METRIC = 2;
	public static final int UNDEFINED = -1;

	/**
	 * Packs a {@link WorldPoint} into a compact {@code int} encoding.
	 *
	 * @param point world point (may be {@code null}).
	 * @return packed integer value, or {@link #UNDEFINED} if {@code point} is
	 * {@code null}.
	 */
	public static int packWorldPoint(WorldPoint point)
	{
		if (point == null)
		{
			return -1;
		}
		return packWorldPoint(point.getX(), point.getY(), point.getPlane());
	}

	/**
	 * Packs the provided coordinate triple into a single {@code int}.
	 * First 15 bits are {@code x}, next 15 bits are {@code y}, final 2 bits are the
	 * plane.
	 * Values are masked into range; overflow bits are discarded.
	 *
	 * @param x     world x (0..32767 effectively supported).
	 * @param y     world y (0..32767 effectively supported).
	 * @param plane plane (0..3).
	 * @return packed integer representation.
	 */
	public static int packWorldPoint(int x, int y, int plane)
	{
		return (x & 0x7FFF) | ((y & 0x7FFF) << 15) | ((plane & 0x3) << 30);
	}

	/**
	 * Unpacks a packed world point into a new {@link WorldPoint} instance.
	 *
	 * @param packedPoint packed coordinate.
	 * @return decoded {@link WorldPoint}.
	 */
	public static WorldPoint unpackWorldPoint(int packedPoint)
	{
		final int x = unpackWorldX(packedPoint);
		final int y = unpackWorldY(packedPoint);
		final int plane = unpackWorldPlane(packedPoint);
		return new WorldPoint(x, y, plane);
	}

	/**
	 * Extracts the x component from a packed world point.
	 *
	 * @param packedPoint packed coordinate.
	 * @return x value.
	 */
	public static int unpackWorldX(int packedPoint)
	{
		return packedPoint & 0x7FFF;
	}

	/**
	 * Extracts the y component from a packed world point.
	 *
	 * @param packedPoint packed coordinate.
	 * @return y value.
	 */
	public static int unpackWorldY(int packedPoint)
	{
		return (packedPoint >> 15) & 0x7FFF;
	}

	/**
	 * Extracts the plane component from a packed world point.
	 *
	 * @param packedPoint packed coordinate.
	 * @return plane value (0..3).
	 */
	public static int unpackWorldPlane(int packedPoint)
	{
		return (packedPoint >> 30) & 0x3;
	}

	/**
	 * Offsets a packed world point by {@code (dx, dy)} on the same plane.
	 *
	 * @param packedPoint base packed point.
	 * @param dx          delta x to add.
	 * @param dy          delta y to add.
	 * @return packed point after applying deltas.
	 */
	public static int dxdy(int packedPoint, int dx, int dy)
	{
		int x = unpackWorldX(packedPoint);
		int y = unpackWorldY(packedPoint);
		int z = unpackWorldPlane(packedPoint);
		return packWorldPoint(x + dx, y + dy, z);
	}

	/**
	 * Computes the distance between two packed points using Chebyshev metric
	 * (diagonal = 1).
	 */
	public static int distanceBetween(int previousPacked, int currentPacked)
	{
		return distanceBetween(previousPacked, currentPacked, 1);
	}

	/**
	 * Computes the 2D distance (ignoring plane) between two packed points using
	 * Chebyshev metric (diagonal = 1).
	 */
	public static int distanceBetween2D(int previousPacked, int currentPacked)
	{
		return distanceBetween2D(previousPacked, currentPacked, 1);
	}

	/**
	 * Computes distance between two packed points with selectable distance metric.
	 *
	 * @param previousPacked first packed point.
	 * @param currentPacked  second packed point.
	 * @param diagonal       {@code 1} for Chebyshev (max), {@code 2} for Manhattan
	 *                       (sum). Otherwise returns Euclidean squared distance.
	 * @return distance or {@code Integer.MAX_VALUE} if plane differs.
	 */
	public static int distanceBetween(int previousPacked, int currentPacked, int diagonal)
	{
		final int previousX = WorldPointUtil.unpackWorldX(previousPacked);
		final int previousY = WorldPointUtil.unpackWorldY(previousPacked);
		final int previousZ = WorldPointUtil.unpackWorldPlane(previousPacked);
		final int currentX = WorldPointUtil.unpackWorldX(currentPacked);
		final int currentY = WorldPointUtil.unpackWorldY(currentPacked);
		final int currentZ = WorldPointUtil.unpackWorldPlane(currentPacked);
		return distanceBetween(previousX, previousY, previousZ,
			currentX, currentY, currentZ, diagonal);
	}

	/**
	 * Computes 2D distance (ignoring plane) between two packed points with
	 * selectable metric.
	 *
	 * @see #distanceBetween(int, int, int, int, int, int, int)
	 */
	public static int distanceBetween2D(int previousPacked, int currentPacked, int diagonal)
	{
		final int previousX = WorldPointUtil.unpackWorldX(previousPacked);
		final int previousY = WorldPointUtil.unpackWorldY(previousPacked);
		final int currentX = WorldPointUtil.unpackWorldX(currentPacked);
		final int currentY = WorldPointUtil.unpackWorldY(currentPacked);
		return distanceBetween2D(previousX, previousY, currentX, currentY, diagonal);
	}

	/**
	 * Computes distance between two coordinates with selectable metric; returns
	 * {@code Integer.MAX_VALUE} if planes differ.
	 *
	 * @param previousX x of first point.
	 * @param previousY y of first point.
	 * @param previousZ plane of first point.
	 * @param currentX  x of second point.
	 * @param currentY  y of second point.
	 * @param currentZ  plane of second point.
	 * @param diagonal  metric selector ({@code 1}=Chebyshev, {@code 2}=Manhattan,
	 *                  otherwise Euclidean squared distance).
	 * @return distance or {@code Integer.MAX_VALUE} if planes differ.
	 */
	public static int distanceBetween(
		int previousX,
		int previousY,
		int previousZ,
		int currentX,
		int currentY,
		int currentZ,
		int diagonal)
	{
		final int dz = previousZ - currentZ;

		if (dz != 0)
		{
			return Integer.MAX_VALUE;
		}

		return distanceBetween2D(previousX, previousY, currentX, currentY, diagonal);
	}

	/**
	 * Computes a 2D distance using either Chebyshev, Manhattan or Euclidean squared
	 * distance metric.
	 *
	 * @param previousX x of first point.
	 * @param previousY y of first point.
	 * @param currentX  x of second point.
	 * @param currentY  y of second point.
	 * @param diagonal  metric selector ({@code 1}=Chebyshev, {@code 2}=Manhattan,
	 *                  otherwise Euclidean squared distance).
	 * @return distance.
	 */
	public static int distanceBetween2D(int previousX, int previousY,
		int currentX, int currentY, int diagonal)
	{
		final int dx = previousX - currentX;
		final int dy = previousY - currentY;

		if (diagonal == CHEBYSHEV_DISTANCE_METRIC)
		{
			return Math.max(Math.abs(dx), Math.abs(dy));
		}
		else if (diagonal == MANHATTAN_DISTANCE_METRIC)
		{
			return Math.abs(dx) + Math.abs(dy);
		}

		return dx * dx + dy * dy;
	}

	/**
	 * Convenience overload using Chebyshev distance between two
	 * {@link WorldPoint}s.
	 */
	public static int distanceBetween(WorldPoint previous, WorldPoint current)
	{
		return distanceBetween(previous, current, 1);
	}

	/**
	 * Distance between two {@link WorldPoint}s with selectable metric.
	 *
	 * @see #distanceBetween(int, int, int, int, int, int, int)
	 */
	public static int distanceBetween(WorldPoint previous, WorldPoint current, int diagonal)
	{
		return distanceBetween(previous.getX(), previous.getY(), previous.getPlane(),
			current.getX(), current.getY(), current.getPlane(), diagonal);
	}

	/**
	 * Distance from a packed point to a {@link WorldArea} using Chebyshev metric,
	 * respecting plane.
	 * Returns {@code Integer.MAX_VALUE} if the plane differs.
	 */
	public static int distanceToArea(int packedPoint, WorldArea area)
	{
		final int plane = unpackWorldPlane(packedPoint);
		if (area.getPlane() != plane)
		{
			return Integer.MAX_VALUE;
		}
		return distanceToArea2D(packedPoint, area);
	}

	/**
	 * 2D distance (Chebyshev) from a packed point to a {@link WorldArea} ignoring
	 * plane, equivalent to
	 * {@link WorldArea#distanceTo(WorldPoint)} semantics in 2D.
	 */
	public static int distanceToArea2D(int packedPoint, WorldArea area)
	{
		final int y = unpackWorldY(packedPoint);
		final int x = unpackWorldX(packedPoint);
		final int areaMaxX = area.getX() + area.getWidth() - 1;
		final int areaMaxY = area.getY() + area.getHeight() - 1;
		final int dx = Math.max(Math.max(area.getX() - x, 0), x - areaMaxX);
		final int dy = Math.max(Math.max(area.getY() - y, 0), y - areaMaxY);

		return Math.max(dx, dy);
	}

	private static int rotate(int originalX, int originalY, int z, int rotation)
	{
		int chunkX = originalX & -CHUNK_SIZE;
		int chunkY = originalY & -CHUNK_SIZE;
		int x = originalX & (CHUNK_SIZE - 1);
		int y = originalY & (CHUNK_SIZE - 1);
		switch (rotation)
		{
			case 1:
				return packWorldPoint(chunkX + y, chunkY + (CHUNK_SIZE - 1 - x), z);
			case 2:
				return packWorldPoint(chunkX + (CHUNK_SIZE - 1 - x), chunkY + (CHUNK_SIZE - 1 - y), z);
			case 3:
				return packWorldPoint(chunkX + (CHUNK_SIZE - 1 - y), chunkY + x, z);
		}
		return packWorldPoint(originalX, originalY, z);
	}

	private static int unpackChunkRotation(int chunkData)
	{
		return chunkData >> 1 & 0x3;
	}

	private static int unpackChunkTemplateY(int chunkData)
	{
		return (chunkData >> 3 & 0x7FF) * CHUNK_SIZE;
	}

	private static int unpackChunkTemplateX(int chunkData)
	{
		return (chunkData >> 14 & 0x3FF) * CHUNK_SIZE;
	}

	private static int unpackChunkTemplatePlane(int chunkData)
	{
		return chunkData >> 24 & 0x3;
	}

	public static int fromLocalInstance(Client client, Player localPlayer)
	{
		WorldView worldView = localPlayer.getWorldView();
		int worldViewId = worldView.getId();
		boolean isOnBoat = worldViewId != WorldView.TOPLEVEL;
		if (isOnBoat)
		{
			WorldEntity worldEntity = client.getTopLevelWorldView().worldEntities().byIndex(worldViewId);
			return fromLocalInstance(client, worldEntity.getLocalLocation());
		}
		return fromLocalInstance(client, localPlayer.getLocalLocation());
	}

	/**
	 * The position of the boat the player is on, in the top-level world and in local units (128 per tile,
	 * so the low 7 bits are the position within the tile). Uses the server's position for this tick rather
	 * than the smoothed render position. Returns {@code null} when the player is not on a boat.
	 */
	public static LocalPoint boatLocation(Client client, Player localPlayer)
	{
		WorldEntity boat = boat(client, localPlayer);
		if (boat == null)
		{
			return null;
		}
		LocalPoint target = boat.getTargetLocation();
		return target != null ? target : boat.getLocalLocation();
	}

	/**
	 * The boat the player is on, or {@code null} when the player is not on a boat.
	 */
	public static WorldEntity boat(Client client, Player localPlayer)
	{
		WorldView worldView = localPlayer.getWorldView();
		if (worldView.getId() == WorldView.TOPLEVEL)
		{
			return null;
		}
		return client.getTopLevelWorldView().worldEntities().byIndex(worldView.getId());
	}

	/**
	 * Converts an instanced {@link LocalPoint} to its corresponding packed world
	 * point coordinate, resolving the
	 * underlying template chunk mapping and rotation.
	 *
	 * @param client     RuneLite client.
	 * @param localPoint local scene coordinate.
	 * @return packed world point.
	 */
	public static int fromLocalInstance(Client client, LocalPoint localPoint)
	{
		WorldView worldView = client.getWorldView(localPoint.getWorldView());
		int plane = worldView.getPlane();

		if (!worldView.isInstance())
		{
			return packWorldPoint(
				(localPoint.getX() >> LOCAL_COORD_BITS) + worldView.getBaseX(),
				(localPoint.getY() >> LOCAL_COORD_BITS) + worldView.getBaseY(),
				plane);
		}

		int[][][] instanceTemplateChunks = worldView.getInstanceTemplateChunks();

		// get position in the scene
		int sceneX = localPoint.getSceneX();
		int sceneY = localPoint.getSceneY();

		// get chunk from scene
		int chunkX = sceneX / CHUNK_SIZE;
		int chunkY = sceneY / CHUNK_SIZE;

		// get the template chunk for the chunk
		int templateChunk = instanceTemplateChunks[plane][chunkX][chunkY];

		int rotation = unpackChunkRotation(templateChunk);
		int templateChunkY = unpackChunkTemplateY(templateChunk);
		int templateChunkX = unpackChunkTemplateX(templateChunk);
		int templateChunkPlane = unpackChunkTemplatePlane(templateChunk);

		// calculate world point of the template
		int x = templateChunkX + (sceneX & (CHUNK_SIZE - 1));
		int y = templateChunkY + (sceneY & (CHUNK_SIZE - 1));

		// create and rotate point back to 0, to match with template
		return rotate(x, y, templateChunkPlane, 4 - rotation);
	}

	/**
	 * Converts a packed world point to one or more packed world points representing
	 * its locations within an instanced
	 * map (e.g., dungeons or raids). If the current top-level world is not
	 * instanced, the result contains exactly the
	 * original point.
	 *
	 * @param client      RuneLite client.
	 * @param packedPoint packed world coordinate.
	 * @return list of packed coordinates valid in the current instance.
	 */
	public static PrimitiveIntList toLocalInstance(Client client, int packedPoint)
	{
		WorldView worldView = client.getTopLevelWorldView();

		PrimitiveIntList worldPoints = new PrimitiveIntList();
		if (!worldView.isInstance())
		{
			worldPoints.add(packedPoint);
			return worldPoints;
		}

		int baseX = worldView.getBaseX();
		int baseY = worldView.getBaseY();
		int worldPointX = unpackWorldX(packedPoint);
		int worldPointY = unpackWorldY(packedPoint);
		int worldPointPlane = unpackWorldPlane(packedPoint);

		int[][][] instanceTemplateChunks = worldView.getInstanceTemplateChunks();

		// find instance chunks using the template point. there might be more than one.
		for (int z = 0; z < instanceTemplateChunks.length; z++)
		{
			for (int x = 0; x < instanceTemplateChunks[z].length; ++x)
			{
				for (int y = 0; y < instanceTemplateChunks[z][x].length; ++y)
				{
					int chunkData = instanceTemplateChunks[z][x][y];
					int rotation = unpackChunkRotation(chunkData);
					int templateChunkY = unpackChunkTemplateY(chunkData);
					int templateChunkX = unpackChunkTemplateX(chunkData);
					int plane = unpackChunkTemplatePlane(chunkData);
					if (worldPointX >= templateChunkX && worldPointX < templateChunkX + CHUNK_SIZE
						&& worldPointY >= templateChunkY && worldPointY < templateChunkY + CHUNK_SIZE
						&& plane == worldPointPlane)
					{
						worldPoints.add(rotate(
							baseX + x * CHUNK_SIZE + (worldPointX & (CHUNK_SIZE - 1)),
							baseY + y * CHUNK_SIZE + (worldPointY & (CHUNK_SIZE - 1)),
							z,
							rotation));
					}
				}
			}
		}
		return worldPoints;
	}

	private static boolean isInScene(WorldView worldView, int packedPoint)
	{
		int x = unpackWorldX(packedPoint);
		int y = unpackWorldY(packedPoint);

		int baseX = worldView.getBaseX();
		int baseY = worldView.getBaseY();

		int maxX = baseX + worldView.getSizeX();
		int maxY = baseY + worldView.getSizeY();

		return x >= baseX && x < maxX && y >= baseY && y < maxY;
	}

	/**
	 * Converts a packed world point into a {@link LocalPoint} relative to the
	 * top-level world view if it resides in
	 * the currently loaded scene and on the same plane; returns {@code null}
	 * otherwise.
	 *
	 * @param client      RuneLite client.
	 * @param packedPoint packed world point.
	 * @return {@link LocalPoint} or {@code null} if out of scene or plane.
	 */
	public static LocalPoint toLocalPoint(Client client, int packedPoint)
	{
		WorldView worldView = client.getTopLevelWorldView();

		if (worldView.getPlane() != unpackWorldPlane(packedPoint))
		{
			return null;
		}

		if (!isInScene(worldView, packedPoint))
		{
			return null;
		}

		return new LocalPoint(
			(unpackWorldX(packedPoint) - worldView.getBaseX() << LOCAL_COORD_BITS) + (1 << LOCAL_COORD_BITS - 1),
			(unpackWorldY(packedPoint) - worldView.getBaseY() << LOCAL_COORD_BITS) + (1 << LOCAL_COORD_BITS - 1),
			worldView.getId());
	}
}

package shortestpath.items;

import java.util.Objects;
import java.util.Set;

import lombok.Getter;

import shortestpath.settings.Effect;

/**
 * An immutable fact describing a single item-state change: the input that
 * changed (keyed as {@code "container:<id>"} or {@code "varbit:<id>"}) and the
 * {@link Effect}s it triggers. Produced by {@link ItemStateService}; the shell
 * reads the effect set to decide which follow-up actions to run rather than
 * re-deriving them from the event.
 */
@Getter
public final class ItemChange
{
	private final String key;
	private final Set<Effect> effects;

	ItemChange(String key, Set<Effect> effects)
	{
		this.key = Objects.requireNonNull(key);
		this.effects = Set.copyOf(effects);
	}
}

package shortestpath.items;

import java.util.HashMap;
import java.util.Map;
import java.util.Set;

import javax.inject.Inject;
import javax.inject.Singleton;

import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarbitID;
import shortestpath.requirement.PlayerStateSource;
import shortestpath.requirement.TransportEligibility;
import shortestpath.requirement.model.Unlock;
import shortestpath.settings.Effect;
import shortestpath.settings.TeleportationItem;

/**
 * Owns the plugin's player item state observed from game events — the live
 * open-bank container and the container/varbit inputs that feed the
 * eligibility snapshot — and reports each admitted change to the shell as an
 * {@link ItemChange} fact. The service never writes back to the engine; the
 * shell maps the fact's declared effects to its follow-up actions, and
 * downstream projections key their caches on {@link #itemStateRevision()}
 * rather than pulling path types in here.
 */
@Singleton
public class ItemStateService
{
	/**
	 * LIVE reference to the last-opened bank container — never copied or
	 * snapshotted, so it reads empty once the bank closes.
	 */
	private ItemContainer bank;

	// Bumped by every admitted item-state change; readers that project this
	// state (e.g. the bank-pickup projection) key their caches on it instead
	// of this service observing their invalidation needs.
	private int itemStateRevision;

	@Inject
	public ItemStateService()
	{
	}

	/**
	 * Test/harness seam: returns an instance detached from Guice. The
	 * production instance is the injected singleton.
	 */
	public static ItemStateService forTesting()
	{
		return new ItemStateService();
	}

	/**
	 * Consumes an item-container event. The bank container id additionally
	 * updates the live bank reference; the tracked containers (bank,
	 * inventory, worn equipment) return a fact declaring
	 * {@link Effect#ELIGIBILITY_STALE}. Any other container is not item
	 * state and returns {@code null}.
	 */
	public ItemChange onContainerChanged(int containerId, ItemContainer container)
	{
		if (containerId == InventoryID.BANK)
		{
			this.bank = container;
		}
		if (containerId == InventoryID.BANK || containerId == InventoryID.INV
			|| containerId == InventoryID.WORN)
		{
			itemStateRevision++;
			return new ItemChange("container:" + containerId, Set.of(Effect.ELIGIBILITY_STALE));
		}
		return null;
	}

	/**
	 * Consumes a varbit event. Rune pouch contents and the Lumbridge Elite
	 * diary feed the eligibility snapshot but change without firing a
	 * container event, so their varbits return a fact declaring
	 * {@link Effect#ELIGIBILITY_STALE}. Any other varbit returns
	 * {@code null}.
	 */
	public ItemChange onVarbitChanged(int varbitId)
	{
		if (varbitId == VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE
			|| containsVarbit(OwnedItems.RUNE_POUCH_RUNE_VARBITS, varbitId)
			|| containsVarbit(OwnedItems.RUNE_POUCH_AMOUNT_VARBITS, varbitId))
		{
			itemStateRevision++;
			return new ItemChange("varbit:" + varbitId, Set.of(Effect.ELIGIBILITY_STALE));
		}
		return null;
	}

	private static boolean containsVarbit(int[] varbits, int varbitId)
	{
		for (int id : varbits)
		{
			if (id == varbitId)
			{
				return true;
			}
		}
		return false;
	}

	public ItemContainer getBank()
	{
		return bank;
	}

	/**
	 * Harness/test seeding seam; production writes arrive through
	 * {@link #onContainerChanged} for the bank container id. Bumps
	 * {@link #itemStateRevision()} like the event path does, so a re-seeded
	 * bank is never served by a projection computed against the previous
	 * container.
	 */
	public void noteBankContainer(ItemContainer container)
	{
		this.bank = container;
		itemStateRevision++;
	}

	/**
	 * The item-state epoch: bumped by every admitted container/varbit change,
	 * by {@link #noteBankContainer}, and by {@link #reset}. Readers that cache
	 * a projection over this state must recompute when it moves.
	 */
	public int itemStateRevision()
	{
		return itemStateRevision;
	}

	/**
	 * Clears the session-scoped state — the live bank reference. The service
	 * is a singleton on the plugin injector, which RuneLite reuses across
	 * shutDown/startUp cycles, so the shell calls this on shutdown to restore
	 * the lifetime the bank field had when it lived on the per-session
	 * pathfinder config: nothing observed in one session may feed eligibility
	 * in the next. The revision bump keeps downstream caches from serving a
	 * projection computed against the cleared state.
	 */
	public void reset()
	{
		bank = null;
		itemStateRevision++;
	}

	/**
	 * Captures the client state both the pathfinding verdicts and the bank-pickup plans
	 * read: the carried pool (inventory + worn + rune pouch in hand), the bank-path pool
	 * (which adds the bank contents when bank paths are enabled), the bank contents
	 * themselves, the runes inside a banked rune pouch, the fairy-ring staff gate and
	 * the currency threshold. Shared by
	 * {@link shortestpath.requirement.RequirementContext#capture RequirementContext.capture}
	 * and the lazy {@code PathfinderConfig#getEligibility()} rebuild so exactly one
	 * collection path exists.
	 */
	public static TransportEligibility collectEligibility(
		PlayerStateSource source,
		ItemContainer bank,
		TeleportationItem teleportationItemSetting,
		int currencyThreshold,
		boolean includeBankPath,
		Set<Unlock> unlocks)
	{
		Map<Integer, Integer> carriedItems = collectItems(source, bank,
			teleportationItemSetting, true, true, false, true);
		Map<Integer, Integer> bankPathItems = includeBankPath
			? collectItems(source, bank, teleportationItemSetting, true, true, true, true)
			: carriedItems;
		Map<Integer, Integer> bankHas = new HashMap<>();
		OwnedItems.addContainer(bankHas, bank);
		int bankPouchId = -1;
		for (int pouchId : OwnedItems.RUNE_POUCHES)
		{
			if (bankHas.containsKey(pouchId))
			{
				bankPouchId = pouchId;
				break;
			}
		}
		Map<Integer, Integer> bankPouchRunes = bankPouchId == -1
			? Map.of()
			: source.runePouchContents();
		boolean fairyRingStaffRequired =
			source.varbit(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) != 1;
		return new TransportEligibility(carriedItems, bankPathItems, bankHas, bankPouchId, bankPouchRunes,
			fairyRingStaffRequired, teleportationItemSetting, currencyThreshold,
			unlocks, bank != null);
	}

	/**
	 * Item id to quantity over the selected containers, summed across containers.
	 */
	private static Map<Integer, Integer> collectItems(
		PlayerStateSource source,
		ItemContainer bank,
		TeleportationItem teleportationItemSetting,
		boolean checkInventory,
		boolean checkEquipment,
		boolean checkBank,
		boolean checkRunePouch)
	{
		Map<Integer, Integer> itemsAndQuantities = new HashMap<>(28 + 11 + 500);

		if (checkInventory)
		{
			OwnedItems.addContainer(itemsAndQuantities, source.itemContainer(InventoryID.INV));
		}

		if (checkEquipment)
		{
			OwnedItems.addContainer(itemsAndQuantities, source.itemContainer(InventoryID.WORN));
		}

		if (checkBank
			&& (TeleportationItem.INVENTORY_AND_BANK.equals(teleportationItemSetting)
				|| TeleportationItem.INVENTORY_AND_BANK_NON_CONSUMABLE.equals(teleportationItemSetting)))
		{
			OwnedItems.addContainer(itemsAndQuantities, bank);
		}

		if (checkRunePouch)
		{
			source.addRunePouchContents(itemsAndQuantities);
		}

		return itemsAndQuantities;
	}
}

package shortestpath.items;

import java.util.Arrays;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;

/**
 * Collects the items a player owns as item id to quantity, summing an item
 * held in several places. Pathfinding and the item hints share it so they
 * count items the same way.
 */
public final class OwnedItems
{
	private OwnedItems()
	{
	}

	public static final List<Integer> RUNE_POUCHES = Arrays.asList(
		ItemID.BH_RUNE_POUCH, ItemID.BH_RUNE_POUCH_TROUVER,
		ItemID.DIVINE_RUNE_POUCH, ItemID.DIVINE_RUNE_POUCH_TROUVER
	);
	public static final int[] RUNE_POUCH_RUNE_VARBITS =
		{
			VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_TYPE_4,
			VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_TYPE_6
		};
	public static final int[] RUNE_POUCH_AMOUNT_VARBITS =
		{
			VarbitID.RUNE_POUCH_QUANTITY_1, VarbitID.RUNE_POUCH_QUANTITY_2, VarbitID.RUNE_POUCH_QUANTITY_3, VarbitID.RUNE_POUCH_QUANTITY_4,
			VarbitID.RUNE_POUCH_QUANTITY_5, VarbitID.RUNE_POUCH_QUANTITY_6
		};

	public static void addContainer(Map<Integer, Integer> owned, ItemContainer container)
	{
		if (container == null || container.getItems() == null)
		{
			return;
		}
		for (Item item : container.getItems())
		{
			if (item.getId() >= 0 && item.getQuantity() > 0)
			{
				owned.merge(item.getId(), item.getQuantity(), Integer::sum);
			}
		}
	}

	/**
	 * Adds the runes in the rune pouch, if {@code owned} already holds a rune pouch.
	 */
	public static void addRunePouchContents(Client client, Map<Integer, Integer> owned)
	{
		if (RUNE_POUCHES.stream().noneMatch(owned::containsKey))
		{
			return;
		}
		runePouchContents(client).forEach((runeId, amount) -> owned.merge(runeId, amount, Integer::sum));
	}

	/**
	 * Returns the runes in the rune pouch as rune id to amount. The varbits that
	 * hold the contents are current wherever the pouch is, including the bank.
	 */
	public static Map<Integer, Integer> runePouchContents(Client client)
	{
		Map<Integer, Integer> runes = new HashMap<>();
		EnumComposition runePouchEnum = client.getEnum(EnumID.RUNEPOUCH_RUNE);
		if (runePouchEnum == null)
		{
			return runes;
		}
		for (int i = 0; i < RUNE_POUCH_RUNE_VARBITS.length; i++)
		{
			int runeEnumId = client.getVarbitValue(RUNE_POUCH_RUNE_VARBITS[i]);
			int runeId = runeEnumId > 0 ? runePouchEnum.getIntValue(runeEnumId) : 0;
			int runeAmount = client.getVarbitValue(RUNE_POUCH_AMOUNT_VARBITS[i]);
			if (runeId > 0 && runeAmount > 0)
			{
				runes.merge(runeId, runeAmount, Integer::sum);
			}
		}
		return runes;
	}
}

package shortestpath.leagues;

import java.util.Collections;
import java.util.EnumSet;
import java.util.Set;

/**
 * Immutable view of the league facts a {@link LeagueModeState} held at one
 * refresh. {@link LeagueModeState} is the live, per-config holder that
 * {@code refresh()} rewrites on every world hop or login; this snapshot is
 * what a per-refresh {@code RequirementContext} retains, so a requirement
 * chain keeps answering from the facts of the refresh that built it even if
 * a later refresh has already replaced the live state.
 *
 * <p>The read contract mirrors {@link LeagueModeState}'s: outside seasonal
 * mode every region is considered unlocked and no region is blocked, so
 * normal pathfinding is unaffected.
 */
public final class LeagueModeSnapshot
{
	/**
	 * The default snapshot: non-seasonal, not Deadman, no unlocks — the same
	 * facts a freshly constructed or null-source-refreshed
	 * {@link LeagueModeState} reports.
	 */
	public static final LeagueModeSnapshot NON_SEASONAL = new LeagueModeSnapshot(false, false, Set.of());

	private final boolean seasonal;
	private final boolean deadman;
	private final Set<LeagueRegion> unlockedRegions;

	public LeagueModeSnapshot(boolean seasonal, boolean deadman, Set<LeagueRegion> unlockedRegions)
	{
		this.seasonal = seasonal;
		this.deadman = deadman;
		this.unlockedRegions = unlockedRegions == null || unlockedRegions.isEmpty()
			? Set.of()
			: Collections.unmodifiableSet(EnumSet.copyOf(unlockedRegions));
	}

	public boolean isSeasonal()
	{
		return seasonal;
	}

	public boolean isDeadman()
	{
		return deadman;
	}

	/**
	 * Whether the supplied region is currently traversable. Outside of
	 * seasonal mode every region is considered unlocked.
	 */
	public boolean isUnlocked(LeagueRegion region)
	{
		if (region == null)
		{
			return true;
		}
		if (region.isAlwaysUnlocked())
		{
			return true;
		}
		if (!seasonal)
		{
			return true;
		}
		if (region.isAlwaysBlocked())
		{
			return false;
		}
		return unlockedRegions.contains(region);
	}

	/**
	 * Whether the supplied tile is in the always-blocked region while the
	 * player is on a seasonal world. Returns {@code false} on non-seasonal
	 * worlds so normal pathfinding is unaffected.
	 */
	public boolean isInBlockedRegion(int packedPoint)
	{
		if (!seasonal)
		{
			return false;
		}
		return LeagueRegionChecker.getRegion(packedPoint).isAlwaysBlocked();
	}
}

package shortestpath.leagues;

import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.WorldType;
import shortestpath.requirement.PlayerStateSource;

/**
 * Snapshot of the player's Demonic Pacts League state, refreshed once per
 * {@code PathfinderConfig.refresh()} cycle (i.e. on world change, login, or
 * any config-driven recompute).
 *
 * <p>
 * The Pathfinder asks two questions of this object on the hot path:
 * </p>
 * <ul>
 *   <li>{@link #isSeasonal()} — is the player currently on a Leagues world?
 *       When false, all league-specific filtering is bypassed.</li>
 *   <li>{@link #isUnlocked(LeagueRegion)} — has the player unlocked the
 *       supplied region? Always-unlocked regions
 *       ({@link LeagueRegion#isAlwaysUnlocked()}) return {@code true}
 *       regardless of seasonal status; always-blocked regions
 *       ({@link LeagueRegion#isAlwaysBlocked()}) always return {@code false}
 *       when seasonal.</li>
 * </ul>
 *
 * <p>
 * The unlock set is rebuilt from the {@code LEAGUE_AREA_SELECTION_*} varbit
 * slots ({@link #AREA_SELECTION_VARBITS}). Each slot stores a numeric area
 * id matching the wiki's enumeration (mapping defined in
 * {@link #AREA_VARBIT_TO_REGION}):
 * </p>
 * <ul>
 *   <li>Slot 0 ({@code 10662}) — pre-set to Varlamore on a seasonal world.</li>
 *   <li>Slot 1 ({@code 10663}) — Karamja, awarded for free with the player's
 *       first paid pick at 80 tasks.</li>
 *   <li>Slots 2-3 ({@code 10664}/{@code 10665}) — the player's three area
 *       picks at 200/300/450 tasks.</li>
 *   <li>Slots 4-5 ({@code 10666}/{@code 10667}) — reserved by the game for
 *       additional bonus unlocks; we read them defensively.</li>
 * </ul>
 *
 * <p>
 * The mapping is deliberately hard-coded here — these IDs are known not to
 * change during a league season.
 * </p>
 */
public class LeagueModeState
{
	/**
	 * Varbit IDs storing the league area unlocks. The values match
	 * {@code LEAGUE_AREA_SELECTION_0..5} from RuneLite's gameval VarbitID
	 * table. Slot 0 is the auto-set Varlamore slot, slot 1 is the Karamja
	 * free pick, and the remaining slots correspond to the three player
	 * picks at 200/300/450 tasks plus two bonus slots reserved by the game.
	 */
	static final int[] AREA_SELECTION_VARBITS = {
		10662, 10663, 10664, 10665, 10666, 10667,
	};

	/**
	 * Maps the numeric area id stored in a {@code LEAGUE_AREA_SELECTION_*}
	 * varbit to its {@link LeagueRegion}. Numbering was found through trial
	 * and error (id 1 = Misthalin is included for completeness even though
	 * it is never selectable).
	 */
	private static final Map<Integer, LeagueRegion> AREA_VARBIT_TO_REGION;

	static
	{
		AREA_VARBIT_TO_REGION = Map.ofEntries(
			Map.entry(1, LeagueRegion.MISTHALIN),
			Map.entry(2, LeagueRegion.KARAMJA),
			Map.entry(3, LeagueRegion.ASGARNIA),
			Map.entry(4, LeagueRegion.KANDARIN),
			Map.entry(5, LeagueRegion.MORYTANIA),
			Map.entry(6, LeagueRegion.DESERT),
			Map.entry(7, LeagueRegion.TIRANNWN),
			Map.entry(8, LeagueRegion.FREMENNIK),
			Map.entry(11, LeagueRegion.WILDERNESS),
			Map.entry(20, LeagueRegion.KOUREND),
			Map.entry(21, LeagueRegion.VARLAMORE));
	}

	/**
	 * The current facts, replaced wholesale by every {@link #refresh} /
	 * {@link #setForTest}. Held as one immutable object so a search thread
	 * reading through this live state always sees a consistent snapshot —
	 * never torn fields from two overlapping refreshes — and so
	 * {@link #snapshot()} can hand a per-refresh requirement context a frozen
	 * view that later refreshes cannot mutate.
	 */
	private volatile LeagueModeSnapshot current = LeagueModeSnapshot.NON_SEASONAL;

	/**
	 * Re-reads the world type and the area-unlock varbits through the player
	 * state source. Called from {@code PathfinderConfig.refresh()} which
	 * already runs on world change, login, and config edits.
	 *
	 * <p>
	 * On a {@code null} source this resets to a non-seasonal state with no
	 * extra unlocks; this is the safe default because non-seasonal logic
	 * mirrors normal pathfinding.
	 * </p>
	 */
	public void refresh(PlayerStateSource source)
	{
		if (source == null)
		{
			current = LeagueModeSnapshot.NON_SEASONAL;
			return;
		}
		EnumSet<WorldType> worldTypes = source.worldType();
		boolean seasonal = worldTypes != null && worldTypes.contains(WorldType.SEASONAL);
		boolean deadman = worldTypes != null && worldTypes.contains(WorldType.DEADMAN);

		EnumSet<LeagueRegion> next = EnumSet.noneOf(LeagueRegion.class);
		if (seasonal)
		{
			for (int varbitId : AREA_SELECTION_VARBITS)
			{
				addRegionFromSlot(source, varbitId, next);
			}
		}
		current = new LeagueModeSnapshot(seasonal, deadman, next);
	}

	/**
	 * The facts of the last refresh as an immutable value. A per-refresh
	 * requirement context retains this instead of this live object, so its
	 * verdicts cannot track a later refresh's writes.
	 */
	public LeagueModeSnapshot snapshot()
	{
		return current;
	}

	public boolean isSeasonal()
	{
		return current.isSeasonal();
	}

	/**
	 * Whether the player is on a Deadman Mode world ({@link WorldType#DEADMAN};
	 * tournament worlds are flagged DEADMAN too). Tracked here because this
	 * object already owns world-type detection.
	 */
	public boolean isDeadman()
	{
		return current.isDeadman();
	}

	/**
	 * Whether the supplied region is currently traversable. Outside of
	 * seasonal mode every region is considered unlocked.
	 */
	public boolean isUnlocked(LeagueRegion region)
	{
		return current.isUnlocked(region);
	}

	/**
	 * Whether the supplied tile is in the always-blocked region while the
	 * player is on a seasonal world. Returns {@code false} on non-seasonal
	 * worlds so normal pathfinding is unaffected.
	 */
	public boolean isInBlockedRegion(int packedPoint)
	{
		return current.isInBlockedRegion(packedPoint);
	}

	/**
	 * Test hook: forces the seasonal flag and unlock set without touching
	 * the client. The Deadman flag keeps its current value, matching the
	 * pre-snapshot behaviour where this only replaced seasonal state.
	 */
	public void setForTest(boolean seasonal, Set<LeagueRegion> unlocked)
	{
		current = new LeagueModeSnapshot(seasonal, current.isDeadman(), unlocked);
	}

	private static void addRegionFromSlot(PlayerStateSource source, int varbitId, Set<LeagueRegion> out)
	{
		int value = source.varbit(varbitId);
		if (value <= 0)
		{
			return;
		}
		LeagueRegion region = AREA_VARBIT_TO_REGION.get(value);
		if (region != null)
		{
			out.add(region);
		}
	}
}

package shortestpath.leagues;

import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;

import lombok.extern.slf4j.Slf4j;
import shortestpath.ShortestPathPlugin;
import shortestpath.Util;
import shortestpath.WorldPointUtil;

/**
 * Resolves a packed world point to its {@link LeagueRegion} for the Demonic
 * Pacts League.
 *
 * <p>
 * Mirrors the static-utility shape of
 * {@link shortestpath.pathfinder.WildernessChecker}. The mapping is keyed by
 * OSRS map region id (a 64x64-tile chunk identifier matching
 * {@code WorldPoint.getRegionID()}: {@code (x >> 6) << 8 | (y >> 6)}) and
 * loaded from {@code /leagues/regions.tsv} on first access.
 * </p>
 *
 * <p>
 * Tiles whose region id is absent from the mapping fall back to
 * {@link LeagueRegion#NEUTRAL}. This is deliberate: it covers instances and
 * dynamic regions (POH, raids, dungeon entrances) which are universally
 * accessible during the league regardless of unlocked areas.
 * </p>
 */
@Slf4j
public class LeagueRegionChecker
{
	private static final String RESOURCE_PATH = "/leagues/regions.tsv";

	private static volatile Map<Integer, LeagueRegion> regionsById;

	private LeagueRegionChecker()
	{
	}

	/**
	 * Returns the league region containing the supplied packed world point.
	 * Never returns {@code null}; unmapped tiles resolve to
	 * {@link LeagueRegion#NEUTRAL}.
	 */
	public static LeagueRegion getRegion(int packedPoint)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int regionId = ((x >> 6) << 8) | (y >> 6);
		return regions().getOrDefault(regionId, LeagueRegion.NEUTRAL);
	}

	/**
	 * Convenience predicate for the always-blocked region.
	 */
	public static boolean isInMisthalin(int packedPoint)
	{
		return getRegion(packedPoint) == LeagueRegion.MISTHALIN;
	}

	/**
	 * Returns the underlying region-id-to-region map. Lazily initialised on
	 * first call. Visible to tests via {@link #reload(String)}.
	 */
	private static Map<Integer, LeagueRegion> regions()
	{
		Map<Integer, LeagueRegion> snapshot = regionsById;
		if (snapshot == null)
		{
			synchronized (LeagueRegionChecker.class)
			{
				snapshot = regionsById;
				if (snapshot == null)
				{
					snapshot = loadFromResource();
					regionsById = snapshot;
				}
			}
		}
		return snapshot;
	}

	/**
	 * Replaces the in-memory mapping with a parsed copy of the supplied
	 * TSV body. Intended for tests. Pass {@code null} to clear the cache so
	 * the next call re-loads from the resource file.
	 */
	static synchronized void reload(String tsv)
	{
		if (tsv == null)
		{
			regionsById = null;
			return;
		}
		regionsById = parse(tsv);
	}

	private static Map<Integer, LeagueRegion> loadFromResource()
	{
		try (InputStream in = ShortestPathPlugin.class.getResourceAsStream(RESOURCE_PATH))
		{
			if (in == null)
			{
				log.warn("League regions resource not found at {}; defaulting all tiles to NEUTRAL", RESOURCE_PATH);
				return new HashMap<>();
			}
			String body = new String(Util.readAllBytes(Objects.requireNonNull(in)), StandardCharsets.UTF_8);
			return parse(body);
		}
		catch (IOException e)
		{
			log.error("Failed to load league regions from {}", RESOURCE_PATH, e);
			return new HashMap<>();
		}
	}

	private static Map<Integer, LeagueRegion> parse(String tsv)
	{
		Map<Integer, LeagueRegion> result = new HashMap<>();
		if (tsv == null || tsv.isEmpty())
		{
			return result;
		}
		int lineNumber = 0;
		for (String rawLine : tsv.split("\\R"))
		{
			lineNumber++;
			String line = rawLine.trim();
			if (line.isEmpty() || line.startsWith("#"))
			{
				continue;
			}
			String[] parts = line.split("\\s+", 2);
			if (parts.length != 2)
			{
				log.warn("Skipping malformed league regions row {}: '{}'", lineNumber, rawLine);
				continue;
			}
			final int regionId;
			try
			{
				regionId = Integer.parseInt(parts[0]);
			}
			catch (NumberFormatException e)
			{
				log.warn("Skipping league regions row {} with non-numeric region id '{}'", lineNumber, parts[0]);
				continue;
			}
			final LeagueRegion region;
			try
			{
				region = LeagueRegion.valueOf(parts[1]);
			}
			catch (IllegalArgumentException e)
			{
				log.warn("Skipping league regions row {} with unknown region '{}'", lineNumber, parts[1]);
				continue;
			}
			result.put(regionId, region);
		}
		return result;
	}
}

package shortestpath.overlay;

import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import shortestpath.ShortestPathPlugin;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.PathStep;
import shortestpath.settings.Settings;

abstract class AbstractHighlightOverlay extends Overlay
{
	// Extra tiles of grace past the recalculation distance: beyond it the route
	// recalculates but the stale path stays on screen while the replacement is
	// being computed, so the nearest step is still the best guide meanwhile.
	private static final int REPLANNING_MARGIN_TILES = 5;

	protected final Client client;
	protected final ShortestPathPlugin plugin;
	protected final Settings settings;

	protected AbstractHighlightOverlay(Client client, ShortestPathPlugin plugin, Settings settings)
	{
		this.client = client;
		this.plugin = plugin;
		this.settings = settings;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	protected int getPlayerPathIndex(List<PathStep> path)
	{
		if (client.getLocalPlayer() == null)
		{
			return -1;
		}
		int playerLocation = WorldPointUtil.fromLocalInstance(client, client.getLocalPlayer().getLocalLocation());
		return playerPathIndex(path, playerLocation, settings.lifecycle().recalculateDistance());
	}

	static int playerPathIndex(List<PathStep> path, int playerLocation, int recalculateDistance)
	{
		for (int i = 0; i < path.size(); i++)
		{
			if (path.get(i).getPackedPosition() == playerLocation)
			{
				return i;
			}
		}

		// On an exact-match miss the player may still be close enough to the path that the
		// route has not been recalculated; keep the highlight on the nearest step for as
		// long as the displayed route survives. The strict bound mirrors isNearPath, and
		// steps on other planes (Integer.MAX_VALUE distance) are never candidates.
		int maxDistance = recalculateDistance < 0 ? -1 : recalculateDistance + REPLANNING_MARGIN_TILES;
		int bestIndex = -1;
		int bestDistance = Integer.MAX_VALUE;
		for (int i = 0; i < path.size(); i++)
		{
			int distance = WorldPointUtil.distanceBetween(playerLocation, path.get(i).getPackedPosition());
			if (distance == Integer.MAX_VALUE || (maxDistance >= 0 && distance >= maxDistance))
			{
				continue;
			}
			if (distance < bestDistance)
			{
				bestDistance = distance;
				bestIndex = i;
			}
		}
		return bestIndex;
	}
}

package shortestpath.overlay;

import java.awt.Graphics2D;
import java.awt.geom.AffineTransform;
import java.awt.geom.Path2D;

/**
 * Draws a small triangular arrowhead at the end of a line segment, rotated to the segment's
 * direction, in the current colour of the graphics context.
 * <p>
 * Adapted from Quest Helper's {@code DirectionArrow.drawLineArrowHead}
 * (Copyright (c) 2021, Zoinkwiz &lt;https://github.com/Zoinkwiz&gt;, BSD 2-Clause licence),
 * as also used by the port-tasks plugin.
 */
public final class ArrowHead
{
	private ArrowHead()
	{
	}

	/**
	 * Fills an arrowhead pointing from (x1, y1) towards (x2, y2), with its tip at (x2, y2).
	 *
	 * @param size length of the arrowhead in pixels (its width is {@code size})
	 */
	public static void draw(Graphics2D graphics, double x1, double y1, double x2, double y2, double size)
	{
		Path2D head = new Path2D.Double();
		head.moveTo(0, 0);
		head.lineTo(-size / 2.0, -size);
		head.lineTo(size / 2.0, -size);
		head.closePath();

		AffineTransform tx = new AffineTransform();
		double angle = Math.atan2(y2 - y1, x2 - x1);
		tx.translate(x2, y2);
		tx.rotate(angle - Math.PI / 2d);

		Graphics2D g = (Graphics2D) graphics.create();
		// Compose (not replace) so the overlay's existing transform/clip stay intact.
		g.transform(tx);
		g.fill(head);
		g.dispose();
	}
}

package shortestpath.overlay;

import com.google.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import shortestpath.ShortestPathPlugin;
import shortestpath.items.ItemStateService;
import shortestpath.pathfinder.ActiveSearch;
import shortestpath.pathfinder.PathStep;
import shortestpath.requirement.BankPickupRequirements;
import shortestpath.settings.Settings;

public class BankItemHighlightOverlay extends AbstractHighlightOverlay
{
	private final ItemManager itemManager;
	private final Settings settings;
	private final ItemStateService itemState;

	@Inject
	public BankItemHighlightOverlay(Client client, ShortestPathPlugin plugin, ItemManager itemManager, Settings settings,
		ItemStateService itemState)
	{
		super(client, plugin, settings);
		this.itemManager = itemManager;
		this.settings = settings;
		this.itemState = itemState;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!settings.display().highlightBankPickupItems())
		{
			return null;
		}

		ActiveSearch search = plugin.getActiveSearch();
		if (search == null)
		{
			return null;
		}

		List<PathStep> path = search.getPath();
		if (path == null || path.isEmpty())
		{
			return null;
		}

		Widget bankContainer = client.getWidget(InterfaceID.Bankmain.ITEMS);
		if (bankContainer == null || bankContainer.isHidden())
		{
			return null;
		}

		if (itemState.getBank() == null)
		{
			return null;
		}

		Set<Integer> bankLocations = plugin.getPathfinderConfig().getDestinations("bank");
		if (bankLocations == null)
		{
			return null;
		}

		int pathIndex = getPlayerPathIndex(path);
		if (pathIndex < 0)
		{
			return null;
		}

		BankPickupRequirements.BankPickupResult pickup = plugin.getPathfinderConfig().getBankPickup(path, pathIndex, plugin.getActiveSearch());
		if (pickup == null || pickup.bankItemIds.isEmpty())
		{
			return null;
		}

		Widget[] items = bankContainer.getChildren();
		if (items == null)
		{
			return null;
		}

		Color highlight = settings.display().colourBankPickupHighlight();
		for (Widget item : items)
		{
			if (item == null || item.isHidden() || item.getItemId() < 0)
			{
				continue;
			}
			if (pickup.bankItemIds.contains(item.getItemId()))
			{
				BufferedImage outline = itemManager.getItemOutline(item.getItemId(), item.getItemQuantity(), highlight);
				if (outline != null)
				{
					graphics.drawImage(outline, item.getBounds().x, item.getBounds().y, null);
				}
			}
		}

		return null;
	}
}

package shortestpath.overlay;

import com.google.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;
import shortestpath.DebugState;
import shortestpath.ShortestPathPlugin;
import shortestpath.pathfinder.ActiveSearch;
import shortestpath.pathfinder.AStarPathfinder;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.PathTerminationReason;
import shortestpath.pathfinder.PathfinderResult;
import shortestpath.pathfinder.PathfinderStats;

public class DebugOverlayPanel extends OverlayPanel
{
	private static final int PANEL_WIDTH = 230;
	private static final Color PROBLEM = Color.RED;
	private static final long STATIC_BUILD_THRESHOLD_NANOS = 1_000_000;

	private final ShortestPathPlugin plugin;
	private final Client client;

	@Inject
	public DebugOverlayPanel(ShortestPathPlugin plugin, Client client)
	{
		super(plugin);
		this.plugin = plugin;
		this.client = client;

		setPosition(OverlayPosition.TOP_LEFT);
		panelComponent.setPreferredSize(new Dimension(PANEL_WIDTH, 0));
	}

	private LineComponent makeLine(String left, String right)
	{
		return makeLine(left, right, Color.WHITE);
	}

	private LineComponent makeLine(String left, String right, Color rightColor)
	{
		return LineComponent.builder()
			.left(left)
			.right(right)
			.rightColor(rightColor)
			.build();
	}

	private LineComponent makeHeader(String text)
	{
		return LineComponent.builder()
			.left(text)
			.leftColor(Color.ORANGE)
			.build();
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		List<LayoutableRenderableEntity> components = panelComponent.getChildren();
		DebugState debug = plugin.getDebugState();
		int tick = client.getTickCount();

		components.add(
			TitleComponent.builder()
				.text("Shortest Path Debug")
				.color(Color.ORANGE)
				.build());

		renderSearch(components, debug);
		renderRestart(components, debug, tick);
		renderErrors(components, debug, tick);

		return super.render(graphics);
	}

	private void renderSearch(List<LayoutableRenderableEntity> components, DebugState debug)
	{
		ActiveSearch search = plugin.getActiveSearch();
		if (search == null)
		{
			components.add(makeHeader("No search"));
			return;
		}

		AStarPathfinder aStar = search instanceof AStarPathfinder ? (AStarPathfinder) search : null;
		PathfinderResult result = search.getResult();
		boolean problem = search == debug.getCancelledSearch() || isFailure(result);
		components.add(LineComponent.builder()
			.left((aStar != null ? "A*" : "Legacy") + " \u00b7 " + state(search, aStar, result, debug))
			.leftColor(problem ? PROBLEM : Color.ORANGE)
			.build());

		if (result != null)
		{
			components.add(makeLine("Result:", result.getTerminationReason() + ", cost " + result.getPathCost(),
				isFailure(result) ? PROBLEM : Color.WHITE));
			if (result.getMessage() != null)
			{
				components.add(makeLine("Message:", result.getMessage(), PROBLEM));
			}
		}

		List<PathStep> path = search.getPath();
		String tiles = path == null ? "none" : path.size() + " tiles";
		// While recalculating, the shown path is the previous route but the click count is the
		// new search's — suppress it rather than mix the two.
		if (aStar != null && !aStar.isShowingProvisionalPath())
		{
			tiles += ", " + aStar.getClickPoints().size() + " clicks";
		}
		components.add(makeLine("Path:", tiles));

		PathfinderStats stats = search.getStats();
		if (stats == null)
		{
			return;
		}
		components.add(makeLine("Time:", millis(stats.getElapsedTimeNanos())));
		if (aStar != null)
		{
			components.add(makeLine("  Forward search:", millis(aStar.getForwardSearchNanos())));
			components.add(makeLine("  Walk canonicalize:", millis(aStar.getWalkCanonicalizeNanos())));
			if (!aStar.getWalkDiagnostics().isEmpty())
				components.add(makeLine("  Legs kept as found:", Integer.toString(aStar.getWalkDiagnostics().size())));
			int keptSteps = aStar.getKeptStepIndices().size();
			components.add(makeLine("  Walk rewrite:", millis(aStar.getWalkRewriteNanos())
				+ (keptSteps > 0 ? ", " + keptSteps + " kept" : "")));
			components.add(makeLine("  Target prep:", aStar.isTargetReused() ? "reused"
				: millis(aStar.getReverseSearchNanos() + aStar.getHeuristicPrepareNanos())));
			components.add(makeLine("  Graph prep:", aStar.isGraphReused() ? "reused"
				: millis(aStar.getGraphPrepareNanos())));
			components.add(makeLine("  Account prep:", millis(aStar.getAccountPrepareNanos())));
			// Static data is built once; only the search that built it spends measurable time on it.
			if (aStar.getRoutingStaticNanos() >= STATIC_BUILD_THRESHOLD_NANOS)
			{
				components.add(makeLine("  Static data:", millis(aStar.getRoutingStaticNanos())));
			}
		}
	}

	private void renderRestart(List<LayoutableRenderableEntity> components, DebugState debug, int tick)
	{
		DebugState.Restart restart = debug.getRestart();
		if (restart == null)
		{
			return;
		}
		components.add(makeLine("Restarts:", restart.count + " (last: " + restart.reason + ", "
			+ ago(restart.tick, tick) + ")"));
		String outcome = restart.outcome;
		if (!DebugState.STARTED.equals(outcome))
		{
			components.add(makeLine("Restart outcome:", outcome, PROBLEM));
		}
	}

	private void renderErrors(List<LayoutableRenderableEntity> components, DebugState debug, int tick)
	{
		if (debug.getClientErrorCount() > 0)
		{
			components.add(makeLine("Client error:", error(debug.getClientErrorCount(), debug.getClientError(),
				debug.getClientErrorTick(), tick), PROBLEM));
		}
		if (debug.getSearchErrorCount() > 0)
		{
			components.add(makeLine("Search error:", error(debug.getSearchErrorCount(), debug.getSearchError(),
				debug.getSearchErrorTick(), tick), PROBLEM));
		}
	}

	private static String state(ActiveSearch search, AStarPathfinder aStar, PathfinderResult result, DebugState debug)
	{
		if (search == debug.getCancelledSearch())
		{
			return "cancelled, not replaced";
		}
		if (aStar != null && aStar.isShowingProvisionalPath())
		{
			return "running, previous route shown";
		}
		if (!search.isDone())
		{
			return "running";
		}
		return isFailure(result) ? "failed" : "done";
	}

	private static boolean isFailure(PathfinderResult result)
	{
		return result != null && result.getTerminationReason() == PathTerminationReason.BACKEND_FAILURE;
	}

	private static String error(int count, String message, int errorTick, int tick)
	{
		return count + "x, last " + ago(errorTick, tick) + ": " + message;
	}

	private static String ago(int then, int now)
	{
		return then < 0 ? "-" : (now - then) + " ticks ago";
	}

	private static String millis(long nanos)
	{
		return String.format("%.2fms", nanos / 1_000_000.0);
	}
}

package shortestpath.overlay;

import com.google.inject.Inject;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import shortestpath.ItemVariations;
import shortestpath.ShortestPathPlugin;
import shortestpath.pathfinder.ActiveSearch;
import shortestpath.pathfinder.PathStep;
import shortestpath.transport.Transport;
import shortestpath.requirement.TransportEligibility;
import shortestpath.transport.TransportType;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.settings.Settings;

public class InventoryHighlightOverlay extends AbstractHighlightOverlay
{
	private static final int[] EQUIPMENT_SLOT_WIDGET_IDS = {
		InterfaceID.Wornitems.SLOT0,
		InterfaceID.Wornitems.SLOT1,
		InterfaceID.Wornitems.SLOT2,
		InterfaceID.Wornitems.SLOT3,
		InterfaceID.Wornitems.SLOT4,
		InterfaceID.Wornitems.SLOT5,
		InterfaceID.Wornitems.SLOT7,
		InterfaceID.Wornitems.SLOT9,
		InterfaceID.Wornitems.SLOT10,
		InterfaceID.Wornitems.SLOT12,
		InterfaceID.Wornitems.SLOT13,
	};

	private final ItemManager itemManager;
	// Fairy-ring scan cache: pathfinder searches hand out immutable path lists, so the
	// last scanned list doubles as the cache key by reference identity.
	private List<PathStep> scannedPath;
	private int lastFairyRingEdgeIndex = -1;
	private final Settings settings;

	@Inject
	public InventoryHighlightOverlay(Client client, ShortestPathPlugin plugin, ItemManager itemManager, Settings settings)
	{
		super(client, plugin, settings);
		this.itemManager = itemManager;
		this.settings = settings;
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!settings.display().highlightInventoryItems())
		{
			return null;
		}

		ActiveSearch search = plugin.getActiveSearch();
		if (search == null)
		{
			return null;
		}

		List<PathStep> path = search.getPath();
		if (path == null || path.isEmpty())
		{
			return null;
		}

		int pathIndex = getPlayerPathIndex(path);
		if (pathIndex < 0 || pathIndex + 1 >= path.size())
		{
			return null;
		}

		Set<Transport> transports = plugin.transportsForEdge(path.get(pathIndex), path.get(pathIndex + 1));
		Set<Integer> itemsToHighlight = new HashSet<>();
		boolean lumbridgeEliteDone = client.getVarbitValue(VarbitID.LUMBRIDGE_DIARY_ELITE_COMPLETE) == 1;
		// The dramen staff requirement lives outside the transport's item requirements,
		// and the staff can be equipped ahead of time — so highlight it whenever the
		// remaining path uses a fairy ring, not only while standing on the ring edge.
		// The Lumbridge Elite diary removes the requirement entirely.
		boolean ringAhead = fairyRingAhead(path, pathIndex);
		if (!lumbridgeEliteDone && ringAhead)
		{
			addItemIds(itemsToHighlight, ItemVariations.DRAMEN_STAFF.getIds());
		}

		for (Transport transport : transports)
		{
			TransportType type = transport.getType();
			if (!TransportType.TELEPORTATION_ITEM.equals(type)
				&& !TransportType.TELEPORTATION_BOX.equals(type)
				&& !TransportType.FAIRY_RING.equals(type)
				&& !TransportType.QUETZAL_WHISTLE.equals(type))
			{
				continue;
			}
			if (transport.getItemRequirements() == null || transport.getItemRequirements().size() == 0)
			{
				continue;
			}
			for (ItemRequirement req : transport.getItemRequirements().getRequirements())
			{
				addItemIds(itemsToHighlight, req.getItemIds());
				addItemIds(itemsToHighlight, req.getStaffIds());
				addItemIds(itemsToHighlight, req.getOffhandIds());
			}
		}

		if (itemsToHighlight.isEmpty())
		{
			return null;
		}

		// Build set of dramen/lunar staff IDs — skip highlighting when already equipped,
		// since wearing them passively enables fairy rings without any active use.
		Set<Integer> dramenStaffIds = new HashSet<>();
		for (int id : TransportEligibility.fairyStaffIds())
		{
			dramenStaffIds.add(id);
		}

		Color highlight = settings.display().colourBankPickupHighlight();

		// Highlight matching items in the inventory
		Widget inventoryContainer = client.getWidget(InterfaceID.Inventory.ITEMS);
		if (inventoryContainer != null && !inventoryContainer.isHidden())
		{
			Widget[] items = inventoryContainer.getChildren();
			if (items != null)
			{
				for (Widget item : items)
				{
					if (item == null || item.isHidden() || item.getItemId() < 0)
					{
						continue;
					}
					if (itemsToHighlight.contains(item.getItemId()))
					{
						BufferedImage outline = itemManager.getItemOutline(item.getItemId(), item.getItemQuantity(), highlight);
						if (outline != null)
						{
							graphics.drawImage(outline, item.getBounds().x, item.getBounds().y, null);
						}
					}
				}
			}
		}

		// Highlight matching items in the equipment tab. Equipped items are
		// rendered by child item widgets of the static slot components; the slot
		// widgets themselves never carry an item id.
		for (int slotWidgetId : EQUIPMENT_SLOT_WIDGET_IDS)
		{
			Widget slot = client.getWidget(slotWidgetId);
			if (slot == null || slot.isHidden())
			{
				continue;
			}
			Widget[] children = slot.getChildren();
			if (children == null)
			{
				continue;
			}
			for (Widget item : children)
			{
				if (item == null || item.isHidden() || item.getItemId() < 0)
				{
					continue;
				}
				int itemId = item.getItemId();
				if (!itemsToHighlight.contains(itemId))
				{
					continue;
				}
				// Dramen/lunar staff: skip when equipped — wearing it passively enables fairy rings
				if (dramenStaffIds.contains(itemId))
				{
					continue;
				}
				BufferedImage outline = itemManager.getItemOutline(itemId, 1, highlight);
				if (outline != null)
				{
					graphics.drawImage(outline, item.getBounds().x, item.getBounds().y, null);
				}
			}
		}

		return null;
	}

	/**
	 * Whether any remaining path edge at or after {@code fromIndex} is a fairy ring.
	 * Scans the whole path once per path instance and caches the last ring edge index;
	 * a ring is ahead exactly when that index is at or beyond the player's edge.
	 */
	private boolean fairyRingAhead(List<PathStep> path, int fromIndex)
	{
		if (path != scannedPath)
		{
			scannedPath = path;
			lastFairyRingEdgeIndex = -1;
			for (int i = 0; i + 1 < path.size(); ++i)
			{
				for (Transport transport : plugin.transportsForEdge(path.get(i), path.get(i + 1)))
				{
					if (TransportType.FAIRY_RING.equals(transport.getType()))
					{
						lastFairyRingEdgeIndex = i;
						break;
					}
				}
			}
		}
		return lastFairyRingEdgeIndex >= fromIndex;
	}

	private static void addItemIds(Set<Integer> target, int[] ids)
	{
		if (ids != null)
		{
			for (int id : ids)
			{
				if (id >= 0)
				{
					target.add(id);
				}
			}
		}
	}
}

package shortestpath.overlay;

import com.google.inject.Inject;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Stroke;
import java.awt.geom.Area;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import shortestpath.PrimitiveIntHashMap;
import shortestpath.ShortestPathPlugin;
import shortestpath.TileStyle;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.TransportAvailability;
import shortestpath.settings.Settings;
import shortestpath.transport.Transport;

public class PathMapOverlay extends Overlay
{
	private final Client client;
	private final ShortestPathPlugin plugin;
	private final Settings settings;

	@Inject
	private PathMapOverlay(Client client, ShortestPathPlugin plugin, Settings settings)
	{
		this.client = client;
		this.plugin = plugin;
		this.settings = settings;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.MANUAL);
		drawAfterLayer(InterfaceID.Worldmap.MAP_CONTAINER);
	}

	private static final Color COLOR_AVAILABLE = Color.WHITE;
	private static final Color COLOR_UNAVAILABLE = Color.ORANGE;

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!settings.display().drawMap())
		{
			return null;
		}

		if (client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
		{
			return null;
		}

		Rectangle worldMapRectangle = Objects.requireNonNull(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).getBounds();
		Area worldMapClipArea = getWorldMapClipArea(worldMapRectangle);
		graphics.setClip(worldMapClipArea);

		if (settings.display().drawCollisionMap())
		{
			graphics.setColor(settings.display().colourCollisionMap());
			int mapWorldPoint = plugin.calculateMapPoint(worldMapRectangle.x, worldMapRectangle.y);
			int extentX = WorldPointUtil.unpackWorldX(mapWorldPoint);
			int extentY = WorldPointUtil.unpackWorldY(mapWorldPoint);
			int extentWidth = getWorldMapExtentWidth(worldMapRectangle);
			int extentHeight = getWorldMapExtentHeight(worldMapRectangle);
			final CollisionMap map = plugin.getMap();
			final int z = client.getTopLevelWorldView().getPlane();
			for (int x = extentX; x < (extentX + extentWidth + 1); x++)
			{
				for (int y = extentY - extentHeight; y < (extentY + 1); y++)
				{
					if (map.isBlocked(x, y, z))
					{
						drawOnMap(graphics, WorldPointUtil.packWorldPoint(x, y, z), false, null);
					}
				}
			}
		}

		if (settings.display().drawTransports())
		{
			PrimitiveIntHashMap<Transport[]> allTransports = plugin.getAllDisplayTransports();
			PrimitiveIntHashMap<Transport[]> availableTransports = plugin.getTransports();

			for (int a : allTransports.keys())
			{
				if (a == Transport.UNDEFINED_ORIGIN)
				{
					continue; // skip teleports
				}

				int mapAX = plugin.mapWorldPointToGraphicsPointX(a);
				int mapAY = plugin.mapWorldPointToGraphicsPointY(a);
				if (!worldMapClipArea.contains(mapAX, mapAY))
				{
					continue;
				}

				Transport[] availableAtOrigin = availableTransports.getOrDefault(a, TransportAvailability.EMPTY_TRANSPORTS);

				for (Transport b : allTransports.getOrDefault(a, TransportAvailability.EMPTY_TRANSPORTS))
				{
					if (b == null || (b.getType() != null && b.getType().isTeleport()))
					{
						continue; // skip teleports
					}

					int mapBX = plugin.mapWorldPointToGraphicsPointX(b.getDestination());
					int mapBY = plugin.mapWorldPointToGraphicsPointY(b.getDestination());
					if (!worldMapClipArea.contains(mapBX, mapBY))
					{
						continue;
					}

					boolean isAvailable = Arrays.asList(availableAtOrigin).contains(b);
					graphics.setColor(isAvailable ? COLOR_AVAILABLE : COLOR_UNAVAILABLE);
					graphics.drawLine(mapAX, mapAY, mapBX, mapBY);
				}
			}
		}

		if (plugin.getActiveSearch() != null)
		{
			Color colour = plugin.getPathColor();
			List<PathStep> path = plugin.getActiveSearch().getPath();
			Point cursorPos = client.getMouseCanvasPosition();
			if (plugin.isSailing())
			{
				// On a boat the path sails the boat's headings: a line along each heading it holds, with a small square
				// at the end of each move
				graphics.setColor(plugin.isPathUnreachable() ? plugin.getPathColor() : ShortestPathPlugin.COLOUR_SAILING_PATH);
				for (int i = 0; i < path.size(); i++)
				{
					int point = path.get(i).getPackedPosition();
					if (i > 0)
					{
						drawSolidLineOnMap(graphics, path.get(i - 1).getPackedPosition(), point);
					}
					drawSmallSquareOnMap(graphics, point);
				}
			}
			else if (TileStyle.ARROW_LINE.equals(settings.display().pathStyle()))
			{
				graphics.setColor(colour);
				drawArrowPath(graphics, path);
			}
			else
			{
				for (int i = 0; i < path.size(); i++)
				{
					graphics.setColor(colour);
					int point = path.get(i).getPackedPosition();
					int lastPoint = (i > 0) ? path.get(i - 1).getPackedPosition() : point;
					if (WorldPointUtil.distanceBetween(point, lastPoint) > 1)
					{
						drawOnMap(graphics, lastPoint, point, true, cursorPos);
					}
					drawOnMap(graphics, point, true, cursorPos);
				}
			}
			for (int target : plugin.getActiveSearch().getTargets().points())
			{
				if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition())
				{
					graphics.setColor(settings.display().colourPathCalculating());
					drawOnMap(graphics, target, true, cursorPos);
				}
			}
		}

		return null;
	}

	/**
	 * Draws the path as a directed polyline: consecutive same-direction walking steps are compressed
	 * into one straight segment, each segment ends in a small arrowhead showing travel direction, and
	 * teleport/transport jumps are dashed. (Arrowhead technique adapted from Quest Helper's
	 * DirectionArrow, see {@link ArrowHead}.)
	 */
	private void drawArrowPath(Graphics2D graphics, List<PathStep> path)
	{
		final Stroke walkStroke = new BasicStroke(2, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND);
		final Stroke jumpStroke = new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL, 0, new float[]{9}, 0);

		int i = 0;
		while (i < path.size() - 1)
		{
			int from = path.get(i).getPackedPosition();
			int next = path.get(i + 1).getPackedPosition();

			if (WorldPointUtil.distanceBetween(from, next) > 1)
			{
				// Teleport/transport jump: dashed segment.
				drawMapSegment(graphics, from, next, jumpStroke);
				i++;
				continue;
			}

			// Extend the straight walking run while the direction stays the same.
			int dx = WorldPointUtil.unpackWorldX(next) - WorldPointUtil.unpackWorldX(from);
			int dy = WorldPointUtil.unpackWorldY(next) - WorldPointUtil.unpackWorldY(from);
			int j = i + 1;
			while (j < path.size() - 1)
			{
				int a = path.get(j).getPackedPosition();
				int b = path.get(j + 1).getPackedPosition();
				if (WorldPointUtil.distanceBetween(a, b) > 1
					|| WorldPointUtil.unpackWorldX(b) - WorldPointUtil.unpackWorldX(a) != dx
					|| WorldPointUtil.unpackWorldY(b) - WorldPointUtil.unpackWorldY(a) != dy)
				{
					break;
				}
				j++;
			}
			drawMapSegment(graphics, from, path.get(j).getPackedPosition(), walkStroke);
			i = j;
		}
	}

	private void drawMapSegment(Graphics2D graphics, int from, int to, Stroke stroke)
	{
		int x1 = plugin.mapWorldPointToGraphicsPointX(from);
		int y1 = plugin.mapWorldPointToGraphicsPointY(from);
		int x2 = plugin.mapWorldPointToGraphicsPointX(to);
		int y2 = plugin.mapWorldPointToGraphicsPointY(to);
		if (x1 == Integer.MIN_VALUE || y1 == Integer.MIN_VALUE
			|| x2 == Integer.MIN_VALUE || y2 == Integer.MIN_VALUE)
		{
			return;
		}
		graphics.setStroke(stroke);
		graphics.drawLine(x1, y1, x2, y2);
		// Skip the head on segments too short to fit it (e.g. zoomed far out).
		if (Math.hypot(x2 - x1, y2 - y1) >= 10)
		{
			ArrowHead.draw(graphics, x1, y1, x2, y2, 7);
		}
	}

	private void drawSmallSquareOnMap(Graphics2D graphics, int point)
	{
		int x = plugin.mapWorldPointToGraphicsPointX(point);
		int y = plugin.mapWorldPointToGraphicsPointY(point);
		int nextX = plugin.mapWorldPointToGraphicsPointX(WorldPointUtil.dxdy(point, 1, -1));
		if (x == Integer.MIN_VALUE || y == Integer.MIN_VALUE || nextX == Integer.MIN_VALUE)
		{
			return;
		}
		int size = Math.max(2, (nextX - x) / 2);
		graphics.fillRect(x - size / 2, y - size / 2, size, size);
	}

	private void drawSolidLineOnMap(Graphics2D graphics, int from, int to)
	{
		int x1 = plugin.mapWorldPointToGraphicsPointX(from);
		int y1 = plugin.mapWorldPointToGraphicsPointY(from);
		int x2 = plugin.mapWorldPointToGraphicsPointX(to);
		int y2 = plugin.mapWorldPointToGraphicsPointY(to);
		if (x1 == Integer.MIN_VALUE || y1 == Integer.MIN_VALUE || x2 == Integer.MIN_VALUE || y2 == Integer.MIN_VALUE)
		{
			return;
		}
		graphics.setStroke(new BasicStroke(2));
		graphics.drawLine(x1, y1, x2, y2);
	}

	private void drawOnMap(Graphics2D graphics, int point, boolean checkHover, Point cursorPos)
	{
		drawOnMap(graphics, point, WorldPointUtil.dxdy(point, 1, -1), checkHover, cursorPos);
	}

	private void drawOnMap(Graphics2D graphics, int point, int offsetPoint, boolean checkHover, Point cursorPos)
	{
		int startX = plugin.mapWorldPointToGraphicsPointX(point);
		int startY = plugin.mapWorldPointToGraphicsPointY(point);
		int endX = plugin.mapWorldPointToGraphicsPointX(offsetPoint);
		int endY = plugin.mapWorldPointToGraphicsPointY(offsetPoint);

		if (startX == Integer.MIN_VALUE || startY == Integer.MIN_VALUE ||
			endX == Integer.MIN_VALUE || endY == Integer.MIN_VALUE)
		{
			return;
		}

		int x = startX;
		int y = startY;
		final int width = endX - x;
		final int height = endY - y;
		x -= width / 2;
		y -= height / 2;

		if (WorldPointUtil.distanceBetween(point, offsetPoint) > 1)
		{
			graphics.setStroke(new BasicStroke(1, BasicStroke.CAP_BUTT, BasicStroke.JOIN_BEVEL, 0, new float[]{9}, 0));
			graphics.drawLine(startX, startY, endX, endY);
		}
		else
		{
			if (checkHover && cursorPos != null &&
				cursorPos.getX() >= x && cursorPos.getX() <= (endX - width / 2) &&
				cursorPos.getY() >= y && cursorPos.getY() <= (endY - width / 2))
			{
				graphics.setColor(graphics.getColor().darker());
			}
			graphics.fillRect(x, y, width, height);
		}
	}

	private Area getWorldMapClipArea(Rectangle baseRectangle)
	{
		final Widget overview = client.getWidget(InterfaceID.Worldmap.OVERVIEW_CONTAINER);
		final Widget surfaceSelector = client.getWidget(InterfaceID.Worldmap.MAPLIST_BOX_GRAPHIC0);

		Area clipArea = new Area(baseRectangle);

		if (overview != null && !overview.isHidden())
		{
			clipArea.subtract(new Area(overview.getBounds()));
		}

		if (surfaceSelector != null && !surfaceSelector.isHidden())
		{
			clipArea.subtract(new Area(surfaceSelector.getBounds()));
		}

		return clipArea;
	}

	private int getWorldMapExtentWidth(Rectangle baseRectangle)
	{
		return (WorldPointUtil.unpackWorldX(
			plugin.calculateMapPoint(
				baseRectangle.x + baseRectangle.width,
				baseRectangle.y + baseRectangle.height))
			-
			WorldPointUtil.unpackWorldX(
				plugin.calculateMapPoint(
					baseRectangle.x,
					baseRectangle.y)));
	}

	private int getWorldMapExtentHeight(Rectangle baseRectangle)
	{
		return (WorldPointUtil.unpackWorldY(
			plugin.calculateMapPoint(
				baseRectangle.x,
				baseRectangle.y))
			-
			WorldPointUtil.unpackWorldY(
				plugin.calculateMapPoint(
					baseRectangle.x + baseRectangle.width,
					baseRectangle.y + baseRectangle.height)));
	}
}

package shortestpath.overlay;

import com.google.inject.Inject;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Objects;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.JagexColors;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import shortestpath.ShortestPathPlugin;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.PathStep;
import shortestpath.settings.Settings;
import shortestpath.transport.Transport;

public class PathMapTooltipOverlay extends Overlay
{
	private static final int TOOLTIP_OFFSET_HEIGHT = 25;
	private static final int TOOLTIP_OFFSET_WIDTH = 15;
	private static final int TOOLTIP_PADDING_HEIGHT = 1;
	private static final int TOOLTIP_PADDING_WIDTH = 2;
	private static final int TOOLTIP_TEXT_OFFSET_HEIGHT = -2;

	private final Client client;
	private final ShortestPathPlugin plugin;
	private final Settings settings;

	@Inject
	private PathMapTooltipOverlay(Client client, ShortestPathPlugin plugin, Settings settings)
	{
		this.client = client;
		this.plugin = plugin;
		this.settings = settings;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_HIGHEST);
		setLayer(OverlayLayer.MANUAL);
		drawAfterInterface(InterfaceID.WORLDMAP);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!settings.display().drawMap() || client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER) == null)
		{
			return null;
		}

		if (plugin.getActiveSearch() != null)
		{
			List<PathStep> path = plugin.getActiveSearch().getPath();
			Point cursorPos = client.getMouseCanvasPosition();
			for (int i = 0; i < path.size(); i++)
			{
				int nextPoint = WorldPointUtil.UNDEFINED;
				if (path.size() > i + 1)
				{
					nextPoint = path.get(i + 1).getPackedPosition();
				}
				if (drawTooltip(graphics, cursorPos, path.get(i).getPackedPosition(), nextPoint, i + 1, path, i))
				{
					return null;
				}
			}
			for (int target : plugin.getActiveSearch().getTargets().points())
			{
				if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition())
				{
					drawTooltip(graphics, cursorPos, target, WorldPointUtil.UNDEFINED, -1, path, -1);
				}
			}
		}

		return null;
	}

	private boolean drawTooltip(Graphics2D graphics, Point cursorPos, int point, int nextPoint, int n,
		List<PathStep> path, int pathIndex)
	{
		int offsetPoint = WorldPointUtil.dxdy(point, 1, -1);
		int startX = plugin.mapWorldPointToGraphicsPointX(point);
		int startY = plugin.mapWorldPointToGraphicsPointY(point);
		int endX = plugin.mapWorldPointToGraphicsPointX(offsetPoint);
		int endY = plugin.mapWorldPointToGraphicsPointY(offsetPoint);

		if (startX == Integer.MIN_VALUE || startY == Integer.MIN_VALUE ||
			endX == Integer.MIN_VALUE || endY == Integer.MIN_VALUE)
		{
			return false;
		}

		int width = endX - startX;

		if (cursorPos.getX() < (startX - width / 2) || cursorPos.getX() > (endX - width / 2) ||
			cursorPos.getY() < (startY - width / 2) || cursorPos.getY() > (endY - width / 2))
		{
			return false;
		}

		List<String> rows = new ArrayList<>(Arrays.asList("Shortest path:",
			n < 0 ? "Unused target" : ("Step " + n + " of " + plugin.getActiveSearch().getPath().size())));
		if (nextPoint != WorldPointUtil.UNDEFINED)
		{
			PathStep currentStep = path.get(pathIndex);
			PathStep nextStep = plugin.nextPathStep(path, pathIndex);
			for (Transport transport : plugin.transportsForEdge(currentStep, nextStep))
			{
				String displayInfo = plugin.formatTransportDisplay(transport);
				if (displayInfo != null && !displayInfo.isEmpty())
				{
					// Check if this transport goes to POH - if so, look ahead to find the exit
					// transport
					String pohExitInfo = plugin.getPohExitInfo(nextPoint, path, pathIndex);
					if (pohExitInfo != null)
					{
						displayInfo = displayInfo + " (Exit: " + pohExitInfo + ")";
					}
					rows.add(displayInfo);
					break;
				}
			}
		}

		graphics.setFont(FontManager.getRunescapeFont());
		FontMetrics fm = graphics.getFontMetrics();
		int tooltipHeight = fm.getHeight();
		int tooltipWidth = 0;
		if (rows.stream().map(fm::stringWidth).max(Integer::compare).isPresent())
		{
			tooltipWidth = rows.stream().map(fm::stringWidth).max(Integer::compareTo).get();
		}
		int clippedHeight = tooltipHeight * rows.size() + TOOLTIP_PADDING_HEIGHT * 2;
		int clippedWidth = tooltipWidth + TOOLTIP_PADDING_WIDTH * 2;

		Rectangle worldMapBounds = Objects.requireNonNull(client.getWidget(InterfaceID.Worldmap.MAP_CONTAINER)).getBounds();
		int worldMapRightBoundary = worldMapBounds.width + worldMapBounds.x;
		int worldMapBottomBoundary = worldMapBounds.height + worldMapBounds.y;

		int drawPointX = startX + TOOLTIP_OFFSET_WIDTH;
		int drawPointY = startY;
		if (drawPointX + clippedWidth > worldMapRightBoundary)
		{
			drawPointX = worldMapRightBoundary - clippedWidth;
		}
		if (drawPointY + clippedHeight > worldMapBottomBoundary)
		{
			drawPointY = startY - clippedHeight;
		}
		drawPointY += TOOLTIP_OFFSET_HEIGHT;

		int tooltipRectX = drawPointX - TOOLTIP_PADDING_WIDTH;
		int tooltipRectY = drawPointY - TOOLTIP_PADDING_HEIGHT;

		graphics.setColor(JagexColors.TOOLTIP_BACKGROUND);
		graphics.fillRect(tooltipRectX, tooltipRectY, clippedWidth, clippedHeight);

		graphics.setColor(JagexColors.TOOLTIP_BORDER);
		graphics.drawRect(tooltipRectX, tooltipRectY, clippedWidth, clippedHeight);

		graphics.setColor(JagexColors.TOOLTIP_TEXT);
		for (int i = 0; i < rows.size(); i++)
		{
			graphics.drawString(rows.get(i), drawPointX, drawPointY + TOOLTIP_TEXT_OFFSET_HEIGHT + (i + 1) * tooltipHeight);
		}

		return true;
	}
}

package shortestpath.overlay;

import com.google.inject.Inject;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.Shape;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import shortestpath.PrimitiveIntList;
import shortestpath.ShortestPathPlugin;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.PathStep;
import shortestpath.settings.Settings;

public class PathMinimapOverlay extends Overlay
{
	private final Client client;
	private final ShortestPathPlugin plugin;
	private final Settings settings;

	@Inject
	private PathMinimapOverlay(Client client, ShortestPathPlugin plugin, Settings settings)
	{
		this.client = client;
		this.plugin = plugin;
		this.settings = settings;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	public static void renderMinimapRect(Client client, Graphics2D graphics, Point center, Color color)
	{
		renderMinimapRect(client, graphics, center, color, 1.0);
	}

	// The scale overloads draw a sailing path's half-size dots
	public static void renderMinimapRect(Client client, Graphics2D graphics, Point center, Color color, double scale)
	{
		double angle = client.getCameraYawTarget() * Perspective.UNIT14;
		double tileSize = client.getMinimapZoom() * scale;
		int x = (int) Math.round(center.getX() - tileSize / 2);
		int y = (int) Math.round(center.getY() - tileSize / 2);
		int width = (int) Math.round(tileSize);
		int height = (int) Math.round(tileSize);
		graphics.setColor(color);
		graphics.rotate(angle, center.getX(), center.getY());
		graphics.fillRect(x, y, width, height);
		graphics.rotate(-angle, center.getX(), center.getY());
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!settings.display().drawMinimap() || plugin.getActiveSearch() == null)
		{
			return null;
		}

		Shape minimapClipArea = plugin.getMinimapClipArea();
		if (minimapClipArea == null)
		{
			return null;
		}
		else
		{
			graphics.setClip(minimapClipArea);
		}
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);

		java.util.List<PathStep> pathPoints = plugin.getActiveSearch().getPath();
		// On a boat the path sails the boat's headings, with a point a few tiles apart at the end of each move: half-size
		// blue dots
		boolean sailing = plugin.isSailing();
		Color pathColor = sailing && !plugin.isPathUnreachable()
			? ShortestPathPlugin.COLOUR_SAILING_PATH : plugin.getPathColor();
		for (PathStep point : pathPoints)
		{
			int pathPoint = point.getPackedPosition();
			if (WorldPointUtil.unpackWorldPlane(pathPoint) != client.getTopLevelWorldView().getPlane())
			{
				continue;
			}

			drawOnMinimap(graphics, pathPoint, pathColor, sailing ? 0.5 : 1.0);
		}
		for (int target : plugin.getActiveSearch().getTargets().points())
		{
			if (!pathPoints.isEmpty() && target != pathPoints.get(pathPoints.size() - 1).getPackedPosition())
			{
				drawOnMinimap(graphics, target, settings.display().colourPathCalculating());
			}
		}

		return null;
	}

	private void drawOnMinimap(Graphics2D graphics, int location, Color color)
	{
		drawOnMinimap(graphics, location, color, 1.0);
	}

	private void drawOnMinimap(Graphics2D graphics, int location, Color color, double scale)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));

			if (lp == null)
			{
				continue;
			}

			Point posOnMinimap = Perspective.localToMinimap(client, lp);

			if (posOnMinimap == null)
			{
				continue;
			}

			renderMinimapRect(client, graphics, posOnMinimap, color, scale);
		}
	}
}

package shortestpath.overlay;

import com.google.inject.Inject;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Stroke;
import java.awt.geom.Line2D;
import java.awt.geom.Path2D;
import java.awt.geom.Rectangle2D;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.Set;

import net.runelite.api.Client;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Point;
import net.runelite.api.Tile;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import shortestpath.PrimitiveIntHashMap;
import shortestpath.PrimitiveIntList;
import shortestpath.ShortestPathPlugin;
import shortestpath.TileCounter;
import shortestpath.TileStyle;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.AStarPathfinder;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.TransportAvailability;
import shortestpath.poh.PohService;
import shortestpath.requirement.BankPickupRequirements;
import shortestpath.transport.Transport;
import shortestpath.requirement.TransportEligibility;
import shortestpath.settings.Settings;

public class PathTileOverlay extends Overlay
{
	private static final int TRANSPORT_LABEL_GAP = 3;
	private static final long TRACER_STEP_MS = 200L;
	private static final int TRACER_WINDOW_TILES = 60;
	private static final int SPRITE_STRIDE = 10;
	private static final int SPRITE_ITEM_ID = ItemID.GAUNTLET_ESCAPE_CRYSTAL;
	private final Client client;
	private final ShortestPathPlugin plugin;
	private final ItemManager itemManager;
	private final Settings settings;
	private int playerTileLabelOffset = 0;
	private boolean teleportPulseDrawn = false;

	@Inject
	public PathTileOverlay(Client client, ShortestPathPlugin plugin, ItemManager itemManager, Settings settings)
	{
		this.client = client;
		this.plugin = plugin;
		this.itemManager = itemManager;
		this.settings = settings;
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_LOW);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	private static final Color COLOR_AVAILABLE = Color.WHITE;
	private static final Color COLOR_UNAVAILABLE = Color.ORANGE;
	private static final Color COLOR_CLICK_POINT = new Color(255, 0, 255, 150);

	private void renderTransports(Graphics2D graphics)
	{
		PrimitiveIntHashMap<Transport[]> allTransports = plugin.getAllDisplayTransports();
		PrimitiveIntHashMap<Transport[]> availableTransports = plugin.getTransports();

		for (int a : allTransports.keys())
		{
			if (a == Transport.UNDEFINED_ORIGIN)
			{
				continue; // skip teleports
			}

			Point ca = tileCenter(a);

			if (ca == null)
			{
				continue;
			}

			boolean drawStart = false;
			StringBuilder s = new StringBuilder();
			Transport[] availableAtOrigin = availableTransports.getOrDefault(a, TransportAvailability.EMPTY_TRANSPORTS);

			for (Transport b : allTransports.getOrDefault(a, TransportAvailability.EMPTY_TRANSPORTS))
			{
				if (b == null || (b.getType() != null && b.getType().isTeleport()))
				{
					continue; // skip teleports
				}

				boolean isAvailable = Arrays.asList(availableAtOrigin).contains(b);
				graphics.setColor(isAvailable ? COLOR_AVAILABLE : COLOR_UNAVAILABLE);

				int destination = b.getDestination();
				if (destination == Transport.UNDEFINED_DESTINATION)
				{
					continue;
				}
				Point cb = tileCenter(destination);
				if (cb != null)
				{
					graphics.drawLine(ca.getX(), ca.getY(), cb.getX(), cb.getY());
					drawStart = true;
				}
				if (WorldPointUtil.unpackWorldPlane(destination) > WorldPointUtil.unpackWorldPlane(a))
				{
					s.append("+");
				}
				else if (WorldPointUtil.unpackWorldPlane(destination) < WorldPointUtil.unpackWorldPlane(a))
				{
					s.append("-");
				}
				else
				{
					s.append("=");
				}
			}

			if (drawStart)
			{
				drawTile(graphics, a, settings.display().colourTransports(), -1, true);
			}

			graphics.setColor(Color.WHITE);
			graphics.drawString(s.toString(), ca.getX(), ca.getY());
		}
	}

	private void renderCollisionMap(Graphics2D graphics)
	{
		CollisionMap map = plugin.getMap();
		for (Tile[] row : client.getTopLevelWorldView().getScene().getTiles()[client.getTopLevelWorldView().getPlane()])
		{
			for (Tile tile : row)
			{
				if (tile == null)
				{
					continue;
				}

				Polygon tilePolygon = Perspective.getCanvasTilePoly(client, tile.getLocalLocation());

				if (tilePolygon == null)
				{
					continue;
				}

				int location = WorldPointUtil.fromLocalInstance(client, tile.getLocalLocation());
				int x = WorldPointUtil.unpackWorldX(location);
				int y = WorldPointUtil.unpackWorldY(location);
				int z = WorldPointUtil.unpackWorldPlane(location);

				String s = (!map.n(x, y, z) ? "n" : "") +
					(!map.s(x, y, z) ? "s" : "") +
					(!map.e(x, y, z) ? "e" : "") +
					(!map.w(x, y, z) ? "w" : "");

				if (map.isBlocked(x, y, z))
				{
					graphics.setColor(settings.display().colourCollisionMap());
					graphics.fill(tilePolygon);
				}
				if (!s.isEmpty() && !s.equals("nsew"))
				{
					graphics.setColor(Color.WHITE);
					int stringX = (int) (tilePolygon.getBounds().getCenterX()
						- graphics.getFontMetrics().getStringBounds(s, graphics).getWidth() / 2);
					int stringY = (int) tilePolygon.getBounds().getCenterY();
					graphics.drawString(s, stringX, stringY);
				}
			}
		}
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		playerTileLabelOffset = 0;
		teleportPulseDrawn = false;

		if (settings.display().drawTransports())
		{
			renderTransports(graphics);
		}

		if (settings.display().drawCollisionMap())
		{
			renderCollisionMap(graphics);
		}

		if (settings.display().drawTiles() && plugin.getActiveSearch() != null && plugin.getActiveSearch().getPath() != null)
		{
			Color colorCalculating = new Color(
				settings.display().colourPathCalculating().getRed(),
				settings.display().colourPathCalculating().getGreen(),
				settings.display().colourPathCalculating().getBlue(),
				settings.display().colourPathCalculating().getAlpha() / 2);
			Color pathColor = plugin.getPathColor();
			Color color = new Color(
				pathColor.getRed(),
				pathColor.getGreen(),
				pathColor.getBlue(),
				pathColor.getAlpha() / 2);

			List<PathStep> path = plugin.getActiveSearch().getPath();
			int counter = 0;
			if (plugin.isSailing())
			{
				// On a boat the path sails the boat's headings: lines along each heading it holds, drawn through the
				// spot within each tile where the boat actually sits
				Color sailingColor = plugin.isPathUnreachable() ? plugin.getPathColor() : ShortestPathPlugin.COLOUR_SAILING_PATH;
				for (int i = 1; i < path.size(); i++)
				{
					drawOffsetLine(graphics, path.get(i - 1).getPackedPosition(), path.get(i).getPackedPosition(),
						plugin.getSailingPivotX(), plugin.getSailingPivotY(), sailingColor);
					drawTransportInfo(graphics, path.get(i - 1), path.get(i), path, i - 1);
				}
				drawUnreachedTargets(graphics, path, colorCalculating, true);
			}
			else if (TileStyle.LINES.equals(settings.display().pathStyle()) || TileStyle.ARROW_LINE.equals(settings.display().pathStyle()))
			{
				boolean arrows = TileStyle.ARROW_LINE.equals(settings.display().pathStyle());
				for (int i = 1; i < path.size(); i++)
				{
					PathStep currentStep = path.get(i - 1);
					PathStep nextStep = path.get(i);
					// Arrowheads only where they carry information: at direction changes and the end.
					boolean head = arrows && (i == path.size() - 1
						|| directionChanges(currentStep.getPackedPosition(), nextStep.getPackedPosition(),
							path.get(i + 1).getPackedPosition()));
					drawLine(graphics, currentStep.getPackedPosition(), nextStep.getPackedPosition(), color,
						1 + counter++, head);
					drawTransportInfo(graphics, currentStep, nextStep, path, i - 1);
				}
			}
			else if (TileStyle.TURN_MARKERS.equals(settings.display().pathStyle()))
			{
				for (int i = 0; i < path.size(); i++)
				{
					PathStep currentStep = path.get(i);
					int pathPoint = currentStep.getPackedPosition();
					int pathX = WorldPointUtil.unpackWorldX(pathPoint);
					int pathY = WorldPointUtil.unpackWorldY(pathPoint);
					// Markers only where the route changes direction, plus both endpoints.
					boolean marker = i == 0 || i == path.size() - 1
						|| directionChanges(path.get(i - 1).getPackedPosition(), pathPoint,
							path.get(i + 1).getPackedPosition());
					// Skip markers inside POH (no collision data, tiles render at wrong positions)
					if (marker && !PohService.isInsidePoh(pathX, pathY))
					{
						drawTile(graphics, pathPoint, color, counter, true);
						drawTurnMarkerGlyph(graphics, path, i);
					}
					counter++;
					drawTransportInfo(graphics, currentStep, plugin.nextPathStep(path, i), path, i);
				}
				drawUnreachedTargets(graphics, path, colorCalculating, true);
			}
			else if (TileStyle.TRACER.equals(settings.display().pathStyle()))
			{
				// Faint polyline under the moving marker so the full route stays readable
				// without looking identical to LINES.
				Color tracerLineColour = new Color(color.getRed(), color.getGreen(), color.getBlue(),
					color.getAlpha() / 2);
				for (int i = 1; i < path.size(); i++)
				{
					PathStep currentStep = path.get(i - 1);
					PathStep nextStep = path.get(i);
					drawLine(graphics, currentStep.getPackedPosition(), nextStep.getPackedPosition(), tracerLineColour,
						1 + counter++, false);
					drawTransportInfo(graphics, currentStep, nextStep, path, i - 1);
				}
				if (!path.isEmpty())
				{
					// One marker walks the path on a wall-clock phase — the overlay repaints
					// every frame, so no tick subscription is needed (the drawTeleportPulse idiom).
					// The window caps the walk to the slice near the player: over a full-length
					// path the marker sits off-screen most of the time on long routes.
					int tracerWindow = Math.min(path.size(), TRACER_WINDOW_TILES);
					int tracerIndex = (int) ((System.currentTimeMillis() / TRACER_STEP_MS) % tracerWindow);
					int tracerPoint = path.get(tracerIndex).getPackedPosition();
					int tracerX = WorldPointUtil.unpackWorldX(tracerPoint);
					int tracerY = WorldPointUtil.unpackWorldY(tracerPoint);
					if (!PohService.isInsidePoh(tracerX, tracerY))
					{
						Point current = tileCenter(tracerPoint);
						if (current != null)
						{
							Color previousColour = graphics.getColor();
							graphics.setColor(pathColor);
							int radius = 6;
							graphics.fillOval(current.getX() - radius, current.getY() - radius, radius * 2, radius * 2);
							if (tracerIndex + 1 < path.size())
							{
								Point next = tileCenter(path.get(tracerIndex + 1).getPackedPosition());
								if (next != null)
								{
									ArrowHead.draw(graphics, current.getX(), current.getY(), next.getX(), next.getY(), 10);
								}
							}
							graphics.setColor(previousColour);
						}
					}
				}
				drawUnreachedTargets(graphics, path, colorCalculating, true);
			}
			else if (TileStyle.SPRITE_MARKERS.equals(settings.display().pathStyle()))
			{
				for (int i = 0; i < path.size(); i++)
				{
					PathStep currentStep = path.get(i);
					int pathPoint = currentStep.getPackedPosition();
					int pathX = WorldPointUtil.unpackWorldX(pathPoint);
					int pathY = WorldPointUtil.unpackWorldY(pathPoint);
					// Bounded stride — a sprite every SPRITE_STRIDE tiles plus the destination,
					// never one sprite per tile (per-tile sprite density is too heavy).
					boolean marker = i % SPRITE_STRIDE == 0 || i == path.size() - 1;
					// Skip sprites inside POH (no collision data, tiles render at wrong positions)
					if (marker && !PohService.isInsidePoh(pathX, pathY))
					{
						Point p = tileCenter(pathPoint);
						if (p != null)
						{
							BufferedImage sprite = itemManager.getImage(SPRITE_ITEM_ID);
							if (sprite != null)
							{
								if (i == path.size() - 1)
								{
									// The destination reads as the endpoint: larger sprite plus a ring.
									int dw = sprite.getWidth() * 3 / 2;
									int dh = sprite.getHeight() * 3 / 2;
									graphics.drawImage(sprite, p.getX() - dw / 2, p.getY() - dh / 2, dw, dh, null);
									int radius = Math.max(dw, dh) / 2 + 3;
									Color previousColour = graphics.getColor();
									graphics.setColor(settings.display().colourText());
									graphics.drawOval(p.getX() - radius, p.getY() - radius, radius * 2, radius * 2);
									graphics.setColor(previousColour);
								}
								else
								{
									graphics.drawImage(sprite, p.getX() - sprite.getWidth() / 2,
										p.getY() - sprite.getHeight() / 2, null);
								}
							}
							drawCounter(graphics, p.getX(), p.getY(), counter);
						}
					}
					counter++;
					drawTransportInfo(graphics, currentStep, plugin.nextPathStep(path, i), path, i);
				}
				drawUnreachedTargets(graphics, path, colorCalculating, true);
			}
			else
			{
				boolean showTiles = TileStyle.TILES.equals(settings.display().pathStyle());
				for (int i = 0; i < path.size(); i++)
				{
					// Skip drawing tiles inside POH (no collision data, tiles render at wrong positions)
					PathStep currentStep = path.get(i);
					int pathPoint = currentStep.getPackedPosition();
					int pathX = WorldPointUtil.unpackWorldX(pathPoint);
					int pathY = WorldPointUtil.unpackWorldY(pathPoint);
					if (!PohService.isInsidePoh(pathX, pathY))
					{
						drawTile(graphics, pathPoint, color, counter, showTiles);
					}
					counter++;
					drawTransportInfo(graphics, currentStep, plugin.nextPathStep(path, i), path, i);
				}
				drawUnreachedTargets(graphics, path, colorCalculating, showTiles);
			}

			if (plugin.isPathUnreachable() && settings.display().showUnreachableText())
			{
				playerTileLabelOffset += drawLabelOnPlayerTile(graphics, settings.display().unreachableText(), playerTileLabelOffset);
			}
			String missingItems = plugin.getMissingTargetItemsText();
			if (missingItems != null)
			{
				playerTileLabelOffset += drawLabelOnPlayerTile(graphics, missingItems, playerTileLabelOffset);
			}
		}

		// Click points without the path are floating marks, so they follow the same drawTiles
		// gate and POH skip as the path tiles.
		if (settings.display().drawTiles() && settings.display().drawClickPoints() && plugin.getActiveSearch() instanceof AStarPathfinder)
		{
			AStarPathfinder aStar = (AStarPathfinder) plugin.getActiveSearch();
			if (aStar.isDone() && !aStar.isShowingProvisionalPath())
			{
				List<PathStep> path = aStar.getPath();
				for (int index : aStar.getClickPoints())
				{
					int point = path.get(index).getPackedPosition();
					if (!PohService.isInsidePoh(WorldPointUtil.unpackWorldX(point),
						WorldPointUtil.unpackWorldY(point)))
					{
						drawTile(graphics, point, COLOR_CLICK_POINT, -1, true);
					}
				}
			}
		}

		return null;
	}

	private Point tileCenter(int b)
	{
		if (b == WorldPointUtil.UNDEFINED || client == null)
		{
			return null;
		}

		// Map the canonical point into the viewed instance before checking the
		// plane — inside an instance (e.g. a POH) the stored template plane can
		// differ from the instance plane without being on a different floor.
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, b);
		for (int i = 0; i < points.size(); i++)
		{
			int point = points.get(i);
			if (point == WorldPointUtil.UNDEFINED
				|| WorldPointUtil.unpackWorldPlane(point) != client.getTopLevelWorldView().getPlane())
			{
				continue;
			}

			LocalPoint lp = WorldPointUtil.toLocalPoint(client, point);
			if (lp == null)
			{
				continue;
			}

			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly == null)
			{
				continue;
			}

			int cx = poly.getBounds().x + poly.getBounds().width / 2;
			int cy = poly.getBounds().y + poly.getBounds().height / 2;
			return new Point(cx, cy);
		}

		return null;
	}

	private void drawTile(Graphics2D graphics, int location, Color color, int counter, boolean draw)
	{
		if (client == null)
		{
			return;
		}

		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			int point = points.get(i);
			if (point == WorldPointUtil.UNDEFINED)
			{
				continue;
			}

			LocalPoint lp = WorldPointUtil.toLocalPoint(client, point);
			if (lp == null)
			{
				continue;
			}

			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly == null)
			{
				continue;
			}

			if (draw)
			{
				graphics.setColor(color);
				graphics.fill(poly);
			}

			drawCounter(graphics, poly.getBounds().getCenterX(), poly.getBounds().getCenterY(), counter);
		}
	}

	private void drawUnreachedTargets(Graphics2D graphics, List<PathStep> path, Color colorCalculating, boolean draw)
	{
		for (int target : plugin.getActiveSearch().getTargets().points())
		{
			if (!path.isEmpty() && target != path.get(path.size() - 1).getPackedPosition())
			{
				drawTile(graphics, target, colorCalculating, -1, draw);
			}
		}
	}

	private static boolean directionChanges(int previous, int current, int next)
	{
		int dx1 = WorldPointUtil.unpackWorldX(current) - WorldPointUtil.unpackWorldX(previous);
		int dy1 = WorldPointUtil.unpackWorldY(current) - WorldPointUtil.unpackWorldY(previous);
		int dx2 = WorldPointUtil.unpackWorldX(next) - WorldPointUtil.unpackWorldX(current);
		int dy2 = WorldPointUtil.unpackWorldY(next) - WorldPointUtil.unpackWorldY(current);
		return dx1 != dx2 || dy1 != dy2;
	}

	// Turn markers get a glyph inside the fill: an arrowhead along the outgoing
	// segment so the marker reads as "turn this way", a ring for the destination
	// which has no outgoing segment.
	private void drawTurnMarkerGlyph(Graphics2D graphics, List<PathStep> path, int index)
	{
		Point here = tileCenter(path.get(index).getPackedPosition());
		if (here == null)
		{
			return;
		}
		Color previousColour = graphics.getColor();
		graphics.setColor(settings.display().colourText());
		if (index + 1 < path.size())
		{
			Point next = tileCenter(path.get(index + 1).getPackedPosition());
			if (next != null)
			{
				ArrowHead.draw(graphics, here.getX(), here.getY(), next.getX(), next.getY(), 8);
			}
		}
		else
		{
			int radius = 5;
			graphics.drawOval(here.getX() - radius, here.getY() - radius, radius * 2, radius * 2);
		}
		graphics.setColor(previousColour);
	}

	private void drawLine(Graphics2D graphics, int startLoc, int endLoc, Color color, int counter, boolean arrowHead)
	{
		PrimitiveIntList starts = WorldPointUtil.toLocalInstance(client, startLoc);
		PrimitiveIntList ends = WorldPointUtil.toLocalInstance(client, endLoc);

		if (starts.isEmpty() || ends.isEmpty())
		{
			return;
		}

		int start = starts.get(0);
		int end = ends.get(0);

		final int z = client.getTopLevelWorldView().getPlane();
		if (WorldPointUtil.unpackWorldPlane(start) != z)
		{
			return;
		}

		LocalPoint lpStart = WorldPointUtil.toLocalPoint(client, start);
		LocalPoint lpEnd = WorldPointUtil.toLocalPoint(client, end);

		if (lpStart == null || lpEnd == null)
		{
			return;
		}

		final int startHeight = Perspective.getTileHeight(client, lpStart, z);
		final int endHeight = Perspective.getTileHeight(client, lpEnd, z);

		Point p1 = Perspective.localToCanvas(client, lpStart.getX(), lpStart.getY(), startHeight);
		Point p2 = Perspective.localToCanvas(client, lpEnd.getX(), lpEnd.getY(), endHeight);

		if (p1 == null || p2 == null)
		{
			return;
		}

		Line2D.Double line = new Line2D.Double(p1.getX(), p1.getY(), p2.getX(), p2.getY());

		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(4));
		graphics.draw(line);
		if (arrowHead)
		{
			ArrowHead.draw(graphics, p1.getX(), p1.getY(), p2.getX(), p2.getY(), 12);
		}

		if (counter == 1)
		{
			drawCounter(graphics, p1.getX(), p1.getY(), 0);
		}
		drawCounter(graphics, p2.getX(), p2.getY(), counter);
	}

	// A line between two tiles, shifted from the tile centres by (offsetX, offsetY) local units
	private void drawOffsetLine(Graphics2D graphics, int startLoc, int endLoc, int offsetX, int offsetY, Color color)
	{
		// In an instance the path is in template coordinates, as for the walking path's lines
		PrimitiveIntList starts = WorldPointUtil.toLocalInstance(client, startLoc);
		PrimitiveIntList ends = WorldPointUtil.toLocalInstance(client, endLoc);
		if (starts.isEmpty() || ends.isEmpty())
		{
			return;
		}

		final int z = client.getTopLevelWorldView().getPlane();
		if (WorldPointUtil.unpackWorldPlane(starts.get(0)) != z)
		{
			return;
		}

		LocalPoint start = WorldPointUtil.toLocalPoint(client, starts.get(0));
		LocalPoint end = WorldPointUtil.toLocalPoint(client, ends.get(0));
		if (start == null || end == null)
		{
			return;
		}
		start = new LocalPoint(start.getX() + offsetX, start.getY() + offsetY, start.getWorldView());
		end = new LocalPoint(end.getX() + offsetX, end.getY() + offsetY, end.getWorldView());

		Point p1 = Perspective.localToCanvas(client, start.getX(), start.getY(), Perspective.getTileHeight(client, start, z));
		Point p2 = Perspective.localToCanvas(client, end.getX(), end.getY(), Perspective.getTileHeight(client, end, z));
		if (p1 == null || p2 == null)
		{
			return;
		}

		graphics.setColor(color);
		graphics.setStroke(new BasicStroke(4));
		graphics.draw(new Line2D.Double(p1.getX(), p1.getY(), p2.getX(), p2.getY()));
	}

	private void drawCounter(Graphics2D graphics, double x, double y, int counter)
	{
		if (counter >= 0 && !TileCounter.DISABLED.equals(settings.display().showTileCounter()))
		{
			int n = settings.display().tileCounterStep() > 0 ? settings.display().tileCounterStep() : 1;
			int s = plugin.getActiveSearch().getPath().size();
			if ((counter % n != 0) && (s != (counter + 1)))
			{
				return;
			}
			if (TileCounter.REMAINING.equals(settings.display().showTileCounter()))
			{
				counter = s - counter - 1;
			}
			if (n > 1 && counter == 0)
			{
				return;
			}
			String counterText = Integer.toString(counter);
			graphics.setColor(settings.display().colourText());
			graphics.drawString(
				counterText,
				(int) (x - graphics.getFontMetrics().getStringBounds(counterText, graphics).getWidth() / 2), (int) y);
		}
	}

	private int drawLabelAtCanvasPoint(Graphics2D graphics, Point point, String text, int verticalOffset)
	{
		if (point == null || text == null || text.isEmpty())
		{
			return 0;
		}

		double height = drawLabel(graphics, point, text, verticalOffset);

		return (int) height + TRANSPORT_LABEL_GAP;
	}

	private int drawLabelAtPackedLocation(Graphics2D graphics, int location, String text, int verticalOffset)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));
			if (lp == null)
			{
				continue;
			}

			Point p = Perspective.localToCanvas(client, lp, client.getTopLevelWorldView().getPlane());
			if (p == null)
			{
				continue;
			}

			verticalOffset += drawLabelAtCanvasPoint(graphics, p, text, verticalOffset);
		}
		return verticalOffset;
	}

	/**
	 * A pulsing "teleport from here" highlight: diamond rings expanding out from the tile and fading,
	 * looping. Drawn every frame (scene overlays repaint continuously) off wall-clock time, so the motion
	 * stays smooth regardless of game ticks. Anchored to the tile the player casts from — for a
	 * cast-from-anywhere teleport that sits under the player, drawing the eye to "teleport now".
	 */
	private void drawTeleportPulse(Graphics2D graphics, int location)
	{
		PrimitiveIntList points = WorldPointUtil.toLocalInstance(client, location);
		for (int i = 0; i < points.size(); i++)
		{
			LocalPoint lp = WorldPointUtil.toLocalPoint(client, points.get(i));
			if (lp == null)
			{
				continue;
			}
			Polygon poly = Perspective.getCanvasTilePoly(client, lp);
			if (poly == null || poly.npoints == 0)
			{
				continue;
			}
			final double cx = poly.getBounds().getCenterX();
			final double cy = poly.getBounds().getCenterY();

			final long period = 1400L;
			final int rings = 2;
			final Color base = settings.display().colourTeleportPulse();
			final Color previousColour = graphics.getColor();
			final Stroke previousStroke = graphics.getStroke();
			graphics.setStroke(new BasicStroke(2.2f));
			for (int r = 0; r < rings; r++)
			{
				// Stagger the two rings by half a period so one is always small/bright while the other
				// is large/faint — a continuous outward pulse.
				double phase = ((System.currentTimeMillis() + (long) (r * period / (double) rings)) % period)
					/ (double) period;
				double scale = 1.0 + phase * 2.6;
				int alpha = (int) Math.round(170 * (1.0 - phase));
				if (alpha <= 0)
				{
					continue;
				}
				Path2D ring = new Path2D.Double();
				for (int v = 0; v < poly.npoints; v++)
				{
					double x = cx + (poly.xpoints[v] - cx) * scale;
					double y = cy + (poly.ypoints[v] - cy) * scale;
					if (v == 0)
					{
						ring.moveTo(x, y);
					}
					else
					{
						ring.lineTo(x, y);
					}
				}
				ring.closePath();
				graphics.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), alpha));
				graphics.draw(ring);
			}
			graphics.setColor(previousColour);
			graphics.setStroke(previousStroke);
		}
	}

	private double drawLabel(Graphics2D graphics, Point point, String text, int verticalOffset)
	{
		Rectangle2D textBounds = graphics.getFontMetrics().getStringBounds(text, graphics);
		double height = textBounds.getHeight();
		int x = (int) (point.getX() - textBounds.getWidth() / 2);
		int y = (int) (point.getY() - height) - verticalOffset;
		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(settings.display().colourText());
		graphics.drawString(text, x, y);
		return height;
	}

	private int drawLabelOnPlayerTile(Graphics2D graphics, String text, int verticalOffset)
	{
		if (client.getLocalPlayer() == null)
		{
			return 0;
		}

		Point playerPoint = Perspective.localToCanvas(client, client.getLocalPlayer().getLocalLocation(), client.getTopLevelWorldView().getPlane());
		return drawLabelAtCanvasPoint(graphics, playerPoint, text, verticalOffset);
	}

	private void drawTransportInfo(Graphics2D graphics, PathStep currentStep, PathStep nextStep, List<PathStep> path, int pathIndex)
	{
		int location = currentStep.getPackedPosition();
		int lx = WorldPointUtil.unpackWorldX(location);
		int ly = WorldPointUtil.unpackWorldY(location);
		// Inside an instance the stored template plane can differ from the
		// viewed instance plane without being on a different floor (a POH with
		// a basement shifts its ground floor up a plane), so POH steps skip the
		// plane check here; every draw below re-maps the step through
		// toLocalInstance and plane-checks the mapped point instead.
		if (nextStep == null ||
			(WorldPointUtil.unpackWorldPlane(location) != client.getTopLevelWorldView().getPlane() &&
				!PohService.isInsidePoh(lx, ly)
			))
		{
			return;
		}

		// Sailing: teleports are suppressed while aboard a boat. When the path is
		// unreachable as a result, show a one-time hint on the player tile.
		if (settings.display().showTransportInfo() && pathIndex == 0 && plugin.getPathfinderConfig().isOnSailingBoat()
			&& plugin.getActiveSearch().isDone() && plugin.isPathUnreachable())
		{
			playerTileLabelOffset = drawLabelOnPlayerTile(graphics,
				"Disembark the boat to resume pathfinding", playerTileLabelOffset);
			return;
		}

		if (plugin.isPathUnreachable() || !plugin.getActiveSearch().isDone())
		{
			return;
		}
		int locationEnd = nextStep.getPackedPosition();
		Set<Transport> candidateTransports = plugin.transportsForEdge(currentStep, nextStep);

		// Teleports ("use this item/spell") get a pulsing highlight on the tile you cast
		// from. Only the first teleport edge of the path pulses — the next "teleport
		// now" moment — and the pulse is independent of the transport info labels.
		if (settings.display().showTeleportPulse() && !teleportPulseDrawn)
		{
			for (Transport transport : candidateTransports)
			{
				if (transport.getType() != null && transport.getType().isTeleport())
				{
					drawTeleportPulse(graphics, location);
					teleportPulseDrawn = true;
					break;
				}
			}
		}

		if (!settings.display().showTransportInfo())
		{
			return;
		}

		// Workaround for weird pathing inside PoH to instead show info on the player
		// tile
		Player player = client.getLocalPlayer();
		if (player == null)
		{
			return;
		}
		LocalPoint playerLocalPoint = player.getLocalLocation();
		WorldPoint playerWorldPoint = player.getWorldLocation();
		if (client.getTopLevelWorldView().isInstance())
		{
			playerWorldPoint = WorldPoint.fromLocalInstance(client, playerLocalPoint);
		}
		int playerPackedPoint = WorldPointUtil.packWorldPoint(playerWorldPoint);
		int px = WorldPointUtil.unpackWorldX(playerPackedPoint);
		int py = WorldPointUtil.unpackWorldY(playerPackedPoint);
		int tx = WorldPointUtil.unpackWorldX(location);
		int ty = WorldPointUtil.unpackWorldY(location);
		boolean transportAndPlayerInsidePoh = PohService.isInsidePoh(tx, ty)
			&& PohService.isInsidePoh(px, py);

		// When inside POH, only show the POH exit info once (not per-transport)
		if (transportAndPlayerInsidePoh)
		{
			// No floor check here: path steps carry planes from the generic POH
			// template (the landing is modelled at plane 0), while the player maps
			// back at whatever template plane their actual house chunks occupy
			// (e.g. plane 2 for a ground floor) — the two don't correspond, so any
			// plane comparison would suppress the hint in real houses.
			String pohExitInfo = plugin.getPohExitInfo(location, path, pathIndex - 1);

			if (pohExitInfo == null)
			{
				return;
			}
			String text = "Exit: " + pohExitInfo;

			Point p = Perspective.localToCanvas(client, playerLocalPoint, client.getTopLevelWorldView().getPlane());
			if (p == null)
			{
				return;
			}

			drawLabel(graphics, p, text, 0);
			return;
		}

		// Check if this is a bank step and items need to be picked up
		{
			BankPickupRequirements.BankPickupResult bankPickup = plugin.getPathfinderConfig().getBankPickup(path, pathIndex, plugin.getActiveSearch());
			if (bankPickup != null && !bankPickup.phrases.isEmpty())
			{
				List<String> bankPickupItems = bankPickup.phrases;
				String pickupText = "Pick up: " + String.join(", ", bankPickupItems);
				playerTileLabelOffset = drawLabelAtPackedLocation(graphics, location, pickupText, playerTileLabelOffset);

				// By default, bank pickup info replaces the default transport hint text;
				// enable the option to show both
				if (!settings.display().showBankPickupInfo())
				{
					return;
				}
			}
		}

		// Only show transports the player can currently use; fall back to all if none are usable.
		// A missing snapshot (pre-login or off the client thread) means no filtering —
		// the same "show all" the empty-usable fallback below produces anyway.
		TransportEligibility eligibility = plugin.getPathfinderConfig().getEligibility();
		List<Transport> usableTransports = new ArrayList<>();
		if (eligibility != null)
		{
			for (Transport t : candidateTransports)
			{
				if (eligibility.satisfiedByPlayer(t))
				{
					usableTransports.add(t);
				}
			}
		}
		Collection<Transport> transportsToShow = usableTransports.isEmpty() ? candidateTransports : usableTransports;

		for (Transport transport : transportsToShow)
		{
			String text = plugin.formatTransportDisplay(transport);
			if (text == null || text.isEmpty())
			{
				continue;
			}

			// Check if this transport goes to POH - if so, look ahead to find the exit
			// transport
			String pohExitInfo = plugin.getPohExitInfo(locationEnd, path, pathIndex);
			if (pohExitInfo != null)
			{
				text = text + " (Exit: " + pohExitInfo + ")";
			}

			playerTileLabelOffset = drawLabelAtPackedLocation(graphics, location, text, playerTileLabelOffset);
		}
	}
}

