package shortestpath.pathfinder;

import java.util.List;
import shortestpath.requirement.model.ItemRequirement;

/**
 * The target a finished route reaches, and whether the player will hold its items there. Immutable.
 */
public final class Arrival
{
	private final Target target;
	private final TargetStatus status;
	private final List<ItemRequirement> missingItems;

	public Arrival(Target target, TargetStatus status, List<ItemRequirement> missingItems)
	{
		this.target = target;
		this.status = status;
		this.missingItems = List.copyOf(missingItems);
	}

	public Target getTarget()
	{
		return target;
	}

	/**
	 * How the player comes to hold the target's items: {@link TargetStatus#CARRIED} for a target
	 * that needs none.
	 */
	public TargetStatus getStatus()
	{
		return status;
	}

	/**
	 * For an {@link TargetStatus#UNKNOWN} target, the item groups found neither carried nor in the
	 * bank; empty otherwise.
	 */
	public List<ItemRequirement> getMissingItems()
	{
		return missingItems;
	}

	/** Whether the route goes through a bank to pick up the target's items. */
	public boolean picksUpItemsFromBank()
	{
		return status == TargetStatus.BANK;
	}
}

package shortestpath.pathfinder;

import java.util.List;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import shortestpath.items.ItemStateService;
import shortestpath.requirement.BankPickupRequirements.BankPickupResult;
import shortestpath.requirement.model.TransportItems;

/**
 * The bank-pickup projection for the active path: which items a route's
 * target needs picked up when the path passes a bank. Lives on the engine
 * side — it reads path state and the item-state service — so the item-state
 * service never pulls path types in. Cached on
 * (item-state revision, path identity, step index, search identity): the
 * revision covers container/varbit events, the search identity covers
 * restarts that reuse a path, and a search still awaiting its result
 * recomputes each call since the target's items are not yet known.
 */
public class BankPickupProjection
{
	private BankPickupResult cache;
	private List<PathStep> cachePath;
	private int cacheIndex = -1;
	private ActiveSearch cacheSearch;
	private int cacheRevision = -1;
	private boolean cachePending;

	public BankPickupResult get(Client client, ItemStateService itemState, PathfinderConfig config,
		List<PathStep> path, int pathIndex, ActiveSearch search)
	{
		Set<Integer> bankLocations = config.getDestinations("bank");
		ItemContainer bank = itemState.getBank();
		if (bank == null || bankLocations == null
				|| path == null || pathIndex < 0 || pathIndex >= path.size())
		{
			return null;
		}
		PathfinderResult result = search == null ? null : search.getResult();
		// The target's items are only known once the search has its result, which appears just
		// after the final path: keep recomputing until then.
		boolean pending = search != null && result == null;
		if (!cachePending && !pending && itemState.itemStateRevision() == cacheRevision
			&& path == cachePath && pathIndex == cacheIndex && search == cacheSearch)
		{
			return cache;
		}
		cacheRevision = itemState.itemStateRevision();
		cachePath = path;
		cacheIndex = pathIndex;
		cacheSearch = search;
		cachePending = pending;
		cache = BankPickupResult.compute(
				client, bank, config, bankLocations, path, pathIndex,
				itemsToPickUp(result));
		return cache;
	}

	/** The items a route's target needs from the bank, or {@code null} when it picks none up. */
	private static TransportItems itemsToPickUp(PathfinderResult result)
	{
		Arrival arrival = result == null ? null : result.getArrival();
		return arrival != null && arrival.picksUpItemsFromBank() ? arrival.getTarget().getRequiredItems() : null;
	}
}

package shortestpath.pathfinder;

import shortestpath.PrimitiveIntList;
import shortestpath.WorldPointUtil;
import shortestpath.transport.Transport;

public class CollisionMap
{
	// Enum.values() makes copies every time which hurts performance in the hotpath
	private static final OrdinalDirection[] ORDINAL_VALUES = OrdinalDirection.values();

	private final SplitFlagMap collisionData;
	// This is only safe if pathfinding is single-threaded. Holds the ids of the neighbour nodes
	// appended to the NodeGraph during the most recent getNeighbors call.
	private final PrimitiveIntList neighbors = new PrimitiveIntList(16);
	private final boolean[] traversable = new boolean[8];

	public CollisionMap(SplitFlagMap collisionData)
	{
		this.collisionData = collisionData;
	}

	/**
	 * The region grid bounds to scan when enumerating every collision tile (e.g.
	 * {@link shortestpath.pathfinder.astar.RoutingStaticBuilder}). Delegates to
	 * {@link SplitFlagMap#getRegionExtents()} by default; overridable so tests can substitute a
	 * small synthetic extent without touching that shared static state.
	 */
	public SplitFlagMap.RegionExtent regionExtent()
	{
		return SplitFlagMap.getRegionExtents();
	}

	private static int packedPointFromOrdinal(int startPacked, OrdinalDirection direction)
	{
		final int x = WorldPointUtil.unpackWorldX(startPacked);
		final int y = WorldPointUtil.unpackWorldY(startPacked);
		final int plane = WorldPointUtil.unpackWorldPlane(startPacked);
		return WorldPointUtil.packWorldPoint(x + direction.x, y + direction.y, plane);
	}

	public byte getRegionPlaneCounts(int regionIndex)
	{
		return collisionData.getRegionPlaneCounts(regionIndex);
	}

	private boolean get(int x, int y, int z, int flag)
	{
		return collisionData.get(x, y, z, flag);
	}

	public boolean n(int x, int y, int z)
	{
		return get(x, y, z, SplitFlagMap.FLAG_NORTH);
	}

	public boolean s(int x, int y, int z)
	{
		return n(x, y - 1, z);
	}

	public boolean e(int x, int y, int z)
	{
		return get(x, y, z, SplitFlagMap.FLAG_EAST);
	}

	public boolean w(int x, int y, int z)
	{
		return e(x - 1, y, z);
	}

	// The wall flags record whether a structural boundary (a wall or door
	// edge) sits on the edge, regardless of whether the edge is currently
	// passable. They stay unset on edges that are blocked only by an
	// object's footprint or a tile-level floor/seal block.
	public boolean wallN(int x, int y, int z)
	{
		return get(x, y, z, SplitFlagMap.FLAG_WALL_NORTH);
	}

	public boolean wallS(int x, int y, int z)
	{
		return wallN(x, y - 1, z);
	}

	public boolean wallE(int x, int y, int z)
	{
		return get(x, y, z, SplitFlagMap.FLAG_WALL_EAST);
	}

	public boolean wallW(int x, int y, int z)
	{
		return wallE(x - 1, y, z);
	}

	private boolean ne(int x, int y, int z)
	{
		return n(x, y, z) && e(x, y + 1, z) && e(x, y, z) && n(x + 1, y, z);
	}

	private boolean nw(int x, int y, int z)
	{
		return n(x, y, z) && w(x, y + 1, z) && w(x, y, z) && n(x - 1, y, z);
	}

	private boolean se(int x, int y, int z)
	{
		return s(x, y, z) && e(x, y - 1, z) && e(x, y, z) && s(x + 1, y, z);
	}

	private boolean sw(int x, int y, int z)
	{
		return s(x, y, z) && w(x, y - 1, z) && w(x, y, z) && s(x - 1, y, z);
	}

	public boolean isBlocked(int x, int y, int z)
	{
		return !n(x, y, z) && !s(x, y, z) && !e(x, y, z) && !w(x, y, z);
	}

	/**
	 * Returns the ordinary 8-direction walking mask (bits N, NE, E, SE, S, SW, W, NW); a diagonal
	 * is open only when both flanking cardinal moves are.
	 */
	public byte ordinaryWalkingMask(int packedPoint)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int z = WorldPointUtil.unpackWorldPlane(packedPoint);
		if (isBlocked(x, y, z))
		{
			return 0;
		}

		int mask = 0;
		if (n(x, y, z)) mask |= 1;
		if (ne(x, y, z)) mask |= 1 << 1;
		if (e(x, y, z)) mask |= 1 << 2;
		if (se(x, y, z)) mask |= 1 << 3;
		if (s(x, y, z)) mask |= 1 << 4;
		if (sw(x, y, z)) mask |= 1 << 5;
		if (w(x, y, z)) mask |= 1 << 6;
		if (nw(x, y, z)) mask |= 1 << 7;
		return (byte) mask;
	}

	/** Returns authoritative walking neighbours without transport-specific edges. */
	public int[] ordinaryWalkingNeighbors(int packedPoint)
	{
		final int x = WorldPointUtil.unpackWorldX(packedPoint);
		final int y = WorldPointUtil.unpackWorldY(packedPoint);
		final int z = WorldPointUtil.unpackWorldPlane(packedPoint);
		if (!isBlocked(x, y, z))
		{
			final int mask = Byte.toUnsignedInt(ordinaryWalkingMask(packedPoint));
			final int[] result = new int[Integer.bitCount(mask)];
			int index = 0;
			for (int bit = 0; bit < 8; bit++)
			{
				if ((mask & (1 << bit)) != 0)
				{
					result[index++] = WorldPointUtil.packWorldPoint(
						x + new int[]{0, 1, 1, 1, 0, -1, -1, -1}[bit],
						y + new int[]{1, 1, 0, -1, -1, -1, 0, 1}[bit], z);
				}
			}
			return result;
		}

		int[] result = new int[8];
		int count = 0;
		for (int dx = -1; dx <= 1; dx++)
		{
			for (int dy = -1; dy <= 1; dy++)
			{
				if (dx == 0 && dy == 0 || !isWalkable(x + dx, y + dy, z))
				{
					continue;
				}
				if (dx == 0 || dy == 0 || (isWalkable(x + dx, y, z) && isWalkable(x, y + dy, z)))
				{
					result[count++] = WorldPointUtil.packWorldPoint(x + dx, y + dy, z);
				}
			}
		}
		return java.util.Arrays.copyOf(result, count);
	}

	private boolean isWalkable(int x, int y, int z)
	{
		return n(x, y, z) || s(x, y, z) || e(x, y, z) || w(x, y, z);
	}

	/**
	 * {@code bankPathEnabled} is whether this search may visit a bank: the setting, or a search
	 * whose target needs items from the bank.
	 */
	public PrimitiveIntList getNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel,
		boolean targetInWilderness, NodeGraph graph, boolean bankPathEnabled)
	{
		if (graph.isTile(node))
		{
			return getTileNeighbors(node, visited, config, wildernessLevel, graph, bankPathEnabled);
		}
		else
		{
			return getAbstractNodeNeighbors(node, visited, config, targetInWilderness, graph);
		}
	}

	// Get neighbours for a walkable tile:
	//      * Neighbouring tiles we can walk to
	//      * A transition into banked state, if the current tile is a bank.
	//      * Transition into abstract global teleport nodes, if we haven't tried that yet.
	private PrimitiveIntList getTileNeighbors(int node, VisitedTiles visited, PathfinderConfig config, int wildernessLevel, NodeGraph graph,
		boolean bankPathEnabled)
	{
		final int packedPosition = graph.packedPosition(node);
		final int x = WorldPointUtil.unpackWorldX(packedPosition);
		final int y = WorldPointUtil.unpackWorldY(packedPosition);
		final int z = WorldPointUtil.unpackWorldPlane(packedPosition);

		neighbors.clear();

		// The banked state is only entered through an explicit, costed transition: standing on a
		// bank-accessible tile emits a bank-visit edge carrying the configured penalty, so the
		// charge sits on the decision to bank rather than on the edges leaving the bank tile.
		// The edge is flagged as a transport so Pathfinder queues it on the cost-ordered pending
		// heap — the FIFO tile boundary queue is only ordered for unit-cost walking edges.
		boolean pathBankVisited = graph.bankVisited(node);
		if (!pathBankVisited && bankPathEnabled && config.bankAccessible(packedPosition)
			&& !visited.get(packedPosition, true))
		{
			neighbors.add(graph.createBankVisit(packedPosition, node, config.getBankVisitCost()));
		}

		// Firstly check if there are any transports or teleports which are applicable from the current tile.
		Transport[] transports = config.getTransportsPacked(pathBankVisited).getOrDefault(packedPosition, TransportAvailability.EMPTY_TRANSPORTS);
		// If this tile was itself reached via a delayed-visit teleport (e.g. QUETZAL_WHISTLE), propagate its
		// differential cost to any competing delayed-visit transports emitted from here. This prevents the
		// pathfinder from choosing a chain (e.g. whistle → landing site A → fly to B) over a direct teleport
		// to B, because the chain inherits the teleport's penalty and is therefore always more expensive.
		int inheritedDifferential = (graph.isTransport(node) && graph.isDelayedVisit(node))
			? graph.differentialCost(node)
			: 0;
		for (Transport transport : transports)
		{
			boolean delayedVisit = transport.getType().sharesDestinationsWith() != null;
			// Do not consider a transport if its target tile is already settled —
			// dequeued from pending via a cheaper-or-equal route.
			// For transports that share destinations with a teleport, skip this check
			// so both can compete in the priority queue (delayed visit).
			if (!delayedVisit && visited.get(transport.getDestination(), pathBankVisited))
			{
				continue;
			}
			// Inherit the parent teleport's differential as a real cost on chained shared-destination transports,
			// so that chaining (e.g. fly to landing site A then use station to B) is always more expensive than
			// a direct teleport to B.
			int chainPenalty = (delayedVisit && inheritedDifferential > 0) ? inheritedDifferential : 0;
			// NB: Do not need to check for wilderness level for transports, since transports have specific origin tile.
			neighbors.add(graph.createTransport(
				transport.getDestination(),
				node,
				transport.getDuration(),
				config.getAdditionalTransportCost(transport) + chainPenalty,
				pathBankVisited,
				delayedVisit,
				delayedVisit ? config.getDifferentialCost(transport) : 0,
				transport));
		}

		// Global teleports are only considered from an abstract node, so each
		// wilderness/bank state expands them once.
		AbstractNodeKind abstractKind = AbstractNodeKind.fromWildernessLevel(wildernessLevel);
		if (!visited.getAbstract(abstractKind, pathBankVisited))
		{
			neighbors.add(graph.createAbstract(abstractKind, node, pathBankVisited));
		}

		// Then add tiles which we can walk to, which go into the FIFO boundary queue.
		if (isBlocked(x, y, z))
		{
			boolean westBlocked = isBlocked(x - 1, y, z);
			boolean eastBlocked = isBlocked(x + 1, y, z);
			boolean southBlocked = isBlocked(x, y - 1, z);
			boolean northBlocked = isBlocked(x, y + 1, z);
			boolean southWestBlocked = isBlocked(x - 1, y - 1, z);
			boolean southEastBlocked = isBlocked(x + 1, y - 1, z);
			boolean northWestBlocked = isBlocked(x - 1, y + 1, z);
			boolean northEastBlocked = isBlocked(x + 1, y + 1, z);
			traversable[0] = !westBlocked;
			traversable[1] = !eastBlocked;
			traversable[2] = !southBlocked;
			traversable[3] = !northBlocked;
			traversable[4] = !southWestBlocked && !westBlocked && !southBlocked;
			traversable[5] = !southEastBlocked && !eastBlocked && !southBlocked;
			traversable[6] = !northWestBlocked && !westBlocked && !northBlocked;
			traversable[7] = !northEastBlocked && !eastBlocked && !northBlocked;
		}
		else
		{
			traversable[0] = w(x, y, z);
			traversable[1] = e(x, y, z);
			traversable[2] = s(x, y, z);
			traversable[3] = n(x, y, z);
			traversable[4] = sw(x, y, z);
			traversable[5] = se(x, y, z);
			traversable[6] = nw(x, y, z);
			traversable[7] = ne(x, y, z);
		}

		for (int i = 0; i < traversable.length; i++)
		{
			OrdinalDirection d = ORDINAL_VALUES[i];
			int neighborPacked = packedPointFromOrdinal(packedPosition, d);
			if (visited.get(neighborPacked, pathBankVisited))
			{
				continue;
			}

			if (traversable[i])
			{
				neighbors.add(graph.createTile(neighborPacked, node, pathBankVisited));
			}
			else if (Math.abs(d.x + d.y) == 1 && isBlocked(x + d.x, y + d.y, z))
			{
				// The transport starts from a blocked adjacent tile, e.g. fairy ring
				// Only checks non-teleport transports (includes portals and levers, but not
				// items and spells)
				Transport[] neighborTransports = config.getTransportsPacked(pathBankVisited).getOrDefault(neighborPacked,
					TransportAvailability.EMPTY_TRANSPORTS);
				for (Transport transport : neighborTransports)
				{
					if (transport.getOrigin() == Transport.UNDEFINED_ORIGIN
						|| !(transport.isUsableAtWildernessLevel(wildernessLevel))
						|| visited.get(transport.getOrigin(), pathBankVisited))
					{
						continue;
					}
					neighbors.add(graph.createTile(transport.getOrigin(), node, pathBankVisited));
				}
			}
		}

		return neighbors;
	}

	// The only abstract nodes are currently for global teleports
	private PrimitiveIntList getAbstractNodeNeighbors(int node, VisitedTiles visited, PathfinderConfig config,
		boolean targetInWilderness, NodeGraph graph)
	{
		neighbors.clear();
		int sourceTile = graph.getClosestTilePosition(node);
		boolean bankVisited = graph.bankVisited(node);
		int maxWildernessLevel = graph.abstractKind(node).maxWildernessLevel();
		for (Transport transport : config.getUsableTeleports(bankVisited))
		{
			boolean delayedVisit = transport.getType().sharesDestinationsWith() != null;
			if (!delayedVisit && visited.get(transport.getDestination(), bankVisited))
			{
				continue;
			}
			if (!transport.isUsableAtWildernessLevel(maxWildernessLevel))
			{
				continue;
			}
			if (config.avoidWilderness(sourceTile, transport.getDestination(), targetInWilderness))
			{
				continue;
			}
			// The differential cost is only used for priority-queue ordering (compareCost), not
			// propagated as real cost, so applying it unconditionally is safe: a nearby partner
			// station can still win the dequeue race, and a far-away whistle still resolves as the
			// cheapest path because no competitor has a lower real cost to the same destination.
			int differentialCost = delayedVisit ? config.getDifferentialCost(transport) : 0;
			neighbors.add(graph.createTransport(
				transport.getDestination(),
				node,
				transport.getDuration(),
				config.getAdditionalTransportCost(transport),
				bankVisited,
				delayedVisit,
				differentialCost,
				transport));
		}
		return neighbors;
	}
}

package shortestpath.pathfinder;

import java.util.Collections;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * The search states that finish a route: a goal tile, in a bank layer where the player holds that
 * target's items.
 *
 * <p>Searches already tell apart a path that has visited a bank from one that hasn't, because
 * banked items unlock transports. Required items use the same split. Each target's
 * {@link TargetStatus} is decided once, from the player's {@link HeldItems}, before the search
 * starts:
 * <ul>
 *     <li>{@link TargetStatus#CARRIED} (or no required items): the target finishes the route in
 *     either layer.</li>
 *     <li>{@link TargetStatus#BANK}: only after a bank visit, so the search itself picks the bank
 *     that makes the whole trip cheapest, and weighs that against the other targets.</li>
 *     <li>{@link TargetStatus#UNKNOWN}: never, while any other target can be completed. When none
 *     can, every target finishes the route in either layer, so the player still sees the way to
 *     the closest one.</li>
 * </ul>
 * A blocked target's fallback tiles from {@link TargetGoals} finish the route in the same layers
 * as the target itself.
 */
public final class GoalStates
{
	private static final int UNBANKED = 1;
	private static final int BANKED = 2;
	private static final int EITHER = UNBANKED | BANKED;

	private final Targets targets;
	private final TargetGoals tiles;
	private final HeldItems heldItems;
	private final Map<Integer, TargetStatus> statuses;
	// The layers each target finishes the route in, as UNBANKED/BANKED bits.
	private final Map<Integer, Integer> layers;
	// Goal tiles that finish the route in either layer, and those only after banking. Disjoint.
	private final Set<Integer> eitherLayerTiles;
	private final Set<Integer> bankedOnlyTiles;
	private final Set<Integer> allTiles;
	private final boolean viable;

	private GoalStates(Targets targets, TargetGoals tiles, HeldItems heldItems, Map<Integer, TargetStatus> statuses,
		Map<Integer, Integer> layers)
	{
		this.targets = targets;
		this.tiles = tiles;
		this.heldItems = heldItems;
		this.statuses = statuses;
		this.layers = layers;
		Set<Integer> eitherLayer = new HashSet<>();
		Set<Integer> bankedOnly = new HashSet<>();
		boolean anyViable = false;
		for (Map.Entry<Integer, Integer> entry : layers.entrySet())
		{
			int target = entry.getKey();
			int targetLayers = entry.getValue();
			if (targetLayers == 0)
			{
				continue;
			}
			anyViable |= tiles.isViable(target);
			Set<Integer> into = targetLayers == EITHER ? eitherLayer : bankedOnly;
			into.add(target);
			into.addAll(tiles.fallbacks(target));
		}
		// A tile that finishes the route in either layer for one target needs no bank for another.
		bankedOnly.removeAll(eitherLayer);
		Set<Integer> all = new HashSet<>(eitherLayer);
		all.addAll(bankedOnly);
		this.eitherLayerTiles = Collections.unmodifiableSet(eitherLayer);
		this.bankedOnlyTiles = Collections.unmodifiableSet(bankedOnly);
		this.allTiles = Collections.unmodifiableSet(all);
		this.viable = anyViable;
	}

	/** Resolves {@code targets} against the map and the items {@code config} last collected. */
	public static GoalStates resolve(PathfinderConfig config, int start, Targets targets)
	{
		return resolve(TargetGoals.resolve(config, start, targets.points()), targets, config.getHeldItems());
	}

	static GoalStates resolve(TargetGoals tiles, Targets targets, HeldItems heldItems)
	{
		Map<Integer, TargetStatus> statuses = new HashMap<>();
		Map<Integer, Integer> layers = new HashMap<>();
		boolean anyCompletable = false;
		for (Target target : targets)
		{
			TargetStatus status = target.hasRequiredItems() ? heldItems.statusOf(target.getRequiredItems())
				: TargetStatus.CARRIED;
			int targetLayers = status == TargetStatus.CARRIED ? EITHER : status == TargetStatus.BANK ? BANKED : 0;
			statuses.put(target.getPoint(), status);
			layers.put(target.getPoint(), targetLayers);
			anyCompletable |= targetLayers != 0 && tiles.isViable(target.getPoint());
		}
		if (!anyCompletable)
		{
			// No target can be completed with what the player holds, so route as if none needed
			// items: the closest target is still where the player is going.
			layers.replaceAll((point, targetLayers) -> EITHER);
		}
		return new GoalStates(targets, tiles, heldItems, statuses, layers);
	}

	/** Whether reaching {@code tile} in the given bank layer finishes the route. */
	public boolean accepts(int tile, boolean banked)
	{
		return eitherLayerTiles.contains(tile) || banked && bankedOnlyTiles.contains(tile);
	}

	/** Whether a path in the given bank layer may finish at or near the target at {@code point}. */
	public boolean acceptsTarget(int point, boolean banked)
	{
		return (layers.getOrDefault(point, 0) & (banked ? BANKED : UNBANKED)) != 0;
	}

	/** Every tile that finishes the route in some layer. */
	public Set<Integer> tiles()
	{
		return allTiles;
	}

	/** Whether some goal tile only finishes the route after a bank visit, so the search must bank. */
	public boolean needsBank()
	{
		return !bankedOnlyTiles.isEmpty();
	}

	/**
	 * Whether any target that finishes the route could ever be reached; see
	 * {@link TargetGoals#hasViableGoal()}.
	 */
	public boolean hasViableGoal()
	{
		return viable;
	}

	/**
	 * The arrival of a route that ends on {@code tile} in the given layer: the target the tile
	 * belongs to, the tile itself when it is a target, and otherwise the first target it is a
	 * fallback tile for. {@code null} when the tile finishes the route for no target.
	 */
	public Arrival arrival(int tile, boolean banked)
	{
		Integer reached = acceptsTarget(tile, banked) ? Integer.valueOf(tile) : null;
		for (int point : targets.points())
		{
			if (reached == null && acceptsTarget(point, banked) && tiles.fallbacks(point).contains(tile))
			{
				reached = point;
			}
		}
		if (reached == null)
		{
			return null;
		}
		Target target = targets.get(reached);
		TargetStatus status = statuses.get(reached);
		return new Arrival(target, status, status == TargetStatus.UNKNOWN
			? heldItems.missing(target.getRequiredItems()) : List.of());
	}
}

package shortestpath.pathfinder;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Set;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.requirement.model.TransportItems;

/**
 * The items the player holds, as item id to quantity: what they carry (inventory, worn items and
 * rune pouch), and that plus the bank as last seen. A bank not opened this session is empty.
 * Immutable; {@link PathfinderConfig} takes a new snapshot on every refresh.
 */
public final class HeldItems
{
	public static final HeldItems NONE = new HeldItems(Map.of(), Map.of(), false);

	private final Map<Integer, Integer> carried;
	private final Map<Integer, Integer> carriedAndBanked;
	private final boolean bankSeen;

	public HeldItems(Map<Integer, Integer> carried, Map<Integer, Integer> carriedAndBanked, boolean bankSeen)
	{
		this.carried = Map.copyOf(carried);
		this.carriedAndBanked = Map.copyOf(carriedAndBanked);
		this.bankSeen = bankSeen;
	}

	/** Inventory, worn items and the rune pouch. */
	public Map<Integer, Integer> carried()
	{
		return carried;
	}

	/** The carried items plus the bank's contents. */
	public Map<Integer, Integer> carriedAndBanked()
	{
		return carriedAndBanked;
	}

	/** Whether the bank has been opened this session, so its contents are known. */
	public boolean isBankSeen()
	{
		return bankSeen;
	}

	/** Whether {@code required} is carried, covered once the bank is added, or neither. */
	public TargetStatus statusOf(TransportItems required)
	{
		if (covers(carried, required))
		{
			return TargetStatus.CARRIED;
		}
		if (covers(carriedAndBanked, required))
		{
			return TargetStatus.BANK;
		}
		return TargetStatus.UNKNOWN;
	}

	/** The item groups of {@code required} that the carried items and the bank together don't cover. */
	public List<ItemRequirement> missing(TransportItems required)
	{
		List<ItemRequirement> missing = new ArrayList<>();
		for (ItemRequirement group : required.getRequirements())
		{
			if (!covers(carriedAndBanked, new TransportItems(List.of(group))))
			{
				missing.add(group);
			}
		}
		return missing;
	}

	// Required items are held, never spent, so no currency threshold applies.
	private static boolean covers(Map<Integer, Integer> items, TransportItems required)
	{
		return required.isSatisfiedBy(items, Set.of(), Integer.MAX_VALUE);
	}
}

package shortestpath.pathfinder;

/**
 * A minimal growable FIFO of primitive {@code int} node ids backed by a ring buffer.
 * <p>
 * Replaces the {@code ArrayDeque<Node>} boundary queue in {@link Pathfinder} so the search frontier
 * no longer boxes node references. Only the operations the pathfinder needs are implemented; it is
 * single-threaded (worker only) like the queue it replaces.
 */
public class IntDeque
{
	private int[] elements;
	private int head;
	private int tail;
	private int size;

	public IntDeque(int initialCapacity)
	{
		elements = new int[Math.max(1, initialCapacity)];
	}

	int size()
	{
		return size;
	}

	public boolean isEmpty()
	{
		return size == 0;
	}

	public void addLast(int value)
	{
		if (size == elements.length)
		{
			grow();
		}
		elements[tail] = value;
		tail = increment(tail);
		size++;
	}

	public void addFirst(int value)
	{
		if (size == elements.length)
		{
			grow();
		}
		head = decrement(head);
		elements[head] = value;
		size++;
	}

	/**
	 * @return the first element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	public int peekFirst()
	{
		return size == 0 ? NodeGraph.NO_NODE : elements[head];
	}

	/**
	 * @return the removed first element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	public int pollFirst()
	{
		if (size == 0)
		{
			return NodeGraph.NO_NODE;
		}
		final int value = elements[head];
		head = increment(head);
		size--;
		return value;
	}

	public void clear()
	{
		head = 0;
		tail = 0;
		size = 0;
	}

	private int increment(int index)
	{
		return index + 1 == elements.length ? 0 : index + 1;
	}

	private int decrement(int index)
	{
		return index == 0 ? elements.length - 1 : index - 1;
	}

	private void grow()
	{
		final int oldCapacity = elements.length;
		final int[] grown = new int[oldCapacity << 1];
		for (int i = 0; i < size; i++)
		{
			grown[i] = elements[(head + i) % oldCapacity];
		}
		elements = grown;
		head = 0;
		tail = size;
	}
}

package shortestpath.pathfinder;

import java.util.Arrays;

/**
 * A binary min-heap of primitive {@code int} node ids ordered by {@link NodeGraph#compareCost}.
 * <p>
 * Replaces the {@code PriorityQueue<TransportNode>} pending queue in {@link Pathfinder} so transport
 * candidates are stored as int ids rather than boxed node objects. The ordering key is fixed when a
 * node is created (its differential cost never changes), so no decrease-key support is needed; the
 * pathfinder discards stale cheaper duplicates with its dequeue-time visited re-check. Single-threaded
 * (worker only), matching the queue it replaces.
 */
public class IntMinHeap
{
	private final NodeGraph graph;
	private int[] heap;
	private int size;

	public IntMinHeap(NodeGraph graph, int initialCapacity)
	{
		this.graph = graph;
		this.heap = new int[Math.max(1, initialCapacity)];
	}

	int size()
	{
		return size;
	}

	public boolean isEmpty()
	{
		return size == 0;
	}

	/**
	 * @return the minimum-cost element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	public int peek()
	{
		return size == 0 ? NodeGraph.NO_NODE : heap[0];
	}

	public void add(int id)
	{
		if (size == heap.length)
		{
			heap = Arrays.copyOf(heap, heap.length << 1);
		}
		heap[size] = id;
		siftUp(size);
		size++;
	}

	/**
	 * @return the removed minimum-cost element, or {@link NodeGraph#NO_NODE} if empty.
	 */
	public int poll()
	{
		if (size == 0)
		{
			return NodeGraph.NO_NODE;
		}
		final int top = heap[0];
		size--;
		if (size > 0)
		{
			heap[0] = heap[size];
			siftDown(0);
		}
		return top;
	}

	public void clear()
	{
		size = 0;
	}

	private void siftUp(int index)
	{
		final int id = heap[index];
		final int key = graph.compareCost(id);
		while (index > 0)
		{
			final int parent = (index - 1) >> 1;
			if (key >= graph.compareCost(heap[parent]))
			{
				break;
			}
			heap[index] = heap[parent];
			index = parent;
		}
		heap[index] = id;
	}

	private void siftDown(int index)
	{
		final int id = heap[index];
		final int key = graph.compareCost(id);
		final int half = size >> 1;
		while (index < half)
		{
			int child = (index << 1) + 1;
			int childKey = graph.compareCost(heap[child]);
			final int right = child + 1;
			if (right < size)
			{
				final int rightKey = graph.compareCost(heap[right]);
				if (rightKey < childKey)
				{
					child = right;
					childKey = rightKey;
				}
			}
			if (key <= childKey)
			{
				break;
			}
			heap[index] = heap[child];
			index = child;
		}
		heap[index] = id;
	}
}

package shortestpath.pathfinder;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import shortestpath.WorldPointUtil;
import shortestpath.transport.Transport;

/**
 * Structure-of-Arrays store for pathfinding nodes.
 * <p>
 * The previous design allocated one {@link Object} per explored tile (a {@code Node} or
 * {@code TransportNode}). Heavy searches explore hundreds of thousands of tiles, so this produced
 * hundreds of thousands of live objects, each carrying a ~16-byte header plus several object
 * references (issue #491). Here every node is instead an {@code int} index into parallel primitive
 * arrays, so a whole search holds only a handful of arrays regardless of how many nodes it visits.
 * <p>
 * The fields packed per node are exactly those of the old {@code Node}/{@code TransportNode}:
 * packed world position, the index of the previous node ({@link #NO_NODE} for the start),
 * accumulated cost, the transport differential cost (queue-ordering only), a set of boolean flags,
 * and the {@link AbstractNodeKind} ordinal for abstract nodes — plus the {@link Transport}
 * that produced a transport edge, so consumers can identify which transport the path actually
 * used instead of reconstructing it from origin/destination (ambiguous on shared-destination
 * transports).
 * <p>
 * <strong>Threading.</strong> The search runs on a single worker thread, but the render thread
 * reads the partial path while the search is still running (progressive rendering via
 * {@code Pathfinder.getPath()}). Node data is write-once and is published to the render thread by
 * the single volatile {@code Pathfinder.bestLastNode} handoff rather than by marking these arrays
 * {@code volatile} (which would cripple the hot loop, see the field comment). The chain walks
 * ({@link #getPathSteps} / {@link #getClosestTilePosition}) snapshot the arrays into locals and
 * tolerate an index that is out of bounds or released. This means a walk concurrent with a
 * grow/release can never throw; at worst it yields a one-frame-stale path.
 */
public class NodeGraph
{
	public static final int NO_NODE = -1;

	private static final byte FLAG_BANK_VISITED = 1;       // bit0
	private static final byte FLAG_ABSTRACT = 1 << 1;      // bit1
	private static final byte FLAG_DELAYED_VISIT = 1 << 2; // bit2
	private static final byte FLAG_TRANSPORT = 1 << 3;     // bit3
	private static final byte FLAG_BANK_VISIT = 1 << 4;    // bit4
	private static final byte FLAG_WEIGHTED = 1 << 5;      // bit5

	// Enum.values() copies on every call, so cache it for the abstractKind lookup.
	private static final AbstractNodeKind[] ABSTRACT_KINDS = AbstractNodeKind.values();

	// The node arrays are NOT volatile: making them volatile forces every accessor (packedPosition,
	// cost, isTile, compareCost, the append() writes, ...) to re-read the array reference on each
	// call and blocks the JIT from caching the base in a register or eliminating bounds checks. The
	// hot loop touches these hundreds of times per node, so volatile reads roughly halved field
	// throughput (~1.6x slower searches). Safe publication to the render thread is provided instead
	// by the single volatile Pathfinder.bestLastNode handoff: the worker writes the node data, then
	// volatile-writes bestLastNode; the render thread volatile-reads bestLastNode before walking,
	// which establishes happens-before for all the plain writes above it. The walk methods snapshot
	// the references into locals and tolerate a null (post-release) or stale-but-valid (mid-grow,
	// Arrays.copyOf preserves every index) array, so a concurrent grow/release never throws.
	private int[] packedPosition;
	private int[] previous;
	private int[] cost;
	private int[] differentialCost;
	private byte[] flags;
	private byte[] abstractKind;
	private Transport[] transports;
	private int size;

	public NodeGraph(int initialCapacity)
	{
		final int capacity = Math.max(1, initialCapacity);
		packedPosition = new int[capacity];
		previous = new int[capacity];
		cost = new int[capacity];
		differentialCost = new int[capacity];
		flags = new byte[capacity];
		abstractKind = new byte[capacity];
		transports = new Transport[capacity];
	}

	public int size()
	{
		return size;
	}

	private void ensureCapacity()
	{
		if (size < packedPosition.length)
		{
			return;
		}
		// Grow by 50% like ArrayList. Arrays.copyOf preserves every existing index, and node data
		// is write-once, so a render thread reading a pre-grow array still sees correct values for
		// the indices it walks.
		final int newCapacity = packedPosition.length + (packedPosition.length >> 1);
		packedPosition = Arrays.copyOf(packedPosition, newCapacity);
		previous = Arrays.copyOf(previous, newCapacity);
		cost = Arrays.copyOf(cost, newCapacity);
		differentialCost = Arrays.copyOf(differentialCost, newCapacity);
		flags = Arrays.copyOf(flags, newCapacity);
		abstractKind = Arrays.copyOf(abstractKind, newCapacity);
		transports = Arrays.copyOf(transports, newCapacity);
	}

	private int append(int packed, int prev, int nodeCost, int diffCost, byte flagBits, byte kind)
	{
		ensureCapacity();
		final int id = size;
		packedPosition[id] = packed;
		previous[id] = prev;
		cost[id] = nodeCost;
		differentialCost[id] = diffCost;
		abstractKind[id] = kind;
		flags[id] = flagBits;
		size = id + 1;
		return id;
	}

	private int costOf(int id)
	{
		return id == NO_NODE ? 0 : cost[id];
	}

	/**
	 * The search root. Carries no previous node and zero cost.
	 */
	public int createStart(int packedPosition)
	{
		return append(packedPosition, NO_NODE, 0, 0, (byte) 0, (byte) 0);
	}

	/**
	 * A concrete walkable tile. Travel cost is the walking distance from the previous node, but
	 * only when the previous node is itself a tile (mirrors the old {@code Node.cost}); reaching a
	 * tile from an abstract node adds no travel cost.
	 */
	public int createTile(int packedPosition, int previous, boolean bankVisited)
	{
		final int travelTime = (previous != NO_NODE && isTile(previous))
			? WorldPointUtil.distanceBetween(this.packedPosition[previous], packedPosition)
			: 0;
		final byte flagBits = bankVisited ? FLAG_BANK_VISITED : 0;
		return append(packedPosition, previous, costOf(previous) + travelTime, 0, flagBits, (byte) 0);
	}

	/**
	 * A transport destination tile. Cost is the previous cost plus the transport's travel time and
	 * any additional cost; there is no walking-distance term (mirrors the old {@code TransportNode}).
	 * The chosen {@link Transport} is stored on the node so the reconstructed path can report
	 * which transport produced the edge.
	 */
	public int createTransport(int packedPosition, int previous, int travelTime, int additionalCost,
		boolean bankVisited, boolean delayedVisit, int differentialCost, Transport transport)
	{
		byte flagBits = FLAG_TRANSPORT;
		if (bankVisited)
		{
			flagBits |= FLAG_BANK_VISITED;
		}
		if (delayedVisit)
		{
			flagBits |= FLAG_DELAYED_VISIT;
		}
		final int id = append(packedPosition, previous, costOf(previous) + travelTime + additionalCost,
			differentialCost, flagBits, (byte) 0);
		transports[id] = transport;
		return id;
	}

	/**
	 * The paid transition into the banked state. Emitted from a bank-accessible tile when the
	 * path has not banked yet: the node stays on the same position and carries the configured
	 * bank visit cost, so the penalty is charged once on the decision to bank rather than on
	 * the edges leaving the bank tile.
	 * <p>
	 * The node is flagged as a transport even though no real transport exists: {@link
	 * Pathfinder#addNeighbors} routes transport-flagged nodes to the cost-ordered pending
	 * heap instead of the FIFO tile boundary queue, which is only correct for unit-cost
	 * walking edges. A costed transition must go through the heap or nodes would no longer
	 * be expanded in increasing cost order.
	 */
	public int createBankVisit(int packedPosition, int previous, int bankVisitCost)
	{
		return append(packedPosition, previous, costOf(previous) + bankVisitCost, 0,
			(byte) (FLAG_TRANSPORT | FLAG_BANK_VISITED | FLAG_BANK_VISIT), (byte) 0);
	}

	/**
	 * A tile reached by a weighted move (sailing moves). Like a transport destination it is queued
	 * by {@link #compareCost} and only marked visited when dequeued, so the cheapest way to reach
	 * it wins. {@code heuristic} is stored as the differential cost, which turns the queue order
	 * into A*. {@code moveIndex} identifies the sailing move that reached the tile — it decides
	 * which way the boat faces on it and can't be recovered from the move's displacement, which
	 * different headings can share at low speeds.
	 */
	public int createWeightedTile(int packedPosition, int previous, int moveCost, int heuristic,
		boolean bankVisited, int moveIndex)
	{
		byte flagBits = FLAG_WEIGHTED;
		if (bankVisited)
		{
			flagBits |= FLAG_BANK_VISITED;
		}
		// Weighted tiles are never abstract, so the abstractKind slot carries the sailing move
		// (shifted by one, so the default 0 means no move — the start, walking and transport nodes)
		return append(packedPosition, previous, costOf(previous) + moveCost, heuristic, flagBits,
			(byte) (moveIndex + 1));
	}

	/**
	 * An abstract search-state node (global teleports). Has no world position and inherits the
	 * previous node's cost (mirrors the old {@code Node.abstractNode}).
	 */
	public int createAbstract(AbstractNodeKind abstractKind, int previous, boolean bankVisited)
	{
		byte flagBits = FLAG_ABSTRACT;
		if (bankVisited)
		{
			flagBits |= FLAG_BANK_VISITED;
		}
		return append(WorldPointUtil.UNDEFINED, previous, costOf(previous), 0, flagBits,
			(byte) abstractKind.ordinal());
	}

	public int packedPosition(int id)
	{
		return packedPosition[id];
	}

	public int previous(int id)
	{
		return previous[id];
	}

	public int cost(int id)
	{
		return cost[id];
	}

	public int differentialCost(int id)
	{
		return differentialCost[id];
	}

	/**
	 * The cost used for priority-queue ordering, includes the transport differential.
	 */
	public int compareCost(int id)
	{
		return cost[id] + differentialCost[id];
	}

	public boolean bankVisited(int id)
	{
		return (flags[id] & FLAG_BANK_VISITED) != 0;
	}

	public boolean isTile(int id)
	{
		return (flags[id] & FLAG_ABSTRACT) == 0;
	}

	public boolean isAbstract(int id)
	{
		return (flags[id] & FLAG_ABSTRACT) != 0;
	}

	public boolean isTransport(int id)
	{
		return (flags[id] & FLAG_TRANSPORT) != 0;
	}

	public boolean isDelayedVisit(int id)
	{
		return (flags[id] & FLAG_DELAYED_VISIT) != 0;
	}

	/**
	 * The transport that produced the edge into {@code id}, or null for walking edges,
	 * bank-visit transitions and the start node.
	 */
	public Transport transport(int id)
	{
		return transports[id];
	}

	public boolean isWeighted(int id)
	{
		return (flags[id] & FLAG_WEIGHTED) != 0;
	}

	/**
	 * Index into the search's {@link shortestpath.pathfinder.sailing.SailingMoves} of the move that reached this weighted tile,
	 * or -1 for nodes no sailing move reached (the start, walking tiles, transport destinations).
	 * Shares the abstractKind slot, which weighted tiles never use.
	 */
	public int moveIndex(int id)
	{
		return abstractKind[id] - 1;
	}

	public AbstractNodeKind abstractKind(int id)
	{
		return ABSTRACT_KINDS[abstractKind[id]];
	}

	/**
	 * Walks the previous chain from {@code id} to the start, collecting the tile nodes into an
	 * ordered list of path steps. Abstract nodes are skipped, and so are bank-visit
	 * transitions: a bank visit is a state change, not a movement step — the tile the player
	 * banked at is already in the path as the preceding step.
	 * <p>
	 * Safe to call from the render thread during the search: the arrays are snapshotted into locals
	 * and the walk is bounds-tolerant, so a concurrent grow or {@link #release()} yields an empty
	 * or one-frame-stale result rather than throwing.
	 */
	public List<PathStep> getPathSteps(int id)
	{
		final int[] prev = previous;
		final int[] packed = packedPosition;
		final byte[] flg = flags;
		final Transport[] trans = transports;
		if (prev == null || packed == null || flg == null || trans == null || id == NO_NODE)
		{
			return new ArrayList<>();
		}
		final int len = prev.length;

		int node = id;
		int n = 0;
		while (node != NO_NODE && node < len)
		{
			// A bank visit is elided as a state change, not a step — except when it terminates the
			// path, where dropping it would lose the final tile's banked state.
			if ((flg[node] & (FLAG_ABSTRACT | FLAG_BANK_VISIT)) == 0
				|| (node == id && (flg[node] & FLAG_BANK_VISIT) != 0))
			{
				n++;
			}
			node = prev[node];
		}

		final List<PathStep> pathSteps = new ArrayList<>(n);
		for (int i = 0; i < n; i++)
		{
			pathSteps.add(null);
		}

		node = id;
		int i = n;
		while (node != NO_NODE && node < len && i > 0)
		{
			if ((flg[node] & (FLAG_ABSTRACT | FLAG_BANK_VISIT)) == 0
				|| (node == id && (flg[node] & FLAG_BANK_VISIT) != 0))
			{
				pathSteps.set(--i, new PathStep(packed[node], (flg[node] & FLAG_BANK_VISITED) != 0,
					trans[node]));
			}
			node = prev[node];
		}

		return pathSteps;
	}

	/**
	 * Walks the previous chain from {@code id} until the first tile node and returns its packed
	 * position, or {@link WorldPointUtil#UNDEFINED} if none. Same threading guarantees as
	 * {@link #getPathSteps}.
	 */
	public int getClosestTilePosition(int id)
	{
		final int[] prev = previous;
		final int[] packed = packedPosition;
		final byte[] flg = flags;
		if (prev == null || packed == null || flg == null)
		{
			return WorldPointUtil.UNDEFINED;
		}
		final int len = prev.length;
		int node = id;
		while (node != NO_NODE && node < len && (flg[node] & FLAG_ABSTRACT) != 0)
		{
			node = prev[node];
		}
		return (node != NO_NODE && node < len) ? packed[node] : WorldPointUtil.UNDEFINED;
	}

	/**
	 * Releases the backing arrays once the search is finished and the final path has been
	 * materialised, so the large per-search working set becomes eligible for garbage collection
	 * (the old design dropped the explored {@code Node} objects the same way by clearing the
	 * frontier collections). A render-thread walk in flight keeps its own local references and
	 * finishes safely.
	 */
	public void release()
	{
		packedPosition = null;
		previous = null;
		cost = null;
		differentialCost = null;
		flags = null;
		abstractKind = null;
		transports = null;
		size = 0;
	}
}

package shortestpath.pathfinder;

public enum OrdinalDirection
{
	WEST(-1, 0),
	EAST(1, 0),
	SOUTH(0, -1),
	NORTH(0, 1),
	SOUTH_WEST(-1, -1),
	SOUTH_EAST(1, -1),
	NORTH_WEST(-1, 1),
	NORTH_EAST(1, 1);

	final int x;
	final int y;

	OrdinalDirection(int x, int y)
	{
		this.x = x;
		this.y = y;
	}
}

package shortestpath.pathfinder;

import lombok.Getter;
import shortestpath.transport.Transport;

@Getter
public final class PathStep
{
	private final int packedPosition;
	private final boolean bankVisited;
	/**
	 * The transport that produced the edge leading to this step, or null when the step
	 * was reached by walking (or was built without transport identity). Carrying the
	 * chosen transport on the step removes the ambiguity of reconstructing "which
	 * transport was used" from origin+destination, which cannot distinguish transports
	 * that share a destination tile.
	 */
	private final Transport transport;

	public PathStep(int packedPosition, boolean bankVisited)
	{
		this(packedPosition, bankVisited, null);
	}

	public PathStep(int packedPosition, boolean bankVisited, Transport transport)
	{
		this.packedPosition = packedPosition;
		this.bankVisited = bankVisited;
		this.transport = transport;
	}
}

package shortestpath.pathfinder;

public enum PathTerminationReason
{
	TARGET_REACHED,
	SEARCH_EXHAUSTED,
	CUTOFF_REACHED,
	CANCELLED,
	BACKEND_FAILURE
}

package shortestpath.pathfinder;

import java.util.List;
import java.util.Set;

import lombok.Getter;
import shortestpath.PrimitiveIntList;
import shortestpath.WorldPointUtil;
import shortestpath.leagues.LeagueModeState;

public class Pathfinder implements ActiveSearch
{
	private final PathfinderStats stats;
	@Getter
	private final int start;
	@Getter
	private final Targets targets;
	// Which (tile, bank layer) states terminate the search: the targets plus, for each blocked
	// target, its fallback tiles (issue #640), each in the layers where the player holds that
	// target's items.
	private final GoalStates goals;
	// Whether any goal could possibly terminate the search: non-blocked,
	// a transport destination, or resolved to at least one walkable nearby tile.
	// When false the search is skipped entirely, since no goal can ever be visited.
	private final boolean hasViableGoal;
	// Whether the search may visit a bank: the setting, or a target whose items are in the bank.
	private final boolean bankPathEnabled;
	private final PathfinderConfig config;
	private final CollisionMap map;
	private final boolean targetInWilderness;
	private final boolean targetInBlockedRegion;
	private final Runnable completionCallback;
	// Nodes are stored structure-of-arrays style: each node is an int id into the graph, instead of
	// an object per explored tile. This keeps a whole search to a handful of arrays (issue #491).
	private final NodeGraph graph = new NodeGraph(1 << 14);
	// Capacities should be enough to store all nodes without requiring the queue to grow
	// They were found by checking the max queue size
	private final IntDeque boundary = new IntDeque(4096);
	private final IntMinHeap pending = new IntMinHeap(graph, 256);
	private final VisitedTiles visited;
	@Getter
	private volatile boolean done = false;
	private volatile boolean cancelled = false;
	// Read by the render thread during the search to draw the partial path; written by the worker.
	private volatile int bestLastNode = NodeGraph.NO_NODE;
	// The path the render thread builds progressively while the search runs.
	private List<PathStep> pathSteps = List.of();
	private boolean pathNeedsUpdate = false;
	// Built once on the worker thread when the search finishes, then served to the render thread so
	// it never walks the node chain (which is released) after the search is done.
	private volatile List<PathStep> finalPath = null;
	private volatile int closestReachedPoint = WorldPointUtil.UNDEFINED;
	private volatile int finalPathCost = PathfinderResult.NO_PATH_COST;
	private volatile Arrival arrival;
	private int bestRemainingDistance = Integer.MAX_VALUE;
	private int bestTravelledDistance = Integer.MAX_VALUE;
	private int bestX = Integer.MAX_VALUE;
	private int bestY = Integer.MAX_VALUE;
	// First explored node within the configured unreachable distance.
	private int shortestAcceptedNode = NodeGraph.NO_NODE;
	private int shortestAcceptedTarget = WorldPointUtil.UNDEFINED;
	private int reachedTarget = WorldPointUtil.UNDEFINED;
	private PathTerminationReason terminationReason;
	/**
	 * Teleportation transports are updated when this changes.
	 * Can be either:
	 * 0 = all teleports can be used (e.g. Chronicle)
	 * 20 = most teleports can be used (e.g. Varrock Teleport)
	 * 30 = some teleports can be used (e.g. Amulet of Glory)
	 * 31 = no teleports can be used
	 */
	private int wildernessLevel;

	/** A search towards {@code targets} that need no items. */
	public Pathfinder(PathfinderConfig config, int start, Set<Integer> targets, Runnable completionCallback)
	{
		this(config, start, Targets.at(targets), completionCallback);
	}

	/**
	 * A search that ends at whichever of {@code targets} is cheapest to reach holding that target's
	 * items; see {@link GoalStates}.
	 */
	public Pathfinder(PathfinderConfig config, int start, Targets targets, Runnable completionCallback)
	{
		stats = new PathfinderStats();
		this.config = config;
		this.map = config.getMap();
		this.start = start;
		this.targets = targets;
		this.goals = GoalStates.resolve(config, start, targets);
		this.hasViableGoal = goals.hasViableGoal();
		this.bankPathEnabled = config.isBankPathEnabled() || goals.needsBank();
		this.completionCallback = completionCallback;
		visited = new VisitedTiles(map, config.getBankVisitCost());
		targetInWilderness = WildernessChecker.isInWilderness(targets.points());
		targetInBlockedRegion = anyInBlockedRegion(config.getLeagueModeState(), targets.points());
		wildernessLevel = 31;
	}

	private static boolean anyInBlockedRegion(LeagueModeState league, Set<Integer> packed)
	{
		if (!league.isSeasonal() || packed == null || packed.isEmpty())
		{
			return false;
		}
		for (Integer point : packed)
		{
			if (league.isInBlockedRegion(point))
			{
				return true;
			}
		}
		return false;
	}

	public Pathfinder(PathfinderConfig config, int start, Set<Integer> targets)
	{
		this(config, start, targets, null);
	}

	public Pathfinder(PathfinderConfig config, int start, Targets targets)
	{
		this(config, start, targets, null);
	}

	public void cancel()
	{
		cancelled = true;
	}

	public PathfinderStats getStats()
	{
		if (stats.started && stats.ended)
		{
			return stats;
		}

		// Don't give incomplete results
		return null;
	}

	public List<PathStep> getPath()
	{
		int lastNode = bestLastNode; // For thread safety, read bestLastNode once
		if (lastNode == NodeGraph.NO_NODE)
		{
			List<PathStep> finalised = finalPath;
			return finalised != null ? finalised : pathSteps;
		}

		// Once the search is finished the node graph is released, so serve the pre-built snapshot.
		if (done)
		{
			List<PathStep> finalised = finalPath;
			if (finalised != null)
			{
				return finalised;
			}
		}

		if (pathNeedsUpdate)
		{
			List<PathStep> walked = graph.getPathSteps(lastNode);
			// An empty result means the graph was released mid-walk; keep the last good path.
			if (!walked.isEmpty())
			{
				pathSteps = walked;
				pathNeedsUpdate = false;
			}
		}

		return pathSteps;
	}

	public PathfinderResult getResult()
	{
		PathfinderStats currentStats = getStats();
		if (currentStats == null)
		{
			return null;
		}

		List<PathStep> currentPath = getPath();
		boolean reached = reachedTarget != WorldPointUtil.UNDEFINED;
		int target = reached ? reachedTarget
			: (targets.isEmpty() ? WorldPointUtil.UNDEFINED : targets.points().iterator().next());
		// getStats() only returns non-null once the search has ended, so the snapshot is set.
		return new PathfinderResult(
			start,
			target,
			reached,
			currentPath,
			closestReachedPoint,
			finalPathCost,
			currentStats.getNodesChecked(),
			currentStats.getTransportsChecked(),
			currentStats.getElapsedTimeNanos(),
			terminationReason,
			null,
			arrival
		);
	}

	private void addNeighbors(int node, boolean nodeIsTile, int nodePacked)
	{
		PrimitiveIntList nodes = map.getNeighbors(node, visited, config, wildernessLevel, targetInWilderness, graph,
			bankPathEnabled);
		final int count = nodes.size();
		for (int i = 0; i < count; i++)
		{
			int neighbor = nodes.get(i);
			// Each graph.xxx(id) re-indexes a backing array, so read each neighbour field once and
			// reuse the loop-invariant node fields passed in (the JIT cached these for free when nodes
			// were objects, but not when they are int ids into structure-of-arrays storage).
			final boolean neighborIsTile = graph.isTile(neighbor);
			if (nodeIsTile && neighborIsTile)
			{
				final int neighborPacked = graph.packedPosition(neighbor);
				if (config.avoidWilderness(nodePacked, neighborPacked, targetInWilderness))
				{
					continue;
				}
				if (config.avoidBlockedRegion(nodePacked, neighborPacked, targetInBlockedRegion))
				{
					continue;
				}
			}

			final boolean neighborIsTransport = graph.isTransport(neighbor);
			// Transports queue on the cost-ordered pending heap, so marking their
			// destination visited at enqueue would let an expensive queued transport
			// shadow a cheaper route emitted later; transports are checked and marked
			// when dequeued instead. Walking-tile and abstract neighbours still claim
			// their tile at enqueue.
			if (!neighborIsTransport)
			{
				visited.set(neighbor, graph);
			}
			if (neighborIsTransport)
			{
				pending.add(neighbor);
				++stats.transportsChecked;
			}
			else
			{
				boundary.addLast(neighbor);
				++stats.nodesChecked;
			}
		}
	}

	/**
	 * Pathfinding to an unreachable target is slightly different from normal pathfinding.
	 * Straight-line movement before diagonal movement is no longer prioritized, because the
	 * original target is moved to the closest reachable tile. To avoid having to move the
	 * original target we instead do the following to favour the closest reachable tile:
	 * - 1) Pick the path with the minimum Euclidean distance (no need to use square root though)
	 * - 2) If a tie occurs, pick the path with minimum travelled distance
	 * - 3) If another tie occurs, pick the path with minimum x-coordinate
	 * - 4) If another tie occurs, pick the path with minimum y-coordinate
	 */
	private boolean updateBestPathWhenUnreachable(int node, int packedPosition)
	{
		boolean update = false;

		final int travelledDistance = graph.cost(node);
		for (int target : targets.points())
		{
			int remainingDistance = WorldPointUtil.distanceBetween(target, packedPosition, WorldPointUtil.EUCLIDEAN_SQUARED_DISTANCE_METRIC);
			int x = WorldPointUtil.unpackWorldX(packedPosition);
			int y = WorldPointUtil.unpackWorldY(packedPosition);
			if ((remainingDistance < bestRemainingDistance) ||
				(remainingDistance == bestRemainingDistance && travelledDistance < bestTravelledDistance) ||
				(remainingDistance == bestRemainingDistance && travelledDistance == bestTravelledDistance && x < bestX) ||
				(remainingDistance == bestRemainingDistance && travelledDistance == bestTravelledDistance && x == bestX && y < bestY))
			{
				bestRemainingDistance = remainingDistance;
				bestTravelledDistance = travelledDistance;
				bestX = x;
				bestY = y;
				bestLastNode = node;
				pathNeedsUpdate = true;
				update = true;
			}
		}

		return update;
	}

	private void updateCustomPathWhenUnreachable(int node, int packedPosition)
	{
		if (targets.size() <= 1 || shortestAcceptedNode != NodeGraph.NO_NODE)
		{
			return;
		}

		final boolean banked = graph.bankVisited(node);
		for (int target : targets.points())
		{
			if (goals.acceptsTarget(target, banked)
				&& WorldPointUtil.distanceBetween(target, packedPosition, WorldPointUtil.MANHATTAN_DISTANCE_METRIC) <= config.getUnreachableTargetDistance())
			{
				shortestAcceptedNode = node;
				shortestAcceptedTarget = target;
				return;
			}
		}
	}

	/**
	 * Update wilderness level based on the current node position.
	 */
	private void updateWildernessLevel(int packedPosition)
	{
		if (wildernessLevel > 0)
		{
			// These are overlapping boundaries, so if the node isn't in level 30, it's in 0-29
			// likewise, if the node isn't in level 20, it's in 0-19
			if (wildernessLevel > 30 && !WildernessChecker.isInLevel30Wilderness(packedPosition))
			{
				wildernessLevel = 30;
			}
			if (wildernessLevel > 20 && !WildernessChecker.isInLevel20Wilderness(packedPosition))
			{
				wildernessLevel = 20;
			}
			if (wildernessLevel > 0 && !WildernessChecker.isInWilderness(packedPosition))
			{
				wildernessLevel = 0;
			}
		}
	}

	@Override
	public void run()
	{
		stats.start();
		boundary.addFirst(graph.createStart(start));

		// The cutoff counts time without progress towards the target.
		SearchDeadline deadline = new SearchDeadline(config.getCalculationCutoffMillis());

		// When every target is a blocked tile that no transport lands on and no
		// walkable tile exists within the unreachable distance, no node can ever
		// satisfy the goal set — skip the search instead of exhausting the map.
		while (!cancelled && hasViableGoal && (!boundary.isEmpty() || !pending.isEmpty()))
		{
			int boundaryHead = boundary.peekFirst();
			int pendingHead = pending.peek();

			int node;
			// On a cost tie the pending heap wins: a queued transport that is strictly
			// cheaper than the walking route must claim its destination before an
			// equal-cost boundary node can expand and emit a competing walking edge.
			if (pendingHead != NodeGraph.NO_NODE
				&& (boundaryHead == NodeGraph.NO_NODE || graph.compareCost(pendingHead) <= graph.cost(boundaryHead)))
			{
				node = pending.poll();

				// Every node in pending is transport-flagged (transports and bank-visit
				// transitions; walking tiles and abstract nodes never enter it) and none
				// of them claimed their destination at enqueue. The first, cheapest,
				// dequeue wins the tile; later queued duplicates for the same tile are
				// dropped here.
				int packed = graph.packedPosition(node);
				boolean bank = graph.bankVisited(node);
				if (visited.get(packed, bank))
				{
					continue;
				}
				visited.set(packed, bank);
			}
			else
			{
				node = boundary.pollFirst();
			}
			if (node == NodeGraph.NO_NODE)
			{
				continue;
			}
			// Read the node's tile-ness and position once; every graph.xxx(id) re-indexes a backing
			// array, and these are used by several of the checks below.
			final boolean nodeIsTile = graph.isTile(node);
			final int nodePacked = nodeIsTile ? graph.packedPosition(node) : WorldPointUtil.UNDEFINED;
			if (nodeIsTile)
			{
				updateWildernessLevel(nodePacked);

				if (goals.accepts(nodePacked, graph.bankVisited(node)))
				{
					bestLastNode = node;
					reachedTarget = nodePacked;
					if (shortestAcceptedNode != NodeGraph.NO_NODE)
					{
						bestLastNode = shortestAcceptedNode;
						reachedTarget = shortestAcceptedTarget;
					}
					pathNeedsUpdate = true;
					terminationReason = PathTerminationReason.TARGET_REACHED;
					break;
				}

				if (updateBestPathWhenUnreachable(node, nodePacked))
				{
					deadline.progressed();
				}
				updateCustomPathWhenUnreachable(node, nodePacked);
			}

			if (deadline.expired())
			{
				terminationReason = PathTerminationReason.CUTOFF_REACHED;
				break;
			}

			addNeighbors(node, nodeIsTile, nodePacked);
		}

		if (cancelled)
		{
			terminationReason = PathTerminationReason.CANCELLED;
		}
		else if (terminationReason == null)
		{
			terminationReason = PathTerminationReason.SEARCH_EXHAUSTED;
		}

		// Materialise the final path and closest reached tile on the worker thread, publish them,
		// then release the large node graph. Once done is set the render thread serves finalPath
		// and never touches the released graph, so this is race-free with progressive rendering.
		int lastNode = bestLastNode;
		if (lastNode != NodeGraph.NO_NODE)
		{
			finalPath = graph.getPathSteps(lastNode);
			closestReachedPoint = graph.getClosestTilePosition(lastNode);
			finalPathCost = graph.cost(lastNode);
			if (reachedTarget != WorldPointUtil.UNDEFINED)
			{
				arrival = goals.arrival(reachedTarget, graph.bankVisited(lastNode));
			}
		}
		else
		{
			finalPath = pathSteps;
			closestReachedPoint = start;
			finalPathCost = PathfinderResult.NO_PATH_COST;
		}

		done = !cancelled;

		boundary.clear();
		visited.clear();
		pending.clear();
		graph.release();

		stats.end(); // Include cleanup in stats to get the total cost of pathfinding

		if (completionCallback != null)
		{
			completionCallback.run();
		}
	}

	public static class PathfinderStats extends shortestpath.pathfinder.PathfinderStats
	{
	}
}

package shortestpath.pathfinder;

/**
 * Which engine computes a route.
 *
 * <p>{@link #ASTAR} is opt-in and matches legacy on reachability and legality, but two
 * cost-level divergences are deliberate: transports recorded with a zero duration are
 * taken at that cost, so free hops legacy's ordering never exploited can appear in a
 * route; and legacy's queue-ordering penalty for chaining onto a shared-destination
 * transport (e.g. a one-tick hop that lands on another transport's origin) is not
 * reproduced, so such chains can price differently. Both affect the route's cost, not
 * whether it is valid.
 */
public enum PathfinderBackend
{
	LEGACY("Legacy"),
	ASTAR("A*");

	private final String displayName;

	PathfinderBackend(String displayName)
	{
		this.displayName = displayName;
	}

	@Override
	public String toString()
	{
		return displayName;
	}
}

