		}

		@Override
		public String toString()
		{
			return "RoutingStaticBuilder.Diagnostics{"
				+ "totalMs=" + (totalNanos / 1_000_000) + ", enumerateWalkableMs=" + (enumerateWalkableNanos / 1_000_000)
				+ ", naturalComponentsMs=" + (naturalComponentsNanos / 1_000_000)
				+ ", cutValidationMs=" + (cutValidationNanos / 1_000_000)
				+ ", routingComponentsMs=" + (routingComponentsNanos / 1_000_000)
				+ ", reachabilityMs=" + (reachabilityNanos / 1_000_000)
				+ ", searchTilesMs=" + (searchTilesNanos / 1_000_000)
				+ ", sitesAndAttachmentsMs=" + (sitesAndAttachmentsNanos / 1_000_000)
				+ ", sparseNetworkMs=" + (sparseNetworkNanos / 1_000_000)
				+ ", validateMs=" + (validateNanos / 1_000_000)
				+ ", walkableTileCount=" + walkableTileCount + ", naturalComponentCount=" + naturalComponentCount
				+ ", routingComponentCount=" + routingComponentCount
				+ ", largestRoutingComponentSize=" + largestRoutingComponentSize
				+ ", reachableNaturalComponentCount=" + reachableNaturalComponentCount
				+ ", inputCutCount=" + inputCutCount + ", duplicateCutCount=" + duplicateCutCount
				+ ", invalidCutCount=" + invalidCutCount + ", nonSeparatingCutCount=" + nonSeparatingCutCount
				+ ", crossingCount=" + crossingCount + ", searchTileCount=" + searchTileCount
				+ ", siteCount=" + siteCount + ", reachableBankCount=" + reachableBankCount + "}";
		}
	}

	/** The derived static world plus the diagnostics collected while building it. */
	public static final class Result
	{
		public final RoutingStatic routingStatic;
		public final Diagnostics diagnostics;

		Result(RoutingStatic routingStatic, Diagnostics diagnostics)
		{
			this.routingStatic = routingStatic;
			this.diagnostics = diagnostics;
		}
	}

	/**
	 * Builds the derived {@link RoutingStatic}.
	 *
	 * @param collision      authoritative walking-neighbour source.
	 * @param rawTransports  the plugin's raw, unfiltered, account-independent transports, keyed by
	 *                       packed origin tile or {@link shortestpath.WorldPointUtil#UNDEFINED} for
	 *                       origin-less (global) transports/teleports &mdash;
	 *                       {@code TransportLoader.loadAllFromResources()}'s direct result. Must
	 *                       include every {@link TransportType}, seasonal included.
	 * @param bankTiles      the whole bank destination set ({@code Destination.tsv}'s "bank" column),
	 *                       with no account filtering.
	 * @param cuts           candidate separator cut edges as packed {@code (from, to)} pairs:
	 *                       {@code cuts[2*i]}/{@code cuts[2*i+1]}.
	 */
	public static Result build(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports,
		Set<Integer> bankTiles, int[] cuts) throws IOException
	{
		return build(collision, rawTransports, bankTiles, cuts, SEED_TILE);
	}

	/**
	 * Same as {@link #build(CollisionMap, Map, Set, int[])}, but with an overridable structural
	 * reachability seed tile. Production callers must use the four-argument overload (the
	 * production seed policy is not configurable); this overload exists so synthetic-world unit
	 * tests can exercise structural reachability without embedding the real seed tile
	 * {@code (3221, 3218, 0)} in every tiny test world.
	 */
	public static Result build(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports,
		Set<Integer> bankTiles, int[] cuts, int seedTile) throws IOException
	{
		long totalStarted = System.nanoTime();

		long stepStarted = System.nanoTime();
		TileSelection selected = discoverCandidateTiles(collision, rawTransports, cuts, seedTile);
		WalkableTiles walkable = enumerateWalkableTiles(collision, selected);
		selected = null;
		int walkableTileCount = walkable.tiles.length;
		long enumerateWalkableNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		int[] componentIds = new int[walkable.tiles.length];
		int naturalComponentCount = floodFillComponents(walkable, null, componentIds);
		long naturalComponentsNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		CutSet cutSet = validateCuts(cuts, walkable);
		long cutValidationNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		boolean[] reachableNatural = structuralReachability(collision, walkable, componentIds, naturalComponentCount,
			rawTransports, seedTile);
		int reachableNaturalCount = count(reachableNatural);
		BitSet reachableTiles = new BitSet(walkable.tiles.length);
		for (int i = 0; i < componentIds.length; i++)
		{
			if (reachableNatural[componentIds[i]]) reachableTiles.set(i);
		}
		long reachabilityNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		// Reachability now needs only one bit per tile, so the next pass can reuse the labels.
		Arrays.fill(componentIds, 0);
		int maxRoutingComponentId = floodFillComponents(walkable, cutSet.blocked, componentIds);
		// Component arrays are indexed by id, so capacity is maxComponentId + 1 with empty groups retained.
		int routingComponentCount = maxRoutingComponentId + 1;
		int largestRoutingComponentSize = largestGroup(componentIds, maxRoutingComponentId);
		long routingComponentsNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		SearchTiles search = buildSearchTiles(walkable, componentIds, reachableTiles, routingComponentCount);
		long searchTilesNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		List<Crossing> crossings = buildCrossings(cutSet.valid, componentIds, walkable);
		// Release the scratch map before assembling and validating the final routing data.
		walkable = null;
		componentIds = null;
		int nonSeparating = cutSet.valid.size() - crossings.size();
		SitesAndAttachments sites = buildSites(rawTransports, bankTiles, crossings, search, collision,
			routingComponentCount);
		long sitesAndAttachmentsNanos = System.nanoTime() - stepStarted;

		stepStarted = System.nanoTime();
		SparseWalkingNetworkBuilder.Result sparse = SparseWalkingNetworkBuilder.build(sites.siteTiles,
			sites.siteComponentOffsets, sites.siteComponentIds);
		long sparseNetworkNanos = System.nanoTime() - stepStarted;

		int[] crossingFrom = new int[crossings.size()];
		int[] crossingTo = new int[crossings.size()];
		int[] crossingCost = new int[crossings.size()];
		for (int i = 0; i < crossings.size(); i++)
		{
			Crossing crossing = crossings.get(i);
			crossingFrom[i] = binarySearchUnsigned(sites.siteTiles, crossing.fromTile);
			crossingTo[i] = binarySearchUnsigned(sites.siteTiles, crossing.toTile);
			crossingCost[i] = 1;
		}

		stepStarted = System.nanoTime();
		RoutingStatic result = RoutingStatic.takeOwnership(search.tiles, search.components, search.masks, search.northOffsets,
			search.southOffsets, sites.siteTiles, sites.siteComponentOffsets, sites.siteComponentIds, routingComponentCount,
			sites.componentSiteOffsets, sites.componentSiteIds, sites.reachableBankTiles, crossingFrom, crossingTo,
			crossingCost, sparse.originalCount, sparse.vertexCount, sparse.steinerCount, sparse.undirectedEdgeCount,
			sparse.adjacencyCount(), sparse.offsets, sparse.destinations, sparse.weights);
		long validateNanos = System.nanoTime() - stepStarted;

		long totalNanos = System.nanoTime() - totalStarted;
		Diagnostics diagnostics = new Diagnostics(enumerateWalkableNanos, naturalComponentsNanos, cutValidationNanos,
			routingComponentsNanos, reachabilityNanos, searchTilesNanos, sitesAndAttachmentsNanos, sparseNetworkNanos,
			validateNanos, totalNanos, walkableTileCount, naturalComponentCount, maxRoutingComponentId,
			largestRoutingComponentSize, reachableNaturalCount, cuts.length / 2, cutSet.duplicateCount,
			cutSet.invalidCount, nonSeparating, crossings.size(), search.tiles.length, sites.siteTiles.length,
			sites.reachableBankTiles.length);
		return new Result(result, diagnostics);
	}

	/**
	 * The ordinary walking graph over every walkable tile, with natural components and structural
	 * reachability computed exactly as {@link #build} does. The tooling cut generator partitions
	 * this graph, so generated cuts and the runtime agree on what a walking edge is.
	 */
	public static final class WalkingGraph
	{
		private final WalkableTiles walkable;
		private final int[] naturalId;
		private final int naturalComponentCount;
		private final boolean[] reachableNatural;

		private WalkingGraph(WalkableTiles walkable, int[] naturalId, int naturalComponentCount,
			boolean[] reachableNatural)
		{
			this.walkable = walkable;
			this.naturalId = naturalId;
			this.naturalComponentCount = naturalComponentCount;
			this.reachableNatural = reachableNatural;
		}

		/** Number of walkable tiles; tile indexes follow ascending unsigned packed order. */
		public int tileCount()
		{
			return walkable.tiles.length;
		}

		public int tile(int index)
		{
			return walkable.tiles[index];
		}

		/** Index of a walkable tile, or -1 when the tile is not walkable. */
		public int indexOf(int tile)
		{
			return walkable.index.get(tile);
		}

		/** Natural component id of a tile index, in {@code 1..naturalComponentCount()}. */
		public int naturalComponent(int index)
		{
			return naturalId[index];
		}

		public int naturalComponentCount()
		{
			return naturalComponentCount;
		}

		public boolean isStructurallyReachable(int naturalComponent)
		{
			return reachableNatural[naturalComponent];
		}

		/** Indexes of the walkable tiles reachable in one ordinary walking step. */
		public int[] neighbours(int index)
		{
			int[] tiles = ordinaryNeighborsFromMask(walkable.tiles[index], walkable.masks[index]);
			int[] result = new int[tiles.length];
			int count = 0;
			for (int tile : tiles)
			{
				int neighbour = walkable.index.get(tile);
				if (neighbour >= 0) result[count++] = neighbour;
			}
			return count == result.length ? result : Arrays.copyOf(result, count);
		}
	}

	/** Builds the walking graph used for cut generation; see {@link WalkingGraph}. */
	public static WalkingGraph walkingGraph(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports)
	{
		return walkingGraph(collision, rawTransports, SEED_TILE);
	}

	static WalkingGraph walkingGraph(CollisionMap collision, Map<Integer, Set<Transport>> rawTransports, int seedTile)
	{
		WalkableTiles walkable = enumerateWalkableTiles(collision);
		int[] naturalId = new int[walkable.tiles.length];
		int naturalComponentCount = floodFillComponents(walkable, null, naturalId);
		boolean[] reachable = structuralReachability(collision, walkable, naturalId, naturalComponentCount,
			rawTransports, seedTile);
		return new WalkingGraph(walkable, naturalId, naturalComponentCount, reachable);
	}

	// ---- Tile selection and enumeration in ascending unsigned packed order ----

	private static final class WalkableTiles
	{
		final int[] tiles;
		final byte[] masks;
		final TileIndex index;

		WalkableTiles(int[] tiles, byte[] masks)
		{
			this.tiles = tiles;
			this.masks = masks;
			this.index = new TileIndex(tiles);
		}
	}

	private static WalkableTiles enumerateWalkableTiles(CollisionMap collision)
	{
		return enumerateWalkableTiles(collision, TileSelection.allWalkable(collision));
	}

	private static WalkableTiles enumerateWalkableTiles(CollisionMap collision, TileSelection selected)
	{
		int[] tiles = new int[selected.tileCount()];
		byte[] masks = new byte[tiles.length];
		int next = 0;
		// Packed tiles sort by plane, then y, then x; emit that order without sorting or copying.
		for (int plane = 0; plane < 4; plane++)
		{
			for (int ry = 0; ry < selected.height; ry++)
			{
				int baseY = (selected.minY + ry) * REGION_SIZE;
				for (int ly = 0; ly < REGION_SIZE; ly++)
				{
					int rowStart = ly * REGION_SIZE;
					for (int rx = 0; rx < selected.width; rx++)
					{
						BitSet region = selected.regions[(rx + ry * selected.width) * 4 + plane];
						if (region == null) continue;
						int baseX = (selected.minX + rx) * REGION_SIZE;
						for (int bit = region.nextSetBit(rowStart); bit >= 0 && bit < rowStart + REGION_SIZE;
							bit = region.nextSetBit(bit + 1))
						{
							int tile = WorldPointUtil.packWorldPoint(baseX + (bit & (REGION_SIZE - 1)), baseY + ly, plane);
							tiles[next] = tile;
							masks[next++] = collision.ordinaryWalkingMask(tile);
						}
					}
				}
			}
		}
		return new WalkableTiles(tiles, masks);
	}

	/** Keep endpoint-connected land before allocating arrays; open sea can otherwise look walkable. */
	private static TileSelection discoverCandidateTiles(CollisionMap collision,
		Map<Integer, Set<Transport>> rawTransports, int[] cuts, int seedTile)
	{
		TileSelection selected = new TileSelection(collision);
		IntDeque queue = new IntDeque(4096);
		selected.attach(seedTile, collision, queue);
		if (queue.isEmpty())
		{
			throw new IllegalStateException("missing structural reachability seed: no natural component attaches to the production seed tile");
		}
		for (Set<Transport> transports : rawTransports.values())
		{
			for (Transport transport : transports)
			{
				if (transport.getOrigin() != WorldPointUtil.UNDEFINED)
					selected.attach(transport.getOrigin(), collision, queue);
				selected.attach(transport.getDestination(), collision, queue);
			}
		}
		// Preserve cut diagnostics and crossings even when their land is unreachable.
		for (int tile : cuts) selected.add(tile, collision, queue);
		while (!queue.isEmpty())
		{
			int tile = queue.pollFirst();
			int x = WorldPointUtil.unpackWorldX(tile);
			int y = WorldPointUtil.unpackWorldY(tile);
			int plane = WorldPointUtil.unpackWorldPlane(tile);
			int mask = Byte.toUnsignedInt(collision.ordinaryWalkingMask(tile));
			for (int bit = 0; bit < 8; bit++)
			{
				if ((mask & (1 << bit)) != 0)
					selected.add(WorldPointUtil.packWorldPoint(x + NEIGHBOR_DX[bit], y + NEIGHBOR_DY[bit], plane), collision, queue);
			}
		}
		return selected;
	}

	/** One bit per discovered tile, allocating bits only for regions the discovery reaches. */
	private static final class TileSelection
	{
		final BitSet[] regions;
		final int minX, minY, width, height;

		TileSelection(CollisionMap collision)
		{
			SplitFlagMap.RegionExtent extent = collision.regionExtent();
			minX = extent.getMinX();
			minY = extent.getMinY();
			width = extent.getWidth() + 1;
			height = extent.getHeight() + 1;
			regions = new BitSet[width * height * 4];
		}

		static TileSelection allWalkable(CollisionMap collision)
		{
			TileSelection selected = new TileSelection(collision);
			for (int ry = 0; ry < selected.height; ry++)
			{
				for (int rx = 0; rx < selected.width; rx++)
				{
					int region = rx + ry * selected.width;
					int baseX = (selected.minX + rx) * REGION_SIZE;
					int baseY = (selected.minY + ry) * REGION_SIZE;
					for (int plane = 0; plane < Math.min(4, collision.getRegionPlaneCounts(region)); plane++)
					{
						for (int ly = 0; ly < REGION_SIZE; ly++)
						{
							for (int lx = 0; lx < REGION_SIZE; lx++)
							{
								if (!collision.isBlocked(baseX + lx, baseY + ly, plane))
									selected.mark(region * 4 + plane, ly * REGION_SIZE + lx);
							}
						}
					}
				}
			}
			return selected;
		}

		int tileCount()
		{
			int count = 0;
			for (BitSet region : regions)
				if (region != null) count += region.cardinality();
			return count;
		}

		private void mark(int region, int bit)
		{
			BitSet bits = regions[region];
			if (bits == null) regions[region] = bits = new BitSet(REGION_SIZE * REGION_SIZE);
			bits.set(bit);
		}

		void attach(int tile, CollisionMap collision, IntDeque queue)
		{
			if (!collision.isBlocked(WorldPointUtil.unpackWorldX(tile), WorldPointUtil.unpackWorldY(tile),
				WorldPointUtil.unpackWorldPlane(tile)))
			{
				add(tile, collision, queue);
			}
			else
			{
				for (int neighbor : collision.ordinaryWalkingNeighbors(tile)) add(neighbor, collision, queue);
			}
		}

		void add(int tile, CollisionMap collision, IntDeque queue)
		{
			int x = WorldPointUtil.unpackWorldX(tile);
			int y = WorldPointUtil.unpackWorldY(tile);
			int plane = WorldPointUtil.unpackWorldPlane(tile);
			int rx = x / REGION_SIZE - minX, ry = y / REGION_SIZE - minY;
			if (rx < 0 || rx >= width || ry < 0 || ry >= height) return;
			int region = rx + ry * width;
			if (plane >= collision.getRegionPlaneCounts(region)) return;
			int index = region * 4 + plane;
			int bit = (y & (REGION_SIZE - 1)) * REGION_SIZE + (x & (REGION_SIZE - 1));
			BitSet bits = regions[index];
			if (bits != null && bits.get(bit)) return;
			if (collision.isBlocked(x, y, plane)) return;
			mark(index, bit);
			queue.addLast(tile);
		}
	}

	// ---- Step 1/3: flood fill (natural when blocked==null, routing when blocked is a valid-cut set) ----

	/** Returns the number of components assigned (ids {@code 1..count}), 0 if there were no walkable tiles. */
	private static int floodFillComponents(WalkableTiles walkable, LongOpenHashSet blocked, int[] componentOut)
	{
		int n = walkable.tiles.length;
		IntDeque queue = new IntDeque(4096);
		int nextId = 1;
		for (int seed = 0; seed < n; seed++)
		{
			if (componentOut[seed] != 0)
			{
				continue;
			}
			queue.addLast(seed);
			componentOut[seed] = nextId;
			while (!queue.isEmpty())
			{
				int position = queue.pollFirst();
				int tile = walkable.tiles[position];
				int x = WorldPointUtil.unpackWorldX(tile);
				int y = WorldPointUtil.unpackWorldY(tile);
				int plane = WorldPointUtil.unpackWorldPlane(tile);
				int mask = Byte.toUnsignedInt(walkable.masks[position]);
				for (int bit = 0; bit < 8; bit++)
				{
					if ((mask & (1 << bit)) == 0)
					{
						continue;
					}
					int neighbor = WorldPointUtil.packWorldPoint(x + NEIGHBOR_DX[bit], y + NEIGHBOR_DY[bit], plane);
					int neighborPosition = walkable.index.get(neighbor);
					if (neighborPosition < 0 || componentOut[neighborPosition] != 0)
					{
						continue;
					}
					if (blocked != null && blocked.contains(canonicalKey(tile, neighbor)))
					{
						continue;
					}
					componentOut[neighborPosition] = nextId;
					queue.addLast(neighborPosition);
				}
			}
			nextId++;
		}
		return nextId - 1;
	}

	// Clockwise 0-N,1-NE,2-E,3-SE,4-S,5-SW,6-W,7-NW; the bit layout of CollisionMap.ordinaryWalkingMask.
	private static final int[] NEIGHBOR_DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] NEIGHBOR_DY = {1, 1, 0, -1, -1, -1, 0, 1};

	private static int[] ordinaryNeighborsFromMask(int tile, byte maskByte)
	{
		int mask = Byte.toUnsignedInt(maskByte);
		int x = WorldPointUtil.unpackWorldX(tile);
		int y = WorldPointUtil.unpackWorldY(tile);
		int z = WorldPointUtil.unpackWorldPlane(tile);
		int[] result = new int[Integer.bitCount(mask)];
		int count = 0;
		for (int bit = 0; bit < 8; bit++)
		{
			if ((mask & (1 << bit)) != 0)
			{
				result[count++] = WorldPointUtil.packWorldPoint(x + NEIGHBOR_DX[bit], y + NEIGHBOR_DY[bit], z);
			}
		}
		return result;
	}

	private static int largestGroup(int[] componentOf, int componentCount)
	{
		if (componentCount <= 0)
		{
			return 0;
		}
		int[] sizes = new int[componentCount + 1];
		for (int component : componentOf)
		{
			sizes[component]++;
		}
		int largest = 0;
		for (int size : sizes)
		{
			largest = Math.max(largest, size);
		}
		return largest;
	}

	// ---- Cuts: validity ("ignore cuts that are not current walking edges") + canonical dedup ----

	private static final class CutSet
	{
		final List<long[]> valid; // each entry {a, b} as raw ints boxed in a long[2] for simplicity
		final LongOpenHashSet blocked;
		final int duplicateCount;
		final int invalidCount;

		CutSet(List<long[]> valid, LongOpenHashSet blocked, int duplicateCount, int invalidCount)
		{
			this.valid = valid;
			this.blocked = blocked;
			this.duplicateCount = duplicateCount;
			this.invalidCount = invalidCount;
		}
	}

	private static CutSet validateCuts(int[] cuts, WalkableTiles walkable)
	{
		HashSet<Long> seenCanonical = new HashSet<>();
		int duplicateCount = 0;
		List<long[]> candidates = new ArrayList<>();
		int pairCount = cuts.length / 2;
		for (int i = 0; i < pairCount; i++)
		{
			int rawA = cuts[2 * i];
			int rawB = cuts[2 * i + 1];
			int a = Integer.compareUnsigned(rawA, rawB) <= 0 ? rawA : rawB;
			int b = Integer.compareUnsigned(rawA, rawB) <= 0 ? rawB : rawA;
			long key = canonicalKey(a, b);
			if (!seenCanonical.add(key))
			{
				duplicateCount++;
				continue;
			}
			candidates.add(new long[] {Integer.toUnsignedLong(a), Integer.toUnsignedLong(b)});
		}
		List<long[]> valid = new ArrayList<>();
		LongOpenHashSet blocked = new LongOpenHashSet(Math.max(16, candidates.size() * 2));
		int invalidCount = 0;
		for (long[] candidate : candidates)
		{
			int a = (int) candidate[0];
			int b = (int) candidate[1];
			int posA = walkable.index.get(a);
			int[] neighborsOfA = posA < 0 ? new int[0] : ordinaryNeighborsFromMask(a, walkable.masks[posA]);
			if (posA < 0 || !contains(neighborsOfA, 0, neighborsOfA.length, b))
			{
				invalidCount++;
				continue;
			}
			valid.add(candidate);
			blocked.add(canonicalKey(a, b));
		}
		return new CutSet(valid, blocked, duplicateCount, invalidCount);
	}

	private static long canonicalKey(int a, int b)
	{
		int min = Integer.compareUnsigned(a, b) <= 0 ? a : b;
		int max = Integer.compareUnsigned(a, b) <= 0 ? b : a;
		return (Integer.toUnsignedLong(min) << 32) | Integer.toUnsignedLong(max);
	}

	// ---- Structural reachability: closure over NATURAL components ----
	// Reachability must use natural, not routing, components: a cut never makes a tile unreachable.
	// The closure is an account-independent overapproximation of the geography routes can use, so it
	// deliberately follows every known transport, seasonal ones included, whatever its requirements.
	// It only prunes components nothing can reach, such as the sea. Whether an account can take a
	// transport is decided later, by PreparedRoutingAccount and the forward search.

	private static boolean[] structuralReachability(CollisionMap collision, WalkableTiles walkable, int[] naturalId,
		int naturalComponentCount, Map<Integer, Set<Transport>> rawTransports, int seedTile)
	{
		Map<Integer, List<Integer>> edges = new HashMap<>();
		Set<Integer> globalDestinations = new HashSet<>();
		for (Set<Transport> set : rawTransports.values())
		{
			for (Transport transport : set)
			{
				int origin = transport.getOrigin();
				int destination = transport.getDestination();

				// attachmentEdges: every endpoint point of every transport, any type, any origin state.
				int[] originAttachments = origin == WorldPointUtil.UNDEFINED ? new int[0]
					: naturalAttachments(origin, walkable, naturalId, collision);
				int[] destinationAttachments = naturalAttachments(destination, walkable, naturalId, collision);
				addAttachmentClique(edges, originAttachments);
				addAttachmentClique(edges, destinationAttachments);

				if (origin == WorldPointUtil.UNDEFINED)
				{
					// globalDestinations: global-teleport destinations.
					for (int naturalComponent : destinationAttachments)
					{
						globalDestinations.add(naturalComponent);
					}
				}
				else
				{
					// transportEdges: local transports, directed origin -> destination.
					for (int fromComponent : originAttachments)
					{
						for (int toComponent : destinationAttachments)
						{
							edges.computeIfAbsent(fromComponent, k -> new ArrayList<>()).add(toComponent);
						}
					}
				}
			}
		}

		int[] seedComponents = naturalAttachments(seedTile, walkable, naturalId, collision);
		if (seedComponents.length == 0)
		{
			throw new IllegalStateException(
				"missing structural reachability seed: no natural component attaches to the production seed tile");
		}

		boolean[] reachable = new boolean[naturalComponentCount + 1];
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		for (int seed : seedComponents)
		{
			if (!reachable[seed])
			{
				reachable[seed] = true;
				queue.add(seed);
			}
		}
		while (!queue.isEmpty())
		{
			int component = queue.poll();
			for (int next : edges.getOrDefault(component, List.of()))
			{
				if (!reachable[next])
				{
					reachable[next] = true;
					queue.add(next);
				}
			}
			for (int global : globalDestinations)
			{
				if (!reachable[global])
				{
					reachable[global] = true;
					queue.add(global);
				}
			}
		}
		return reachable;
	}

	private static void addAttachmentClique(Map<Integer, List<Integer>> edges, int[] attachments)
	{
		if (attachments.length < 2)
		{
			return;
		}
		for (int a : attachments)
		{
			for (int b : attachments)
			{
				if (a != b)
				{
					edges.computeIfAbsent(a, k -> new ArrayList<>()).add(b);
				}
			}
		}
	}

	/**
	 * Natural components a point attaches to: its own component if it is walkable, otherwise
	 * the union of its ordinary walking neighbours' components.
	 */
	private static int[] naturalAttachments(int point, WalkableTiles walkable, int[] naturalId, CollisionMap collision)
	{
		int position = walkable.index.get(point);
		if (position >= 0)
		{
			return new int[] {naturalId[position]};
		}
		int[] neighbors = collision.ordinaryWalkingNeighbors(point);
		int[] buffer = new int[8];
		int count = 0;
		for (int neighbor : neighbors)
		{
			int neighborPosition = walkable.index.get(neighbor);
			if (neighborPosition >= 0)
			{
				int component = naturalId[neighborPosition];
				if (!contains(buffer, 0, count, component))
				{
					buffer[count++] = component;
				}
			}
		}
		return Arrays.copyOf(buffer, count);
	}

	// ---- Section A: search tiles, routing components, walking masks, north/south ----

	private static final class SearchTiles
	{
		final int[] tiles;
		final TileComponents components;
		final char[] northOffsets, southOffsets;
		final byte[] masks;

		SearchTiles(int[] tiles, TileComponents components, byte[] masks, char[] northOffsets, char[] southOffsets)
		{
			this.tiles = tiles;
			this.components = components;
			this.masks = masks;
			this.northOffsets = northOffsets;
			this.southOffsets = southOffsets;
		}
	}

	private static SearchTiles buildSearchTiles(WalkableTiles walkable, int[] routingId,
		BitSet reachableTiles, int componentCount)
	{
		int count = reachableTiles.cardinality();
		int[] tileArray = new int[count];
		TileComponents componentArray = new TileComponents(count, componentCount);
		byte[] maskArray = new byte[count];
		int next = 0;
		for (int i = reachableTiles.nextSetBit(0); i >= 0; i = reachableTiles.nextSetBit(i + 1))
		{
			tileArray[next] = walkable.tiles[i];
			componentArray.set(next, routingId[i]);
			maskArray[next++] = walkable.masks[i];
		}
		char[] north = new char[tileArray.length];
		char[] south = new char[tileArray.length];
		for (int i = 0; i < tileArray.length; i++)
		{
			int y = WorldPointUtil.unpackWorldY(tileArray[i]);
			int n = y == 32767 ? -1 : binarySearchUnsigned(tileArray, tileArray[i] + Y_UNIT);
			int s = y == 0 ? -1 : binarySearchUnsigned(tileArray, tileArray[i] - Y_UNIT);
			// Adjacent rows contain at most 32768 distinct x coordinates, so these offsets fit.
			north[i] = n < 0 ? 0 : (char) (n - i);
			south[i] = s < 0 ? 0 : (char) (i - s);
		}
		return new SearchTiles(tileArray, componentArray, maskArray, north, south);
	}

	// ---- Section: routing components / crossings ----

	private static final class Crossing
	{
		final int fromTile, toTile;

		Crossing(int fromTile, int toTile)
		{
			this.fromTile = fromTile;
			this.toTile = toTile;
		}
	}

	private static List<Crossing> buildCrossings(List<long[]> validCuts, int[] routingId, WalkableTiles walkable)
	{
		List<Crossing> crossings = new ArrayList<>();
		for (long[] cut : validCuts)
		{
			int a = (int) cut[0];
			int b = (int) cut[1];
			int posA = walkable.index.get(a);
			int posB = walkable.index.get(b);
			if (posA < 0 || posB < 0 || routingId[posA] == routingId[posB])
			{
				continue;
			}
			crossings.add(new Crossing(a, b));
		}
		crossings.sort((left, right) ->
		{
			int cmp = Integer.compareUnsigned(left.fromTile, right.fromTile);
			return cmp != 0 ? cmp : Integer.compareUnsigned(left.toTile, right.toTile);
		});
		return crossings;
	}

	// ---- Sections B/C/D/E: sites and attachments ----

	private static final class SitesAndAttachments
	{
		final int[] siteTiles, siteComponentOffsets, siteComponentIds, componentSiteOffsets, componentSiteIds;
		final int[] reachableBankTiles;

		SitesAndAttachments(int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds,
			int[] componentSiteOffsets, int[] componentSiteIds, int[] reachableBankTiles)
		{
			this.siteTiles = siteTiles;
			this.siteComponentOffsets = siteComponentOffsets;
			this.siteComponentIds = siteComponentIds;
			this.componentSiteOffsets = componentSiteOffsets;
			this.componentSiteIds = componentSiteIds;
			this.reachableBankTiles = reachableBankTiles;
		}
	}

	private static SitesAndAttachments buildSites(Map<Integer, Set<Transport>> rawTransports, Set<Integer> bankTiles,
		List<Crossing> crossings, SearchTiles search, CollisionMap collision, int routingComponentCount)
	{
		HashSet<Integer> siteSet = new HashSet<>();
		for (Set<Transport> set : rawTransports.values())
		{
			for (Transport transport : set)
			{
				if (transport.getOrigin() != WorldPointUtil.UNDEFINED)
				{
					siteSet.add(transport.getOrigin());
				}
				siteSet.add(transport.getDestination());
			}
		}
		for (Crossing crossing : crossings)
		{
			siteSet.add(crossing.fromTile);
			siteSet.add(crossing.toTile);
		}
		List<Integer> reachableBanks = new ArrayList<>();
		for (int bank : bankTiles)
		{
			if (routingAttachments(bank, search, collision).length > 0)
			{
				reachableBanks.add(bank);
				siteSet.add(bank);
			}
		}

		int[] siteTiles = toSortedUnsignedArray(siteSet);
		int[] reachableBankTiles = toSortedUnsignedArray(reachableBanks);

		int[] siteComponentOffsets = new int[siteTiles.length + 1];
		int[][] perSite = new int[siteTiles.length][];
		int totalSiteComponentValues = 0;
		for (int i = 0; i < siteTiles.length; i++)
		{
			perSite[i] = routingAttachments(siteTiles[i], search, collision);
			siteComponentOffsets[i + 1] = siteComponentOffsets[i] + perSite[i].length;
			totalSiteComponentValues += perSite[i].length;
		}
		int[] siteComponentIds = new int[totalSiteComponentValues];
		int cursor = 0;
		for (int[] components : perSite)
		{
			for (int component : components)
			{
				siteComponentIds[cursor++] = component;
			}
		}

		int[] groupCounts = new int[routingComponentCount];
		for (int component : siteComponentIds)
		{
			groupCounts[component]++;
		}
		int[] componentSiteOffsets = new int[routingComponentCount + 1];
		for (int i = 0; i < routingComponentCount; i++)
		{
			componentSiteOffsets[i + 1] = componentSiteOffsets[i] + groupCounts[i];
		}
		int[] componentSiteIds = new int[componentSiteOffsets[routingComponentCount]];
		int[] fillCursor = Arrays.copyOf(componentSiteOffsets, componentSiteOffsets.length);
		for (int site = 0; site < siteTiles.length; site++)
		{
			for (int p = siteComponentOffsets[site]; p < siteComponentOffsets[site + 1]; p++)
			{
				int component = siteComponentIds[p];
				componentSiteIds[fillCursor[component]++] = site;
			}
		}

		return new SitesAndAttachments(siteTiles, siteComponentOffsets, siteComponentIds, componentSiteOffsets,
			componentSiteIds, reachableBankTiles);
	}

	/**
	 * Routing components a point attaches to, using the final reachability-filtered search tiles:
	 * the tile's own component if it is a search tile, otherwise those of its walking neighbours.
	 * This matches {@link RoutingStatic#attachments} at runtime.
	 */
	private static int[] routingAttachments(int point, SearchTiles search, CollisionMap collision)
	{
		int index = binarySearchUnsigned(search.tiles, point);
		if (index >= 0)
		{
			return new int[] {search.components.get(index)};
		}
		int[] neighbors = collision.ordinaryWalkingNeighbors(point);
		int[] buffer = new int[8];
		int count = 0;
		for (int neighbor : neighbors)
		{
			int neighborIndex = binarySearchUnsigned(search.tiles, neighbor);
			if (neighborIndex >= 0)
			{
				int component = search.components.get(neighborIndex);
				if (!contains(buffer, 0, count, component))
				{
					buffer[count++] = component;
				}
			}
		}
		Arrays.sort(buffer, 0, count);
		return Arrays.copyOf(buffer, count);
	}

	// ---- Small shared utilities ----

	private static boolean contains(int[] values, int start, int end, int target)
	{
		for (int i = start; i < end; i++)
		{
			if (values[i] == target)
			{
				return true;
			}
		}
		return false;
	}

	private static int count(boolean[] values)
	{
		int count = 0;
		for (boolean value : values)
		{
			if (value)
			{
				count++;
			}
		}
		return count;
	}

	private static int[] toSortedUnsignedArray(java.util.Collection<Integer> values)
	{
		int[] result = new int[values.size()];
		int i = 0;
		for (int value : values)
		{
			result[i++] = value;
		}
		sortUnsigned(result);
		return result;
	}

	private static void sortUnsigned(int[] values)
	{
		for (int i = 0; i < values.length; i++)
		{
			values[i] ^= Integer.MIN_VALUE;
		}
		Arrays.sort(values);
		for (int i = 0; i < values.length; i++)
		{
			values[i] ^= Integer.MIN_VALUE;
		}
	}

	private static int nextPowerOfTwo(int value)
	{
		int highest = Integer.highestOneBit(value);
		return highest == value ? highest : highest * 2;
	}

	private static int binarySearchUnsigned(int[] values, int target)
	{
		int low = 0, high = values.length - 1;
		while (low <= high)
		{
			int middle = low + (high - low) / 2;
			int compare = Integer.compareUnsigned(values[middle], target);
			if (compare == 0)
			{
				return middle;
			}
			if (compare < 0)
			{
				low = middle + 1;
			}
			else
			{
				high = middle - 1;
			}
		}
		return -1;
	}

	/** Each entry covers 64 packed tiles; set bits give membership and the offset from the first tile. */
	private static final class TileIndex
	{
		private final int[] tiles;
		private final int[] slots; // slots[h] - 1 == index; 0 == empty
		private final long[] present;
		private final int mask;

		TileIndex(int[] sortedTiles)
		{
			int groups = 0;
			for (int i = 0; i < sortedTiles.length; i++)
			{
				if (i == 0 || (sortedTiles[i] >>> 6) != (sortedTiles[i - 1] >>> 6)) groups++;
			}
			int capacity = nextPowerOfTwo(Math.max(16, groups) * 2);
			tiles = sortedTiles;
			slots = new int[capacity];
			present = new long[capacity];
			mask = capacity - 1;
			for (int i = 0; i < sortedTiles.length; i++)
			{
				int group = sortedTiles[i] >>> 6;
				int h = hash(group) & mask;
				while (slots[h] != 0 && (tiles[slots[h] - 1] >>> 6) != group)
				{
					h = (h + 1) & mask;
				}
				if (slots[h] == 0) slots[h] = i + 1;
				present[h] |= 1L << (sortedTiles[i] & 63);
			}
		}

		int get(int tile)
		{
			int group = tile >>> 6;
			long bit = 1L << (tile & 63);
			int h = hash(group) & mask;
			while (slots[h] != 0)
			{
				int first = slots[h] - 1;
				if ((tiles[first] >>> 6) == group)
				{
					return (present[h] & bit) == 0 ? -1 : first + Long.bitCount(present[h] & (bit - 1));
				}
				h = (h + 1) & mask;
			}
			return -1;
		}

		private static int hash(int value)
		{
			int h = value * 0x9E3779B1;
			return h ^ (h >>> 16);
		}
	}

	/** Open-addressing packed 64-bit canonical-cut-pair set. */
	private static final class LongOpenHashSet
	{
		private long[] keys;
		private int mask;
		private int size;

		LongOpenHashSet(int expectedSize)
		{
			int capacity = nextPowerOfTwo(Math.max(16, expectedSize) * 2);
			keys = new long[capacity];
			Arrays.fill(keys, Long.MIN_VALUE);
			mask = capacity - 1;
		}

		void add(long value)
		{
			int h = hash(value) & mask;
			while (keys[h] != Long.MIN_VALUE)
			{
				if (keys[h] == value)
				{
					return;
				}
				h = (h + 1) & mask;
			}
			keys[h] = value;
			size++;
		}

		boolean contains(long value)
		{
			int h = hash(value) & mask;
			while (keys[h] != Long.MIN_VALUE)
			{
				if (keys[h] == value)
				{
					return true;
				}
				h = (h + 1) & mask;
			}
			return false;
		}

		private static int hash(long value)
		{
			long h = value * 0x9E3779B97F4A7C15L;
			h ^= h >>> 32;
			return (int) h;
		}
	}
}

package shortestpath.pathfinder.astar;

import java.util.function.IntPredicate;
import shortestpath.pathfinder.WildernessChecker;

/**
 * Per-search positional restrictions applied on top of the prepared graph, mirroring the gates
 * the legacy pathfinder checks while relaxing edges ({@code avoidWilderness} and the league's
 * always-blocked region).
 *
 * <p>They are per-search rather than part of the account identity: the underlying setting can
 * change on every config refresh, and enforcing them removes edges instead of adding any, so
 * the prepared target's heuristic only ever under-estimates the restricted graph's distances and
 * stays admissible. Sessions may therefore reuse prepared accounts, targets and heuristics
 * across searches regardless of these settings.
 */
public final class SearchRestrictions
{
	private static final SearchRestrictions NONE = new SearchRestrictions(false, null);

	/** Avoid stepping or teleporting into the wilderness from outside it. */
	private final boolean avoidWilderness;
	/** Whether a tile lies in the league's always-blocked region, or {@code null} when the gate is off. */
	private final IntPredicate blockedRegion;

	private SearchRestrictions(boolean avoidWilderness, IntPredicate blockedRegion)
	{
		this.avoidWilderness = avoidWilderness;
		this.blockedRegion = blockedRegion;
	}

	/** No gates: every edge the graph offers may be relaxed. */
	public static SearchRestrictions none()
	{
		return NONE;
	}

	/**
	 * @param avoidWilderness bar steps and global teleports that enter the wilderness from
	 *                        outside it; the caller folds in legacy's exemption for a target in
	 *                        the wilderness
	 * @param blockedRegion   tests whether a tile lies in the league's always-blocked region, or
	 *                        {@code null} when the gate is off (a non-seasonal world, or a target
	 *                        inside the blocked region lifting the gate, as in legacy)
	 */
	public static SearchRestrictions of(boolean avoidWilderness, IntPredicate blockedRegion)
	{
		return avoidWilderness || blockedRegion != null ? new SearchRestrictions(avoidWilderness, blockedRegion)
			: NONE;
	}

	/** Whether any gate is active; when false, relaxing an edge never asks for a tile's status. */
	boolean anyGate()
	{
		return avoidWilderness || blockedRegion != null;
	}

	boolean avoidsWilderness()
	{
		return avoidWilderness;
	}

	/** Whether {@code tile} is inside the league's always-blocked region; false when the gate is off. */
	boolean inBlockedRegion(int tile)
	{
		return blockedRegion != null && blockedRegion.test(tile);
	}

	/**
	 * Whether a walking step between adjacent tiles may be relaxed, including the step onto a
	 * blocked transport origin. Like legacy, crossing into the wilderness or the blocked region
	 * is barred while moving inside either area, or out of it, is allowed.
	 */
	public boolean stepAllowed(int fromTile, int toTile)
	{
		if (!anyGate())
		{
			return true;
		}
		return stepAllowed(WildernessChecker.isInWilderness(fromTile), WildernessChecker.isInWilderness(toTile),
			inBlockedRegion(fromTile), inBlockedRegion(toTile));
	}

	boolean stepAllowed(boolean fromWilderness, boolean toWilderness, boolean fromBlocked, boolean toBlocked)
	{
		if (avoidWilderness && !fromWilderness && toWilderness)
		{
			return false;
		}
		return blockedRegion == null || fromBlocked || !toBlocked;
	}

	/**
	 * Whether a global teleport cast with {@code capability} may land on {@code destination}.
	 * {@link TeleportCapability#ALL} means the cast happens outside the wilderness, so a
	 * wilderness landing is barred while avoiding it; a cast from inside the wilderness
	 * (any {@code OVER_*} capability) may land inside it, as in legacy.
	 */
	boolean globalAllowed(TeleportCapability capability, int destination)
	{
		return !avoidWilderness || capability != TeleportCapability.ALL
			|| !WildernessChecker.isInWilderness(destination);
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;

/** Immutable two-layer account-specific site graph with reverse CSR edges. */
public final class SiteGraph
{
	public enum EdgeKind
	{
		LOCAL,
		BANK_TRANSITION,
		BANK_GLOBAL_ENTRY,
		BANK_GLOBAL_DESTINATION,
		SEPARATOR
	}

	private final RoutingStatic stat;
	private final PreparedRoutingAccount account;
	private final int nodeCount;
	private final boolean hasBankedGlobalHub;
	private final int[] reverseOffsets;
	private final int[] reverseFromStates;
	private final int[] reverseCosts;
	private final boolean[] reverseStartsGenerator;
	private final byte[] reverseKinds;

	public SiteGraph(RoutingStatic stat, PreparedRoutingAccount account)
	{
		this.stat = stat;
		this.account = account;
		int spatialCount = stat.siteCount();
		validateEndpoints(account, stat);
		int[] bankSites = bankSites(stat, account);
		int[] globalDestinations = globalDestinations(account, stat);
		hasBankedGlobalHub = account.allowTransports() && account.bankPathEnabled() && bankSites.length != 0
			&& globalDestinations.length != 0;
		nodeCount = spatialCount + (hasBankedGlobalHub ? 1 : 0);

		EdgeBuilder edges = new EdgeBuilder();
		addLocalEdges(edges, account.localView(false), false, stat);
		addLocalEdges(edges, account.localView(true), true, stat);
		if (account.bankPathEnabled())
		{
			for (int bankSite : bankSites)
			{
				edges.add(stateId(bankSite, false), stateId(bankSite, true), account.bankVisitCost(), true,
					EdgeKind.BANK_TRANSITION);
			}
		}
		if (hasBankedGlobalHub)
		{
			int hub = spatialCount;
			for (int bankSite : bankSites)
			{
				edges.add(stateId(bankSite, false), stateId(hub, true), account.bankVisitCost(), true,
					EdgeKind.BANK_GLOBAL_ENTRY);
			}
			for (int destination : globalDestinations)
			{
				int cost = minimumGlobalCost(account.globalView(true), destination);
				if (cost != CostArithmetic.INF)
				{
					edges.add(stateId(hub, true), stateId(stat.siteIndex(destination), true), cost, false,
						EdgeKind.BANK_GLOBAL_DESTINATION);
				}
			}
		}
		for (int i = 0; i < stat.crossingCount(); i++)
		{
			int from = stat.crossingFromSite(i);
			int to = stat.crossingToSite(i);
			int cost = CostArithmetic.validate(stat.crossingCost(i));
			for (boolean banked : new boolean[] {false, true})
			{
				edges.add(stateId(from, banked), stateId(to, banked), cost, true, EdgeKind.SEPARATOR);
				edges.add(stateId(to, banked), stateId(from, banked), cost, true, EdgeKind.SEPARATOR);
			}
		}
		Csr csr = edges.build(nodeCount * 2);
		reverseOffsets = csr.offsets;
		reverseFromStates = csr.fromStates;
		reverseCosts = csr.costs;
		reverseStartsGenerator = csr.startsGenerator;
		reverseKinds = csr.kinds;
	}

	public static SiteGraph compile(RoutingStatic stat, PreparedRoutingAccount account)
	{
		return new SiteGraph(stat, account);
	}

	public RoutingStatic routingStatic()
	{
		return stat;
	}
	public PreparedRoutingAccount preparedAccount()
	{
		return account;
	}
	public int spatialNodeCount()
	{
		return stat.siteCount();
	}
	public int nodeCount()
	{
		return nodeCount;
	}
	public int stateCount()
	{
		return nodeCount * 2;
	}
	public boolean hasBankedGlobalHub()
	{
		return hasBankedGlobalHub;
	}
	public int bankedGlobalHubNode()
	{
		return hasBankedGlobalHub ? stat.siteCount() : -1;
	}
	public int siteTile(int node)
	{
		return stat.siteTile(node);
	}
	public int nodeForTile(int tile)
	{
		return stat.siteIndex(tile);
	}

	public int reverseEdgeCount()
	{
		return reverseFromStates.length;
	}
	public int reverseEdgeStart(int state)
	{
		return reverseOffsets[state];
	}
	public int reverseEdgeEnd(int state)
	{
		return reverseOffsets[state + 1];
	}
	public int reverseFromState(int edge)
	{
		return reverseFromStates[edge];
	}
	public int reverseCost(int edge)
	{
		return reverseCosts[edge];
	}
	public boolean reverseStartsGenerator(int edge)
	{
		return reverseStartsGenerator[edge];
	}
	public EdgeKind reverseKind(int edge)
	{
		return EdgeKind.values()[reverseKinds[edge]];
	}

	public static int stateId(int node, boolean banked)
	{
		if (node < 0)
			throw new IllegalArgumentException("negative site node");
		return node * 2 + (banked ? 1 : 0);
	}

	private static void addLocalEdges(
		EdgeBuilder edges, PreparedRoutingAccount.View view, boolean banked, RoutingStatic stat)
	{
		for (int i = 0; i < view.count; i++)
		{
			int from = stat.siteIndex(view.origins[i]);
			int to = stat.siteIndex(view.destinations[i]);
			if (view.costs[i] != CostArithmetic.INF)
			{
				edges.add(stateId(from, banked), stateId(to, banked), view.costs[i], true, EdgeKind.LOCAL);
			}
		}
	}

	private static void validateEndpoints(PreparedRoutingAccount account, RoutingStatic stat)
	{
		for (boolean banked : new boolean[] {false, true})
		{
			PreparedRoutingAccount.View local = account.localView(banked);
			for (int i = 0; i < local.count; i++)
			{
				requireSite(stat, local.origins[i], "local origin");
				requireSite(stat, local.destinations[i], "local destination");
			}
			PreparedRoutingAccount.View global = account.globalView(banked);
			for (int i = 0; i < global.count; i++)
				requireSite(stat, global.destinations[i], "global destination");
		}
	}

	private static void requireSite(RoutingStatic stat, int tile, String label)
	{
		if (stat.siteIndex(tile) < 0)
		{
			throw new IllegalStateException(label + " is not a static site: " + Integer.toUnsignedString(tile));
		}
	}

	/** The static bank sites this account may use. */
	private static int[] bankSites(RoutingStatic stat, PreparedRoutingAccount account)
	{
		int[] result = new int[stat.reachableBankCount()];
		int count = 0;
		for (int i = 0; i < result.length; i++)
		{
			int tile = stat.reachableBankTile(i);
			int site = stat.siteIndex(tile);
			if (site < 0)
				throw new IllegalStateException("reachable bank is not a static site");
			if (account.bankAccessible(tile))
				result[count++] = site;
		}
		return Arrays.copyOf(result, count);
	}

	private static int[] globalDestinations(PreparedRoutingAccount account, RoutingStatic stat)
	{
		PreparedRoutingAccount.View view = account.globalView(true);
		int[] result = new int[view.count];
		int count = 0;
		for (int i = 0; i < view.count; i++)
		{
			int destination = view.destinations[i];
			boolean present = false;
			for (int j = 0; j < count; j++)
				present |= result[j] == destination;
			if (!present)
				result[count++] = destination;
		}
		result = Arrays.copyOf(result, count);
		for (int i = 1; i < count; i++)
		{
			int value = result[i];
			int j = i - 1;
			while (j >= 0 && Integer.compareUnsigned(result[j], value) > 0)
			{
				result[j + 1] = result[j--];
			}
			result[j + 1] = value;
		}
		for (int destination : result)
			requireSite(stat, destination, "global destination");
		return result;
	}

	private static int minimumGlobalCost(PreparedRoutingAccount.View view, int destination)
	{
		int minimum = CostArithmetic.INF;
		for (int i = 0; i < view.count; i++)
		{
			if (view.destinations[i] == destination && view.costs[i] < minimum)
				minimum = view.costs[i];
		}
		return minimum;
	}

	private static final class EdgeBuilder
	{
		private int size;
		private int[] from = new int[64], to = new int[64], costs = new int[64];
		private boolean[] starts = new boolean[64];
		private byte[] kinds = new byte[64];

		void add(int fromState, int toState, int cost, boolean startsGenerator, EdgeKind kind)
		{
			CostArithmetic.validate(cost);
			if (cost == CostArithmetic.INF)
				return;
			if (size == from.length)
			{
				int capacity = size * 2;
				from = Arrays.copyOf(from, capacity);
				to = Arrays.copyOf(to, capacity);
				costs = Arrays.copyOf(costs, capacity);
				starts = Arrays.copyOf(starts, capacity);
				kinds = Arrays.copyOf(kinds, capacity);
			}
			from[size] = fromState;
			to[size] = toState;
			costs[size] = cost;
			starts[size] = startsGenerator;
			kinds[size++] = (byte) kind.ordinal();
		}

		Csr build(int stateCount)
		{
			int[] offsets = new int[stateCount + 1];
			for (int i = 0; i < size; i++)
				offsets[to[i] + 1]++;
			for (int i = 1; i < offsets.length; i++)
				offsets[i] += offsets[i - 1];
			int[] positions = Arrays.copyOfRange(offsets, 1, offsets.length);
			int[] sortedFrom = new int[size], sortedCosts = new int[size];
			boolean[] sortedStarts = new boolean[size];
			byte[] sortedKinds = new byte[size];
			for (int i = 0; i < size; i++)
			{
				int position = --positions[to[i]];
				sortedFrom[position] = from[i];
				sortedCosts[position] = costs[i];
				sortedStarts[position] = starts[i];
				sortedKinds[position] = kinds[i];
			}
			return new Csr(offsets, sortedFrom, sortedCosts, sortedStarts, sortedKinds);
		}
	}

	private static final class Csr
	{
		final int[] offsets, fromStates, costs;
		final boolean[] startsGenerator;
		final byte[] kinds;

		Csr(int[] offsets, int[] fromStates, int[] costs, boolean[] startsGenerator, byte[] kinds)
		{
			this.offsets = offsets;
			this.fromStates = fromStates;
			this.costs = costs;
			this.startsGenerator = startsGenerator;
			this.kinds = kinds;
		}
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import java.util.Comparator;
import shortestpath.WorldPointUtil;

/**
 * Builds the sparse same-component walking network used by {@link ReverseLabels#computeSparse}.
 *
 * <p>Within each routing component, walking distance between two sites on the same plane is at
 * least their Chebyshev distance. Instead of connecting every pair of sites, the construction
 * works in rotated Manhattan coordinates {@code a = x + y}, {@code b = x - y}, where Manhattan
 * distance is exactly twice Chebyshev distance, and adds Steiner vertices along balanced
 * coordinate splits so that the shortest path between any two sites equals that distance.
 * Every edge weight is therefore doubled walking distance; {@link ReverseLabels#computeSparse}
 * halves it once at the end.
 */
public final class SparseWalkingNetworkBuilder
{
	private SparseWalkingNetworkBuilder()
	{
	}

	/** Section G in flat, undirected CSR form (adjacencyCount == 2 * undirectedEdgeCount). */
	public static final class Result
	{
		public final int originalCount;
		public final int vertexCount;
		public final int steinerCount;
		public final int undirectedEdgeCount;
		public final int[] offsets;
		public final int[] destinations;
		public final int[] weights;

		private Result(int originalCount, int vertexCount, int steinerCount, int undirectedEdgeCount, int[] offsets,
			int[] destinations, int[] weights)
		{
			this.originalCount = originalCount;
			this.vertexCount = vertexCount;
			this.steinerCount = steinerCount;
			this.undirectedEdgeCount = undirectedEdgeCount;
			this.offsets = offsets;
			this.destinations = destinations;
			this.weights = weights;
		}

		public int adjacencyCount()
		{
			return destinations.length;
		}
	}

	/**
	 * Builds the network from the static sites and their routing-component attachments:
	 *
	 * <ul>
	 *   <li>{@code siteTiles[s]}: packed tile of site {@code s}, ascending.</li>
	 *   <li>{@code siteComponentOffsets}, {@code siteComponentIds}: each site's ascending
	 *       routing-component attachments. A site attached to several components contributes
	 *       one point to each component, all sharing the same site vertex.</li>
	 * </ul>
	 *
	 * <p>Vertices {@code 0..siteTiles.length-1} are the sites, followed by Steiner vertices. A
	 * site with no component attachment is an isolated vertex.
	 *
	 * @param siteTiles              packed tiles, ascending unsigned packed order, one per site
	 * @param siteComponentOffsets   length {@code siteTiles.length + 1}, CSR offsets into {@code siteComponentIds}
	 * @param siteComponentIds       routing-component ids per site, ascending within each site's range
	 * @return the flattened CSR sparse walking network (section G)
	 */
	public static Result build(int[] siteTiles, int[] siteComponentOffsets, int[] siteComponentIds)
	{
		int originalCount = siteTiles.length;
		int maxComponentId = -1;
		for (int cid : siteComponentIds)
		{
			if (cid > maxComponentId)
			{
				maxComponentId = cid;
			}
		}
		int componentCount = maxComponentId + 1;

		// Bucket sites by component id; only components that own at least one site are processed,
		// in ascending id order.
		int[] bucketCounts = new int[componentCount];
		for (int cid : siteComponentIds)
		{
			bucketCounts[cid]++;
		}
		int[] bucketOffsets = new int[componentCount + 1];
		for (int c = 0; c < componentCount; c++)
		{
			bucketOffsets[c + 1] = bucketOffsets[c] + bucketCounts[c];
		}
		int[] bucketSites = new int[siteComponentIds.length];
		int[] cursor = bucketOffsets.clone();
		for (int site = 0; site < originalCount; site++)
		{
			for (int p = siteComponentOffsets[site]; p < siteComponentOffsets[site + 1]; p++)
			{
				int cid = siteComponentIds[p];
				bucketSites[cursor[cid]++] = site;
			}
		}

		EdgeList edges = new EdgeList();
		int next = originalCount;
		for (int cid = 0; cid < componentCount; cid++)
		{
			int start = bucketOffsets[cid];
			int end = bucketOffsets[cid + 1];
			int size = end - start;
			if (size == 0)
			{
				continue;
			}
			Point[] points = new Point[size];
			for (int i = 0; i < size; i++)
			{
				int siteIndex = bucketSites[start + i];
				int tile = siteTiles[siteIndex];
				int x = WorldPointUtil.unpackWorldX(tile);
				int y = WorldPointUtil.unpackWorldY(tile);
				points[i] = new Point(siteIndex, x + y, x - y);
			}
			Arrays.sort(points, BY_A_B_ORIGINAL);
			next = buildComponent(next, points, edges);
		}

		int vertexCount = next;
		int steinerCount = vertexCount - originalCount;
		return undirectedAdjacency(originalCount, vertexCount, steinerCount, edges);
	}

	private enum Axis
	{
		A, B
	}

	private static final class Point
	{
		final int original;
		final int a;
		final int b;

		Point(int original, int a, int b)
		{
			this.original = original;
			this.a = a;
			this.b = b;
		}
	}

	private static final Comparator<Point> BY_A_B_ORIGINAL = (x, y) ->
	{
		if (x.a != y.a)
		{
			return Integer.compare(x.a, y.a);
		}
		if (x.b != y.b)
		{
			return Integer.compare(x.b, y.b);
		}
		return Integer.compare(x.original, y.original);
	};

	private static int coordOf(Axis axis, Point p)
	{
		return axis == Axis.A ? p.a : p.b;
	}

	private static int otherCoordOf(Axis axis, Point p)
	{
		return axis == Axis.A ? p.b : p.a;
	}

	private static Comparator<Point> axisComparator(Axis axis)
	{
		return (x, y) ->
		{
			int cx = coordOf(axis, x);
			int cy = coordOf(axis, y);
			if (cx != cy)
			{
				return Integer.compare(cx, cy);
			}
			return BY_A_B_ORIGINAL.compare(x, y);
		};
	}

	/**
	 * Recursively splits one component's points. {@code pts} arrives in inherited order (the
	 * global {@code a,b,original} sort at the top level, or a slice of the parent split's
	 * axis-sorted list below it); that order, not any re-sort here, decides which Steiner vertex
	 * id each point receives in {@link #addProjectionLevel}, keeping numbering deterministic.
	 */
	private static int buildComponent(int next, Point[] pts, EdgeList edges)
	{
		if (pts.length <= 1)
		{
			return next;
		}
		int a0 = pts[0].a;
		int b0 = pts[0].b;
		boolean allSameA = true;
		boolean allSameB = true;
		for (Point p : pts)
		{
			if (p.a != a0)
			{
				allSameA = false;
			}
			if (p.b != b0)
			{
				allSameB = false;
			}
		}
		if (allSameA && allSameB)
		{
			// Coincident points are chained with zero-weight edges; pts is already sorted by `original`
			// here, since a/b are constant and the inherited order derives from a sort
			// keyed on (axis-or-a-b, a, b, original).
			for (int i = 0; i + 1 < pts.length; i++)
			{
				edges.add(pts[i].original, pts[i + 1].original, 0);
			}
			return next;
		}
		Axis axis = allSameA ? Axis.B : Axis.A;
		return splitOn(axis, next, pts, edges);
	}

	/** Splits {@code pts} at the most balanced gap along {@code axis} and recurses on both halves. */
	private static int splitOn(Axis axis, int next, Point[] pts, EdgeList edges)
	{
		Point[] sorted = pts.clone();
		Arrays.sort(sorted, axisComparator(axis));
		int split = balancedGapSplit(axis, sorted);
		Point[] left = Arrays.copyOfRange(sorted, 0, split);
		Point[] right = Arrays.copyOfRange(sorted, split, sorted.length);
		int splitCoordinate = Math.floorDiv(
			coordOf(axis, sorted[split - 1]) + coordOf(axis, sorted[split]), 2);
		int afterProjection = addProjectionLevel(axis, splitCoordinate, next, pts, edges);
		int afterLeft = buildComponent(afterProjection, left, edges);
		return buildComponent(afterLeft, right, edges);
	}

	/**
	 * Returns the split index {@code i}: {@code sorted[0..i)} and {@code sorted[i..)} lie on
	 * either side of the chosen gap; the caller
	 * derives the Steiner splitter coordinate from the pair straddling that index.
	 */
	private static int balancedGapSplit(Axis axis, Point[] sorted)
	{
		int n = sorted.length;
		int preferred = n / 2;
		int bestIndex = -1;
		int bestDiff = Integer.MAX_VALUE;
		for (int i = 1; i < n; i++)
		{
			if (coordOf(axis, sorted[i - 1]) < coordOf(axis, sorted[i]))
			{
				int diff = Math.abs(i - preferred);
				if (diff < bestDiff)
				{
					bestDiff = diff;
					bestIndex = i;
				}
			}
		}
		if (bestIndex < 0)
		{
			throw new IllegalStateException("sparse walking split without a strict coordinate gap");
		}
		return bestIndex;
	}

	/**
	 * Allocates one fresh
	 * Steiner vertex per point in {@code pts} (in {@code pts}'s own order), a spoke edge
	 * from each point to its projection vertex, then chains the projections in ascending
	 * order of the other axis coordinate (ties by original site index).
	 */
	private static int addProjectionLevel(Axis axis, int splitCoordinate, int firstProjection, Point[] pts,
		EdgeList edges)
	{
		int count = pts.length;
		int[] steinerIds = new int[count];
		for (int i = 0; i < count; i++)
		{
			steinerIds[i] = firstProjection + i;
			edges.add(pts[i].original, steinerIds[i], Math.abs(coordOf(axis, pts[i]) - splitCoordinate));
		}
		Integer[] order = new Integer[count];
		for (int i = 0; i < count; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, (x, y) ->
		{
			int ox = otherCoordOf(axis, pts[x]);
			int oy = otherCoordOf(axis, pts[y]);
			if (ox != oy)
			{
				return Integer.compare(ox, oy);
			}
			return Integer.compare(pts[x].original, pts[y].original);
		});
		for (int i = 0; i + 1 < count; i++)
		{
			int leftIndex = order[i];
			int rightIndex = order[i + 1];
			int weight = Math.abs(otherCoordOf(axis, pts[leftIndex]) - otherCoordOf(axis, pts[rightIndex]));
			edges.add(steinerIds[leftIndex], steinerIds[rightIndex], weight);
		}
		return firstProjection + count;
	}

	/** Growable primitive (from, to, weight) triples; final counts are small primitive arrays. */
	private static final class EdgeList
	{
		private int[] from = new int[16];
		private int[] to = new int[16];
		private int[] weight = new int[16];
		private int size;

		void add(int a, int b, int w)
		{
			if (size == from.length)
			{
				int capacity = size * 2;
				from = Arrays.copyOf(from, capacity);
				to = Arrays.copyOf(to, capacity);
				weight = Arrays.copyOf(weight, capacity);
			}
			from[size] = a;
			to[size] = b;
			weight[size] = w;
			size++;
		}
	}

	/**
	 * Materialises both directions of every edge as CSR adjacency. The order of entries within
	 * one vertex's range does not affect any distance.
	 */
	private static Result undirectedAdjacency(int originalCount, int vertexCount, int steinerCount, EdgeList edges)
	{
		int[] counts = new int[vertexCount];
		for (int i = 0; i < edges.size; i++)
		{
			counts[edges.from[i]]++;
			counts[edges.to[i]]++;
		}
		int[] offsets = new int[vertexCount + 1];
		for (int v = 0; v < vertexCount; v++)
		{
			offsets[v + 1] = offsets[v] + counts[v];
		}
		int[] destinations = new int[offsets[vertexCount]];
		int[] weights = new int[offsets[vertexCount]];
		int[] cursor = offsets.clone();
		for (int i = 0; i < edges.size; i++)
		{
			int a = edges.from[i];
			int b = edges.to[i];
			int w = edges.weight[i];
			destinations[cursor[a]] = b;
			weights[cursor[a]] = w;
			cursor[a]++;
			destinations[cursor[b]] = a;
			weights[cursor[b]] = w;
			cursor[b]++;
		}
		return new Result(originalCount, vertexCount, steinerCount, edges.size, offsets, destinations, weights);
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import shortestpath.pathfinder.CollisionMap;

/**
 * Query-local target sites and their point-attachment walking edges.
 *
 * <p>An overlay holds one or more target tiles; a search towards it ends at whichever target is
 * cheapest to reach. Targets that are static sites reuse their site node; every other target gets
 * its own synthetic node appended after the account graph's nodes, in target order.
 */
public final class TargetOverlay
{
	private final SiteGraph graph;
	private final RoutingStatic stat;
	private final PreparedRoutingAccount account;
	private final long accountFingerprint;
	private final CollisionMap collision;
	private final int[] packed;
	private final int[] nodes;
	private final int[][] components;
	private final int[][] attachmentSites;
	private final int[][] attachmentCosts;
	private final int[] syntheticTargets;

	public TargetOverlay(SiteGraph graph, CollisionMap collision, int packed)
	{
		this(graph, collision, new int[] {packed});
	}

	public TargetOverlay(SiteGraph graph, CollisionMap collision, int[] packedTargets)
	{
		if (graph == null || collision == null || packedTargets == null)
			throw new NullPointerException();
		this.graph = graph;
		this.stat = graph.routingStatic();
		this.account = graph.preparedAccount();
		this.accountFingerprint = account.fingerprint();
		this.collision = collision;
		this.packed = sortedUnique(packedTargets);
		if (packed.length == 0)
			throw new IllegalArgumentException("target overlay needs at least one target");
		int count = packed.length;
		nodes = new int[count];
		components = new int[count][];
		attachmentSites = new int[count][];
		attachmentCosts = new int[count][];
		int[] synthetic = new int[count];
		int syntheticCount = 0;
		for (int target = 0; target < count; target++)
		{
			int existing = graph.nodeForTile(packed[target]);
			if (existing >= 0)
			{
				nodes[target] = existing;
				components[target] = stat.siteComponents(existing);
			}
			else
			{
				nodes[target] = graph.nodeCount() + syntheticCount;
				synthetic[syntheticCount++] = target;
				components[target] = stat.attachments(packed[target], collision);
			}
			attach(target);
		}
		syntheticTargets = Arrays.copyOf(synthetic, syntheticCount);
	}

	public SiteGraph graph()
	{
		return graph;
	}
	public RoutingStatic routingStatic()
	{
		return stat;
	}
	public PreparedRoutingAccount account()
	{
		return account;
	}
	CollisionMap collision()
	{
		return collision;
	}
	public long accountFingerprint()
	{
		return accountFingerprint;
	}
	public int queryNodeCount()
	{
		return graph.nodeCount() + syntheticTargets.length;
	}

	public int targetCount()
	{
		return packed.length;
	}
	/** The target tiles, in unsigned order. */
	public int[] packedTargets()
	{
		return packed.clone();
	}
	public int packedTarget(int target)
	{
		return packed[target];
	}
	/** Index of {@code tile} among the targets, or a negative value if it is not a target. */
	public int targetIndex(int tile)
	{
		if (packed.length == 1)
			return packed[0] == tile ? 0 : -1;
		int low = 0, high = packed.length - 1;
		while (low <= high)
		{
			int middle = (low + high) >>> 1, compare = Integer.compareUnsigned(packed[middle], tile);
			if (compare == 0) return middle;
			if (compare < 0) low = middle + 1; else high = middle - 1;
		}
		return -1;
	}
	public boolean isTarget(int tile)
	{
		return targetIndex(tile) >= 0;
	}
	public int targetNode(int target)
	{
		return nodes[target];
	}
	public boolean synthetic(int target)
	{
		return nodes[target] >= graph.nodeCount();
	}
	public int[] components(int target)
	{
		return components[target].clone();
	}
	int[] componentsView(int target)
	{
		return components[target];
	}
	public int attachmentCount(int target)
	{
		return attachmentSites[target].length;
	}
	public int attachmentSite(int target, int index)
	{
		return attachmentSites[target][index];
	}
	public int attachmentCost(int target, int index)
	{
		return attachmentCosts[target][index];
	}
	public int targetState(int target, boolean banked)
	{
		return SiteGraph.stateId(nodes[target], banked);
	}

	public int syntheticCount()
	{
		return syntheticTargets.length;
	}
	/** The target index owning synthetic node {@code node}, or a negative value for any other node. */
	int syntheticTarget(int node)
	{
		int index = node - graph.nodeCount();
		return index >= 0 && index < syntheticTargets.length ? syntheticTargets[index] : -1;
	}
	/** Tile of a spatial site node or a synthetic target node. */
	int nodeTile(int node)
	{
		int target = syntheticTarget(node);
		return target >= 0 ? packed[target] : stat.siteTile(node);
	}
	/** Routing components of a spatial site node or a synthetic target node. */
	int[] nodeComponents(int node)
	{
		int target = syntheticTarget(node);
		return target >= 0 ? components[target] : stat.siteComponents(node);
	}

	/** The only target's tile; single-target overlays only. */
	public int packedTarget()
	{
		return packed[single()];
	}
	/** The only target's node; single-target overlays only. */
	public int targetNode()
	{
		return nodes[single()];
	}
	/** Whether the only target is synthetic; single-target overlays only. */
	public boolean synthetic()
	{
		return synthetic(single());
	}
	/** The only target's routing components; single-target overlays only. */
	public int[] components()
	{
		return components(single());
	}
	/** The only target's attachment count; single-target overlays only. */
	public int attachmentCount()
	{
		return attachmentCount(single());
	}
	/** The only target's attachment site; single-target overlays only. */
	public int attachmentSite(int index)
	{
		return attachmentSite(single(), index);
	}
	/** The only target's attachment cost; single-target overlays only. */
	public int attachmentCost(int index)
	{
		return attachmentCost(single(), index);
	}
	/** The only target's state; single-target overlays only. */
	public int targetState(boolean banked)
	{
		return targetState(single(), banked);
	}

	void requireCompatible(SiteGraph candidate)
	{
		if (candidate.routingStatic() != stat || candidate.preparedAccount() != account
			|| candidate.preparedAccount().fingerprint() != accountFingerprint)
		{
			throw new IllegalArgumentException("target overlay belongs to another static/account snapshot");
		}
	}

	private int single()
	{
		if (packed.length != 1)
			throw new IllegalStateException("overlay has " + packed.length + " targets");
		return 0;
	}

	private void attach(int target)
	{
		int[] targetComponents = components[target];
		int capacity = 0;
		for (int component : targetComponents)
			capacity += stat.componentSites(component).length;
		int[] sites = new int[capacity];
		int count = 0;
		for (int component : targetComponents)
		{
			for (int site : stat.componentSites(component))
			{
				if (firstSharedComponent(targetComponents, site) == component)
					sites[count++] = site;
			}
		}
		attachmentSites[target] = Arrays.copyOf(sites, count);
		attachmentCosts[target] = new int[count];
		// Only a synthetic target's attachments enter the reverse search. Walking distances rather
		// than Chebyshev ones keep a target deep in a winding area from looking close to its
		// entrances, which would otherwise make the search flood everything within that slack.
		TargetWalkDistances walk = nodes[target] >= graph.nodeCount()
			? TargetWalkDistances.search(stat, packed[target], targetComponents) : null;
		for (int i = 0; i < count; i++)
		{
			int site = stat.siteTile(attachmentSites[target][i]);
			int chebyshev = distance(packed[target], site);
			attachmentCosts[target][i] = walk == null ? chebyshev : walk.bound(site, chebyshev);
		}
	}

	private int firstSharedComponent(int[] targetComponents, int site)
	{
		for (int component : targetComponents)
		{
			for (int siteComponent : stat.siteComponents(site))
				if (siteComponent == component)
					return component;
		}
		throw new IllegalStateException("target attachment missing shared routing component");
	}

	private static int[] sortedUnique(int[] values)
	{
		int[] sorted = values.clone();
		for (int i = 0; i < sorted.length; i++)
			sorted[i] ^= Integer.MIN_VALUE;
		Arrays.sort(sorted);
		int count = 0;
		for (int i = 0; i < sorted.length; i++)
			if (count == 0 || sorted[count - 1] != sorted[i])
				sorted[count++] = sorted[i];
		for (int i = 0; i < count; i++)
			sorted[i] ^= Integer.MIN_VALUE;
		return Arrays.copyOf(sorted, count);
	}

	private static int distance(int left, int right)
	{
		return shortestpath.WorldPointUtil.distanceBetween(left, right);
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import shortestpath.WorldPointUtil;

/**
 * Lower bounds on the walking cost from a target's attachment sites to the target, from a bounded
 * breadth-first search backwards over the static walking edges, within the target's routing
 * components.
 *
 * <p>Why a walk inside the components is enough: sites are every transport endpoint, crossing
 * endpoint and bank, and routing components are only left by crossing a cut, whose endpoints are
 * sites. A route's last stretch after its last site is therefore a pure walk inside the target's
 * components, and costs at least the distance found here. A site never reached gets the distance
 * of the search's frontier when it stopped (no closer tile was left unvisited), and every bound
 * is at least the Chebyshev distance the overlay used before.
 */
final class TargetWalkDistances
{
	/** Tiles the search may visit per target; larger components get frontier bounds beyond it. */
	static final int TILE_BUDGET = 1 << 16;

	// Bit b of a walking mask steps by (DX[b], DY[b]), as in AStarForwardSearch.walkBase.
	private static final int[] DX = {0, 1, 1, 1, 0, -1, -1, -1};
	private static final int[] DY = {1, 1, 0, -1, -1, -1, 0, 1};

	private final RoutingStatic stat;
	private final int[] components;
	private final NodeDistances distances;
	private final int frontier;

	private TargetWalkDistances(RoutingStatic stat, int[] components, NodeDistances distances, int frontier)
	{
		this.stat = stat;
		this.components = components;
		this.distances = distances;
		this.frontier = frontier;
	}

	/** Null when the target is not a static search tile (its attachments keep Chebyshev costs). */
	static TargetWalkDistances search(RoutingStatic stat, int target, int[] components)
	{
		int start = stat.searchIndex(target);
		if (start < 0) return null;
		NodeDistances distances = new NodeDistances(TILE_BUDGET);
		int[] queue = new int[TILE_BUDGET];
		int head = 0, tail = 0;
		distances.put(start, 0);
		queue[tail++] = start;
		int frontier = 0;
		boolean exhausted = true;
		while (head < tail)
		{
			int node = queue[head++];
			int distance = distances.get(node);
			for (int direction = 0; direction < 8; direction++)
			{
				// The neighbour in this direction is a predecessor if it walks back onto this tile,
				// by the same index arithmetic the forward search uses.
				int from = successor(stat, node, direction), bit = (direction + 4) & 7;
				if (from < 0 || from >= stat.searchTileCount()) continue;
				if ((stat.walkingMask(from) & (1 << bit)) == 0 || successor(stat, from, bit) != node) continue;
				if (distances.get(from) >= 0 || !inComponents(stat.routingComponent(from), components)) continue;
				if (tail == TILE_BUDGET)
				{
					exhausted = false;
					break;
				}
				distances.put(from, distance + 1);
				queue[tail++] = from;
			}
			if (!exhausted)
			{
				// Every unvisited tile is at least as far as the tile being expanded.
				frontier = distance;
				break;
			}
			frontier = distance + 1;
		}
		return new TargetWalkDistances(stat, components, distances, frontier);
	}

	/**
	 * A lower bound on walking from {@code site} to the target, never below {@code chebyshev}.
	 * A site off the search tiles (a blocked transport origin) first steps to a neighbour.
	 */
	int bound(int site, int chebyshev)
	{
		int node = stat.searchIndex(site);
		if (node >= 0) return Math.max(chebyshev, distance(node));
		int x = WorldPointUtil.unpackWorldX(site), y = WorldPointUtil.unpackWorldY(site);
		int plane = WorldPointUtil.unpackWorldPlane(site);
		int best = Integer.MAX_VALUE;
		for (int bit = 0; bit < 8; bit++)
		{
			int neighbour = stat.searchIndex(WorldPointUtil.packWorldPoint(x + DX[bit], y + DY[bit], plane));
			if (neighbour >= 0) best = Math.min(best, distance(neighbour));
		}
		return best == Integer.MAX_VALUE ? chebyshev : Math.max(chebyshev, 1 + best);
	}

	private int distance(int node)
	{
		int known = distances.get(node);
		return known >= 0 ? known : frontier;
	}

	private static int successor(RoutingStatic stat, int node, int bit)
	{
		int south = stat.southNode(node), north = stat.northNode(node);
		switch (bit)
		{
			case 0: return north;
			case 1: return north < 0 ? -1 : north + 1;
			case 2: return node + 1;
			case 3: return south < 0 ? -1 : south + 1;
			case 4: return south;
			case 5: return south < 0 ? -1 : south - 1;
			case 6: return node - 1;
			default: return north < 0 ? -1 : north - 1;
		}
	}

	private static boolean inComponents(int component, int[] components)
	{
		for (int value : components)
			if (value == component) return true;
		return false;
	}

	/** Open-addressing node -> distance map sized for the tile budget. */
	private static final class NodeDistances
	{
		private final int[] keys, values;
		private final int mask;

		NodeDistances(int capacity)
		{
			int size = Integer.highestOneBit(capacity * 2 - 1) << 1;
			keys = new int[size];
			values = new int[size];
			Arrays.fill(keys, -1);
			mask = size - 1;
		}

		void put(int key, int value)
		{
			int slot = mix(key) & mask;
			while (keys[slot] != -1 && keys[slot] != key) slot = (slot + 1) & mask;
			keys[slot] = key;
			values[slot] = value;
		}

		int get(int key)
		{
			int slot = mix(key) & mask;
			while (keys[slot] != -1)
			{
				if (keys[slot] == key) return values[slot];
				slot = (slot + 1) & mask;
			}
			return -1;
		}

		private static int mix(int key)
		{
			int h = key * 0x9E3779B9;
			return h ^ (h >>> 16);
		}
	}
}

package shortestpath.pathfinder.astar;

import shortestpath.WorldPointUtil;
import shortestpath.transport.Transport;

/**
 * Which global teleports the A* backend lets the player cast from a tile, by the tile's
 * wilderness band. These are legacy's global-teleport abstract nodes ({@code AbstractNodeKind}):
 *
 * <pre>
 * OVER_30  level 31+     cast level 31  GLOBAL_TELEPORTS_OVER_30
 * OVER_20  levels 21-30  cast level 30  GLOBAL_TELEPORTS_OVER_20
 * OVER_0   levels 1-20   cast level 20  GLOBAL_TELEPORTS_OVER_0
 * ALL      level 0       cast level 0   GLOBAL_TELEPORTS_NORMAL
 * </pre>
 *
 * A global is castable with a capability when {@link Transport#isUsableAtWildernessLevel} allows
 * the capability's cast level, as in legacy. Cast levels only fall from {@code OVER_30} to
 * {@code ALL}, so each capability can cast everything the one before it can.
 *
 * <p>The bands are {@code WildernessChecker}'s level-30, level-20 and wilderness areas (checked by
 * {@code TeleportCapabilityTest}), on every plane, inlined here because the forward search asks
 * for every state it pops.
 */
public enum TeleportCapability
{
	OVER_30(31), OVER_20(30), OVER_0(20), ALL(0);

	private final int castLevel;

	TeleportCapability(int castLevel)
	{
		this.castLevel = castLevel;
	}

	/** The wilderness level legacy checks a global teleport against in this band. */
	public int castLevel()
	{
		return castLevel;
	}

	/** Whether {@code transport} can be cast as a global teleport in this band. */
	public boolean canCast(Transport transport)
	{
		return transport.isUsableAtWildernessLevel(castLevel);
	}

	/** Whether a tile with this capability may cast everything {@code required} can. */
	boolean allows(TeleportCapability required)
	{
		return castLevel <= required.castLevel;
	}

	// {left, bottom, width, height}: above ground, then underground.
	static final int[][] ABOVE_LEVEL_30 = {{2944, 3760, 448, 448}, {2944, 10155, 518, 221}};
	static final int[][] ABOVE_LEVEL_20 = {{2944, 3680, 448, 448}, {2944, 10075, 518, 301}};
	static final int[][] WILDERNESS = {{2944, 3525, 448, 448}, {2944, 9918, 518, 458}};
	/** Inside the above-ground wilderness area but not wilderness: Ferox Enclave and its south edge. */
	static final int[][] NOT_WILDERNESS = {{3123, 3622, 2, 10}, {3125, 3617, 16, 23}, {3138, 3636, 18, 10},
		{3141, 3625, 14, 11}, {3141, 3619, 7, 6}, {2997, 3525, 34, 9}, {3005, 3534, 21, 10}, {3000, 3534, 5, 5},
		{3031, 3525, 2, 2}};

	public static TeleportCapability at(int tile)
	{
		return at(WorldPointUtil.unpackWorldX(tile), WorldPointUtil.unpackWorldY(tile));
	}

	static TeleportCapability at(int x, int y)
	{
		// Unrolled WILDERNESS, ABOVE_LEVEL_30 and ABOVE_LEVEL_20.
		if (x < 2944 || x >= 3462 || y < 3525) return ALL;
		if (y >= 9918)
		{
			if (y >= 10376) return ALL;
			return y >= 10155 ? OVER_30 : y >= 10075 ? OVER_20 : OVER_0;
		}
		if (x >= 3392) return ALL;
		if (y >= 3760 && y < 4208) return OVER_30;
		if (y >= 3680 && y < 4128) return OVER_20;
		if (y >= 3973 || inAny(NOT_WILDERNESS, x, y)) return ALL;
		return OVER_0;
	}

	/** The areas a tile must lie outside of all of, or inside a {@link #holes() hole}, to allow this capability. */
	int[][] excludedAreas()
	{
		switch (this)
		{
			case OVER_30:
				return new int[0][];
			case OVER_20:
				return ABOVE_LEVEL_30;
			case OVER_0:
				return EXCLUDED_FROM_OVER_0;
			case ALL:
			default:
				return EXCLUDED_FROM_ALL;
		}
	}

	/** Areas inside {@link #excludedAreas()} that still allow this capability. */
	int[][] holes()
	{
		return this == ALL ? NOT_WILDERNESS : new int[0][];
	}

	// The level-30 area reaches further north than the level-20 and wilderness ones, so all are excluded.
	private static final int[][] EXCLUDED_FROM_OVER_0 = {ABOVE_LEVEL_30[0], ABOVE_LEVEL_30[1], ABOVE_LEVEL_20[0],
		ABOVE_LEVEL_20[1]};
	private static final int[][] EXCLUDED_FROM_ALL = {ABOVE_LEVEL_30[0], ABOVE_LEVEL_30[1], ABOVE_LEVEL_20[0],
		ABOVE_LEVEL_20[1], WILDERNESS[0], WILDERNESS[1]};

	static boolean inAny(int[][] areas, int x, int y)
	{
		for (int[] area : areas)
			if (inArea(area, x, y)) return true;
		return false;
	}

	static boolean inArea(int[] area, int x, int y)
	{
		return x >= area[0] && x < area[0] + area[2] && y >= area[1] && y < area[1] + area[3];
	}
}

package shortestpath.pathfinder.astar;

/**
 * Per-tile component numbers, using two bytes when the world's component count permits it.
 * Mutable during construction; ownership passes to the read-only RoutingStatic when built.
 */
final class TileComponents
{
	private final char[] compactIds;
	private final int[] wideIds;
	private final int componentCount;

	TileComponents(int tileCount, int componentCount)
	{
		if (componentCount < 0) throw new IllegalArgumentException("negative component count");
		this.componentCount = componentCount;
		compactIds = componentCount <= Character.MAX_VALUE + 1 ? new char[tileCount] : null;
		wideIds = compactIds == null ? new int[tileCount] : null;
	}

	int length()
	{
		return compactIds == null ? wideIds.length : compactIds.length;
	}

	int get(int tile)
	{
		return compactIds == null ? wideIds[tile] : compactIds[tile];
	}

	void set(int tile, int component)
	{
		if (component < 0 || component >= componentCount)
			throw new IllegalArgumentException("component out of range");
		if (compactIds == null) wideIds[tile] = component;
		else compactIds[tile] = (char) component;
	}
}

package shortestpath.pathfinder.astar;

import java.util.Arrays;
import shortestpath.WorldPointUtil;

/**
 * Where a walking leg may end on its plane: every tile from which the route's next action can be
 * taken with the same consequences. That is one tile for a fixed waypoint, the origins of one
 * transport action for a transport, and an area for a global teleport, which can be cast anywhere
 * the wilderness allows it.
 */
abstract class WalkGoal
{
	/** Whether the leg may end at {@code (x, y)}. */
	abstract boolean contains(int x, int y);

	/**
	 * A lexicographic lower bound on the rest of the leg from {@code (x, y)}: the fewest ticks to
	 * any goal tile in the high 32 bits and, among goal tiles that few ticks away, the least axis
	 * travel in the low 32 bits. Taking both from the same goal tile keeps the bound consistent.
	 */
	abstract long lowerBound(int x, int y);

	/**
	 * Whether the leg may end by stepping onto a goal tile that is blocked, as the A* search
	 * walks onto the blocked origin of a transport (a door or an obstacle) to take it.
	 */
	abstract boolean entersBlockedTiles();

	static long bound(int ticks, int axisTravel)
	{
		return (long) ticks << 32 | axisTravel;
	}

	static int ticks(long bound)
	{
		return (int) (bound >>> 32);
	}

	static int axisTravel(long bound)
	{
		return (int) bound;
	}

	/** One tile: a fixed waypoint, the final destination, or a transport only taken from there. */
	static WalkGoal tile(int packed)
	{
		return tiles(new int[] {packed}, WorldPointUtil.unpackWorldPlane(packed));
	}

	/** The tiles of {@code packed} on {@code plane}, all equivalent places to take the next action. */
	static WalkGoal tiles(int[] packed, int plane)
	{
		int[] xs = new int[packed.length], ys = new int[packed.length];
		int count = 0;
		for (int tile : packed)
		{
			if (WorldPointUtil.unpackWorldPlane(tile) != plane) continue;
			xs[count] = WorldPointUtil.unpackWorldX(tile);
			ys[count++] = WorldPointUtil.unpackWorldY(tile);
		}
		if (count == 0) throw new IllegalArgumentException("goal has no tile on plane " + plane);
		return new Tiles(Arrays.copyOf(xs, count), Arrays.copyOf(ys, count));
	}

	/** Every tile from which teleports needing {@code capability} can be cast. */
	static WalkGoal teleportArea(TeleportCapability capability)
	{
		return new TeleportArea(capability);
	}

	private static final class Tiles extends WalkGoal
	{
		private final int[] xs, ys;

		Tiles(int[] xs, int[] ys)
		{
			this.xs = xs;
			this.ys = ys;
		}

		@Override
		boolean contains(int x, int y)
		{
			for (int i = 0; i < xs.length; i++)
				if (xs[i] == x && ys[i] == y) return true;
			return false;
		}

		@Override
		long lowerBound(int x, int y)
		{
			long best = Long.MAX_VALUE;
			for (int i = 0; i < xs.length; i++)
			{
				int dx = Math.abs(xs[i] - x), dy = Math.abs(ys[i] - y);
				best = Math.min(best, bound(Math.max(dx, dy), dx + dy));
			}
			return best;
		}

		@Override
		boolean entersBlockedTiles()
		{
			return true;
		}

		@Override
		public String toString()
		{
			return xs.length == 1 ? "tile " + xs[0] + "," + ys[0] : xs.length + " tiles";
		}
	}

	/**
	 * The tiles outside a few rectangles, or inside a few holes in them. Leaving the rectangles takes
	 * at least as many moves as the furthest any containing rectangle's nearest edge is, and a
	 * straight walk to that edge costs as much axis travel as it does ticks; reaching a hole is
	 * bounded like reaching a tile.
	 */
	private static final class TeleportArea extends WalkGoal
	{
		private final TeleportCapability capability;
		private final int[][] excluded, holes;
		private final int left, bottom, right, top;

		TeleportArea(TeleportCapability capability)
		{
			this.capability = capability;
			this.excluded = capability.excludedAreas();
			this.holes = capability.holes();
			int l = Integer.MAX_VALUE, b = Integer.MAX_VALUE, r = Integer.MIN_VALUE, t = Integer.MIN_VALUE;
			for (int[] area : excluded)
			{
				l = Math.min(l, area[0]);
				b = Math.min(b, area[1]);
				r = Math.max(r, area[0] + area[2]);
				t = Math.max(t, area[1] + area[3]);
			}
			left = l;
			bottom = b;
			right = r;
			top = t;
		}

		@Override
		boolean contains(int x, int y)
		{
			return TeleportCapability.at(x, y).allows(capability);
		}

		@Override
		long lowerBound(int x, int y)
		{
			if (x < left || x >= right || y < bottom || y >= top) return 0;
			int distance = 0;
			for (int[] area : excluded)
			{
				if (!TeleportCapability.inArea(area, x, y)) continue;
				int left = x - area[0] + 1, right = area[0] + area[2] - x;
				int down = y - area[1] + 1, up = area[1] + area[3] - y;
				distance = Math.max(distance, Math.min(Math.min(left, right), Math.min(down, up)));
			}
			long best = bound(distance, distance);
			for (int[] hole : holes)
			{
				int dx = Math.max(0, Math.max(hole[0] - x, x - (hole[0] + hole[2] - 1)));
				int dy = Math.max(0, Math.max(hole[1] - y, y - (hole[1] + hole[3] - 1)));
				best = Math.min(best, bound(Math.max(dx, dy), dx + dy));
			}
			return best;
		}

		@Override
		boolean entersBlockedTiles()
		{
			return false;
		}

		@Override
		public String toString()
		{
			return "teleport area " + capability;
		}
	}
}

package shortestpath.pathfinder.sailing;

import java.util.Arrays;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

import static net.runelite.api.Constants.REGION_SIZE;
import net.runelite.api.Perspective;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.SplitFlagMap;

/**
 * The hull of the player's boat, so that a sailing move is only taken if the whole boat fits along it, not just its
 * centre.
 * <p>
 * A boat is a rectangle in its own frame (the game's bounds for its world entity: the raft is 1 by 3 tiles, the skiff
 * 2 by 5 and the sloop 3 by 10, reaching further toward its bow), turned to face its heading, at the spot within its
 * tile where the boat sits. Every move lands whole tiles away, so the boat keeps that spot along the whole route.
 * Holding a heading for a move sweeps the rectangle from where the move starts to where it ends, over the convex hull
 * of the two (the game's rounding can take a move slightly off the boat's axis); the move is only taken if no blocked
 * tile overlaps it. Turning between moves isn't checked. A tile blocks a boat if it's blocked or has a wall on any
 * side. Touching a blocked tile's edge is fine, so a 3-wide sloop lined up exactly fits a 3-wide gap, as players have
 * seen in game.
 * <p>
 * An instance belongs to one search: it caches the shapes it sweeps and the blocked tiles it has looked at.
 */
public final class BoatHull
{
	private static final int HEADINGS = 16;
	// The game's angles: 2048 per turn, 128 per heading
	private static final int ANGLES_PER_HEADING = 2048 / HEADINGS;
	private static final double EPSILON = 1e-6;
	private static final int REGION_SHIFT = Integer.numberOfTrailingZeros(REGION_SIZE);
	private static final int REGION_MASK = REGION_SIZE - 1;
	private static final int PLANES = 4;
	// A shape with no rows, so no tiles count as covered where a move starts
	private static final int[] EMPTY_SHAPE = {0};

	// The rectangle in the boat's own frame, in local units (128 per tile): its centre across and along the boat
	// (the bow is toward negative along) and its size
	private final int boundsX;
	private final int boundsY;
	private final int boundsWidth;
	private final int boundsHeight;
	// Where the boat sits within its tile, in local units from the tile's centre
	private final int pivotX;
	private final int pivotY;

	// Tiles the hull covers, relative to the tile it starts on: {first row, then each row's first and last column}.
	// Concurrent: the search fills it on the pathfinding thread while the client thread's arrival
	// check reads and fills it too (ShortestPathPlugin asks covers() each tick for the live boat)
	private final Map<Long, int[]> shapes = new ConcurrentHashMap<>();
	// How far the hull reaches from the centre of the boat's tile, facing any heading, in tiles
	private final double reach;
	// Tiles that block a boat, as one bit per tile and one long per row of each region and plane, filled in as the
	// search reaches them
	private final SplitFlagMap.RegionExtent extent;
	private final long[][] blockedRows;

	private BoatHull(int boundsX, int boundsY, int boundsWidth, int boundsHeight, int pivotX, int pivotY)
	{
		this.boundsX = boundsX;
		this.boundsY = boundsY;
		this.boundsWidth = boundsWidth;
		this.boundsHeight = boundsHeight;
		this.pivotX = pivotX;
		this.pivotY = pivotY;
		extent = SplitFlagMap.getRegionExtents();
		blockedRows = new long[(extent.getWidth() + 1) * (extent.getHeight() + 1) * PLANES][];

		double corner = 0;
		for (int across = -1; across <= 1; across += 2)
		{
			for (int along = -1; along <= 1; along += 2)
			{
				corner = Math.max(corner, Math.hypot(boundsX + across * boundsWidth / 2.0, boundsY + along * boundsHeight / 2.0));
			}
		}
		// A local unit more, for the game's rounding when it turns the hull
		reach = (Math.hypot(pivotX, pivotY) + corner + 1) / Perspective.LOCAL_TILE_SIZE;
	}

	/**
	 * @param boundsX      centre of the boat's rectangle across the boat, in local units (128 per tile)
	 * @param boundsY      centre of the rectangle along the boat, in local units; negative is toward the bow
	 * @param boundsWidth  width of the rectangle, in local units
	 * @param boundsHeight length of the rectangle, in local units
	 * @param pivotX       where the boat sits within its tile, in local units from the tile's centre
	 * @param pivotY       where the boat sits within its tile, in local units from the tile's centre
	 * @return the hull, or {@code null} if the bounds are empty
	 */
	public static BoatHull fromBounds(int boundsX, int boundsY, int boundsWidth, int boundsHeight, int pivotX, int pivotY)
	{
		if (boundsWidth <= 0 || boundsHeight <= 0)
		{
			return null;
		}
		return new BoatHull(boundsX, boundsY, boundsWidth, boundsHeight, pivotX, pivotY);
	}

	/**
	 * The hull's corners facing {@code heading}, in order round the rectangle, in tiles from the centre of the tile the
	 * boat is on: {x0, y0, x1, y1, x2, y2, x3, y3}.
	 */
	public double[] outline(int heading)
	{
		// corners() lists them across then along, so swap the last two to go round
		double[] corners = corners(heading * ANGLES_PER_HEADING, 0, 0);
		return new double[]{corners[0], corners[1], corners[2], corners[3], corners[6], corners[7], corners[4], corners[5]};
	}

	/**
	 * How far the hull reaches from the centre of the boat's tile, facing any heading, in tiles.
	 */
	public double reach()
	{
		return reach;
	}

	/**
	 * Whether the hull, on a tile facing {@code heading}, covers the tile (dx, dy) tiles from it: overlaps it by more
	 * than touching its edge.
	 */
	public boolean covers(int heading, int dx, int dy)
	{
		int[] shape = shape(heading, 0, 0);
		int row = dy - shape[0];
		return row >= 0 && row < rows(shape) && dx >= shape[1 + 2 * row] && dx <= shape[2 + 2 * row];
	}

	/**
	 * Whether the hull, facing {@code heading}, can sail (dx, dy) tiles from tile (x, y, z) without overlapping a tile
	 * that blocks it anywhere along the way, where it starts and ends included.
	 */
	public boolean canMove(CollisionMap map, int x, int y, int z, int heading, int dx, int dy)
	{
		return canMove(map, x, y, z, heading, dx, dy, false);
	}

	/**
	 * Whether the hull, facing {@code heading}, can sail (dx, dy) tiles from tile (x, y, z) without overlapping a tile
	 * that blocks it anywhere along the way — or only ones it doesn't already cover, when {@code exemptStart} marks
	 * the search's first move: a berthed boat's hull can overlap blocked tiles where it starts (a moored boat may sit
	 * over marked tiles), and like {@link SailingSearch#canSailLine}'s first-tile escape they can't stop it leaving.
	 * Later moves keep the full start check, which also catches the hull turning onto a blocked tile between moves.
	 */
	public boolean canMove(CollisionMap map, int x, int y, int z, int heading, int dx, int dy, boolean exemptStart)
	{
		final int[] shape = shape(heading, dx, dy);
		final int[] start = exemptStart ? shape(heading, 0, 0) : EMPTY_SHAPE;
		for (int row = 0; row < rows(shape); row++)
		{
			final int rowY = shape[0] + row;
			final int lo = shape[1 + 2 * row];
			final int hi = shape[2 + 2 * row];
			final int startRow = rowY - start[0];
			if (startRow < 0 || startRow >= rows(start))
			{
				if (anyBlocked(map, x + lo, x + hi, y + rowY, z))
				{
					return false;
				}
				continue;
			}
			if (anyBlocked(map, x + lo, x + Math.min(hi, start[1 + 2 * startRow] - 1), y + rowY, z)
				|| anyBlocked(map, x + Math.max(lo, start[2 + 2 * startRow] + 1), x + hi, y + rowY, z))
			{
				return false;
			}
		}
		return true;
	}

	/**
	 * Lets go of the shapes and blocked tiles cached during a search, once it's done; they're worked out again if needed.
	 */
	void release()
	{
		shapes.clear();
		Arrays.fill(blockedRows, null);
	}

	private static int rows(int[] shape)
	{
		return (shape.length - 1) / 2;
	}

	// Whether any tile from (x0, y) to (x1, y) blocks the boat
	private boolean anyBlocked(CollisionMap map, int x0, int x1, int y, int z)
	{
		for (int x = x0; x <= x1; )
		{
			int last = Math.min(x1, x | REGION_MASK);
			long[] rows = regionRows(map, x >> REGION_SHIFT, y >> REGION_SHIFT, z);
			if (rows == null)
			{
				return true;
			}
			int lo = x & REGION_MASK;
			long mask = (-1L >>> (63 - ((last & REGION_MASK) - lo))) << lo;
			if ((rows[y & REGION_MASK] & mask) != 0)
			{
				return true;
			}
			x = last + 1;
		}
		return false;
	}

	// The tiles of a region and plane that block a boat, one long per row, or null off the map
	private long[] regionRows(CollisionMap map, int regionX, int regionY, int z)
	{
		if (regionX < extent.getMinX() || regionX > extent.getMaxX() || regionY < extent.getMinY()
			|| regionY > extent.getMaxY() || z < 0 || z >= PLANES)
		{
			return null;
		}
		int index = ((regionX - extent.getMinX()) + (regionY - extent.getMinY()) * (extent.getWidth() + 1)) * PLANES + z;
		long[] rows = blockedRows[index];
		if (rows == null)
		{
			rows = new long[REGION_SIZE];
			final int baseX = regionX << REGION_SHIFT;
			final int baseY = regionY << REGION_SHIFT;
			// Which tiles are blocked, including a border one tile wide around the region
			final int size = REGION_SIZE + 2;
			boolean[] blocked = new boolean[size * size];
			for (int row = 0; row < size; row++)
			{
				for (int column = 0; column < size; column++)
				{
					blocked[row * size + column] = map.isBlocked(baseX + column - 1, baseY + row - 1, z);
				}
			}
			for (int row = 0; row < REGION_SIZE; row++)
			{
				long bits = 0;
				for (int column = 0; column < REGION_SIZE; column++)
				{
					final int x = baseX + column;
					final int y = baseY + row;
					final int i = (row + 1) * size + column + 1;
					// A side that can't be crossed into an open tile has a wall on it
					boolean wall = (!map.n(x, y, z) && !blocked[i + size]) || (!map.s(x, y, z) && !blocked[i - size])
						|| (!map.e(x, y, z) && !blocked[i + 1]) || (!map.w(x, y, z) && !blocked[i - 1]);
					if (blocked[i] || wall)
					{
						bits |= 1L << column;
					}
				}
				rows[row] = bits;
			}
			blockedRows[index] = rows;
		}
		return rows;
	}

	// The tiles the hull overlaps while sailing (dx, dy) tiles facing heading, relative to the tile it starts on
	private int[] shape(int heading, int dx, int dy)
	{
		long key = ((long) heading << 40) | ((long) (dx & 0xFFFFF) << 20) | (dy & 0xFFFFF);
		int[] shape = shapes.get(key);
		if (shape == null)
		{
			shape = rasterize(corners(heading * ANGLES_PER_HEADING, dx, dy));
			shapes.put(key, shape);
		}
		return shape;
	}

	// The hull's corners where it starts and where it ends, in tiles around the start tile's centre:
	// {x0, y0, x1, y1, ...}. They're turned in whole local units with the game's sine table, the way the game
	// turns models, so they're exact and edges that line up with tile edges do so exactly.
	private double[] corners(int angle, int dx, int dy)
	{
		final int cos = Perspective.COSINE[angle];
		final int sin = Perspective.SINE[angle];
		double[] points = new double[16];
		int i = 0;
		for (int end = 0; end <= 1; end++)
		{
			for (int across = -1; across <= 1; across += 2)
			{
				for (int along = -1; along <= 1; along += 2)
				{
					int modelX = boundsX + across * boundsWidth / 2;
					int modelY = boundsY + along * boundsHeight / 2;
					int x = pivotX + end * dx * Perspective.LOCAL_TILE_SIZE + ((modelX * cos + modelY * sin) >> 16);
					int y = pivotY + end * dy * Perspective.LOCAL_TILE_SIZE + ((modelY * cos - modelX * sin) >> 16);
					points[i++] = (double) x / Perspective.LOCAL_TILE_SIZE;
					points[i++] = (double) y / Perspective.LOCAL_TILE_SIZE;
				}
			}
		}
		return points;
	}

	// The tiles a convex shape (the hull of the given points) overlaps by more than touching, as rows
	private static int[] rasterize(double[] points)
	{
		double[] hull = convexHull(points);
		int n = hull.length / 2;
		double minY = Double.MAX_VALUE;
		double maxY = -Double.MAX_VALUE;
		for (int i = 0; i < n; i++)
		{
			minY = Math.min(minY, hull[2 * i + 1]);
			maxY = Math.max(maxY, hull[2 * i + 1]);
		}
		// Tile row r covers y from r - 0.5 to r + 0.5, and column c covers x from c - 0.5 to c + 0.5
		int firstRow = (int) Math.floor(minY - 0.5 + EPSILON) + 1;
		int lastRow = (int) Math.ceil(maxY + 0.5 - EPSILON) - 1;
		int[] columns = new int[2 * Math.max(0, lastRow - firstRow + 1)];
		int rows = 0;
		int shapeFirstRow = firstRow;
		for (int row = firstRow; row <= lastRow; row++)
		{
			double[] range = xRange(hull, n, row - 0.5 + EPSILON, row + 0.5 - EPSILON);
			int first = (int) Math.floor(range[0] - 0.5 + EPSILON) + 1;
			int last = (int) Math.ceil(range[1] + 0.5 - EPSILON) - 1;
			if (first > last)
			{
				// Only the rows at either end can be empty, where the shape barely reaches them
				if (rows == 0)
				{
					shapeFirstRow = row + 1;
				}
				continue;
			}
			columns[2 * rows] = first;
			columns[2 * rows + 1] = last;
			rows++;
		}
		int[] shape = new int[1 + 2 * rows];
		shape[0] = shapeFirstRow;
		System.arraycopy(columns, 0, shape, 1, 2 * rows);
		return shape;
	}

	// The smallest and largest x of a convex polygon between two heights
	private static double[] xRange(double[] polygon, int n, double low, double high)
	{
		double min = Double.MAX_VALUE;
		double max = -Double.MAX_VALUE;
		for (int i = 0; i < n; i++)
		{
			double x1 = polygon[2 * i];
			double y1 = polygon[2 * i + 1];
			double x2 = polygon[2 * ((i + 1) % n)];
			double y2 = polygon[2 * ((i + 1) % n) + 1];
			if (y1 >= low && y1 <= high)
			{
				min = Math.min(min, x1);
				max = Math.max(max, x1);
			}
			for (double level : new double[]{low, high})
			{
				if ((y1 - level) * (y2 - level) < 0)
				{
					double x = x1 + (level - y1) * (x2 - x1) / (y2 - y1);
					min = Math.min(min, x);
					max = Math.max(max, x);
				}
			}
		}
		return new double[]{min, max};
	}

	// Andrew's monotone chain; returns the hull's corners in order as {x0, y0, x1, y1, ...}
	private static double[] convexHull(double[] points)
	{
		int n = points.length / 2;
		Integer[] order = new Integer[n];
		for (int i = 0; i < n; i++)
		{
			order[i] = i;
		}
		Arrays.sort(order, (a, b) -> points[2 * a] != points[2 * b]
			? Double.compare(points[2 * a], points[2 * b]) : Double.compare(points[2 * a + 1], points[2 * b + 1]));
		int[] hull = new int[2 * n + 1];
		int k = 0;
		for (int j = 0; j < n; j++)
		{
			while (k >= 2 && cross(points, hull[k - 2], hull[k - 1], order[j]) <= 0)
			{
				k--;
			}
			hull[k++] = order[j];
		}
		int lower = k + 1;
		for (int j = n - 2; j >= 0; j--)
		{
			while (k >= lower && cross(points, hull[k - 2], hull[k - 1], order[j]) <= 0)
			{
				k--;
			}
			hull[k++] = order[j];
		}
		// The last corner is the first one again
		k--;
		double[] result = new double[2 * k];
		for (int i = 0; i < k; i++)
		{
			result[2 * i] = points[2 * hull[i]];
			result[2 * i + 1] = points[2 * hull[i] + 1];
		}
		return result;
	}

	private static double cross(double[] p, int o, int a, int b)
	{
		return (p[2 * a] - p[2 * o]) * (p[2 * b + 1] - p[2 * o + 1]) - (p[2 * a + 1] - p[2 * o + 1]) * (p[2 * b] - p[2 * o]);
	}
}

package shortestpath.pathfinder.sailing;

import java.util.Arrays;

import net.runelite.api.Perspective;

/**
 * The moves the sailing search uses for one boat speed.
 * <p>
 * A boat sails in one of 16 headings, and each tick it moves by that heading's velocity rounded to
 * quarter tiles, so the real direction of a heading depends on the speed: at speed 2, NNE moves 3
 * quarter tiles across and 7 up per tick (23.2 degrees, not 22.5). Holding a heading for 1, 2 or 4
 * ticks always lands a whole number of tiles away, with the boat at the same spot within its tile.
 * Each move here is one heading held for the fewest such ticks, so every leg of a path is a direction
 * the boat can actually sail. The search looks for the shortest route rather than the quickest, so each
 * move costs the distance it sails ({@link #length}).
 * <p>
 * The search uses the boat's base speed for the whole route, since speed boosts are random and
 * temporary; {@link #ESTIMATE} is the fallback when the base speed can't be read.
 */
public final class SailingMoves
{
	private static final String[] HEADING_NAMES = {
		"S", "SSW", "SW", "WSW", "W", "WNW", "NW", "NNW", "N", "NNE", "NE", "ENE", "E", "ESE", "SE", "SSE"
	};

	/**
	 * Fallback speed when the boat's base speed can't be read. Straight and diagonal headings go the same
	 * way at every speed; at speed 2 the in-between headings (NNE and so on) are within a couple of degrees
	 * of their direction at the common speeds 2 to 4.
	 */
	public static final double ESTIMATED_SPEED = 2.0;

	/**
	 * The fastest a real boat's base speed can be, in tiles per tick: the common speeds are 2 to 4, and
	 * double the fastest leaves headroom for quicker hulls. A speed above it is a stale or mis-scaled
	 * reading rather than a faster boat — the moves it builds are so long that nothing can sail them —
	 * so the estimate is used instead.
	 */
	public static final double MAX_SPEED = 8.0;

	public static final SailingMoves ESTIMATE = forSpeed(ESTIMATED_SPEED);

	/**
	 * {@link #length} is in thousandths of a tile, so that adding lengths up is exact.
	 */
	public static final int LENGTH_UNITS_PER_TILE = 1000;

	private final double speed;
	private final int[] dx;
	private final int[] dy;
	private final int[] ticks;
	private final int[] lengths;
	private final int[] headings;
	private final String[] names;

	private SailingMoves(double speed, int[] dx, int[] dy, int[] ticks, int[] lengths, int[] headings, String[] names)
	{
		this.speed = speed;
		this.dx = dx;
		this.dy = dy;
		this.ticks = ticks;
		this.lengths = lengths;
		this.headings = headings;
		this.names = names;
	}

	/**
	 * @param tilesPerTick boat speed, e.g. 1.5 or 2.0; an out-of-range value (including NaN) gives the estimate
	 */
	public static SailingMoves forSpeed(double tilesPerTick)
	{
		if (!(tilesPerTick > 0) || tilesPerTick > MAX_SPEED)
		{
			return ESTIMATE;
		}
		int[] dx = new int[HEADING_NAMES.length];
		int[] dy = new int[HEADING_NAMES.length];
		int[] ticks = new int[HEADING_NAMES.length];
		int[] lengths = new int[HEADING_NAMES.length];
		int[] headings = new int[HEADING_NAMES.length];
		String[] names = new String[HEADING_NAMES.length];
		int count = 0;
		for (int heading = 0; heading < HEADING_NAMES.length; heading++)
		{
			// Headings are 128 angle units apart: 0 is south, 512 west, 1024 north, 1536 east
			int angle = heading * 128;
			int quarterX = quarterTiles(-Perspective.SINE[angle] * tilesPerTick / 512.0);
			int quarterY = quarterTiles(-Perspective.COSINE[angle] * tilesPerTick / 512.0);
			if (quarterX == 0 && quarterY == 0)
			{
				continue;
			}
			// Fewest ticks (1, 2 or 4) after which the boat is a whole number of tiles away
			int k = 1;
			while ((k * quarterX) % 4 != 0 || (k * quarterY) % 4 != 0)
			{
				k *= 2;
			}
			dx[count] = k * quarterX / 4;
			dy[count] = k * quarterY / 4;
			ticks[count] = k;
			// Rounded up, so a route never costs less than its real length and the search's estimate stays a lower bound
			lengths[count] = (int) Math.ceil(Math.hypot(dx[count], dy[count]) * LENGTH_UNITS_PER_TILE);
			headings[count] = heading;
			names[count] = HEADING_NAMES[heading];
			count++;
		}
		if (count == 0)
		{
			// Below about 0.125 tiles per tick every heading rounds to no movement; a garbage or
			// stale base-speed reading must not produce a search that can never move
			return ESTIMATE;
		}
		return new SailingMoves(tilesPerTick, Arrays.copyOf(dx, count), Arrays.copyOf(dy, count),
			Arrays.copyOf(ticks, count), Arrays.copyOf(lengths, count), Arrays.copyOf(headings, count),
			Arrays.copyOf(names, count));
	}

	// The game's velocity along one axis: rounded to local units (128 per tile), then to quarter tiles (32 each)
	private static int quarterTiles(double localUnits)
	{
		double local = Math.signum(localUnits) * Math.round(Math.abs(localUnits));
		return (int) (Math.signum(local) * Math.round(Math.abs(local) / 32.0));
	}

	public double speed()
	{
		return speed;
	}

	public int size()
	{
		return dx.length;
	}

	public int dx(int move)
	{
		return dx[move];
	}

	public int dy(int move)
	{
		return dy[move];
	}

	public int ticks(int move)
	{
		return ticks[move];
	}

	/**
	 * The heading the move holds: 0 is south, 4 west, 8 north and 12 east, like the game's orientation divided by 128.
	 */
	public int heading(int move)
	{
		return headings[move];
	}

	public String name(int move)
	{
		return names[move];
	}

	/**
	 * How far the move sails in a straight line, in thousandths of a tile ({@link #LENGTH_UNITS_PER_TILE}), rounded up.
	 */
	public int length(int move)
	{
		return lengths[move];
	}

	/**
	 * The heading of the move that goes (dx, dy) tiles, or -1 if there is none.
	 */
	public int headingOf(int dx, int dy)
	{
		int move = indexOf(dx, dy);
		return move < 0 ? -1 : headings[move];
	}

	/**
	 * Index of the move that goes (dx, dy) tiles, or -1 if there is none.
	 */
	public int indexOf(int dx, int dy)
	{
		for (int i = 0; i < this.dx.length; i++)
		{
			if (this.dx[i] == dx && this.dy[i] == dy)
			{
				return i;
			}
		}
		return -1;
	}
}

package shortestpath.pathfinder.sailing;

import java.util.List;
import java.util.Set;

import lombok.Getter;
import shortestpath.PrimitiveIntList;
import shortestpath.WorldPointUtil;
import shortestpath.leagues.LeagueModeState;
import shortestpath.pathfinder.ActiveSearch;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.IntDeque;
import shortestpath.pathfinder.IntMinHeap;
import shortestpath.pathfinder.NodeGraph;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.PathTerminationReason;
import shortestpath.pathfinder.PathfinderConfig;
import shortestpath.pathfinder.PathfinderResult;
import shortestpath.pathfinder.PathfinderStats;
import shortestpath.pathfinder.SearchDeadline;
import shortestpath.pathfinder.TargetGoals;
import shortestpath.pathfinder.Targets;
import shortestpath.pathfinder.VisitedTiles;
import shortestpath.pathfinder.WildernessChecker;

/**
 * The sailing search: a Dijkstra over the boat's 16 headings (see {@link SailingMoves}) that keeps the
 * boat's whole hull clear along every move and arrives once the hull covers a target, rather than on
 * a tile. A self-contained search sharing only the public machinery of {@code pathfinder} (NodeGraph,
 * VisitedTiles, TargetGoals, SplitFlagMap) — it is an {@link ActiveSearch}, not a {@code Pathfinder},
 * so a walking search and a sailing search never share a class.
 */
public class SailingPathfinder implements ActiveSearch
{
	private final Stats stats;
	@Getter
	private final int start;
	// The targets keep their required items so a restart after landing honours them, but a
	// sailing search ignores them: a boat can't visit a bank.
	@Getter
	private final Targets targets;
	// Termination set resolved by TargetGoals: the requested targets plus, for
	// each blocked target, its fallback tiles (issue #640).
	private final Set<Integer> goals;
	// Whether any requested target could possibly terminate the search: non-blocked,
	// a transport destination, or resolved to at least one walkable nearby tile.
	// When false the search is skipped entirely, since no goal can ever be visited.
	private final boolean hasViableGoal;
	private final SailingSearch sailing;
	private final PathfinderConfig config;
	private final CollisionMap map;
	private final boolean targetInWilderness;
	private final boolean targetInBlockedRegion;
	private final Runnable completionCallback;
	// Nodes are stored structure-of-arrays style: each node is an int id into the graph, instead of
	// an object per explored tile. This keeps a whole search to a handful of arrays (issue #491).
	private final NodeGraph graph = new NodeGraph(1 << 14);
	// Capacities should be enough to store all nodes without requiring the queue to grow
	// They were found by checking the max queue size
	private final IntDeque boundary = new IntDeque(4096);
	private final IntMinHeap pending = new IntMinHeap(graph, 256);
	private final VisitedTiles visited;
	// The reusable emission buffer the neighbour enumeration fills; a sailing search emits only
	// weighted tiles into it.
	private final PrimitiveIntList neighbors = new PrimitiveIntList(16);
	@Getter
	private volatile boolean done = false;
	private volatile boolean cancelled = false;
	// Read by the render thread during the search to draw the partial path; written by the worker.
	private volatile int bestLastNode = NodeGraph.NO_NODE;
	// The path the render thread builds progressively while the search runs.
	private List<PathStep> pathSteps = List.of();
	private boolean pathNeedsUpdate = false;
	// Built once on the worker thread when the search finishes, then served to the render thread so
	// it never walks the node chain (which is released) after the search is done.
	private volatile List<PathStep> finalPath = null;
	private volatile int closestReachedPoint = WorldPointUtil.UNDEFINED;
	private volatile int finalPathCost = PathfinderResult.NO_PATH_COST;
	private int bestRemainingDistance = Integer.MAX_VALUE;
	private int bestTravelledDistance = Integer.MAX_VALUE;
	private int bestX = Integer.MAX_VALUE;
	private int bestY = Integer.MAX_VALUE;
	private int reachedTarget = WorldPointUtil.UNDEFINED;
	private PathTerminationReason terminationReason;
	/**
	 * Teleportation transports are updated when this changes.
	 * Can be either:
	 * 0 = all teleports can be used (e.g. Chronicle)
	 * 20 = most teleports can be used (e.g. Varrock Teleport)
	 * 30 = some teleports can be used (e.g. Amulet of Glory)
	 * 31 = no teleports can be used
	 */
	private int wildernessLevel;

	/**
	 * @param moves the boat's moves; required — a walking search is a plain {@code Pathfinder}
	 */
	public SailingPathfinder(PathfinderConfig config, int start, Set<Integer> targets, Runnable completionCallback,
		SailingMoves moves)
	{
		this(config, start, targets, completionCallback, moves, null);
	}

	/**
	 * @param moves the boat's moves; required — a walking search is a plain {@code Pathfinder}
	 * @param boatHull the boat's hull, which must fit along every sailing move, or {@code null} for just its centre
	 */
	public SailingPathfinder(PathfinderConfig config, int start, Set<Integer> targets, Runnable completionCallback,
		SailingMoves moves, BoatHull boatHull)
	{
		this(config, start, targets, completionCallback, moves, boatHull, WorldPointUtil.UNDEFINED);
	}

	/**
	 * @param moves          the boat's moves; required — a walking search is a plain {@code Pathfinder}
	 * @param boatHull       the boat's hull, which must fit along every sailing move, or {@code null} for just its centre
	 * @param sailingHeading the heading the boat is facing where the route starts (0 south, 8 north), or -1 when it
	 *                       isn't known: a target the hull already covers then counts as arrived facing any heading
	 */
	public SailingPathfinder(PathfinderConfig config, int start, Set<Integer> targets, Runnable completionCallback,
		SailingMoves moves, BoatHull boatHull, int sailingHeading)
	{
		this(config, start, Targets.at(targets), completionCallback, moves, boatHull, sailingHeading);
	}

	/** As {@link #SailingPathfinder(PathfinderConfig, int, Set, Runnable, SailingMoves, BoatHull, int)}. */
	public SailingPathfinder(PathfinderConfig config, int start, Targets targets, Runnable completionCallback,
		SailingMoves moves, BoatHull boatHull, int sailingHeading)
	{
		stats = new Stats();
		this.config = config;
		this.map = config.getMap();
		this.start = start;
		this.targets = targets;
		Set<Integer> points = targets.points();
		TargetGoals resolved = TargetGoals.resolve(config, start, points);
		this.goals = resolved.goals();
		this.hasViableGoal = resolved.hasViableGoal();
		this.sailing = new SailingSearch(moves, boatHull, points.stream().mapToInt(Integer::intValue).toArray(),
			goals.stream().mapToInt(Integer::intValue).toArray(), sailingHeading);
		this.completionCallback = completionCallback;
		visited = new VisitedTiles(map, config.getBankVisitCost());
		targetInWilderness = WildernessChecker.isInWilderness(points);
		targetInBlockedRegion = anyInBlockedRegion(config.getLeagueModeState(), points);
		wildernessLevel = 31;
	}

	/**
	 * The target the boat, on the tile at {@code packedPosition} and facing {@code heading} (one of the
	 * 16 headings, or -1 when unknown), has arrived at — see {@link SailingSearch#arrivedTarget}. Lets
	 * the plugin ask where the live boat is rather than trusting the search's verdict, which says a
	 * route was found, not that the boat sailed it. {@link WorldPointUtil#UNDEFINED} if it hasn't
	 * arrived.
	 */
	public int arrivedTarget(int packedPosition, int heading)
	{
		return sailing.arrivedTarget(packedPosition, heading);
	}

	private static boolean anyInBlockedRegion(LeagueModeState league, Set<Integer> packed)
	{
		if (!league.isSeasonal() || packed == null || packed.isEmpty())
		{
			return false;
		}
		for (Integer point : packed)
		{
			if (league.isInBlockedRegion(point))
			{
				return true;
			}
		}
		return false;
	}

	public void cancel()
	{
		cancelled = true;
	}

	public PathfinderStats getStats()
	{
		if (stats.started && stats.ended)
		{
			return stats;
		}

		// Don't give incomplete results
		return null;
	}

	public List<PathStep> getPath()
	{
		int lastNode = bestLastNode; // For thread safety, read bestLastNode once
		if (lastNode == NodeGraph.NO_NODE)
		{
			List<PathStep> finalised = finalPath;
			return finalised != null ? finalised : pathSteps;
		}

		// Once the search is finished the node graph is released, so serve the pre-built snapshot.
		if (done)
		{
			List<PathStep> finalised = finalPath;
			if (finalised != null)
			{
				return finalised;
			}
		}

		if (pathNeedsUpdate)
		{
			List<PathStep> walked = graph.getPathSteps(lastNode);
			// An empty result means the graph was released mid-walk; keep the last good path.
			if (!walked.isEmpty())
			{
				pathSteps = walked;
				pathNeedsUpdate = false;
			}
		}

		return pathSteps;
	}

	public PathfinderResult getResult()
	{
		PathfinderStats currentStats = getStats();
		if (currentStats == null)
		{
			return null;
		}

		List<PathStep> currentPath = getPath();
		boolean reached = reachedTarget != WorldPointUtil.UNDEFINED;
		int target = reached ? reachedTarget : (targets.isEmpty() ? WorldPointUtil.UNDEFINED : targets.points().iterator().next());
		// getStats() only returns non-null once the search has ended, so the snapshot is set.
		return new PathfinderResult(
			start,
			target,
			reached,
			currentPath,
			closestReachedPoint,
			finalPathCost,
			currentStats.getNodesChecked(),
			currentStats.getTransportsChecked(),
			currentStats.getElapsedTimeNanos(),
			terminationReason
		);
	}

	private void addNeighbors(int node, int nodePacked)
	{
		final int x = WorldPointUtil.unpackWorldX(nodePacked);
		final int y = WorldPointUtil.unpackWorldY(nodePacked);
		final int z = WorldPointUtil.unpackWorldPlane(nodePacked);
		neighbors.clear();
		sailing.addNeighbors(map, neighbors, node, x, y, z, graph.bankVisited(node), visited, graph);
		final int count = neighbors.size();
		for (int i = 0; i < count; i++)
		{
			int neighbor = neighbors.get(i);
			final int neighborPacked = graph.packedPosition(neighbor);
			if (config.avoidWilderness(nodePacked, neighborPacked, targetInWilderness))
			{
				continue;
			}
			if (config.avoidBlockedRegion(nodePacked, neighborPacked, targetInBlockedRegion))
			{
				continue;
			}
			// Every emitted node is a weighted tile: a sailing move crosses its whole span at once, so
			// check its midpoint too, so a leg can't clip a wilderness or league boundary inside its reach
			final int midPacked = WorldPointUtil.packWorldPoint(
				(WorldPointUtil.unpackWorldX(nodePacked) + WorldPointUtil.unpackWorldX(neighborPacked)) / 2,
				(WorldPointUtil.unpackWorldY(nodePacked) + WorldPointUtil.unpackWorldY(neighborPacked)) / 2,
				WorldPointUtil.unpackWorldPlane(nodePacked));
			if (config.avoidWilderness(nodePacked, midPacked, targetInWilderness)
				|| config.avoidWilderness(midPacked, neighborPacked, targetInWilderness)
				|| config.avoidBlockedRegion(nodePacked, midPacked, targetInBlockedRegion)
				|| config.avoidBlockedRegion(midPacked, neighborPacked, targetInBlockedRegion))
			{
				continue;
			}

			pending.add(neighbor);
			// Only now, past the checks above, is the sailing tile queued at this cost, so a move they turn
			// down doesn't stop another route from queuing the tile
			sailing.setQueuedCost(WorldPointUtil.unpackWorldX(neighborPacked), WorldPointUtil.unpackWorldY(neighborPacked),
				WorldPointUtil.unpackWorldPlane(neighborPacked), graph.bankVisited(neighbor), graph.cost(neighbor));
			++stats.nodesChecked;
		}
	}

	/**
	 * Pathfinding to an unreachable target is slightly different from normal pathfinding.
	 * Straight-line movement before diagonal movement is no longer prioritized, because the
	 * original target is moved to the closest reachable tile. To avoid having to move the
	 * original target we instead do the following to favour the closest reachable tile:
	 * - 1) Pick the path with the minimum Euclidean distance (no need to use square root though)
	 * - 2) If a tie occurs, pick the path with minimum travelled distance
	 * - 3) If another tie occurs, pick the path with minimum x-coordinate
	 * - 4) If another tie occurs, pick the path with minimum y-coordinate
	 */
	private boolean updateBestPathWhenUnreachable(int node, int packedPosition)
	{
		boolean update = false;

		final int travelledDistance = graph.cost(node);
		for (int target : targets.points())
		{
			int remainingDistance = WorldPointUtil.distanceBetween(target, packedPosition, WorldPointUtil.EUCLIDEAN_SQUARED_DISTANCE_METRIC);
			int x = WorldPointUtil.unpackWorldX(packedPosition);
			int y = WorldPointUtil.unpackWorldY(packedPosition);
			if ((remainingDistance < bestRemainingDistance) ||
				(remainingDistance == bestRemainingDistance && travelledDistance < bestTravelledDistance) ||
				(remainingDistance == bestRemainingDistance && travelledDistance == bestTravelledDistance && x < bestX) ||
				(remainingDistance == bestRemainingDistance && travelledDistance == bestTravelledDistance && x == bestX && y < bestY))
			{
				bestRemainingDistance = remainingDistance;
				bestTravelledDistance = travelledDistance;
				bestX = x;
				bestY = y;
				bestLastNode = node;
				pathNeedsUpdate = true;
				update = true;
			}
		}

		return update;
	}

	/**
	 * Update wilderness level based on the current node position.
	 */
	private void updateWildernessLevel(int packedPosition)
	{
		if (wildernessLevel > 0)
		{
			// These are overlapping boundaries, so if the node isn't in level 30, it's in 0-29
			// likewise, if the node isn't in level 20, it's in 0-19
			if (wildernessLevel > 30 && !WildernessChecker.isInLevel30Wilderness(packedPosition))
			{
				wildernessLevel = 30;
			}
			if (wildernessLevel > 20 && !WildernessChecker.isInLevel20Wilderness(packedPosition))
			{
				wildernessLevel = 20;
			}
			if (wildernessLevel > 0 && !WildernessChecker.isInWilderness(packedPosition))
			{
				wildernessLevel = 0;
			}
		}
	}

	@Override
	public void run()
	{
		stats.start();
		boundary.addFirst(graph.createStart(start));

		// The cutoff counts time without progress towards the target.
		SearchDeadline deadline = new SearchDeadline(config.getCalculationCutoffMillis());

		// When every target is a blocked tile that no transport lands on and no
		// walkable tile exists within the unreachable distance, no node can ever
		// satisfy the goal set — skip the search instead of exhausting the map.
		// A sailing search still runs: its hull can cover a target the walking
		// goals can't reach, which is what it arrives on rather than the goal set.
		while (!cancelled && (hasViableGoal || !targets.isEmpty())
			&& (!boundary.isEmpty() || !pending.isEmpty()))
		{
			int boundaryHead = boundary.peekFirst();
			int pendingHead = pending.peek();

			int node;
			// On a cost tie the pending heap wins: a queued transport that is strictly
			// cheaper than the walking route must claim its destination before an
			// equal-cost boundary node can expand and emit a competing walking edge.
			if (pendingHead != NodeGraph.NO_NODE
				&& (boundaryHead == NodeGraph.NO_NODE || graph.compareCost(pendingHead) <= graph.cost(boundaryHead)))
			{
				node = pending.poll();

				// Every node in pending is a sailing tile; none of them claimed their
				// destination at enqueue. The first, cheapest, dequeue wins the tile; later
				// queued duplicates for the same tile are dropped here — unless the duplicate
				// is a sailing move that arrives on its own heading, queued for it because the
				// settled heading didn't cover a target.
				int packed = graph.packedPosition(node);
				boolean bank = graph.bankVisited(node);
				if (visited.get(packed, bank)
					&& !(graph.isWeighted(node)
						&& sailing.arrivedTarget(packed, sailing.arrivalHeading(graph, node)) != WorldPointUtil.UNDEFINED))
				{
					continue;
				}
				visited.set(packed, bank);
			}
			else
			{
				node = boundary.pollFirst();
			}
			if (node == NodeGraph.NO_NODE)
			{
				continue;
			}
			// A sailing search explores only tiles: the start node and the weighted tiles its
			// moves emit, so there is no nodeIsTile branch to keep. The walking search's
			// nearest-tile acceptance (shortestAcceptedNode/updateCustomPathWhenUnreachable) is
			// likewise dropped: accepting the first tile near a target could truncate the path
			// before the hull reaches a heading that covers one.
			final int nodePacked = graph.packedPosition(node);
			updateWildernessLevel(nodePacked);

			final int arrivedTarget = sailing.arrivedTarget(nodePacked, sailing.arrivalHeading(graph, node));
			if (goals.contains(nodePacked) || arrivedTarget != WorldPointUtil.UNDEFINED)
			{
				bestLastNode = node;
				// A sailing arrival reports the target the hull covers, which can sit a
				// boat length from the boat's tile rather than on it
				reachedTarget = goals.contains(nodePacked) ? nodePacked : arrivedTarget;
				pathNeedsUpdate = true;
				terminationReason = PathTerminationReason.TARGET_REACHED;
				break;
			}

			// Unreachable sailing routes still draw toward the target; isPathUnreachable
			// reads result.isReached()
			if (updateBestPathWhenUnreachable(node, nodePacked))
			{
				deadline.progressed();
			}

			if (deadline.expired())
			{
				terminationReason = PathTerminationReason.CUTOFF_REACHED;
				break;
			}

			addNeighbors(node, nodePacked);
		}

		if (cancelled)
		{
			terminationReason = PathTerminationReason.CANCELLED;
		}
		else if (terminationReason == null)
		{
			terminationReason = PathTerminationReason.SEARCH_EXHAUSTED;
		}

		// Materialise the final path and closest reached tile on the worker thread, publish them,
		// then release the large node graph. Once done is set the render thread serves finalPath
		// and never touches the released graph, so this is race-free with progressive rendering.
		int lastNode = bestLastNode;
		if (lastNode != NodeGraph.NO_NODE)
		{
			finalPath = graph.getPathSteps(lastNode);
			closestReachedPoint = graph.getClosestTilePosition(lastNode);
			finalPathCost = graph.cost(lastNode);
		}
		else
		{
			finalPath = pathSteps;
			closestReachedPoint = start;
			finalPathCost = PathfinderResult.NO_PATH_COST;
		}

		done = !cancelled;

		boundary.clear();
		visited.clear();
		pending.clear();
		graph.release();
		sailing.release();

		stats.end(); // Include cleanup in stats to get the total cost of pathfinding

		if (completionCallback != null)
		{
			completionCallback.run();
		}
	}

	// PathfinderStats' counters are package-private in pathfinder, so this keeps its own: the
	// nodes it checked (a sailing search never checks transports, so getTransportsChecked()
	// inherits the base's constant 0) and its own start/end clock.
	private static final class Stats extends PathfinderStats
	{
		private int nodesChecked;
		private long startNanos, endNanos;
		private volatile boolean started, ended;

		void start()
		{
			started = true;
			nodesChecked = 0;
			startNanos = System.nanoTime();
		}

		void end()
		{
			endNanos = System.nanoTime();
			ended = true;
		}

		@Override
		public int getNodesChecked()
		{
			return nodesChecked;
		}

		@Override
		public int getTotalNodesChecked()
		{
			return nodesChecked;
		}

		@Override
		public long getElapsedTimeNanos()
		{
			return endNanos - startNanos;
		}
	}
}

package shortestpath.pathfinder.sailing;

import java.util.Arrays;

import static net.runelite.api.Constants.REGION_SIZE;
import shortestpath.PrimitiveIntList;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.NodeGraph;
import shortestpath.pathfinder.SplitFlagMap;
import shortestpath.pathfinder.VisitedTiles;

/**
 * One sailing search's moves, boat, targets and when it counts as arriving (see {@link SailingPathfinder}).
 * <p>
 * With the boat's hull, the path arrives once a target tile is inside the hull, where the path ends and facing the way
 * it sailed there. Without one, moves land whole tiles away, often several at a time, so a boat can't stop on every
 * tile: at speed 2 every move goes an even number of tiles across and up together, so half of all tiles are out of
 * reach. The path then arrives once the boat is on a target or next to it.
 * <p>
 * It also remembers the cheapest cost each tile has been queued at, so that a tile is only queued again when a route
 * reaches it for less — or, with a hull, when a costlier move would arrive on a heading none has tried: a dearer one
 * would only be dequeued once the tile is done.
 */
final class SailingSearch
{
	private static final int REGION_SHIFT = Integer.numberOfTrailingZeros(REGION_SIZE);
	private static final int REGION_MASK = REGION_SIZE - 1;
	private static final int PLANES = 4;
	private static final int HEADINGS = 16;
	// Sailing moves cost the distance they sail (SailingMoves.length), plus a thousandth of a tile per change of
	// heading, so that of the routes that are equally short the one with the fewest, longest legs wins.
	private static final int SAILING_COST_PER_TURN = 1;

	final SailingMoves moves;
	/** The boat's hull, or {@code null} to keep only the boat's centre clear. */
	final BoatHull hull;
	private final int[] targets;
	// The targets plus their fallback tiles: the search can also end by landing on one of them
	private final int[] goals;
	// The heading the boat is facing where the route starts, or -1 when that isn't known: the start node has no
	// move to face, so without it a target under the hull counts as arrived facing any heading — even one the
	// boat, berthed, isn't pointing
	private final int initialHeading;
	// How far from a target the boat's tile can be while arriving, in tiles: next to it diagonally, or with a hull, as
	// far as the hull reaches plus half a tile's diagonal
	private final double arrivalReach;
	private final SplitFlagMap.RegionExtent extent;
	// The cheapest cost each tile has been queued at, without and with a bank visited, as one array per region and plane,
	// made as the search reaches them
	private final int[][][] queuedCosts = new int[2][][];
	// Which moves have already been queued into each tile at a cost that doesn't beat the tile's cheapest, as a bitmask.
	// A tile's cheapest route may face a way its hull doesn't cover a target in, so a costlier move that would arrive is
	// still queued — once per move
	private final int[][][] queuedArrivals = new int[2][][];

	SailingSearch(SailingMoves moves, BoatHull hull, int[] targets, int[] goals)
	{
		this(moves, hull, targets, goals, WorldPointUtil.UNDEFINED);
	}

	SailingSearch(SailingMoves moves, BoatHull hull, int[] targets, int[] goals, int initialHeading)
	{
		this.moves = moves;
		this.hull = hull;
		this.targets = targets;
		this.goals = goals;
		this.initialHeading = initialHeading;
		arrivalReach = hull == null ? Math.sqrt(2) : hull.reach() + Math.sqrt(2) / 2;
		extent = SplitFlagMap.getRegionExtents();
		int regions = (extent.getWidth() + 1) * (extent.getHeight() + 1) * PLANES;
		queuedCosts[0] = new int[regions][];
		queuedCosts[1] = new int[regions][];
		queuedArrivals[0] = new int[regions][];
		queuedArrivals[1] = new int[regions][];
	}

	/**
	 * The heading the boat faces on {@code node}: the way the move that reached it sailed, or the heading it was
	 * facing where the route began on the start node, which no move reached. -1 means unknown, which lets
	 * {@link #arrivedTarget} try every heading.
	 */
	int arrivalHeading(NodeGraph graph, int node)
	{
		int heading = sailingArrivalHeading(graph, node, moves);
		return heading < 0 ? initialHeading : heading;
	}

	// The heading of the sailing move that reached node, or -1 if it wasn't reached by one (such as the search's
	// start, which faces the boat's own heading instead — see SailingSearch.arrivalHeading).
	// The move is stored on the node rather than recovered from its displacement, which different headings can share
	// at low speeds
	private static int sailingArrivalHeading(NodeGraph graph, int node, SailingMoves moves)
	{
		int move = graph.moveIndex(node);
		return move < 0 ? -1 : moves.heading(move);
	}

	/**
	 * The target the boat, on the tile at {@code packedPosition} and facing {@code heading}, has arrived at: its hull
	 * covers it, facing any heading if {@code heading} is -1 (unknown); or without a hull, it's on a target or next to
	 * it. {@link WorldPointUtil#UNDEFINED} if it hasn't arrived.
	 */
	int arrivedTarget(int packedPosition, int heading)
	{
		for (int target : targets)
		{
			if (hull == null)
			{
				if (WorldPointUtil.distanceBetween(target, packedPosition) <= 1)
				{
					return target;
				}
				continue;
			}
			if (WorldPointUtil.unpackWorldPlane(target) != WorldPointUtil.unpackWorldPlane(packedPosition))
			{
				continue;
			}
			int dx = WorldPointUtil.unpackWorldX(target) - WorldPointUtil.unpackWorldX(packedPosition);
			int dy = WorldPointUtil.unpackWorldY(target) - WorldPointUtil.unpackWorldY(packedPosition);
			for (int facing = heading < 0 ? 0 : heading; facing < (heading < 0 ? HEADINGS : heading + 1); facing++)
			{
				if (hull.covers(facing, dx, dy))
				{
					return target;
				}
			}
		}
		return WorldPointUtil.UNDEFINED;
	}

	/**
	 * A lower bound on the distance left from tile (x, y), in the units of {@link SailingMoves#length}: the nearest
	 * straight-line distance to a goal tile — which the boat has to land on — or to a target less how far from it the
	 * boat can arrive. Rounded down, so it never overestimates.
	 */
	int estimate(int x, int y)
	{
		// Landing on a goal tile ends the search exactly; a target only needs the boat within
		// arrival reach of it
		double tilesLeft = Double.MAX_VALUE;
		for (int goal : goals)
		{
			long dx = WorldPointUtil.unpackWorldX(goal) - x;
			long dy = WorldPointUtil.unpackWorldY(goal) - y;
			tilesLeft = Math.min(tilesLeft, Math.sqrt(dx * dx + dy * dy));
		}
		for (int target : targets)
		{
			long dx = WorldPointUtil.unpackWorldX(target) - x;
			long dy = WorldPointUtil.unpackWorldY(target) - y;
			tilesLeft = Math.min(tilesLeft, Math.sqrt(dx * dx + dy * dy) - arrivalReach);
		}
		if (tilesLeft == Double.MAX_VALUE)
		{
			return 0;
		}
		return (int) (SailingMoves.LENGTH_UNITS_PER_TILE * Math.max(0, tilesLeft));
	}

	/**
	 * The cheapest cost tile (x, y, z) has been queued at so far, or {@link Integer#MAX_VALUE} if it hasn't been; 0 if it's
	 * off the map, so it never is.
	 */
	int queuedCost(int x, int y, int z, boolean bankVisited)
	{
		int region = regionIndex(x, y, z);
		if (region < 0)
		{
			return 0;
		}
		int[] costs = queuedCosts[bankVisited ? 1 : 0][region];
		return costs == null ? Integer.MAX_VALUE : costs[tileIndex(x, y)];
	}

	/**
	 * Notes that tile (x, y, z) is queued at {@code cost}; only lowers the noted cost, so it stays the
	 * cheapest the tile has been queued at (see {@link #queuedCost}).
	 */
	void setQueuedCost(int x, int y, int z, boolean bankVisited, int cost)
	{
		int region = regionIndex(x, y, z);
		int[][] byRegion = queuedCosts[bankVisited ? 1 : 0];
		if (byRegion[region] == null)
		{
			byRegion[region] = new int[REGION_SIZE * REGION_SIZE];
			Arrays.fill(byRegion[region], Integer.MAX_VALUE);
		}
		int index = tileIndex(x, y);
		byRegion[region][index] = Math.min(byRegion[region][index], cost);
	}

	/**
	 * Lets a move reaching tile (x, y, z) at a cost that doesn't beat its cheapest queue anyway when the
	 * boat would arrive on the move's heading — the tile's cheapest route may face a way its hull doesn't
	 * cover a target in. Marks the move queued, so each move is let through once. Only for hull searches:
	 * without a hull arrival doesn't depend on facing.
	 *
	 * @return whether the move should be queued despite its cost
	 */
	boolean queueArrival(int packedPosition, int move, int x, int y, int z, boolean bankVisited)
	{
		if (hull == null || arrivedTarget(packedPosition, moves.heading(move)) == WorldPointUtil.UNDEFINED)
		{
			return false;
		}
		int region = regionIndex(x, y, z);
		if (region < 0)
		{
			return false;
		}
		int[][] byRegion = queuedArrivals[bankVisited ? 1 : 0];
		int[] arrivals = byRegion[region];
		if (arrivals == null)
		{
			arrivals = new int[REGION_SIZE * REGION_SIZE];
			byRegion[region] = arrivals;
		}
		int index = tileIndex(x, y);
		int bit = 1 << move;
		if ((arrivals[index] & bit) != 0)
		{
			return false;
		}
		arrivals[index] |= bit;
		return true;
	}

	/**
	 * Lets go of the costs noted per tile, and the hull's caches, once the search is done.
	 */
	void release()
	{
		Arrays.fill(queuedCosts[0], null);
		Arrays.fill(queuedCosts[1], null);
		Arrays.fill(queuedArrivals[0], null);
		Arrays.fill(queuedArrivals[1], null);
		if (hull != null)
		{
			hull.release();
		}
	}

	// Sailing moves are different lengths, so they are queued by cost on the pending heap like transports rather than
	// the FIFO boundary queue, which is only ordered for unit-cost walking edges: each costs the distance it sails, so
	// the search finds the shortest route rather than the quickest. A tile is only queued again if a route reaches it
	// for less, since a dearer one would only be dequeued once the tile is done — or, with a hull, if a dearer move
	// would arrive on a heading none has tried, since the cheapest route's facing may not cover a target. The cost
	// check comes first, which costs less than the line or hull check. With a hull, the whole boat must fit along the
	// move, which also keeps its centre clear.
	void addNeighbors(CollisionMap map, PrimitiveIntList out, int node, int x, int y, int z, boolean bankVisited,
		VisitedTiles visited, NodeGraph graph)
	{
		// The boat faces the way it sailed into the node — or, on the start node, the way it's pointing, so
		// carrying straight on isn't a turn but putting about first is
		final int arrivalHeading = arrivalHeading(graph, node);
		// The first move gets the hull's berthed-tile escape: a boat can sit over tiles it then sails off
		final boolean firstMove = graph.moveIndex(node) < 0;
		final int costSoFar = graph.cost(node);
		for (int i = 0; i < moves.size(); i++)
		{
			final int dx = moves.dx(i);
			final int dy = moves.dy(i);
			final int neighborPacked = WorldPointUtil.packWorldPoint(x + dx, y + dy, z);
			final int cost = moves.length(i) + (arrivalHeading >= 0 && arrivalHeading != moves.heading(i) ? SAILING_COST_PER_TURN : 0);
			if (visited.get(neighborPacked, bankVisited)
				|| (costSoFar + cost >= queuedCost(x + dx, y + dy, z, bankVisited)
					&& !queueArrival(neighborPacked, i, x + dx, y + dy, z, bankVisited))
				|| !(hull == null ? canSailLine(map, x, y, z, dx, dy)
					: hull.canMove(map, x, y, z, moves.heading(i), dx, dy, firstMove)))
			{
				continue;
			}
			out.add(graph.createWeightedTile(neighborPacked, node, cost, estimate(x + dx, y + dy), bankVisited, i));
		}
	}

	/**
	 * Whether a straight sailing move from tile (x, y, z) by (dx, dy) tiles only crosses open tiles: every tile the
	 * line between the tile centres passes through must be one walking step from the previous one, so a move never
	 * passes over a blocked tile (such as the blocked strip along coastlines). Where the line passes exactly through a
	 * tile corner, both ways around the corner must be open.
	 */
	public static boolean canSailLine(CollisionMap map, int x, int y, int z, int dx, int dy)
	{
		final int nx = Math.abs(dx);
		final int ny = Math.abs(dy);
		final int sx = Integer.signum(dx);
		final int sy = Integer.signum(dy);
		// From a blocked tile, such as one a moored boat sits on, any open tile next to it can be entered, as when
		// walking. Every tile after the first is entered through an open side, so it isn't blocked either.
		boolean fromBlocked = map.isBlocked(x, y, z);
		int cx = x;
		int cy = y;
		int ix = 0;
		int iy = 0;
		while (ix < nx || iy < ny)
		{
			// Compares where the line crosses the next vertical and horizontal tile edges
			long decision = (long) (1 + 2 * ix) * ny - (long) (1 + 2 * iy) * nx;
			if (decision == 0)
			{
				if (!canCross(map, cx, cy, z, sx, 0, fromBlocked) || !canCross(map, cx + sx, cy, z, 0, sy, false)
					|| !canCross(map, cx, cy, z, 0, sy, fromBlocked) || !canCross(map, cx, cy + sy, z, sx, 0, false))
				{
					return false;
				}
				cx += sx;
				cy += sy;
				ix++;
				iy++;
			}
			else if (decision < 0)
			{
				if (!canCross(map, cx, cy, z, sx, 0, fromBlocked))
				{
					return false;
				}
				cx += sx;
				ix++;
			}
			else
			{
				if (!canCross(map, cx, cy, z, 0, sy, fromBlocked))
				{
					return false;
				}
				cy += sy;
				iy++;
			}
			fromBlocked = false;
		}
		return true;
	}

	// Whether a boat can cross from tile (x, y, z) into the tile next to it (ex, ey) away, one of which is 0: through
	// the open side between them, or from a blocked tile into any open one
	private static boolean canCross(CollisionMap map, int x, int y, int z, int ex, int ey, boolean fromBlocked)
	{
		if (fromBlocked)
		{
			return !map.isBlocked(x + ex, y + ey, z);
		}
		if (ey == 0)
		{
			return ex < 0 ? map.w(x, y, z) : map.e(x, y, z);
		}
		return ey < 0 ? map.s(x, y, z) : map.n(x, y, z);
	}

	// Index of the region and plane holding tile (x, y, z), or -1 if it's off the map
	private int regionIndex(int x, int y, int z)
	{
		int regionX = (x >> REGION_SHIFT) - extent.getMinX();
		int regionY = (y >> REGION_SHIFT) - extent.getMinY();
		if (regionX < 0 || regionY < 0 || regionX > extent.getWidth() || regionY > extent.getHeight() || z < 0 || z >= PLANES)
		{
			return -1;
		}
		return (regionX + regionY * (extent.getWidth() + 1)) * PLANES + z;
	}

	private static int tileIndex(int x, int y)
	{
		return ((y & REGION_MASK) << REGION_SHIFT) | (x & REGION_MASK);
	}
}

