import lombok.Getter;

/**
 * The type of comparison to perform when checking a variable requirement.
 */
@Getter
public enum VarCheckType
{
	BIT_SET("&"),
	COOLDOWN_MINUTES("@"),
	EQUAL("="),
	GREATER(">"),
	SMALLER("<");

	private final String code;

	VarCheckType(String code)
	{
		this.code = code;
	}
}

package shortestpath.requirement.model;

import java.util.Map;

import lombok.Getter;

/**
 * Represents a variable-based requirement for a transport.
 * This can be either a varbit or a varplayer requirement.
 *
 * <p>
 * Consolidates the previously separate TransportVarbit and TransportVarPlayer
 * classes which had identical logic.
 * </p>
 */
@Getter
public class VarRequirement
{

	private final VarType varType;
	private final int id;
	private final int value;
	private final VarCheckType checkType;

	public VarRequirement(VarType varType, int id, int value, VarCheckType checkType)
	{
		this.varType = varType;
		this.id = id;
		this.value = value;
		this.checkType = checkType;
	}

	/**
	 * Creates a varbit requirement.
	 */
	public static VarRequirement varbit(int id, int value, VarCheckType checkType)
	{
		return new VarRequirement(VarType.VARBIT, id, value, checkType);
	}

	/**
	 * Creates a varplayer requirement.
	 */
	public static VarRequirement varPlayer(int id, int value, VarCheckType checkType)
	{
		return new VarRequirement(VarType.VARPLAYER, id, value, checkType);
	}

	/**
	 * Checks if this requirement is satisfied given the current variable values.
	 *
	 * @param values A map of variable IDs to their current values
	 * @param currentTimeMinutes current game time in minutes
	 * @return true if the requirement is satisfied
	 */
	public boolean check(Map<Integer, Integer> values, long currentTimeMinutes)
	{
		Integer currentValue = values.get(id);
		if (currentValue == null)
		{
			return false;
		}
		return checkValue(currentValue, currentTimeMinutes);
	}

	/**
	 * Same logic as {@link #check(Map, long)} but with the variable value already resolved (e.g. from the client).
	 *
	 * @param currentTimeMinutes current game time in minutes
	 */
	public boolean checkValue(int currentValue, long currentTimeMinutes)
	{
		switch (checkType)
		{
			case EQUAL:
				return currentValue == value;
			case GREATER:
				return currentValue > value;
			case SMALLER:
				return currentValue < value;
			case BIT_SET:
				return (currentValue & value) > 0;
			case COOLDOWN_MINUTES:
				return (currentTimeMinutes - (long) currentValue) > value;
			default:
				return false;
		}
	}

	public boolean isVarbit()
	{
		return varType == VarType.VARBIT;
	}

	public boolean isVarPlayer()
	{
		return varType == VarType.VARPLAYER;
	}

	@Override
	public int hashCode()
	{
		int result = varType.hashCode();
		result = 31 * result + id;
		result = 31 * result + value;
		result = 31 * result + checkType.hashCode();
		return result;
	}

	@Override
	public boolean equals(Object o)
	{
		if (this == o)
		{
			return true;
		}
		if (o == null || getClass() != o.getClass())
		{
			return false;
		}
		VarRequirement that = (VarRequirement) o;
		return id == that.id && value == that.value && varType == that.varType && checkType == that.checkType;
	}

	@Override
	public String toString()
	{
		return varType + "[" + id + " " + checkType.getCode() + " " + value + "]";
	}

	/**
	 * The type of variable this requirement checks.
	 */
	public enum VarType
	{
		VARBIT,
		VARPLAYER
	}
}

package shortestpath.settings;

import java.util.Set;

import lombok.Getter;

/**
 * An immutable fact describing a single config change: the key that changed
 * and the {@link Effect}s it triggers. Produced by
 * {@link Settings#onConfigChanged}; the shell reads the effect set to decide
 * which follow-up actions to run rather than re-deriving them from the key.
 */
@Getter
public final class ConfigChange
{
	private final String key;
	private final Set<Effect> effects;

	ConfigChange(String key, Set<Effect> effects)
	{
		this.key = key;
		this.effects = Set.copyOf(effects);
	}
}

package shortestpath.settings;

/**
 * The consequences an observed change carries for the plugin shell — whether
 * the change came from a config key (via {@link ConfigChange}) or from a
 * producer observing game state (via the item-state change facts). A change
 * fact carries the set of effects it triggers; the shell decides how to act
 * on them.
 */
public enum Effect
{
	/** The running search can no longer be trusted; pathfinding must restart. */
	ROUTE_INVALIDATING,
	/** The debug overlay panel must be added to or removed from the overlay manager. */
	SIDE_EFFECT_DEBUG_OVERLAY,
	/** The selected pathfinding backend must be prepared (grid/prerender warm-up). */
	SIDE_EFFECT_BACKEND_PREP,
	/** No shell side effect beyond the views republishing; a running search continues. */
	DISPLAY_ONLY,
	/** The eligibility snapshot is stale; the engine rebuilds it lazily. */
	ELIGIBILITY_STALE
}

