package shortestpath;

import java.util.Map;
import java.util.Set;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.Mockito.when;
import org.mockito.junit.MockitoJUnitRunner;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.PathfinderConfig;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportLoader;

@RunWith(MockitoJUnitRunner.class)
public class TransportsForEdgeTest
{
	private static final Map<Integer, Set<Transport>> TRANSPORTS = TransportLoader.loadAllFromResources();
	private static final int LUMBRIDGE_LANDING = WorldPointUtil.packWorldPoint(3221, 3218, 0);

	@Mock
	PathfinderConfig pathfinderConfig;

	@InjectMocks
	ShortestPathPlugin plugin;

	private Transport lumbridgeTeleport;
	private Transport lumbridgeHomeTeleport;

	@Before
	public void before()
	{
		for (Transport transport : TRANSPORTS.get(Transport.UNDEFINED_ORIGIN))
		{
			if (transport.getDestination() == LUMBRIDGE_LANDING)
			{
				if ("Lumbridge Teleport".equals(transport.getDisplayInfo()) && lumbridgeTeleport == null)
				{
					lumbridgeTeleport = transport;
				}
				else if ("Lumbridge Home Teleport".equals(transport.getDisplayInfo()) && lumbridgeHomeTeleport == null)
				{
					lumbridgeHomeTeleport = transport;
				}
			}
		}
		Assert.assertNotNull(lumbridgeTeleport);
		Assert.assertNotNull(lumbridgeHomeTeleport);
	}

	private void mockTeleports(Transport... teleports)
	{
		when(pathfinderConfig.getUsableTeleports(anyBoolean())).thenReturn(teleports);
	}

	private void mockLocalTransports(int origin, Transport... local)
	{
		PrimitiveIntHashMap<Transport[]> packed = new PrimitiveIntHashMap<>(1);
		packed.put(origin, local);
		when(pathfinderConfig.getTransportsPacked(anyBoolean())).thenReturn(packed);
	}

	private void mockNoLocalTransports()
	{
		when(pathfinderConfig.getTransportsPacked(anyBoolean())).thenReturn(new PrimitiveIntHashMap<>(0));
	}

	@Test
	public void testWalkedEdgeOntoTeleportLandingShowsNoHint()
	{
		mockTeleports(lumbridgeTeleport, lumbridgeHomeTeleport);
		mockNoLocalTransports();
		// The path walks onto the Lumbridge teleport landing tile — a single-tile
		// edge that cannot be a teleport, so no teleport hint should be produced.
		PathStep from = new PathStep(WorldPointUtil.packWorldPoint(3222, 3218, 0), false);
		PathStep to = new PathStep(LUMBRIDGE_LANDING, false);
		Assert.assertTrue(plugin.transportsForEdge(from, to).isEmpty());
	}

	@Test
	public void testWalkedEdgeEndingOnTeleportLandingShowsNoHint()
	{
		mockTeleports(lumbridgeTeleport, lumbridgeHomeTeleport);
		mockNoLocalTransports();
		// Same suppression when the landing tile is the last step of the path:
		// the path does not go beyond the tile, so no teleport is used.
		PathStep from = new PathStep(WorldPointUtil.packWorldPoint(3221, 3219, 0), false);
		PathStep to = new PathStep(LUMBRIDGE_LANDING, false);
		Assert.assertTrue(plugin.transportsForEdge(from, to).isEmpty());
	}

	@Test
	public void testJumpEdgeOntoTeleportLandingKeepsFallback()
	{
		mockTeleports(lumbridgeTeleport, lumbridgeHomeTeleport);
		mockNoLocalTransports();
		// Manually constructed steps carry no transport identity; on an actual
		// jump the teleport remains a candidate.
		PathStep from = new PathStep(WorldPointUtil.packWorldPoint(3200, 3200, 0), false);
		PathStep to = new PathStep(LUMBRIDGE_LANDING, false);
		Assert.assertEquals(Set.of(lumbridgeTeleport, lumbridgeHomeTeleport), plugin.transportsForEdge(from, to));
	}

	@Test
	public void testRecordedTransportIsReturnedDirectly()
	{
		PathStep from = new PathStep(WorldPointUtil.packWorldPoint(3200, 3200, 0), false);
		PathStep to = new PathStep(LUMBRIDGE_LANDING, false, lumbridgeTeleport);
		Assert.assertEquals(Set.of(lumbridgeTeleport), plugin.transportsForEdge(from, to));
	}

	@Test
	public void testWalkedEdgeStillReportsLocalTransport()
	{
		// A local transport that moves the player a single tile is still a valid
		// way to traverse a walked edge; only teleports are suppressed.
		Transport adjacentLocal = null;
		for (Map.Entry<Integer, Set<Transport>> entry : TRANSPORTS.entrySet())
		{
			int origin = entry.getKey();
			if (origin == Transport.UNDEFINED_ORIGIN)
			{
				continue;
			}
			for (Transport transport : entry.getValue())
			{
				if ((transport.getType() == null || !transport.getType().isTeleport())
					&& WorldPointUtil.distanceBetween2D(origin, transport.getDestination()) <= 1)
				{
					adjacentLocal = transport;
				}
			}
		}
		Assert.assertNotNull(adjacentLocal);
		mockTeleports(lumbridgeTeleport, lumbridgeHomeTeleport);
		mockLocalTransports(adjacentLocal.getOrigin(), adjacentLocal);
		PathStep from = new PathStep(adjacentLocal.getOrigin(), false);
		PathStep to = new PathStep(adjacentLocal.getDestination(), false);
		Assert.assertEquals(Set.of(adjacentLocal), plugin.transportsForEdge(from, to));
	}
}

package shortestpath;

import java.io.ByteArrayInputStream;
import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.util.Random;
import javax.annotation.Nonnull;
import org.junit.Assert;
import org.junit.Test;

/**
 * Unit tests for {@link Util} helper methods.
 */
public class UtilTest
{

	// --- readAllBytes -----------------------------------------------------

	@Test
	public void readAllBytesEmptyStream() throws IOException
	{
		byte[] data = Util.readAllBytes(new ByteArrayInputStream(new byte[0]));
		Assert.assertNotNull(data);
		Assert.assertEquals(0, data.length);
	}

	@Test
	public void readAllBytesSmall() throws IOException
	{
		byte[] expected = {1, 2, 3, 4, 5};
		byte[] data = Util.readAllBytes(new ByteArrayInputStream(expected));
		Assert.assertArrayEquals(expected, data);
	}

	@Test
	public void readAllBytesLargerThanBuffer() throws IOException
	{
		// Create data larger than the internal 1024 byte buffer to exercise loop logic
		byte[] expected = new byte[4096];
		for (int i = 0; i < expected.length; i++)
		{
			expected[i] = (byte) (i * 31); // deterministic pattern
		}
		byte[] data = Util.readAllBytes(new ByteArrayInputStream(expected));
		Assert.assertArrayEquals(expected, data);
	}

	@Test(expected = IOException.class)
	public void readAllBytesPropagatesIOException() throws IOException
	{
		// InputStream that throws after first read
		InputStream failing = new FilterInputStream(new ByteArrayInputStream(new byte[]{1, 2, 3}))
		{
			private boolean first = true;

			@Override
			public int read(@Nonnull byte[] b, int off, int len) throws IOException
			{
				if (first)
				{
					first = false;
					return super.read(b, off, len);
				}
				throw new IOException("boom");
			}
		};
		// Should throw on second read attempt
		Util.readAllBytes(failing);
	}

	// --- concatenate ------------------------------------------------------

	@Test
	public void concatenateAllNullOrEmptyReturnsNull()
	{
		Assert.assertNull(Util.concatenate(new int[][]{null, new int[0], null}));
	}

	@Test
	public void concatenateSingleArrayIdentity()
	{
		int[] a = {1, 2, 3};
		Assert.assertArrayEquals(a, Util.concatenate(new int[][]{a}));
	}

	@Test
	public void concatenateSkipsNulls()
	{
		int[] a = {1, 2};
		int[] c = {3};
		int[] result = Util.concatenate(new int[][]{a, null, c});
		Assert.assertArrayEquals(new int[]{1, 2, 3}, result);
	}

	@Test
	public void concatenateMultiple()
	{
		int[] a = {1};
		int[] b = {2, 3};
		int[] c = {4, 5, 6};
		int[] result = Util.concatenate(new int[][]{a, b, c});
		Assert.assertArrayEquals(new int[]{1, 2, 3, 4, 5, 6}, result);
	}

	@Test
	public void concatenateLarge()
	{
		// Use random sizes to stress size accumulation & copy loop
		Random rnd = new Random(123);
		int[][] arrays = new int[50][];
		int total = 0;
		for (int i = 0; i < arrays.length; i++)
		{
			int len = rnd.nextInt(10); // small to keep test fast
			if (len == 0)
			{
				arrays[i] = new int[0];
			}
			else
			{
				arrays[i] = new int[len];
				for (int j = 0; j < len; j++)
				{
					arrays[i][j] = i * 100 + j;
				}
				total += len;
			}
		}
		int[] combined = Util.concatenate(arrays);
		if (total == 0)
		{
			Assert.assertNull(combined);
		}
		else
		{
			int count = 0;
			for (int[] arr : arrays)
			{
				if (arr == null)
				{
					continue;
				}
				for (int v : arr)
				{
					Assert.assertNotNull(combined);
					Assert.assertEquals(v, combined[count++]);
				}
			}
			Assert.assertNotNull(combined);
			Assert.assertEquals(total, combined.length);
		}
	}
}

package shortestpath;

import java.util.HashSet;
import java.util.Set;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.junit.MockitoJUnitRunner;
import shortestpath.pathfinder.WildernessChecker;

@RunWith(MockitoJUnitRunner.class)
public class WildernessCheckerTest
{

	private static final int WILDERNESS_GREEN_DRAGONS = WorldPointUtil.packWorldPoint(3339, 3696, 0);
	private static final int WILDERNESS_EDGEVILLE_DUNGEON = WorldPointUtil.packWorldPoint(3089, 9957, 0);
	private static final int WILDERNESS_LAVA_MAZE_DUNGEON = WorldPointUtil.packWorldPoint(3039, 10260, 0);
	private static final int WILDERNESS_DARK_WARRIORS_FORTRESS = WorldPointUtil.packWorldPoint(3023, 3626, 1);
	private static final int WILDERNESS_REVENANT_CAVES = WorldPointUtil.packWorldPoint(3198, 10074, 0);
	private static final int WILDERNESS_SLAYER_CAVE = WorldPointUtil.packWorldPoint(3406, 10144, 0);
	private static final int WILDERNESS_SLAYER_CAVE_SOUTH = WorldPointUtil.packWorldPoint(3385, 10054, 0);
	private static final int WILDERNESS_GOD_WARS_DUNGEON = WorldPointUtil.packWorldPoint(3044, 10134, 0);
	private static final int WILDERNESS_GOD_WARS_DUNGEON_UPSTAIRS = WorldPointUtil.packWorldPoint(3065, 10155, 3);

	private static final int WILDERNESS_FEROX_ENCLAVE = WorldPointUtil.packWorldPoint(3134, 3629, 0);
	private static final int NON_WILDERNESS_PENINSULA = WorldPointUtil.packWorldPoint(3009, 3531, 0);

	private static final int WILDERNESS_BANDIT_CAMP = WorldPointUtil.packWorldPoint(3037, 3700, 0);

	@Test
	public void testIsInWilderness()
	{
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_GREEN_DRAGONS));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_EDGEVILLE_DUNGEON));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_LAVA_MAZE_DUNGEON));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_DARK_WARRIORS_FORTRESS));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_REVENANT_CAVES));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_SLAYER_CAVE));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_GOD_WARS_DUNGEON));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_GOD_WARS_DUNGEON_UPSTAIRS));
		assertTrue(WildernessChecker.isInWilderness(WILDERNESS_SLAYER_CAVE_SOUTH));

		assertFalse(WildernessChecker.isInWilderness(NON_WILDERNESS_PENINSULA));
		assertFalse(WildernessChecker.isInWilderness(WILDERNESS_FEROX_ENCLAVE));
	}

	@Test
	public void testisInWildernessSet()
	{
		Set<Integer> packedPoints = new HashSet<>();

		// All wilderness areas
		packedPoints.add(WILDERNESS_DARK_WARRIORS_FORTRESS);
		packedPoints.add(WILDERNESS_EDGEVILLE_DUNGEON);
		assertTrue(WildernessChecker.isInWilderness(packedPoints));
		packedPoints.clear();

		// All non-wilderness areas
		packedPoints.add(WILDERNESS_FEROX_ENCLAVE);
		packedPoints.add(NON_WILDERNESS_PENINSULA);
		assertFalse(WildernessChecker.isInWilderness(packedPoints));
		packedPoints.clear();

		// Mixed areas
		packedPoints.add(WILDERNESS_GREEN_DRAGONS);
		packedPoints.add(NON_WILDERNESS_PENINSULA);
		assertTrue(WildernessChecker.isInWilderness(packedPoints));
	}

	@Test
	public void testInLevel20Wilderness()
	{
		assertTrue(WildernessChecker.isInLevel20Wilderness(WILDERNESS_BANDIT_CAMP));
		assertTrue(WildernessChecker.isInLevel20Wilderness(WILDERNESS_GOD_WARS_DUNGEON));
		assertTrue(WildernessChecker.isInLevel20Wilderness(WILDERNESS_SLAYER_CAVE)); // Northern entrance at level 29
		// wilderness
		assertFalse(WildernessChecker.isInLevel20Wilderness(WILDERNESS_SLAYER_CAVE_SOUTH));
	}

	@Test
	public void testInLevel30Wilderness()
	{
		assertTrue(WildernessChecker.isInLevel30Wilderness(WILDERNESS_LAVA_MAZE_DUNGEON));
	}
}

