		when(source.itemContainer(InventoryID.INV)).thenReturn(inventory);
		when(source.itemContainer(InventoryID.WORN)).thenReturn(worn);
		when(source.runePouchContents()).thenReturn(pouchRunes);
		doAnswer(invocation ->
		{
			Map<Integer, Integer> owned = invocation.getArgument(0);
			if (OwnedItems.RUNE_POUCHES.stream().anyMatch(owned::containsKey))
			{
				pouchRunes.forEach((runeId, amount) -> owned.merge(runeId, amount, Integer::sum));
			}
			return null;
		}).when(source).addRunePouchContents(any());
		return source;
	}

	private static TransportEligibility collect(PlayerStateSource source, ItemContainer bank,
		TeleportationItem setting, boolean includeBankPath)
	{
		return ItemStateService.collectEligibility(source, bank, setting,
			Integer.MAX_VALUE, includeBankPath, Set.<Unlock>of());
	}

	private static Transport needsItem(int[] itemIds, int quantity)
	{
		return new Transport.TransportBuilder()
			.type(TransportType.TRANSPORT)
			.itemRequirements(new TransportItems(List.of(
				new ItemRequirement(itemIds, new int[0], new int[0], quantity))))
			.build();
	}

	@Test
	public void collectEligibilityToleratesNullContainers()
	{
		PlayerStateSource source = sourceWith(null, null, Map.of());

		TransportEligibility eligibility = collect(source, null,
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertNotNull(eligibility);
		assertFalse("no pool satisfies an item requirement without containers",
			eligibility.usable(THREE_AIR, false));
		assertFalse(eligibility.usable(THREE_AIR, true));
	}

	@Test
	public void collectEligibilityToleratesEmptyContainers()
	{
		PlayerStateSource source = sourceWith(containerOf(), containerOf(), Map.of());

		TransportEligibility eligibility = collect(source, containerOf(),
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertNotNull(eligibility);
		assertFalse(eligibility.usable(THREE_AIR, false));
		assertFalse(eligibility.usable(THREE_AIR, true));
	}

	@Test
	public void nonPositiveQuantitiesAreSkippedByCollection()
	{
		// A zero-quantity stack and a placeholder (negative id) slot must not
		// count as owned items — the bank effectively holds nothing usable.
		ItemContainer bank = containerOf(new Item(ItemID.AIRRUNE, 0), new Item(-1, 5));
		PlayerStateSource source = sourceWith(null, null, Map.of());

		TransportEligibility eligibility = collect(source, bank,
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertFalse("a zero-quantity air rune cannot satisfy the requirement",
			eligibility.usable(needsItem(ItemVariations.AIR_RUNE.getIds(), 1), true));
	}

	@Test
	public void bankSeededViaNoteBankContainerFeedsTheBankedPool()
	{
		ItemStateService service = ItemStateService.forTesting();
		service.noteBankContainer(containerOf(new Item(ItemID.SHANTAY_PASS, 1)));
		PlayerStateSource source = sourceWith(null, null, Map.of());

		TransportEligibility eligibility = collect(source, service.getBank(),
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertFalse("the bank item is not carried", eligibility.usable(SHANTAY_GATE, false));
		assertTrue("the bank item enters the bank-path pool", eligibility.usable(SHANTAY_GATE, true));
	}

	@Test
	public void includeBankPathOffLeavesBankItemsOutOfTheBankedPool()
	{
		ItemStateService service = ItemStateService.forTesting();
		service.noteBankContainer(containerOf(new Item(ItemID.SHANTAY_PASS, 1)));
		PlayerStateSource source = sourceWith(null, null, Map.of());

		TransportEligibility eligibility = collect(source, service.getBank(),
			TeleportationItem.INVENTORY_AND_BANK, false);

		assertFalse("with bank paths off the banked pool is the carried pool",
			eligibility.usable(SHANTAY_GATE, true));
	}

	@Test
	public void bankedRunePouchSuppliesItsRunesOnTheBankPath()
	{
		ItemStateService service = ItemStateService.forTesting();
		service.noteBankContainer(containerOf(new Item(ItemID.BH_RUNE_POUCH, 1)));
		PlayerStateSource source = sourceWith(null, null, Map.of(ItemID.AIRRUNE, 3));

		TransportEligibility eligibility = collect(source, service.getBank(),
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertFalse("pouch runes are not carried", eligibility.usable(THREE_AIR, false));
		assertTrue("a banked pouch's runes feed the bank-path pool",
			eligibility.usable(THREE_AIR, true));
	}

	@Test
	public void firstPouchInDeclaredOrderIsSelected()
	{
		// The bank holds two pouch variants; the selector must pick the one
		// earliest in the declared pouch order (BH before DIVINE).
		ItemStateService service = ItemStateService.forTesting();
		service.noteBankContainer(containerOf(
			new Item(ItemID.DIVINE_RUNE_POUCH, 1), new Item(ItemID.BH_RUNE_POUCH, 1)));
		PlayerStateSource source = sourceWith(null, null, Map.of(ItemID.AIRRUNE, 3));

		TransportEligibility eligibility = collect(source, service.getBank(),
			TeleportationItem.INVENTORY_AND_BANK, true);
		TransportEligibility.BankPickupPlan plan = eligibility.bankPickupPlan(THREE_AIR);

		assertTrue("the declared-first pouch supplies the runes",
			plan.bankItemIds.contains(ItemID.BH_RUNE_POUCH));
		assertFalse("a later pouch is never the selected one",
			plan.bankItemIds.contains(ItemID.DIVINE_RUNE_POUCH));
	}

	@Test
	public void bankWithoutPouchNeverConsultsPouchRunes()
	{
		// The source reports pouch runes, but without a pouch in the bank the
		// bank-pouch rune pool must stay empty and the pickup unsatisfiable.
		ItemStateService service = ItemStateService.forTesting();
		service.noteBankContainer(containerOf());
		PlayerStateSource source = sourceWith(null, null, Map.of(ItemID.AIRRUNE, 3));

		TransportEligibility eligibility = collect(source, service.getBank(),
			TeleportationItem.INVENTORY_AND_BANK, true);

		assertFalse(eligibility.usable(THREE_AIR, true));
		assertNull("the bank cannot supply the runes", eligibility.bankPickupPlan(THREE_AIR).items);
	}

	// ------------------------------------------------------------------
	// Bank-pickup projection — keyed on the item-state revision this service
	// bumps, plus (path identity, index, search identity)
	// ------------------------------------------------------------------

	private static PathfinderConfig pickupConfig()
	{
		PathfinderConfig config = mock(PathfinderConfig.class);
		// The bank-location set is only consulted to gate "is this a bank
		// step"; a real set keeps the compute seam reachable while the test
		// path deliberately misses it, yielding the empty result.
		when(config.getDestinations("bank")).thenReturn(Set.of(12345));
		return config;
	}

	private static ItemStateService serviceWithBank()
	{
		ItemStateService service = ItemStateService.forTesting();
		service.noteBankContainer(mock(ItemContainer.class));
		return service;
	}

	private static BankPickupResult pickup(BankPickupProjection projection, ItemStateService service,
		PathfinderConfig config, List<PathStep> path, int pathIndex)
	{
		return projection.get(null, service, config, path, pathIndex, null);
	}

	@Test
	public void getBankPickupGuardsRejectBadInputs()
	{
		BankPickupProjection projection = new BankPickupProjection();
		PathfinderConfig config = pickupConfig();
		List<PathStep> path = List.of(new PathStep(999, false));

		assertNull("no open bank means no projection",
			pickup(projection, ItemStateService.forTesting(), config, path, 0));

		ItemStateService service = serviceWithBank();
		assertNull("null path is rejected", pickup(projection, service, config, null, 0));
		assertNull("negative index is rejected", pickup(projection, service, config, path, -1));
		assertNull("out-of-range index is rejected",
			pickup(projection, service, config, path, path.size()));

		when(config.getDestinations("bank")).thenReturn(null);
		assertNull("a missing bank-destination set is rejected",
			pickup(projection, service, config, path, 0));
	}

	@Test
	public void bankPickupCacheHitsOnSamePathAndIndexIdentity()
	{
		BankPickupProjection projection = new BankPickupProjection();
		ItemStateService service = serviceWithBank();
		PathfinderConfig config = pickupConfig();
		List<PathStep> path = List.of(new PathStep(999, false), new PathStep(888, false));

		BankPickupResult first = pickup(projection, service, config, path, 0);
		BankPickupResult second = pickup(projection, service, config, path, 0);

		assertSame("same (revision, path identity, index, search) reuses the cached result",
			first, second);
	}

	@Test
	public void bankPickupCacheMissesOnDifferentIndexOrPathInstance()
	{
		BankPickupProjection projection = new BankPickupProjection();
		ItemStateService service = serviceWithBank();
		PathfinderConfig config = pickupConfig();
		List<PathStep> path = List.of(new PathStep(999, false), new PathStep(888, false));

		BankPickupResult first = pickup(projection, service, config, path, 0);

		assertNotSame("a different index recomputes", first,
			pickup(projection, service, config, path, 1));

		List<PathStep> equalButSeparate = List.of(new PathStep(999, false), new PathStep(888, false));
		assertNotSame("an equal-but-separate path list recomputes — the key is identity",
			first, pickup(projection, service, config, equalButSeparate, 0));
	}

	@Test
	public void reseededBankForcesPickupRecompute()
	{
		BankPickupProjection projection = new BankPickupProjection();
		ItemStateService service = serviceWithBank();
		PathfinderConfig config = pickupConfig();
		List<PathStep> path = List.of(new PathStep(999, false));

		BankPickupResult first = pickup(projection, service, config, path, 0);
		service.noteBankContainer(mock(ItemContainer.class));

		assertNotSame("a re-seeded bank bumps the revision and defeats the cache",
			first, pickup(projection, service, config, path, 0));
	}

	@Test
	public void containerAndVarbitEventsDirtyThePickupCache()
	{
		BankPickupProjection projection = new BankPickupProjection();
		ItemStateService service = serviceWithBank();
		PathfinderConfig config = pickupConfig();
		List<PathStep> path = List.of(new PathStep(999, false));

		BankPickupResult first = pickup(projection, service, config, path, 0);
		service.onContainerChanged(InventoryID.INV, mock(ItemContainer.class));
		BankPickupResult afterContainer = pickup(projection, service, config, path, 0);
		assertNotSame("a tracked container event recomputes", first, afterContainer);

		service.onVarbitChanged(OwnedItems.RUNE_POUCH_RUNE_VARBITS[0]);
		assertNotSame("a tracked varbit event recomputes",
			afterContainer, pickup(projection, service, config, path, 0));
	}
}

package shortestpath.items;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.Client;
import net.runelite.api.EnumComposition;
import net.runelite.api.EnumID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.Mockito.verifyNoInteractions;
import static org.mockito.Mockito.when;

@RunWith(MockitoJUnitRunner.class)
public class OwnedItemsTest
{
	private static final int POUCH_AIR = 1;
	private static final int POUCH_LAW = 2;

	@Mock
	private Client client;
	@Mock
	private ItemContainer inventory;
	@Mock
	private ItemContainer equipment;
	@Mock
	private EnumComposition runePouchEnum;

	private final Map<Integer, Integer> owned = new HashMap<>();

	@Test
	public void quantitiesAreSummedAcrossContainers()
	{
		when(inventory.getItems()).thenReturn(new Item[]{new Item(ItemID.COINS, 100)});
		when(equipment.getItems()).thenReturn(new Item[]{new Item(ItemID.COINS, 5)});

		OwnedItems.addContainer(owned, inventory);
		OwnedItems.addContainer(owned, equipment);

		assertEquals(Integer.valueOf(105), owned.get(ItemID.COINS));
	}

	@Test
	public void emptySlotsAndMissingContainersAreIgnored()
	{
		when(inventory.getItems()).thenReturn(new Item[]{new Item(-1, 0), new Item(ItemID.COINS, 0)});

		OwnedItems.addContainer(owned, inventory);
		OwnedItems.addContainer(owned, null);

		assertTrue(owned.isEmpty());
	}

	@Test
	public void runePouchRunesAddToLooseRunes()
	{
		// 1000 loose air runes plus 2 in the pouch is 1002, not 2
		when(inventory.getItems()).thenReturn(new Item[]{
			new Item(ItemID.AIRRUNE, 1000), new Item(ItemID.BH_RUNE_POUCH, 1)});
		setupRunePouch(2, 5);

		OwnedItems.addContainer(owned, inventory);
		OwnedItems.addRunePouchContents(client, owned);

		assertEquals(Integer.valueOf(1002), owned.get(ItemID.AIRRUNE));
		assertEquals(Integer.valueOf(5), owned.get(ItemID.LAWRUNE));
	}

	@Test
	public void runePouchIsOnlyReadWhenOwned()
	{
		OwnedItems.addRunePouchContents(client, owned);

		assertTrue(owned.isEmpty());
		verifyNoInteractions(client);
	}

	@Test
	public void runePouchContentsAreDecodedAsRuneIdToAmount()
	{
		setupRunePouch(2, 5);

		assertEquals(Map.of(ItemID.AIRRUNE, 2, ItemID.LAWRUNE, 5), OwnedItems.runePouchContents(client));
	}

	private void setupRunePouch(int airRunes, int lawRunes)
	{
		when(client.getEnum(EnumID.RUNEPOUCH_RUNE)).thenReturn(runePouchEnum);
		when(runePouchEnum.getIntValue(POUCH_AIR)).thenReturn(ItemID.AIRRUNE);
		when(runePouchEnum.getIntValue(POUCH_LAW)).thenReturn(ItemID.LAWRUNE);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_1)).thenReturn(POUCH_AIR);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_1)).thenReturn(airRunes);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_TYPE_2)).thenReturn(POUCH_LAW);
		when(client.getVarbitValue(VarbitID.RUNE_POUCH_QUANTITY_2)).thenReturn(lawRunes);
	}
}

package shortestpath.leagues;

import java.util.EnumSet;
import static org.junit.Assert.assertEquals;
import org.junit.Test;
import shortestpath.WorldPointUtil;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class LeagueModeStateTest
{
	private static final int VARROCK_WEST = WorldPointUtil.packWorldPoint(3186, 3438, 0);
	private static final int CIVITAS = WorldPointUtil.packWorldPoint(1781, 3100, 0);

	@Test
	public void nonSeasonalReportsEverythingUnlocked()
	{
		LeagueModeState state = new LeagueModeState();
		state.setForTest(false, EnumSet.noneOf(LeagueRegion.class));

		assertTrue(state.isUnlocked(LeagueRegion.MISTHALIN));
		assertTrue(state.isUnlocked(LeagueRegion.KOUREND));
		assertFalse(state.isInBlockedRegion(VARROCK_WEST));
	}

	@Test
	public void seasonalBlocksMisthalinAndLocksUnpickedRegions()
	{
		LeagueModeState state = new LeagueModeState();
		state.setForTest(true, EnumSet.of(LeagueRegion.KANDARIN, LeagueRegion.KARAMJA));

		assertTrue(state.isUnlocked(LeagueRegion.VARLAMORE));
		assertTrue(state.isUnlocked(LeagueRegion.KARAMJA));
		assertTrue(state.isUnlocked(LeagueRegion.NEUTRAL));
		assertTrue(state.isUnlocked(LeagueRegion.KANDARIN));
		assertFalse(state.isUnlocked(LeagueRegion.MISTHALIN));
		assertFalse(state.isUnlocked(LeagueRegion.MORYTANIA));

		assertTrue(state.isInBlockedRegion(VARROCK_WEST));
		assertFalse(state.isInBlockedRegion(CIVITAS));
	}

	@Test
	public void seasonalStartsWithOnlyVarlamoreUnlocked()
	{
		// Pre-80-task state: only Varlamore. Karamja must require its
		// own varbit pick like every other region.
		LeagueModeState state = new LeagueModeState();
		state.setForTest(true, EnumSet.noneOf(LeagueRegion.class));

		assertTrue(state.isUnlocked(LeagueRegion.VARLAMORE));
		assertFalse(state.isUnlocked(LeagueRegion.KARAMJA));
		assertFalse(state.isUnlocked(LeagueRegion.WILDERNESS));
	}

	@Test
	public void areaSelectionVarbitsCoverAllSixSlots()
	{
		// Catches accidental drift if Jagex or RuneLite renumber the
		// LEAGUE_AREA_SELECTION_* varbits. Six contiguous IDs starting at
		// 10662 mirror the gameval VarbitID table.
		assertEquals(6, LeagueModeState.AREA_SELECTION_VARBITS.length);
		for (int i = 0; i < 6; i++)
		{
			assertEquals(LeagueModeState.AREA_SELECTION_VARBITS[i], 10662 + i);
		}
	}
}

