	{
		Grid grid = new Grid(Set.of(pack(3, 3)));
		AStarWalkCanonicalizer canonicalizer = new AStarWalkCanonicalizer(grid, NO_TRANSPORTS);
		int[] first = canonicalizer.walk(pack(0, 0), 8, WalkGoal.tile(pack(4, 8))).tiles;
		int[] again = new AStarWalkCanonicalizer(grid, NO_TRANSPORTS).walk(pack(0, 0), 8, WalkGoal.tile(pack(4, 8))).tiles;
		canonicalizer.walk(pack(2, 0), 5, WalkGoal.tile(pack(7, 0)));
