		keybinds.putFromDialogLine("1: Harmony Island");
		keybinds.putFromDialogLine("<img=42>");
		keybinds.putFromDialogLine("");
		keybinds.putFromDialogLine("4: Varrock");

		assertEquals("1: Harmony Island Portal", keybinds.apply("Harmony Island Portal"));
		assertEquals("4: Varrock Portal", keybinds.apply("Varrock Portal"));
	}

	@Test
	public void testLegacyStoredDataIsDiscarded()
	{
		// Pre-versioning payloads can hold position-derived keys that were
		// never bound; they must not load.
		Map<String, String> keys = new HashMap<>();
		PohService.deserialize("ghorrock=K|waterbirth island=F3", keys);

		assertEquals(Map.of(), keys);
	}

	@Test
	public void testMenuRebuildDropsUnassignedSlots()
	{
		keybinds.putFromDialogLine("1: Harmony Island");
		keybinds.putFromDialogLine("F3: Waterbirth Island");

		// Reopening the menu re-observes the current bindings; the unassigned
		// Waterbirth slot produces no line, so its stale key must be dropped.
		keybinds.dialogOpened();
		keybinds.putFromDialogLine("1: Harmony Island");

		assertEquals("1: Harmony Island Portal", keybinds.apply("Harmony Island Portal"));
		assertEquals("Waterbirth Island Portal", keybinds.apply("Waterbirth Island Portal"));
	}

	@Test
	public void testRefreshAfterReopenDropsStaleKeys()
	{
		keybinds.putFromDialogLine("F3: Waterbirth Island");
		keybinds.dialogOpened();

		Map<String, String> parsed = new HashMap<>();
		parsed.put("harmony island", "1");
		keybinds.replaceIfPresent(parsed);

		assertEquals("1: Harmony Island Portal", keybinds.apply("Harmony Island Portal"));
		assertEquals("Waterbirth Island Portal", keybinds.apply("Waterbirth Island Portal"));
	}
}

package shortestpath.requirement;

import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.ItemID;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.mockito.Mock;
import org.mockito.junit.MockitoJUnitRunner;
import shortestpath.ItemVariations;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.PathfinderConfig;
import shortestpath.pathfinder.TestPathfinderConfig;
import shortestpath.requirement.BankPickupRequirements.BankPickupResult;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.requirement.model.TransportItems;
import shortestpath.settings.TeleportationItem;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.Mockito.when;

/**
 * Tests {@link BankPickupResult#compute} against eligibility snapshots: the pickup
 * phrases and bank item highlights read from the same evaluation the pathfinder used,
 * keyed by the transport recorded on each path step.
 */
@RunWith(MockitoJUnitRunner.class)
public class BankPickupRequirementsTest
{
	private static final int NO_POUCH = -1;
	private static final int[] NO_SUBSTITUTES = new int[0];
	private static final int BANK_TILE = WorldPointUtil.packWorldPoint(3100, 3500, 0);
	private static final int EDGE_ORIGIN = WorldPointUtil.packWorldPoint(3101, 3500, 0);
	private static final int EDGE_DESTINATION = WorldPointUtil.packWorldPoint(3102, 3500, 0);
	private static final Set<Integer> BANK_LOCATIONS = Set.of(BANK_TILE);
	private static final Transport LAW_ONLY = teleport(rune(ItemVariations.LAW_RUNE, 1));
	private static final Transport FALADOR_TELEPORT = teleport(
		rune(ItemVariations.LAW_RUNE, 1), rune(ItemVariations.AIR_RUNE, 3), rune(ItemVariations.WATER_RUNE, 1));

	@Mock
	private Client client;
	@Mock
	private PathfinderConfig pathfinderConfig;
	@Mock
	private ItemContainer bank;
	@Mock
	private ItemComposition lawRune;
	@Mock
	private ItemComposition dramenStaff;
	@Mock
	private ItemComposition coins;

	private final Map<Integer, Integer> playerHas = new HashMap<>();
	private final Map<Integer, Integer> bankHas = new HashMap<>();

	@Test
	public void recordedTransportProducesPickupPhraseDespiteFreeAlternative()
	{
		// The path records the law-requiring teleport it actually used; a free transport
		// sharing the destination must not suppress the pickup for the recorded one.
		bankHas.put(ItemID.LAWRUNE, 1);
		when(pathfinderConfig.getEligibility()).thenReturn(eligibility(false));
		// The leading walk edge carries no recorded transport, so compute still
		// consults the availability fallback for it.
		when(pathfinderConfig.getTransportAvailability(anyBoolean())).thenReturn(
			TestPathfinderConfig.availabilityOf(edge(TransportType.TRANSPORT, null), LAW_ONLY));
		when(client.getItemDefinition(ItemID.LAWRUNE)).thenReturn(lawRune);
		when(lawRune.getName()).thenReturn("Law rune");

		List<PathStep> path = List.of(
			new PathStep(BANK_TILE, false),
			new PathStep(EDGE_ORIGIN, false),
			new PathStep(EDGE_DESTINATION, false, LAW_ONLY));

		BankPickupResult result = BankPickupResult.compute(
			client, bank, pathfinderConfig, BANK_LOCATIONS, path, 0);

		assertEquals(List.of("1 Law rune"), result.phrases);
		assertEquals(Set.of(ItemID.LAWRUNE), result.bankItemIds);
	}

	@Test
	public void identitylessStepWithFreeAlternativeProducesNothing()
	{
		// Without a recorded transport, destination-matched alternatives apply: any one
		// of them being free means no pickup for the edge.
		bankHas.put(ItemID.LAWRUNE, 1);
		when(pathfinderConfig.getEligibility()).thenReturn(eligibility(false));
		when(pathfinderConfig.getTransportAvailability(anyBoolean())).thenReturn(
			TestPathfinderConfig.availabilityOf(
				edge(TransportType.TRANSPORT, null),
				edge(TransportType.TELEPORTATION_SPELL, LAW_ONLY.getItemRequirements())));

		List<PathStep> path = List.of(
			new PathStep(BANK_TILE, false),
			new PathStep(EDGE_ORIGIN, false),
			new PathStep(EDGE_DESTINATION, false));

		BankPickupResult result = BankPickupResult.compute(
			client, bank, pathfinderConfig, BANK_LOCATIONS, path, 0);

		assertTrue(result.phrases.isEmpty());
		assertTrue(result.bankItemIds.isEmpty());
	}

	@Test
	public void bankShortProducesNoPhraseButStillHighlights()
	{
		// 1 banked air covers the carried shortfall but no water is anywhere, so the bank
		// cannot fully supply the teleport: no phrase, but the air is still highlighted.
		playerHas.put(ItemID.LAWRUNE, 1);
		playerHas.put(ItemID.AIRRUNE, 2);
		bankHas.put(ItemID.AIRRUNE, 1);
		when(pathfinderConfig.getEligibility()).thenReturn(eligibility(false));
		when(pathfinderConfig.getTransportAvailability(anyBoolean())).thenReturn(
			TestPathfinderConfig.availabilityOf());

		List<PathStep> path = List.of(
			new PathStep(BANK_TILE, false),
			new PathStep(EDGE_ORIGIN, false),
			new PathStep(EDGE_DESTINATION, false, FALADOR_TELEPORT));

		BankPickupResult result = BankPickupResult.compute(
			client, bank, pathfinderConfig, BANK_LOCATIONS, path, 0);

		assertTrue(result.phrases.isEmpty());
		assertEquals(Set.of(ItemID.AIRRUNE), result.bankItemIds);
	}

	@Test
	public void playerSatisfyingTheRecordedTransportNeedsNoPickup()
	{
		playerHas.put(ItemID.LAWRUNE, 1);
		playerHas.put(ItemID.AIRRUNE, 3);
		playerHas.put(ItemID.WATERRUNE, 1);
		when(pathfinderConfig.getEligibility()).thenReturn(eligibility(false));
		when(pathfinderConfig.getTransportAvailability(anyBoolean())).thenReturn(
			TestPathfinderConfig.availabilityOf());

		List<PathStep> path = List.of(
			new PathStep(BANK_TILE, false),
			new PathStep(EDGE_ORIGIN, false),
			new PathStep(EDGE_DESTINATION, false, FALADOR_TELEPORT));

		BankPickupResult result = BankPickupResult.compute(
			client, bank, pathfinderConfig, BANK_LOCATIONS, path, 0);

		assertTrue(result.phrases.isEmpty());
		assertTrue(result.bankItemIds.isEmpty());
	}

	@Test
	public void fairyRingPathPicksUpTheBankedDramenStaff()
	{
		bankHas.put(ItemID.DRAMEN_STAFF, 1);
		bankHas.put(ItemID.DRAMEN_STAFF_AIR, 1);
		when(pathfinderConfig.getEligibility()).thenReturn(eligibility(true));
		when(pathfinderConfig.getTransportAvailability(anyBoolean())).thenReturn(
			TestPathfinderConfig.availabilityOf());
		when(client.getItemDefinition(ItemID.DRAMEN_STAFF)).thenReturn(dramenStaff);
		when(dramenStaff.getName()).thenReturn("Dramen staff");

		List<PathStep> path = List.of(
			new PathStep(BANK_TILE, false),
			new PathStep(EDGE_ORIGIN, false),
			new PathStep(EDGE_DESTINATION, false,
				new Transport.TransportBuilder().type(TransportType.FAIRY_RING).build()));

		BankPickupResult result = BankPickupResult.compute(
			client, bank, pathfinderConfig, BANK_LOCATIONS, path, 0);

		assertEquals(List.of("1 Dramen staff"), result.phrases);
		assertEquals(Set.of(ItemID.DRAMEN_STAFF, ItemID.DRAMEN_STAFF_AIR), result.bankItemIds);
	}

	@Test
	public void fairyRingPathNeedsNoStaffWhenTheDiaryIsComplete()
	{
		bankHas.put(ItemID.DRAMEN_STAFF, 1);
		when(pathfinderConfig.getEligibility()).thenReturn(eligibility(false));
		when(pathfinderConfig.getTransportAvailability(anyBoolean())).thenReturn(
			TestPathfinderConfig.availabilityOf());

		List<PathStep> path = List.of(
			new PathStep(BANK_TILE, false),
			new PathStep(EDGE_ORIGIN, false),
			new PathStep(EDGE_DESTINATION, false,
				new Transport.TransportBuilder().type(TransportType.FAIRY_RING).build()));

		BankPickupResult result = BankPickupResult.compute(
			client, bank, pathfinderConfig, BANK_LOCATIONS, path, 0);

		assertTrue(result.phrases.isEmpty());
		assertTrue(result.bankItemIds.isEmpty());
	}

	@Test
	public void missingEligibilitySnapshotYieldsEmptyResult()
	{
		List<PathStep> path = List.of(
			new PathStep(BANK_TILE, false),
			new PathStep(EDGE_ORIGIN, false),
			new PathStep(EDGE_DESTINATION, false, LAW_ONLY));

		BankPickupResult result = BankPickupResult.compute(
			client, bank, pathfinderConfig, BANK_LOCATIONS, path, 0);

		assertTrue(result.phrases.isEmpty());
		assertTrue(result.bankItemIds.isEmpty());
	}

	@Test
	public void awayFromABankStepYieldsEmptyResult()
	{
		List<PathStep> path = List.of(
			new PathStep(EDGE_ORIGIN, false),
			new PathStep(EDGE_DESTINATION, false, LAW_ONLY));

		BankPickupResult result = BankPickupResult.compute(
			client, bank, pathfinderConfig, BANK_LOCATIONS, path, 0);

		assertTrue(result.phrases.isEmpty());
		assertTrue(result.bankItemIds.isEmpty());
	}

	@Test
	public void formatPickupsNamesQuantitiesAndCurrencyAmounts()
	{
		when(client.getItemDefinition(ItemID.LAWRUNE)).thenReturn(lawRune);
		when(client.getItemDefinition(ItemID.COINS)).thenReturn(coins);
		when(lawRune.getName()).thenReturn("Law rune");
		when(coins.getName()).thenReturn("Coins");
		Map<Integer, Long> pickups = new LinkedHashMap<>();
		pickups.put(ItemID.LAWRUNE, 2L);
		pickups.put(ItemID.COINS, 5L);

		assertEquals("2 Law rune, Coins (5)", BankPickupRequirements.formatPickups(client, pickups));
	}

	@Test
	public void formatPickupsDegradesWithoutAClient()
	{
		// The detached forTesting() item-state service has no client to resolve
		// names with; the phrases degrade instead of throwing.
		Map<Integer, Long> pickups = new LinkedHashMap<>();
		pickups.put(ItemID.LAWRUNE, 2L);
		pickups.put(ItemID.COINS, 5L);

		assertEquals("2 Unknown item, Unknown item (5)",
			BankPickupRequirements.formatPickups(null, pickups));
	}

	private TransportEligibility eligibility(boolean fairyRingStaffRequired)
	{
		Map<Integer, Integer> bankPathItems = new HashMap<>(playerHas);
		bankHas.forEach((itemId, quantity) -> bankPathItems.merge(itemId, quantity, Integer::sum));
		return new TransportEligibility(playerHas, bankPathItems, bankHas, NO_POUCH, Map.of(),
			fairyRingStaffRequired, TeleportationItem.NONE, Integer.MAX_VALUE, Set.of(), true);
	}

	private static ItemRequirement rune(ItemVariations rune, int quantity)
	{
		return new ItemRequirement(rune.getIds(), NO_SUBSTITUTES, NO_SUBSTITUTES, quantity);
	}

	private static Transport teleport(ItemRequirement... requirements)
	{
		return new Transport.TransportBuilder()
			.type(TransportType.TELEPORTATION_SPELL)
			.itemRequirements(new TransportItems(List.of(requirements)))
			.build();
	}

	private static Transport edge(TransportType type, TransportItems requirements)
	{
		Transport.TransportBuilder builder = new Transport.TransportBuilder()
			.type(type)
			.origin(EDGE_ORIGIN)
			.destination(EDGE_DESTINATION);
		if (requirements != null)
		{
			builder.itemRequirements(requirements);
		}
		return builder.build();
	}
}

package shortestpath.requirement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import static org.mockito.ArgumentMatchers.anyBoolean;
import static org.mockito.ArgumentMatchers.anyInt;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.doReturn;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.ItemID;
import org.junit.Before;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.PathStep;
import shortestpath.pathfinder.PathfinderConfig;
import shortestpath.pathfinder.TransportAvailabilityFixture;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.requirement.model.TransportItems;

/** The bank step's "Pick up" list for the items a path's target needs on arrival. */
public class BankPickupTargetItemsTest
{
	private static final int[] NONE = new int[0];
	private static final int BANK_TILE = WorldPointUtil.packWorldPoint(3092, 3243, 0);
	private static final int NEXT_TILE = WorldPointUtil.packWorldPoint(3093, 3243, 0);
	private static final int TARGET = WorldPointUtil.packWorldPoint(3100, 3243, 0);

	private final Client client = mock(Client.class);
	private final Map<Integer, Integer> playerHas = new HashMap<>();
	private final Map<Integer, Integer> bankHas = new HashMap<>();
	private final Set<String> phrases = new LinkedHashSet<>();
	private final Set<Integer> highlights = new java.util.HashSet<>();

	@Before
	public void names()
	{
		Map<Integer, String> names = Map.of(ItemID.SPADE, "Spade", ItemID.ROPE, "Rope", ItemID.COINS, "Coins");
		doAnswer(call ->
		{
			ItemComposition item = mock(ItemComposition.class);
			when(item.getName()).thenReturn(names.get((Integer) call.getArgument(0)));
			return item;
		}).when(client).getItemDefinition(anyInt());
	}

	private static ItemRequirement anyOf(Map<Integer, Integer> idsToQuantity)
	{
		List<ItemRequirement.Branch> branches = new java.util.ArrayList<>();
		idsToQuantity.forEach((id, quantity) -> branches.add(new ItemRequirement.Branch(new int[] {id}, NONE, NONE, quantity)));
		return new ItemRequirement(branches);
	}

	private static TransportItems needs(ItemRequirement... groups)
	{
		return new TransportItems(List.of(groups));
	}

	private void pickups(TransportItems target)
	{
		TransportEligibility.BankPickupPlan plan =
			TransportEligibility.forPlayerAndBank(playerHas, bankHas, -1, Map.of()).targetPickupPlan(target);
		for (Map.Entry<Integer, Long> entry : plan.items.entrySet())
		{
			Map<Integer, Long> single = new java.util.LinkedHashMap<>();
			single.put(entry.getKey(), entry.getValue());
			phrases.add(BankPickupRequirements.formatPickups(client, single));
		}
		highlights.addAll(plan.bankItemIds);
	}

	@Test
	public void bankedItemIsPickedUpAndHighlighted()
	{
		bankHas.put(ItemID.SPADE, 1);
		pickups(needs(anyOf(Map.of(ItemID.SPADE, 1))));
		assertEquals(Set.of("1 Spade"), phrases);
		assertEquals(Set.of(ItemID.SPADE), highlights);
	}

	@Test
	public void carriedItemNeedsNoPickup()
	{
		playerHas.put(ItemID.SPADE, 1);
		bankHas.put(ItemID.SPADE, 1);
		pickups(needs(anyOf(Map.of(ItemID.SPADE, 1))));
		assertTrue(phrases.isEmpty());
		assertTrue(highlights.isEmpty());
	}

	@Test
	public void alternativeTheBankHoldsIsChosen()
	{
		bankHas.put(ItemID.ROPE, 3);
		pickups(needs(anyOf(Map.of(ItemID.SPADE, 1, ItemID.ROPE, 1))));
		assertEquals(Set.of("1 Rope"), phrases);
		assertEquals(Set.of(ItemID.ROPE), highlights);
	}

	@Test
	public void onlyTheShortfallIsPickedUp()
	{
		playerHas.put(ItemID.COINS, 400);
		bankHas.put(ItemID.COINS, 5000);
		pickups(needs(anyOf(Map.of(ItemID.COINS, 1000))));
		assertEquals(Set.of("Coins (600)"), phrases);
	}

	@Test
	public void groupsTheBankCannotCoverAreLeftOut()
	{
		bankHas.put(ItemID.SPADE, 1);
		pickups(needs(anyOf(Map.of(ItemID.SPADE, 1)), anyOf(Map.of(ItemID.ROPE, 1))));
		assertEquals(Set.of("1 Spade"), phrases);
	}

	@Test
	public void bankVisitIsTheStepBeforeAndTheFirstBankedStep()
	{
		List<PathStep> path = List.of(new PathStep(NEXT_TILE, false), new PathStep(BANK_TILE, false),
			new PathStep(BANK_TILE, true), new PathStep(NEXT_TILE, true));
		assertFalse(BankPickupRequirements.visitsBankAt(path, 0));
		assertTrue(BankPickupRequirements.visitsBankAt(path, 1));
		assertTrue(BankPickupRequirements.visitsBankAt(path, 2));
		assertFalse(BankPickupRequirements.visitsBankAt(path, 3));
		assertTrue("a path that starts banked visits at its start",
			BankPickupRequirements.visitsBankAt(List.of(new PathStep(BANK_TILE, true)), 0));
	}

	@Test
	public void computeListsTargetItemsOnlyAtTheBankVisit()
	{
		ItemContainer bank = mock(ItemContainer.class);
		doReturn(new Item[] {new Item(ItemID.SPADE, 1)}).when(bank).getItems();
		ItemContainer empty = mock(ItemContainer.class);
		doReturn(new Item[0]).when(empty).getItems();
		doReturn(empty).when(client).getItemContainer(InventoryID.INV);
		doReturn(empty).when(client).getItemContainer(InventoryID.WORN);
		PathfinderConfig config = mock(PathfinderConfig.class);
		when(config.getTransportAvailability(anyBoolean())).thenReturn(TransportAvailabilityFixture.of());
		when(config.getUnlocks()).thenReturn(Set.of());
		when(config.getEligibility()).thenReturn(
			TransportEligibility.forPlayerAndBank(Map.of(), Map.of(ItemID.SPADE, 1), -1, Map.of()));
		TransportItems spade = needs(anyOf(Map.of(ItemID.SPADE, 1)));
		List<PathStep> path = List.of(new PathStep(BANK_TILE, false), new PathStep(BANK_TILE, true),
			new PathStep(NEXT_TILE, true), new PathStep(TARGET, true));
		Set<Integer> banks = Set.of(BANK_TILE);

		BankPickupRequirements.BankPickupResult atBank = BankPickupRequirements.BankPickupResult.compute(
			client, bank, config, banks, path, 0, spade);
		assertEquals(List.of("1 Spade"), atBank.phrases);
		assertEquals(Set.of(ItemID.SPADE), atBank.bankItemIds);

		assertTrue("without target items nothing is listed", BankPickupRequirements.BankPickupResult.compute(
			client, bank, config, banks, path, 0).phrases.isEmpty());

		List<PathStep> walksPast = List.of(new PathStep(BANK_TILE, false), new PathStep(NEXT_TILE, false),
			new PathStep(TARGET, false));
		assertTrue("a bank tile the path only walks over is no visit", BankPickupRequirements.BankPickupResult
			.compute(client, bank, config, banks, walksPast, 0, spade).phrases.isEmpty());
	}
}

package shortestpath.requirement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import org.junit.Test;
import shortestpath.requirement.model.DestinationRequirements;
import shortestpath.requirement.model.VarCheckType;
import shortestpath.requirement.model.VarRequirement;
import shortestpath.settings.TeleportationItem;
import shortestpath.transport.parser.VarRequirementParser;

/**
 * The bank-destination adapter arm of the middleware: a bank tile's
 * {@link DestinationRequirements} goes through the same
 * {@link Requirements} chain as transports, reading the same refresh
 * snapshot and consulting the same {@link RequirementHooks} seam — a bank
 * tile and a transport can never disagree about the same requirement
 * inside one refresh.
 *
 * <p>The Fortis Colosseum row ({@code 4130>1999}) is the load-bearing
 * real-world case: a strict-greater varplayer gate that must fail closed
 * when the var was never captured.
 */
public class BankRequirementAdapterTest
{
	private static final TeleportationItem MODE = TeleportationItem.INVENTORY;

	private static Requirements requirements(RequirementContext context)
	{
		return RequirementTestFixtures.requirements(context, RequirementTestFixtures.policy(MODE));
	}

	// ------------------------------------------------------------------
	// Empty and absent requirements fast-path.
	// ------------------------------------------------------------------

	@Test
	public void absentAndEmptyRequirementsAreAlwaysSatisfied()
	{
		Requirements requirements = requirements(RequirementTestFixtures.context().build());

		assertTrue(requirements.satisfied(null));
		assertTrue(requirements.satisfied(DestinationRequirements.EMPTY));
		assertEquals(RejectionReason.NONE, requirements.check(DestinationRequirements.EMPTY));

		// A constructed-but-empty requirement is the same fast path: all
		// fields present and empty/zero still count as no requirements.
		DestinationRequirements constructed = new DestinationRequirements(
			new int[Skill.values().length + 3], Set.of(), Set.of(), Set.of());
		assertTrue(constructed.isEmpty());
		assertTrue(requirements.satisfied(constructed));
	}

	// ------------------------------------------------------------------
	// Per-gate coverage through the bank adapter.
	// ------------------------------------------------------------------

	@Test
	public void skillGatedBankFollowsBoostedLevels()
	{
		// Cooks' Guild shape: 99 Cooking.
		int[] skills = new int[Skill.values().length + 3];
		skills[Skill.COOKING.ordinal()] = 99;
		DestinationRequirements guild = RequirementTestFixtures.bankRequirements(
			skills, null, null, null);

		assertTrue(requirements(RequirementTestFixtures.context().build()).satisfied(guild));

		int[] below = RequirementTestFixtures.maxedSkills();
		below[Skill.COOKING.ordinal()] = 98;
		RequirementContext underleveled = RequirementTestFixtures.context()
			.boostedSkillLevelsAndMore(below).build();
		assertFalse(requirements(underleveled).satisfied(guild));
		assertEquals(RejectionReason.SKILL_LEVEL, requirements(underleveled).check(guild));
	}

	@Test
	public void questGatedBankFollowsTheHookFedQuestMap()
	{
		DestinationRequirements gated = RequirementTestFixtures.bankRequirements(
			null, Set.of(Quest.BONE_VOYAGE), null, null);

		// Missing from the captured map → NOT_STARTED → fails closed.
		RequirementContext missing = RequirementTestFixtures.context().build();
		assertFalse(requirements(missing).satisfied(gated));
		assertEquals(RejectionReason.QUEST, requirements(missing).check(gated));

		RequirementContext finished = RequirementTestFixtures.context()
			.questStates(Map.of(Quest.BONE_VOYAGE, QuestState.FINISHED)).build();
		assertTrue(requirements(finished).satisfied(gated));
	}

	@Test
	public void varbitGatedBankFollowsCapturedVarbits()
	{
		// Cooks' Guild door: varbit 4481 == 1.
		Set<VarRequirement> varbits = VarRequirementParser.forVarbits().parse("4481=1");
		DestinationRequirements gated = RequirementTestFixtures.bankRequirements(
			null, null, varbits, null);

		assertTrue(requirements(RequirementTestFixtures.context()
			.varbitValues(Map.of(4481, 1)).build()).satisfied(gated));

		RequirementContext closed = RequirementTestFixtures.context()
			.varbitValues(Map.of(4481, 0)).build();
		assertFalse(requirements(closed).satisfied(gated));
		assertEquals(RejectionReason.VARBIT, requirements(closed).check(gated));
	}

	@Test
	public void fortisColosseumVarplayerIsStrictlyGreater()
	{
		// bank.tsv: "1804 9501 0  Fortis Colosseum  ...  4130>1999" — the
		// colosseum bank is locked until varplayer 4130 exceeds 1999.
		Set<VarRequirement> varPlayers = VarRequirementParser.forVarPlayers().parse("4130>1999");
		assertEquals(1, varPlayers.size());
		assertEquals(VarCheckType.GREATER, varPlayers.iterator().next().getCheckType());
		DestinationRequirements fortis = RequirementTestFixtures.bankRequirements(
			null, null, null, varPlayers);

		// Present but below the threshold.
		RequirementContext below = RequirementTestFixtures.context()
			.varPlayerValues(Map.of(4130, 1500)).build();
		assertFalse(requirements(below).satisfied(fortis));
		assertEquals(RejectionReason.VARPLAYER, requirements(below).check(fortis));

		// Exactly at the threshold still fails — the check is strict >.
		RequirementContext at = RequirementTestFixtures.context()
			.varPlayerValues(Map.of(4130, 1999)).build();
		assertFalse(requirements(at).satisfied(fortis));

		// Above the threshold.
		RequirementContext above = RequirementTestFixtures.context()
			.varPlayerValues(Map.of(4130, 2000)).build();
		assertTrue(requirements(above).satisfied(fortis));
		assertEquals(RejectionReason.NONE, requirements(above).check(fortis));

		// The var was never captured: fail closed.
		RequirementContext absent = RequirementTestFixtures.context().build();
		assertFalse(requirements(absent).satisfied(fortis));
		assertEquals(RejectionReason.VARPLAYER, requirements(absent).check(fortis));
	}

	@Test
	public void bankRequirementsCombineConjunctively()
	{
		// A tile carrying two requirement kinds needs all of them.
		int[] skills = new int[Skill.values().length + 3];
		skills[Skill.COOKING.ordinal()] = 99;
		DestinationRequirements both = RequirementTestFixtures.bankRequirements(
			skills, null, VarRequirementParser.forVarbits().parse("4481=1"), null);

		RequirementContext varMissing = RequirementTestFixtures.context().build();
		assertFalse(requirements(varMissing).satisfied(both));

		int[] low = RequirementTestFixtures.maxedSkills();
		low[Skill.COOKING.ordinal()] = 1;
		RequirementContext lowSkill = RequirementTestFixtures.context()
			.boostedSkillLevelsAndMore(low).varbitValues(Map.of(4481, 1)).build();
		// Skill is checked before varbits, so the skill verdict wins.
		assertEquals(RejectionReason.SKILL_LEVEL, requirements(lowSkill).check(both));

		RequirementContext passing = RequirementTestFixtures.context()
			.varbitValues(Map.of(4481, 1)).build();
		assertTrue(requirements(passing).satisfied(both));
	}

	// ------------------------------------------------------------------
	// Snapshot contract: a built chain reads the captured maps, not the
	// live source — mutating the source after capture cannot move a verdict.
	// ------------------------------------------------------------------

	@Test
	public void verdictsReadTheCapturedSnapshotNotTheLiveSource()
	{
		MapPlayerStateSource source = new MapPlayerStateSource()
			.varp(4130, 2000);
		DestinationRequirements fortis = RequirementTestFixtures.bankRequirements(
			null, null, null, VarRequirementParser.forVarPlayers().parse("4130>1999"));

		RequirementContext context = RequirementContext.capture(
			source,
			new TestRequirementHooks(),
			RequirementTestFixtures.policy(MODE),
			0L,
			List.of(),
			Map.of(1, fortis),
			null,
			Set.of(),
			false,
			new shortestpath.leagues.LeagueModeState(),
			null);
		Requirements requirements = requirements(context);
		assertTrue(requirements.satisfied(fortis));

		// The source now reports a failing value; the already-built chain
		// still reads the snapshot from capture time.
		source.varp(4130, 0);
		assertTrue(requirements.satisfied(fortis));

		// And a fresh capture observes the new value.
		RequirementContext recaptured = RequirementContext.capture(
			source,
			new TestRequirementHooks(),
			RequirementTestFixtures.policy(MODE),
			0L,
			List.of(),
			Map.of(1, fortis),
			null,
			Set.of(),
			false,
			new shortestpath.leagues.LeagueModeState(),
			null);
		assertFalse(requirements(recaptured).satisfied(fortis));
	}
}

package shortestpath.requirement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.leagues.LeagueModeState;
import shortestpath.requirement.model.DestinationRequirements;
import shortestpath.requirement.model.VarCheckType;
import shortestpath.requirement.model.VarRequirement;
import shortestpath.settings.TeleportationItem;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;

/**
 * Hook liveness: every {@link RequirementHooks} seam must reach BOTH
 * consumers — the transport verdict and the bank-destination verdict —
 * after the middleware extraction. A hook that stopped being consulted
 * would fail to move either side of the matrix asserted here.
 *
 * <p>The seams under test are the same ones {@code PathfinderConfig}
 * implements through its private adapter and {@code TestPathfinderConfig}
 * overrides: {@code getQuestState} feeds the captured quest map, and the
 * varbit/varplayer methods are consulted per check against the captured
 * values. No {@code Requirements} internals are mocked — the chains are
 * real and the verdicts come from {@code check}/{@code satisfied}.
 */
public class HookLivenessTest
{
	private static final TeleportationItem MODE = TeleportationItem.INVENTORY;
	private static final int BANK_TILE = WorldPointUtil.packWorldPoint(1804, 9501, 0);

	private static Transport transport()
	{
		return new Transport.TransportBuilder()
			.type(TransportType.TRANSPORT)
			.origin(WorldPointUtil.packWorldPoint(2965, 3378, 0))
			.destination(WorldPointUtil.packWorldPoint(3213, 3424, 0))
			.build();
	}

	private static RequirementContext capture(MapPlayerStateSource source, TestRequirementHooks hooks,
		List<Transport> transports, Map<Integer, DestinationRequirements> bankRequirements)
	{
		return RequirementContext.capture(source, hooks, RequirementTestFixtures.policy(MODE), 0L,
			transports, bankRequirements, null, Set.of(), false, new LeagueModeState(), null);
	}

	private static Requirements chain(RequirementContext context, TestRequirementHooks hooks)
	{
		return new Requirements(context, RequirementTestFixtures.policy(MODE), hooks);
	}

	// ------------------------------------------------------------------
	// getQuestState — consulted while capture snapshots declared quests.
	// ------------------------------------------------------------------

	@Test
	public void questHookMovesTheTransportVerdict()
	{
		Transport gated = new Transport.TransportBuilder()
			.type(TransportType.TRANSPORT)
			.origin(WorldPointUtil.packWorldPoint(2965, 3378, 0))
			.destination(WorldPointUtil.packWorldPoint(3213, 3424, 0))
			.quests(Set.of(Quest.TREE_GNOME_VILLAGE))
			.build();

		TestRequirementHooks finished = new TestRequirementHooks()
			.questState(QuestState.FINISHED);
		RequirementContext done = capture(new MapPlayerStateSource(), finished,
			List.of(gated), Map.of());
		assertTrue(chain(done, finished).usable(gated));

		TestRequirementHooks unfinished = new TestRequirementHooks()
			.questState(QuestState.NOT_STARTED);
		RequirementContext notDone = capture(new MapPlayerStateSource(), unfinished,
			List.of(gated), Map.of());
		assertFalse(chain(notDone, unfinished).usable(gated));
		assertEquals(RejectionReason.QUEST, chain(notDone, unfinished).check(gated));
	}

	@Test
	public void questHookMovesTheBankVerdict()
	{
		DestinationRequirements gated = RequirementTestFixtures.bankRequirements(
			null, Set.of(Quest.BONE_VOYAGE), null, null);

		TestRequirementHooks finished = new TestRequirementHooks()
			.questState(QuestState.FINISHED);
		RequirementContext done = capture(new MapPlayerStateSource(), finished,
			List.of(), Map.of(BANK_TILE, gated));
		assertTrue(chain(done, finished).satisfied(gated));

		TestRequirementHooks unfinished = new TestRequirementHooks()
			.questState(QuestState.NOT_STARTED);
		RequirementContext notDone = capture(new MapPlayerStateSource(), unfinished,
			List.of(), Map.of(BANK_TILE, gated));
		assertFalse(chain(notDone, unfinished).satisfied(gated));
		assertEquals(RejectionReason.QUEST, chain(notDone, unfinished).check(gated));
	}

	// ------------------------------------------------------------------
	// varbitChecks — consulted per check against the captured map.
	// ------------------------------------------------------------------

	@Test
	public void varbitHookMovesTheTransportVerdictOnTheSameChain()
	{
		Transport gated = new Transport.TransportBuilder()
			.type(TransportType.TRANSPORT)
			.origin(WorldPointUtil.packWorldPoint(2965, 3378, 0))
			.destination(WorldPointUtil.packWorldPoint(3213, 3424, 0))
			.varbits("4481=1")
			.build();
		RequirementContext context = RequirementTestFixtures.context()
			.varbitValues(Map.of(4481, 1)).build();
		TestRequirementHooks hooks = new TestRequirementHooks();
		Requirements requirements = chain(context, hooks);

		// The map satisfies the check; flipping the bypass flag forces the
		// failure polarity through the same already-built chain — proof the
		// gate reads the seam per call, not a verdict frozen at capture.
		assertTrue(requirements.usable(gated));
		hooks.failVarbits(true);
		assertFalse(requirements.usable(gated));
		assertEquals(RejectionReason.VARBIT, requirements.check(gated));
	}

	@Test
	public void varbitHookMovesTheBankVerdictOnTheSameChain()
	{
		DestinationRequirements gated = RequirementTestFixtures.bankRequirements(
			null, null, Set.of(VarRequirement.varbit(4481, 1, VarCheckType.EQUAL)), null);
		RequirementContext context = RequirementTestFixtures.context()
			.varbitValues(Map.of(4481, 1)).build();
		TestRequirementHooks hooks = new TestRequirementHooks();
		Requirements requirements = chain(context, hooks);

		assertTrue(requirements.satisfied(gated));
		hooks.failVarbits(true);
		assertFalse(requirements.satisfied(gated));
		assertEquals(RejectionReason.VARBIT, requirements.check(gated));
	}

	// ------------------------------------------------------------------
	// varPlayerChecks — same polarity, bank and transport.
	// ------------------------------------------------------------------

	@Test
	public void varPlayerHookMovesTheTransportVerdictOnTheSameChain()
	{
		Transport gated = new Transport.TransportBuilder()
			.type(TransportType.TRANSPORT)
			.origin(WorldPointUtil.packWorldPoint(2965, 3378, 0))
			.destination(WorldPointUtil.packWorldPoint(3213, 3424, 0))
			.varPlayers("4130>1999")
			.build();
		RequirementContext context = RequirementTestFixtures.context()
			.varPlayerValues(Map.of(4130, 2000)).build();
		TestRequirementHooks hooks = new TestRequirementHooks();
		Requirements requirements = chain(context, hooks);

		assertTrue(requirements.usable(gated));
		hooks.failVarPlayers(true);
		assertFalse(requirements.usable(gated));
		assertEquals(RejectionReason.VARPLAYER, requirements.check(gated));
	}

	@Test
	public void varPlayerHookMovesTheBankVerdictOnTheSameChain()
	{
		DestinationRequirements gated = RequirementTestFixtures.bankRequirements(
			null, null, null,
			Set.of(VarRequirement.varPlayer(4130, 1999, VarCheckType.GREATER)));
		RequirementContext context = RequirementTestFixtures.context()
			.varPlayerValues(Map.of(4130, 2000)).build();
		TestRequirementHooks hooks = new TestRequirementHooks();
		Requirements requirements = chain(context, hooks);

		assertTrue(requirements.satisfied(gated));
		hooks.failVarPlayers(true);
		assertFalse(requirements.satisfied(gated));
		assertEquals(RejectionReason.VARPLAYER, requirements.check(gated));
	}
}

package shortestpath.requirement;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.GameState;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.api.WorldType;
import net.runelite.api.coords.WorldPoint;
import shortestpath.items.OwnedItems;

/**
 * Map-backed {@link PlayerStateSource} for client-free requirement tests.
 * Every read is answered from test-supplied tables so
 * {@link RequirementContext#capture} runs end-to-end without a
 * {@code Client}: varbits and varplayers, boosted and real skill levels,
 * total and combat level (the combat slot falls through to the interface
 * default, computed from the real levels), quest states, the quest-points
 * maximum, player location, modal-widget state, item containers, rune-pouch
 * contents and the league world types.
 *
 * <p>Thread contract: the fake treats the client-thread checks as satisfied
 * by default ({@link #isOnClientThread()} true, {@link #checkOnClientThread()}
 * a no-op). Flipping {@link #offClientThread()} makes the checks honour the
 * loud contract, which lets tests prove the contract on the fake itself when
 * needed. State getters never consult the flag — a map fake exists precisely
 * so capture can be exercised anywhere.
 */
final class MapPlayerStateSource implements PlayerStateSource
{
	private GameState gameState = GameState.LOGGED_IN;
	private final Map<Integer, Integer> varbits = new HashMap<>();
	private final Map<Integer, Integer> varps = new HashMap<>();
	private final Map<Skill, Integer> boostedSkillLevels = new EnumMap<>(Skill.class);
	private final Map<Skill, Integer> realSkillLevels = new EnumMap<>(Skill.class);
	private int totalLevel;
	private final Map<Quest, QuestState> questStates = new EnumMap<>(Quest.class);
	private int maximumQuestPoints;
	private WorldPoint localPlayerWorldLocation;
	private boolean modalWidgetOpen;
	private final Map<Integer, ItemContainer> itemContainers = new HashMap<>();
	private final Map<Integer, Integer> runePouchRunes = new HashMap<>();
	private EnumSet<WorldType> worldTypes = EnumSet.noneOf(WorldType.class);
	private boolean onClientThread = true;

	MapPlayerStateSource gameState(GameState state)
	{
		gameState = state;
		return this;
	}

	/** Sets a varbit value; later calls overwrite, so post-capture mutation tests can change it. */
	MapPlayerStateSource varbit(int id, int value)
	{
		varbits.put(id, value);
		return this;
	}

	/** Sets a varplayer value; later calls overwrite. */
	MapPlayerStateSource varp(int id, int value)
	{
		varps.put(id, value);
		return this;
	}

	MapPlayerStateSource boostedSkillLevel(Skill skill, int level)
	{
		boostedSkillLevels.put(skill, level);
		return this;
	}

	MapPlayerStateSource realSkillLevel(Skill skill, int level)
	{
		realSkillLevels.put(skill, level);
		return this;
	}

	MapPlayerStateSource totalLevel(int level)
	{
		totalLevel = level;
		return this;
	}

	MapPlayerStateSource questState(Quest quest, QuestState state)
	{
		questStates.put(quest, state);
		return this;
	}

	MapPlayerStateSource maximumQuestPoints(int points)
	{
		maximumQuestPoints = points;
		return this;
	}

	MapPlayerStateSource localPlayerWorldLocation(WorldPoint point)
	{
		localPlayerWorldLocation = point;
		return this;
	}

	MapPlayerStateSource modalWidgetOpen(boolean open)
	{
		modalWidgetOpen = open;
		return this;
	}

	MapPlayerStateSource itemContainer(int inventoryId, ItemContainer container)
	{
		itemContainers.put(inventoryId, container);
		return this;
	}

	MapPlayerStateSource runePouchRune(int runeId, int amount)
	{
		runePouchRunes.put(runeId, amount);
		return this;
	}

	MapPlayerStateSource worldTypes(WorldType first, WorldType... rest)
	{
		worldTypes = EnumSet.of(first, rest);
		return this;
	}

	/** Puts the fake off the client thread: the thread check becomes loud. */
	MapPlayerStateSource offClientThread()
	{
		onClientThread = false;
		return this;
	}

	@Override
	public GameState gameState()
	{
		return gameState;
	}

	@Override
	public int varbit(int varbitId)
	{
		return varbits.getOrDefault(varbitId, 0);
	}

	@Override
	public int varp(int varpId)
	{
		return varps.getOrDefault(varpId, 0);
	}

	@Override
	public int boostedSkillLevel(Skill skill)
	{
		return boostedSkillLevels.getOrDefault(skill, 0);
	}

	@Override
	public int realSkillLevel(Skill skill)
	{
		return realSkillLevels.getOrDefault(skill, 0);
	}

	@Override
	public int totalLevel()
	{
		return totalLevel;
	}

	@Override
	public QuestState questState(Quest quest)
	{
		return questStates.getOrDefault(quest, QuestState.NOT_STARTED);
	}

	@Override
	public int maximumQuestPoints()
	{
		return maximumQuestPoints;
	}

	@Override
	public WorldPoint localPlayerWorldLocation()
	{
		return localPlayerWorldLocation;
	}

	@Override
	public boolean modalWidgetOpen()
	{
		return modalWidgetOpen;
	}

	@Override
	public ItemContainer itemContainer(int inventoryId)
	{
		return itemContainers.get(inventoryId);
	}

	@Override
	public Map<Integer, Integer> runePouchContents()
	{
		return runePouchRunes;
	}

	@Override
	public void addRunePouchContents(Map<Integer, Integer> owned)
	{
		// Same shape as the production reader: the pouch runes are only added
		// when the carried set already holds a rune pouch.
		if (OwnedItems.RUNE_POUCHES.stream().noneMatch(owned::containsKey))
		{
			return;
		}
		runePouchRunes.forEach((runeId, amount) -> owned.merge(runeId, amount, Integer::sum));
	}

	@Override
	public EnumSet<WorldType> worldType()
	{
		return worldTypes;
	}

	@Override
	public void checkOnClientThread()
	{
		if (!onClientThread)
		{
			throw new IllegalStateException(
				"player-state reads must run on the client thread; route the caller through the client thread");
		}
	}

	@Override
	public boolean isOnClientThread()
	{
		return onClientThread;
	}
}

package shortestpath.requirement;

import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import org.junit.Test;
import shortestpath.TestShortestPathConfig;
import shortestpath.poh.PohMountedItem;
import shortestpath.poh.PohService;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

public class PathfinderConfigPohMountedItemTest
{
	private static final Map<PohMountedItem, String> OBJECTS = Map.of(
		PohMountedItem.GLORY, "Edgeville Amulet of Glory 13523",
		PohMountedItem.XERICS_TALISMAN, "Look out Xeric's Talisman 33411",
		PohMountedItem.DIGSITE_PENDANT, "Digsite Digsite Pendant 33417",
		PohMountedItem.MYTHICAL_CAPE, "Teleport Mythical cape 31986");

	@Test
	public void emptySelectionDisablesEveryMountedItem()
	{
		Set<PohMountedItem> selected = EnumSet.noneOf(PohMountedItem.class);
		for (String objectInfo : OBJECTS.values())
		{
			assertFalse(PohService.isMountedItemEnabled(selected, objectInfo));
		}
	}

	@Test
	public void singletonSelectionsAreIndependent()
	{
		assertSelection(PohMountedItem.XERICS_TALISMAN);
		assertSelection(PohMountedItem.GLORY);
	}

	@Test
	public void allMountedItemsReproduceTheEnabledBehaviour()
	{
		Set<PohMountedItem> selected = EnumSet.allOf(PohMountedItem.class);
		for (String objectInfo : OBJECTS.values())
		{
			assertTrue(PohService.isMountedItemEnabled(selected, objectInfo));
		}
	}

	@Test
	public void legacyBooleanSuppliesTheInitialMultiSelection()
	{
		assertTrue(new TestShortestPathConfig().pohMountedItems().containsAll(
			EnumSet.allOf(PohMountedItem.class)));
		TestShortestPathConfig legacyDisabled = new TestShortestPathConfig()
		{
			@Override
			public boolean usePohMountedItems()
			{
				return false;
			}
		};
		assertTrue(legacyDisabled.pohMountedItems().isEmpty());
	}

	@Test
	public void carriedXericsTalismanIsNotAMountedObject()
	{
		String carriedDisplayInfo = "Xeric's talisman: 1. Xeric's Lookout";
		assertNull(PohMountedItem.fromObjectInfo(carriedDisplayInfo));
		assertTrue(PohService.isMountedItemEnabled(
			EnumSet.noneOf(PohMountedItem.class), carriedDisplayInfo));
	}

	private static void assertSelection(PohMountedItem selectedItem)
	{
		Set<PohMountedItem> selected = EnumSet.of(selectedItem);
		for (Map.Entry<PohMountedItem, String> entry : OBJECTS.entrySet())
		{
			assertSame(entry.getKey(), PohMountedItem.fromObjectInfo(entry.getValue()));
			if (entry.getKey().equals(selectedItem))
			{
				assertTrue(PohService.isMountedItemEnabled(selected, entry.getValue()));
			}
			else
			{
				assertFalse(PohService.isMountedItemEnabled(selected, entry.getValue()));
			}
		}
	}
}

