import shortestpath.requirement.model.TransportItems;
import shortestpath.requirement.model.ItemRequirement;
import shortestpath.settings.TeleportationItem;
import shortestpath.poh.PohMountedItem;
import shortestpath.poh.PohNexusPortal;
import shortestpath.transport.Transport;
import shortestpath.transport.TransportType;
import shortestpath.transport.parser.VarRequirementParser;

/**
 * The capture-seam contract: {@link RequirementContext#capture} reads the
 * player only through {@link PlayerStateSource}, so a map-backed source
 * exercises the whole path — var and quest tables, the eligibility
 * snapshot, sailing and league state — with no {@code Client} anywhere.
 * The production source's loud off-thread contract is pinned against a
 * mocked {@code Client} (the only client mock on this path): every getter
 * must throw, and {@code isOnClientThread} must answer without throwing.
 */
public class PlayerStateSourceTest
{
	private static final TeleportationItem MODE = TeleportationItem.INVENTORY;
	private static final int FALADOR = WorldPointUtil.packWorldPoint(2965, 3378, 0);
	private static final int VARROCK = WorldPointUtil.packWorldPoint(3213, 3424, 0);
	private static final int POH = WorldPointUtil.packWorldPoint(1858, 7051, 0);
	private static final int BANK_TILE = WorldPointUtil.packWorldPoint(1804, 9501, 0);

	private static ItemContainer container(Item... items)
	{
		ItemContainer container = mock(ItemContainer.class);
		when(container.getItems()).thenReturn(items);
		return container;
	}

	// ------------------------------------------------------------------
	// RequirementContext.capture end-to-end over the map-backed source.
	// ------------------------------------------------------------------

	@Test
	public void capturePopulatesTheContextWithoutAClient()
	{
		MapPlayerStateSource source = new MapPlayerStateSource()
			.varbit(1234, 7)
			.varp(4130, 2000)
			.varp(VarPlayerID.QP, 42)
			.boostedSkillLevel(Skill.COOKING, 99)
			.totalLevel(1500)
			.maximumQuestPoints(200)
			.itemContainer(InventoryID.INV, container(new Item(ItemID.LAWRUNE, 5)));

		TestRequirementHooks hooks = new TestRequirementHooks()
			.questState(QuestState.FINISHED);

		Transport gated = new Transport.TransportBuilder()
			.type(TransportType.TRANSPORT)
			.origin(FALADOR).destination(VARROCK)
			.varbits("1234=7")
			.quests(Set.of(Quest.TREE_GNOME_VILLAGE))
			.itemRequirements(new TransportItems(List.of(
				new ItemRequirement(new int[]{ItemID.LAWRUNE}, null, null, 1))))
			.build();
		DestinationRequirements bankGated = RequirementTestFixtures.bankRequirements(
			null, Set.of(Quest.BONE_VOYAGE), null,
			VarRequirementParser.forVarPlayers().parse("4130>1999"));

		RequirementContext context = RequirementContext.capture(source, hooks,
			RequirementTestFixtures.policy(MODE), 0L,
			List.of(gated), Map.of(BANK_TILE, bankGated), null,
			Set.of(), false, new LeagueModeState(), null);

		// Round-trip: the declared varbit, varplayer and quests landed in the
		// snapshot the gates read.
		assertEquals(Integer.valueOf(7), context.getVarbitValues().get(1234));
		assertEquals(Integer.valueOf(2000), context.getVarPlayerValues().get(4130));
		assertEquals(QuestState.FINISHED, context.getQuestStates().get(Quest.TREE_GNOME_VILLAGE));
		assertEquals(QuestState.FINISHED, context.getQuestStates().get(Quest.BONE_VOYAGE));
		assertEquals(99, context.getBoostedSkillLevelsAndMore()[Skill.COOKING.ordinal()]);
		assertEquals(1500, context.getBoostedSkillLevelsAndMore()[Skill.values().length]);
		assertEquals(42, context.getBoostedSkillLevelsAndMore()[Skill.values().length + 2]);
		assertEquals(200, context.getCurrentMaxQuestPoints());
		assertFalse(context.isOnSailingBoat());

		// The verdicts prove the captured facts reached the gates: the varbit,
		// the hook-fed quest states, and the carried item through the
		// eligibility snapshot all evaluate satisfied.
		Requirements requirements = new Requirements(context,
			RequirementTestFixtures.policy(MODE), new TestRequirementHooks());
		assertEquals(RejectionReason.NONE, requirements.check(gated));
		assertTrue(requirements.satisfied(bankGated));

		// A carried-item shortfall is equally visible: the eligibility
		// snapshot only holds what the containers supplied.
		Transport missingItem = new Transport.TransportBuilder()
			.type(TransportType.BOAT)
			.origin(FALADOR).destination(VARROCK)
			.itemRequirements(new TransportItems(List.of(
				new ItemRequirement(new int[]{ItemID.WATERRUNE}, null, null, 1))))
			.build();
		assertEquals(RejectionReason.ITEM_REQUIREMENT, requirements.check(missingItem));
	}

	@Test
	public void captureReflectsTheSailingVarbit()
	{
		MapPlayerStateSource ashore = new MapPlayerStateSource();
		assertFalse(RequirementContext.capture(ashore, new TestRequirementHooks(),
			RequirementTestFixtures.policy(MODE), 0L, List.of(), Map.of(), null,
			Set.of(), false, new LeagueModeState(), null).isOnSailingBoat());

		MapPlayerStateSource aboard = new MapPlayerStateSource()
			.varbit(VarbitID.SAILING_BOARDED_BOAT, 1);
		assertTrue(RequirementContext.capture(aboard, new TestRequirementHooks(),
			RequirementTestFixtures.policy(MODE), 0L, List.of(), Map.of(), null,
			Set.of(), false, new LeagueModeState(), null).isOnSailingBoat());
	}

	// ------------------------------------------------------------------
	// The map fake's own contract: configurable thread predicate.
	// ------------------------------------------------------------------

	@Test
	public void mapSourceHonoursTheThreadContract()
	{
		MapPlayerStateSource source = new MapPlayerStateSource();
		assertTrue(source.isOnClientThread());
		source.checkOnClientThread();

		source.offClientThread();
		assertFalse(source.isOnClientThread());
		assertThrows(IllegalStateException.class, source::checkOnClientThread);
	}

	// ------------------------------------------------------------------
	// ClientPlayerStateSource loud off-thread contract — the single
	// sanctioned client-mock test on this path.
	// ------------------------------------------------------------------

	private static Client offThreadClient()
	{
		Client client = mock(Client.class);
		Thread clientThread = new Thread("fake-client-thread");
		// The contract under test only holds because the reported client
		// thread is a different object than the calling thread — pin that.
		assertNotSame(Thread.currentThread(), clientThread);
		when(client.getClientThread()).thenReturn(clientThread);
		return client;
	}

	@Test
	public void everyCaptureGetterThrowsOffTheClientThread()
	{
		PlayerStateSource source = new ClientPlayerStateSource(offThreadClient());
		Map<Integer, Integer> owned = new HashMap<>();

		assertThrows(IllegalStateException.class, source::checkOnClientThread);
		assertThrows(IllegalStateException.class, source::gameState);
		assertThrows(IllegalStateException.class, () -> source.varbit(1));
		assertThrows(IllegalStateException.class, () -> source.varp(1));
		assertThrows(IllegalStateException.class, () -> source.boostedSkillLevel(Skill.COOKING));
		assertThrows(IllegalStateException.class, () -> source.realSkillLevel(Skill.COOKING));
		assertThrows(IllegalStateException.class, source::totalLevel);
		assertThrows(IllegalStateException.class, () -> source.questState(Quest.TREE_GNOME_VILLAGE));
		assertThrows(IllegalStateException.class, source::maximumQuestPoints);
		assertThrows(IllegalStateException.class, source::localPlayerWorldLocation);
		assertThrows(IllegalStateException.class, source::modalWidgetOpen);
		assertThrows(IllegalStateException.class, () -> source.itemContainer(InventoryID.INV));
		assertThrows(IllegalStateException.class, source::runePouchContents);
		assertThrows(IllegalStateException.class, () -> source.addRunePouchContents(owned));
		assertThrows(IllegalStateException.class, source::worldType);
	}

	@Test
	public void captureEntryFailsLoudlyOffTheClientThread()
	{
		PlayerStateSource source = new ClientPlayerStateSource(offThreadClient());
		assertThrows(IllegalStateException.class, () -> RequirementContext.capture(
			source, new TestRequirementHooks(),
			RequirementTestFixtures.policy(MODE), 0L, List.of(), Map.of(), null,
			Set.of(), false, new LeagueModeState(), null));
	}

	@Test
	public void isOnClientThreadAnswersWithoutThrowing()
	{
		// Off the client thread the predicate reports false; it must not
		// throw — the stale-eligibility envelope depends on it.
		PlayerStateSource offThread = new ClientPlayerStateSource(offThreadClient());
		assertFalse(offThread.isOnClientThread());

		Client onThread = mock(Client.class);
		when(onThread.getClientThread()).thenReturn(Thread.currentThread());
		PlayerStateSource on = new ClientPlayerStateSource(onThread);
		assertTrue(on.isOnClientThread());
		on.checkOnClientThread();
	}

	// ------------------------------------------------------------------
	// Snapshot immutability: a chain built before a mutation keeps the
	// frozen verdict — the policy copies its sets, the context copies its
	// maps.
	// ------------------------------------------------------------------

	@Test
	public void aBuiltPolicyIsUnmovedByMutatingTheSourceSets()
	{
		Set<TransportType> enabledTypes = EnumSet.allOf(TransportType.class);
		Set<PohNexusPortal> portals = EnumSet.allOf(PohNexusPortal.class);
		Set<PohMountedItem> mounted = EnumSet.allOf(PohMountedItem.class);
		RoutingPolicy policy = new RoutingPolicy(enabledTypes, MODE, true, true, true, true,
			portals, mounted, JewelleryBoxTier.BASIC, Integer.MAX_VALUE, true);

		RequirementContext context = RequirementTestFixtures.context().build();
		Requirements requirements = new Requirements(context, policy,
			new TestRequirementHooks());

		Transport canoe = new Transport.TransportBuilder()
			.type(TransportType.CANOE).origin(FALADOR).destination(VARROCK).build();
		Transport faladorPortal = new Transport.TransportBuilder()
			.type(TransportType.TELEPORTATION_PORTAL_POH).origin(POH).destination(VARROCK)
			.displayInfo("Falador Portal").build();
		Transport mountedGlory = new Transport.TransportBuilder()
			.type(TransportType.TELEPORTATION_BOX).origin(POH).destination(VARROCK)
			.objectInfo("Edgeville Amulet of Glory 13523").build();

		assertEquals(RejectionReason.NONE, requirements.check(canoe));
		assertEquals(RejectionReason.NONE, requirements.check(faladorPortal));
		assertEquals(RejectionReason.NONE, requirements.check(mountedGlory));

		// Mutate everything the policy was built from — the existing chain's
		// verdicts cannot move.
		enabledTypes.clear();
		portals.clear();
		mounted.clear();

		assertEquals(RejectionReason.NONE, requirements.check(canoe));
		assertEquals(RejectionReason.NONE, requirements.check(faladorPortal));
		assertEquals(RejectionReason.NONE, requirements.check(mountedGlory));

		// The sets the policy hands out are themselves immutable.
		assertThrows(UnsupportedOperationException.class, policy.enabledPohNexusPortals()::clear);
		assertThrows(UnsupportedOperationException.class, policy.enabledPohMountedItems()::clear);
	}

	@Test
	public void aBuiltContextIsUnmovedByMutatingTheSourceMaps()
	{
		Map<Quest, QuestState> questStates = new HashMap<>();
		questStates.put(Quest.TREE_GNOME_VILLAGE, QuestState.FINISHED);
		Map<Integer, Integer> varbits = new HashMap<>();
		varbits.put(4481, 1);

		RequirementContext context = RequirementTestFixtures.context()
			.questStates(questStates).varbitValues(varbits).build();
		Requirements requirements = new Requirements(context,
			RequirementTestFixtures.policy(MODE), new TestRequirementHooks());

		Transport gated = new Transport.TransportBuilder()
			.type(TransportType.TRANSPORT).origin(FALADOR).destination(VARROCK)
			.quests(Set.of(Quest.TREE_GNOME_VILLAGE))
			.varbits("4481=1")
			.build();
		assertEquals(RejectionReason.NONE, requirements.check(gated));

		questStates.put(Quest.TREE_GNOME_VILLAGE, QuestState.NOT_STARTED);
		varbits.put(4481, 0);

		assertEquals(RejectionReason.NONE, requirements.check(gated));
	}
}

package shortestpath.requirement;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.HashSet;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;
import org.junit.Test;

/**
 * Mechanical guard for the requirement package's dependency direction.
 *
 * <p>The middleware must stay RuneLite-client-free except for the named adapter files that
 * deliberately delegate to {@code (Client)}-taking helpers ({@link ClientPlayerStateSource} is the
 * capture-path source; {@link BankPickupRequirements} exposes the sanctioned statics the display
 * path reuses). The model package is the leaf layer: it must reference
 * neither the client nor anything under {@code shortestpath.pathfinder}. Per-search restrictions
 * ({@code SearchRestrictions}) belong to the A* backend's search layer and must never leak into
 * the middleware.
 */
public class RequirementPackageBoundaryTest
{
	private static final Path REQUIREMENT_ROOT = Paths.get("src/main/java/shortestpath/requirement");
	private static final Path MODEL_ROOT = REQUIREMENT_ROOT.resolve("model");

	/** Files sanctioned to reference {@code net.runelite.api.Client}. */
	private static final Set<String> CLIENT_WHITELIST = Set.of(
		"ClientPlayerStateSource.java", "BankPickupRequirements.java");

	@Test
	public void clientReferencesAreConfinedToSanctionedAdapters() throws IOException
	{
		Set<Path> scanned = sources(REQUIREMENT_ROOT);
		for (Path source : scanned)
		{
			boolean referencesClient = read(source).contains("net.runelite.api.Client");
			boolean whitelisted = CLIENT_WHITELIST.contains(source.getFileName().toString());
			assertFalse(source + " references net.runelite.api.Client but is not a sanctioned adapter",
				referencesClient && !whitelisted);
		}
		// The scan must actually reach the sanctioned adapters, so a moved source root cannot pass vacuously.
		for (String adapter : CLIENT_WHITELIST)
		{
			assertTrue("sanctioned adapter not scanned: " + adapter,
				scanned.stream().anyMatch(path -> path.getFileName().toString().equals(adapter)));
		}
	}

	@Test
	public void modelPackageIsALeaf() throws IOException
	{
		Set<Path> scanned = sources(MODEL_ROOT);
		assertFalse("no model sources scanned — wrong root?", scanned.isEmpty());
		for (Path source : scanned)
		{
			String text = read(source);
			assertFalse(source + " references net.runelite.api.Client",
				text.contains("net.runelite.api.Client"));
			assertFalse(source + " depends on pathfinder internals",
				text.contains("shortestpath.pathfinder."));
		}
	}

	@Test
	public void perSearchRestrictionsDoNotLeakIntoTheMiddleware() throws IOException
	{
		for (Path source : sources(REQUIREMENT_ROOT))
		{
			assertFalse(source + " references per-search SearchRestrictions",
				read(source).contains("SearchRestrictions"));
		}
	}

	private static Set<Path> sources(Path root) throws IOException
	{
		try (Stream<Path> files = Files.walk(root))
		{
			return files.filter(path -> path.toString().endsWith(".java"))
				.collect(Collectors.toCollection(HashSet::new));
		}
	}

	private static String read(Path source)
	{
		try
		{
			return Files.readString(source);
		}
		catch (IOException e)
		{
			throw new AssertionError(e);
		}
	}
}

package shortestpath.requirement;

import java.util.Arrays;
import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import shortestpath.leagues.LeagueModeState;
import shortestpath.requirement.model.DestinationRequirements;
import shortestpath.poh.JewelleryBoxTier;
import shortestpath.requirement.model.Unlock;
import shortestpath.requirement.model.VarRequirement;
import shortestpath.settings.TeleportationItem;
import shortestpath.poh.PohMountedItem;
import shortestpath.poh.PohNexusPortal;
import shortestpath.transport.TransportType;

/**
 * Shared fixture builders for the requirement middleware tests: a
 * everything-enabled {@link RoutingPolicy}, a defaulted
 * {@link RequirementContext} builder so each case overrides only what its
 * gate reads, an eligibility snapshot with a chosen teleportation-item mode,
 * and a maxed skill array in the {@code skills + total + combat + quest
 * points} layout the skill gate consumes.
 *
 * <p>Every builder produces the frozen values the chain reads at check time —
 * the tests mutate the <em>inputs</em> to prove the snapshot cannot move.
 */
final class RequirementTestFixtures
{
	static final int SKILL_SLOTS = Skill.values().length + 3;
	static final int TOTAL_LEVEL_SLOT = Skill.values().length;

	private RequirementTestFixtures()
	{
	}

	/** Every skill at 99 plus realistic total, combat and quest-point slots. */
	static int[] maxedSkills()
	{
		int[] skills = new int[SKILL_SLOTS];
		Arrays.fill(skills, 99);
		skills[TOTAL_LEVEL_SLOT] = 99 * Skill.values().length;
		skills[TOTAL_LEVEL_SLOT + 1] = 126;
		skills[TOTAL_LEVEL_SLOT + 2] = 300;
		return skills;
	}

	/**
	 * A policy with every transport type enabled, every POH toggle on, every
	 * portal and mounted item enabled, the ornate jewellery box, an
	 * unbounded currency threshold and bank paths included — only the
	 * teleportation-item mode varies between cases.
	 */
	static PolicyBuilder policy()
	{
		return new PolicyBuilder();
	}

	static RoutingPolicy policy(TeleportationItem mode)
	{
		return policy().teleportationItemSetting(mode).build();
	}

	static final class PolicyBuilder
	{
		private Set<TransportType> enabledTypes = EnumSet.allOf(TransportType.class);
		private TeleportationItem teleportationItemSetting = TeleportationItem.INVENTORY;
		private boolean usePoh = true;
		private boolean usePohFairyRing = true;
		private boolean usePohSpiritTree = true;
		private boolean usePohObelisk = true;
		private Set<PohNexusPortal> enabledPohNexusPortals = EnumSet.allOf(PohNexusPortal.class);
		private Set<PohMountedItem> enabledPohMountedItems = EnumSet.allOf(PohMountedItem.class);
		private JewelleryBoxTier pohJewelleryBoxTier = JewelleryBoxTier.ORNATE;
		private int currencyThreshold = Integer.MAX_VALUE;
		private boolean includeBankPath = true;

		PolicyBuilder enabledTypes(Set<TransportType> types)
		{
			enabledTypes = types;
			return this;
		}

		PolicyBuilder teleportationItemSetting(TeleportationItem setting)
		{
			teleportationItemSetting = setting;
			return this;
		}

		PolicyBuilder usePoh(boolean value)
		{
			usePoh = value;
			return this;
		}

		PolicyBuilder usePohFairyRing(boolean value)
		{
			usePohFairyRing = value;
			return this;
		}

		PolicyBuilder usePohSpiritTree(boolean value)
		{
			usePohSpiritTree = value;
			return this;
		}

		PolicyBuilder usePohObelisk(boolean value)
		{
			usePohObelisk = value;
			return this;
		}

		PolicyBuilder enabledPohNexusPortals(Set<PohNexusPortal> portals)
		{
			enabledPohNexusPortals = portals;
			return this;
		}

		PolicyBuilder enabledPohMountedItems(Set<PohMountedItem> items)
		{
			enabledPohMountedItems = items;
			return this;
		}

		PolicyBuilder pohJewelleryBoxTier(JewelleryBoxTier tier)
		{
			pohJewelleryBoxTier = tier;
			return this;
		}

		PolicyBuilder currencyThreshold(int threshold)
		{
			currencyThreshold = threshold;
			return this;
		}

		PolicyBuilder includeBankPath(boolean value)
		{
			includeBankPath = value;
			return this;
		}

		RoutingPolicy build()
		{
			return new RoutingPolicy(enabledTypes, teleportationItemSetting, usePoh,
				usePohFairyRing, usePohSpiritTree, usePohObelisk, enabledPohNexusPortals,
				enabledPohMountedItems, pohJewelleryBoxTier, currencyThreshold, includeBankPath);
		}
	}

	/**
	 * An eligibility snapshot whose carried and bank-path pools both read the
	 * supplied items, with no bank contents, no pouch, no fairy-ring staff
	 * requirement, an unbounded currency threshold and no declared unlocks —
 * the mode is set explicitly so a teleportation-item gate that defers to
	 * item evaluation sees the same setting the policy carries.
	 */
	static TransportEligibility eligibility(TeleportationItem mode, Map<Integer, Integer> carried)
	{
		return eligibility(mode, carried, Integer.MAX_VALUE);
	}

	static TransportEligibility eligibility(TeleportationItem mode, Map<Integer, Integer> carried,
		int currencyThreshold)
	{
		return new TransportEligibility(carried, carried, Map.of(), -1, Map.of(),
			false, mode, currencyThreshold, Set.of(), false);
	}

	/**
	 * An eligibility snapshot where the bank-path pool carries extra items the
	 * carried pool lacks — the shape {@code collectEligibility} produces when
	 * bank paths are enabled and the bank holds usable items.
	 */
	static TransportEligibility bankedEligibility(TeleportationItem mode, Map<Integer, Integer> carried,
		Map<Integer, Integer> bankPath)
	{
		return new TransportEligibility(carried, bankPath, Map.of(), -1, Map.of(),
			false, mode, Integer.MAX_VALUE, Set.of(), true);
	}

	/** A context with every field defaulted to the always-passing value. */
	static ContextBuilder context()
	{
		return new ContextBuilder();
	}

	static RequirementContext context(TransportEligibility eligibility)
	{
		return context().eligibility(eligibility).build();
	}

	static final class ContextBuilder
	{
		private long evaluationTimeMinutes;
		private int[] boostedSkillLevelsAndMore = maxedSkills();
		private int currentMaxQuestPoints = 300;
		private Map<Quest, QuestState> questStates = Map.of();
		private Map<Integer, Integer> varbitValues = Map.of();
		private Map<Integer, Integer> varPlayerValues = Map.of();
		private TransportEligibility eligibility = TransportEligibility.forPlayerAndBank(
			Map.of(), Map.of(), -1, Map.of());
		private Set<Unlock> unlocks = Set.of();
		private boolean respawnPrifddinas;
		private boolean onSailingBoat;
		private LeagueModeState leagueModeState = new LeagueModeState();
		private Set<String> availableSpiritTrees = null;

		ContextBuilder evaluationTimeMinutes(long minutes)
		{
			evaluationTimeMinutes = minutes;
			return this;
		}

		ContextBuilder boostedSkillLevelsAndMore(int[] levels)
		{
			boostedSkillLevelsAndMore = levels;
			return this;
		}

		ContextBuilder currentMaxQuestPoints(int points)
		{
			currentMaxQuestPoints = points;
			return this;
		}

		ContextBuilder questStates(Map<Quest, QuestState> states)
		{
			questStates = states;
			return this;
		}

		ContextBuilder varbitValues(Map<Integer, Integer> values)
		{
			varbitValues = values;
			return this;
		}

		ContextBuilder varPlayerValues(Map<Integer, Integer> values)
		{
			varPlayerValues = values;
			return this;
		}

		ContextBuilder eligibility(TransportEligibility value)
		{
			eligibility = value;
			return this;
		}

		ContextBuilder unlocks(Set<Unlock> values)
		{
			unlocks = values;
			return this;
		}

		ContextBuilder respawnPrifddinas(boolean value)
		{
			respawnPrifddinas = value;
			return this;
		}

		ContextBuilder onSailingBoat(boolean value)
		{
			onSailingBoat = value;
			return this;
		}

		ContextBuilder leagueModeState(LeagueModeState state)
		{
			leagueModeState = state;
			return this;
		}

		ContextBuilder availableSpiritTrees(Set<String> trees)
		{
			availableSpiritTrees = trees;
			return this;
		}

		RequirementContext build()
		{
			return new RequirementContext(evaluationTimeMinutes, boostedSkillLevelsAndMore,
				currentMaxQuestPoints, questStates, varbitValues, varPlayerValues, eligibility,
				unlocks, respawnPrifddinas, onSailingBoat, leagueModeState, availableSpiritTrees);
		}
	}

	/**
	 * A {@link Requirements} chain bound to {@code context} whose hooks
	 * evaluate the context's own captured var maps — the same wiring the
	 * refresh path produces.
	 */
	static Requirements requirements(RequirementContext context, RoutingPolicy policy)
	{
		return new Requirements(context, policy, new TestRequirementHooks());
	}

	static Requirements requirements(RequirementContext context, RoutingPolicy policy,
		TestRequirementHooks hooks)
	{
		return new Requirements(context, policy, hooks);
	}

	/** Convenience for bank-adapter cases: defaults except where named. */
	static DestinationRequirements bankRequirements(int[] skillLevels,
		Set<Quest> quests, Set<VarRequirement> varbits,
		Set<VarRequirement> varPlayers)
	{
		return new DestinationRequirements(skillLevels, quests, varbits, varPlayers);
	}
}

package shortestpath.requirement;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

import java.util.EnumMap;
import java.util.EnumSet;
import java.util.List;
import java.util.Map;
