			new int[][]{
				ItemVariations.STAFF_OF_AIR.getIds(),
				ItemVariations.STAFF_OF_WATER.getIds(),
				ItemVariations.staves(ItemVariations.LAW_RUNE)},
			new int[][]{
				ItemVariations.offhands(ItemVariations.AIR_RUNE),
				ItemVariations.offhands(ItemVariations.WATER_RUNE),
				ItemVariations.offhands(ItemVariations.LAW_RUNE)},
			new int[]{3, 1, 1});
	}

	private static TransportItems houseTeleport()
	{
		return new TransportItems(
			new int[][]{
				ItemVariations.AIR_RUNE.getIds(),
				ItemVariations.EARTH_RUNE.getIds(),
				ItemVariations.LAW_RUNE.getIds()},
			new int[][]{
				ItemVariations.STAFF_OF_AIR.getIds(),
				ItemVariations.STAFF_OF_EARTH.getIds(),
				ItemVariations.staves(ItemVariations.LAW_RUNE)},
			new int[][]{
				ItemVariations.offhands(ItemVariations.AIR_RUNE),
				ItemVariations.offhands(ItemVariations.EARTH_RUNE),
				ItemVariations.offhands(ItemVariations.LAW_RUNE)},
			new int[]{1, 1, 1});
	}

	private static TransportItems varrockTeleport()
	{
		return new TransportItems(
			new int[][]{
				ItemVariations.AIR_RUNE.getIds(),
				ItemVariations.FIRE_RUNE.getIds(),
				ItemVariations.LAW_RUNE.getIds()},
			new int[][]{
				ItemVariations.STAFF_OF_AIR.getIds(),
				ItemVariations.STAFF_OF_FIRE.getIds(),
				ItemVariations.staves(ItemVariations.LAW_RUNE)},
			new int[][]{
				ItemVariations.offhands(ItemVariations.AIR_RUNE),
				ItemVariations.offhands(ItemVariations.FIRE_RUNE),
				ItemVariations.offhands(ItemVariations.LAW_RUNE)},
			new int[]{3, 1, 1});
	}

	private static TransportItems earthAndFire()
	{
		return new TransportItems(
			new int[][]{
				ItemVariations.EARTH_RUNE.getIds(),
				ItemVariations.FIRE_RUNE.getIds()},
			new int[][]{
				ItemVariations.STAFF_OF_EARTH.getIds(),
				ItemVariations.STAFF_OF_FIRE.getIds()},
			new int[][]{
				ItemVariations.offhands(ItemVariations.EARTH_RUNE),
				ItemVariations.offhands(ItemVariations.FIRE_RUNE)},
			new int[]{1, 1});
	}
}

package shortestpath.settings;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.util.EnumSet;
import java.util.Set;

import org.junit.Test;

import net.runelite.client.events.ConfigChanged;
import shortestpath.TestShortestPathConfig;

/**
 * Pins the typed {@link ConfigChange} classification contract: every config
 * key resolves to the exact {@link Effect} set the shell must act on. The
 * routing-read keys carry {@link Effect#ROUTE_INVALIDATING} — the same rows
 * the refresh path reads, so "is read by routing" and "invalidates the route"
 * cannot diverge — while display-only keys never invalidate and the two
 * side-effect keys carry their own effects.
 *
 * <p>Coverage is per-key and explicit: the former restart-regex arms, the
 * keys the regex silently missed but the refresh path always read, the
 * multi-effect backend key, the early-return debug-overlay key, and the
 * display-only keys.
 */
public class ConfigChangeTest
{
	private static final Set<Effect> ROUTE_ONLY = EnumSet.of(Effect.ROUTE_INVALIDATING);
	private static final Set<Effect> DISPLAY = EnumSet.of(Effect.DISPLAY_ONLY);

