package shortestpath.settings;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;

import java.awt.Color;
import java.lang.reflect.Method;
import java.lang.reflect.Proxy;
import java.util.HashMap;
import java.util.Map;
import java.util.Set;
import java.util.TreeSet;

import org.junit.Test;

import net.runelite.client.config.ConfigItem;
import shortestpath.ShortestPathConfig;
import shortestpath.TestShortestPathConfig;
import shortestpath.TileCounter;
import shortestpath.TileStyle;
import shortestpath.poh.JewelleryBoxTier;
import shortestpath.transport.TransportType;

/**
 * Registry-consistency gate for {@link ConfigKey}: the table must classify
 * every config key exactly once and pair each key with the read method its
 * stored value belongs to.
 *
 * <p>Pinned invariants:
 * <ul>
 * <li>every {@code @ConfigItem.keyName} on {@link ShortestPathConfig} has a
 * registry row — including the hidden write-pair keys whose keyName is shared
 * by a getter and a {@code void set*} method — and no row names a key that
 * does not exist;</li>
 * <li>every {@link TransportType#getEnabledKey()}/{@link TransportType#getCostKey()}
 * resolves to a row whose coercion matches the paired getter's return type;</li>
 * <li>the {@code costQuetzalWhistle} override key deliberately pairs with the
 * shared {@code costQuetzals} getter — divergence is asserted by name, not
 * left to naming convention;</li>
 * <li>getter/setter ambiguity resolves to the read method — the reflective
 * rule is {@code parameterCount == 0 && returnType != void}, and the typed
 * registry getters resolve to the same methods by construction.</li>
 * </ul>
 */
public class ConfigKeyTest
{
	/**
	 * Key names that intentionally have no registry row. Currently empty:
	 * every {@code @ConfigItem} is classified — the set exists so a future
	 * exemption is a named decision the test reports, not a silent gap.
	 */
	private static final Set<String> EXEMPTIONS = Set.of();

	/**
	 * All {@code @ConfigItem.keyName} values declared on the config interface,
	 * collected from every annotated method — getters and setters alike.
	 */
	private static Set<String> configItemKeyNames()
	{
		Set<String> keyNames = new TreeSet<>();
		for (Method method : ShortestPathConfig.class.getMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item != null)
			{
				keyNames.add(item.keyName());
			}
		}
		return keyNames;
	}

	/**
	 * The read method carrying {@code keyName}: the annotated member with
	 * {@code parameterCount == 0 && returnType != void}. Keys shared between
	 * a getter and a {@code void set*} write method (the hidden built-* rows)
	 * resolve to the getter; a key with no read method resolves to
	 * {@code null}.
	 */
	private static Method readMethod(String keyName)
	{
		Method read = null;
		for (Method method : ShortestPathConfig.class.getMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item == null || !keyName.equals(item.keyName()))
			{
				continue;
			}
			if (method.getParameterCount() == 0 && method.getReturnType() != void.class)
			{
				if (read != null && !read.equals(method))
				{
					fail("key " + keyName + " has two read methods: "
						+ read.getName() + " and " + method.getName());
				}
				read = method;
			}
		}
		return read;
	}

	/**
	 * The coercion a value of {@code type} requires; {@code null} when the
	 * type is inert to payloads (Coercion.NONE rows).
	 */
	private static Class<?> coercionType(ConfigKey.Coercion coercion)
	{
		switch (coercion)
		{
			case BOOLEAN:
				return boolean.class;
			case INT:
				return int.class;
			case COLOR:
				return Color.class;
			case TELEPORTATION_ITEM:
				return TeleportationItem.class;
			case JEWELLERY_BOX_TIER:
				return JewelleryBoxTier.class;
			case TILE_COUNTER:
				return TileCounter.class;
			case TILE_STYLE:
				return TileStyle.class;
			case NONE:
			default:
				return null;
		}
	}

	private static void assertCoercionMatchesGetter(ConfigKey row)
	{
		Method getter = readMethod(row.getKey());
		assertNotNull("registry key " + row.getKey() + " has no read method", getter);
		Class<?> expected = coercionType(row.getCoercion());
		if (expected == null)
		{
			return; // NONE rows are inert — any return type is acceptable
		}
		assertEquals("coercion of " + row.getKey() + " matches " + getter.getName()
			+ "'s return type", expected, getter.getReturnType());
	}

	@Test
	public void everyConfigItemKeyHasARegistryRow()
	{
		Set<String> keyNames = configItemKeyNames();
		Set<String> rowKeys = new TreeSet<>();
		for (ConfigKey row : ConfigKey.values())
		{
			rowKeys.add(row.getKey());
		}

		Set<String> missing = new TreeSet<>(keyNames);
		missing.removeAll(rowKeys);
		missing.removeAll(EXEMPTIONS);
		assertTrue("config keys with no registry row: " + missing, missing.isEmpty());

		Set<String> dead = new TreeSet<>(rowKeys);
		dead.removeAll(keyNames);
		dead.removeAll(EXEMPTIONS);
		assertTrue("registry rows naming no config key: " + dead, dead.isEmpty());
	}

	@Test
	public void everyRowCoercionMatchesItsPairedGetterType()
	{
		for (ConfigKey row : ConfigKey.values())
		{
			assertCoercionMatchesGetter(row);
		}
	}

	@Test
	public void transportTypeKeysResolveToRows()
	{
		for (TransportType type : TransportType.values())
		{
			String enabledKey = type.getEnabledKey();
			if (enabledKey != null)
			{
				ConfigKey row = ConfigKey.forKey(enabledKey);
				assertNotNull(type + " enabledKey " + enabledKey + " has no row", row);
				assertEquals(type + " enabledKey coercion",
					ConfigKey.Coercion.BOOLEAN, row.getCoercion());
				assertCoercionMatchesGetter(row);
			}
			String costKey = type.getCostKey();
			if (costKey != null)
			{
				ConfigKey row = ConfigKey.forKey(costKey);
				assertNotNull(type + " costKey " + costKey + " has no row", row);
				assertEquals(type + " costKey coercion",
					ConfigKey.Coercion.INT, row.getCoercion());
				assertCoercionMatchesGetter(row);
			}
		}
	}

	/**
	 * The registry getter for a key must read the same method the
	 * transport-type table pairs with that key. A proxy returning a distinct
	 * value per getter makes equivalence meaningful.
	 */
	@Test
	public void transportTypeRowsPairWithTheSameGetters()
	{
		ShortestPathConfig distinct = distinctValueConfig();
		for (TransportType type : TransportType.values())
		{
			if (type.getEnabledKey() != null && type.getEnabledGetter() != null)
			{
				ConfigKey row = ConfigKey.forKey(type.getEnabledKey());
				assertNotNull(row);
				assertEquals(type + " enabledKey " + type.getEnabledKey()
					+ " pairs with the transport table's enabled getter",
					type.getEnabledGetter().apply(distinct), row.getGetter().apply(distinct));
			}
			if (type.getCostKey() != null && type.getCostGetter() != null)
			{
				ConfigKey row = ConfigKey.forKey(type.getCostKey());
				assertNotNull(row);
				assertEquals(type + " costKey " + type.getCostKey()
					+ " pairs with the transport table's cost getter",
					type.getCostGetter().apply(distinct), row.getGetter().apply(distinct));
			}
		}
	}

	/**
	 * QUETZAL_WHISTLE's cost key is {@code costQuetzalWhistle} but the paired
	 * getter is the shared {@code costQuetzals} — asserted by name so the
	 * divergence can never be "fixed" back to a naming convention.
	 */
	@Test
	public void quetzalWhistleCostKeyPairsWithSharedQuetzalGetter()
	{
		assertEquals("costQuetzalWhistle", TransportType.QUETZAL_WHISTLE.getCostKey());
		TestShortestPathConfig config = new TestShortestPathConfig()
		{
			@Override
			public int costQuetzals()
			{
				return 11;
			}

			@Override
			public int costQuetzalWhistle()
			{
				return 22;
			}
		};

		ConfigKey row = ConfigKey.forKey("costQuetzalWhistle");
		assertNotNull("the override key must have its own row", row);
		assertEquals("the row reads the shared quetzal transport cost",
			11, row.getGetter().apply(config));
	}

	/**
	 * Every registry getter applies cleanly against the stub config — the
	 * read methods the rows resolve to are invocable and non-setter shaped.
	 */
	@Test
	public void registryGettersResolveToReadMethods()
	{
		TestShortestPathConfig config = new TestShortestPathConfig();
		for (ConfigKey row : ConfigKey.values())
		{
			Method read = readMethod(row.getKey());
			assertNotNull(row.getKey() + " resolves to a read method", read);
			assertEquals(row.getKey() + " read method takes no arguments",
				0, read.getParameterCount());
			assertTrue(row.getKey() + " read method returns a value",
				read.getReturnType() != void.class);
			row.getGetter().apply(config);
		}
	}

	/**
	 * The hidden write-pair keys share their keyName between a getter and a
	 * {@code void set*} method; resolution must pick the read side both
	 * reflectively and through the service's keyed read.
	 */
	@Test
	public void writePairKeysResolveToTheReadMethod()
	{
		for (String keyName : new String[]{
			"builtTeleportationBoxes", "builtTeleportationPortalsPoh"})
		{
			Method read = readMethod(keyName);
			assertNotNull(keyName + " must resolve to a read method", read);
			assertEquals(keyName, read.getName());
			assertEquals(keyName + " reads a String",
				String.class, read.getReturnType());
			assertEquals("keyed read returns the getter's value",
				"", Settings.wrap(new TestShortestPathConfig()).configuredValue(keyName));
		}
	}

	/**
	 * Keys the panel writes (avoidWilderness / highlightBankPickupItems)
	 * resolve to their read methods — the keyed read returns the configured
	 * value, never invokes a write path.
	 */
	@Test
	public void panelWrittenKeysResolveToReadMethods()
	{
		TestShortestPathConfig config = new TestShortestPathConfig()
		{
			@Override
			public boolean avoidWilderness()
			{
				return false;
			}

			@Override
			public boolean highlightBankPickupItems()
			{
				return true;
			}
		};
		Settings settings = Settings.wrap(config);

		assertEquals(false, settings.configuredValue("avoidWilderness"));
		assertEquals(true, settings.configuredValue("highlightBankPickupItems"));
		assertSame(boolean.class, readMethod("avoidWilderness").getReturnType());
		assertSame(boolean.class, readMethod("highlightBankPickupItems").getReturnType());
	}

	/**
	 * A config proxy whose primitive getters return a distinct value per
	 * method, so getter-equivalence assertions actually discriminate.
	 */
	private static ShortestPathConfig distinctValueConfig()
	{
		Map<String, Integer> ints = new HashMap<>();
		int[] counter = {0};
		return (ShortestPathConfig) Proxy.newProxyInstance(
			ConfigKeyTest.class.getClassLoader(),
			new Class<?>[]{ShortestPathConfig.class},
			(proxy, method, args) ->
			{
				Class<?> type = method.getReturnType();
				if (type == int.class)
				{
					return ints.computeIfAbsent(method.getName(), k -> counter[0] += 1000);
				}
				if (type == boolean.class)
				{
					return method.getName().length() % 2 == 0;
				}
				if (type == double.class)
				{
					return 0.0;
				}
				if (Set.class.isAssignableFrom(type))
				{
					return Set.of();
				}
				if (type == String.class)
				{
					return "";
				}
				if (type.isEnum())
				{
					Object[] constants = type.getEnumConstants();
					return constants == null || constants.length == 0 ? null : constants[0];
				}
				return null;
			});
	}
}

package shortestpath.settings;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.awt.Color;
import java.awt.event.KeyEvent;
import java.lang.reflect.Method;
import java.util.Map;
import java.util.Set;

import org.junit.Test;

import net.runelite.client.config.Keybind;
import shortestpath.ShortestPathConfig;
import shortestpath.TestShortestPathConfig;
import shortestpath.TileCounter;
import shortestpath.TileStyle;
import shortestpath.pathfinder.PathfinderBackend;
import shortestpath.poh.JewelleryBoxTier;
import shortestpath.poh.PohMountedItem;
import shortestpath.poh.PohNexusPortal;

/**
 * Pins the {@link EffectiveConfig} coercion contract: every coercible category
 * applies payload values only when they carry exactly the right runtime type
 * (or, for the string-parsed enums, exactly a {@code fromType} display string),
 * and every negative-space key stays inert no matter what the map holds.
 */
public class EffectiveConfigTest
{
	private static ShortestPathConfig base()
	{
		return new TestShortestPathConfig();
	}

	private static EffectiveConfig effectiveWith(Map<String, Object> overrides)
	{
		Settings settings = Settings.wrap(base());
		settings.applyOverrides(overrides);
		return settings.effective();
	}

	@Test
	public void booleanOverrideApplies()
	{
		// The stub's default is true; a false payload value proves the override took effect.
		EffectiveConfig effective = effectiveWith(Map.of("avoidWilderness", false));
		assertFalse(effective.avoidWilderness());
	}

	@Test
	public void booleanOverrideWrongTypeIsInert()
	{
		EffectiveConfig effective = effectiveWith(Map.of("avoidWilderness", "yes"));
		assertEquals(base().avoidWilderness(), effective.avoidWilderness());
	}

	@Test
	public void intOverrideApplies()
	{
		EffectiveConfig effective = effectiveWith(Map.of("currencyThreshold", 50));
		assertEquals(50, effective.currencyThreshold());
	}

	@Test
	public void intOverrideWrongTypeIsInert()
	{
		// String "50" is not an Integer — the configured value stands.
		EffectiveConfig effective = effectiveWith(Map.of("currencyThreshold", "50"));
		assertEquals(base().currencyThreshold(), effective.currencyThreshold());
	}

	@Test
	public void teleportationItemDisplayStringApplies()
	{
		EffectiveConfig effective = effectiveWith(Map.of("useTeleportationItems", "Inventory and Bank"));
		assertEquals(TeleportationItem.INVENTORY_AND_BANK, effective.useTeleportationItems());
	}

	@Test
	public void teleportationItemEnumNameIsInert()
	{
		// Payload grammar is the fromType display string, not Enum.name().
		EffectiveConfig effective = effectiveWith(Map.of("useTeleportationItems", "INVENTORY_AND_BANK"));
		assertEquals(base().useTeleportationItems(), effective.useTeleportationItems());
	}

	@Test
	public void jewelleryBoxTierDisplayStringApplies()
	{
		EffectiveConfig effective = effectiveWith(Map.of("pohJewelleryBoxTier", "Fancy"));
		assertEquals(JewelleryBoxTier.FANCY, effective.pohJewelleryBoxTier());
	}

	@Test
	public void jewelleryBoxTierEnumNameIsInert()
	{
		EffectiveConfig effective = effectiveWith(Map.of("pohJewelleryBoxTier", "FANCY"));
		assertEquals(base().pohJewelleryBoxTier(), effective.pohJewelleryBoxTier());
	}

	@Test
	public void tileCounterDisplayStringApplies()
	{
		EffectiveConfig effective = effectiveWith(Map.of("showTileCounter", "Remaining"));
		assertEquals(TileCounter.REMAINING, effective.showTileCounter());
	}

	@Test
	public void tileCounterEnumNameIsInert()
	{
		EffectiveConfig effective = effectiveWith(Map.of("showTileCounter", "REMAINING"));
		assertEquals(base().showTileCounter(), effective.showTileCounter());
	}

	@Test
	public void tileStyleDisplayStringApplies()
	{
		EffectiveConfig effective = effectiveWith(Map.of("pathStyle", "Lines"));
		assertEquals(TileStyle.LINES, effective.pathStyle());
	}

	@Test
	public void tileStyleEnumNameIsInert()
	{
		EffectiveConfig effective = effectiveWith(Map.of("pathStyle", "LINES"));
		assertEquals(base().pathStyle(), effective.pathStyle());
	}

	@Test
	public void colorOverrideApplies()
	{
		EffectiveConfig effective = effectiveWith(Map.of("colourText", Color.RED));
		assertEquals(Color.RED, effective.colourText());
	}

	@Test
	public void colorOverrideWrongTypeIsInert()
	{
		// Only a Color instance applies — a hex string falls back to base.
		EffectiveConfig effective = effectiveWith(Map.of("colourText", "#FF0000"));
		assertEquals(base().colourText(), effective.colourText());
	}

	// — Negative space: these keys are inert even when the map holds a value —

	@Test
	public void stringKeyIsInert()
	{
		EffectiveConfig effective = effectiveWith(Map.of("unreachableText", "custom unreachable text"));
		assertEquals(base().unreachableText(), effective.unreachableText());
	}

	@Test
	public void setKeysAreInert()
	{
		// Even correctly-typed Set payloads never reach the getters.
		EffectiveConfig effective = effectiveWith(Map.of(
			"pohNexusPortals", Set.of(PohNexusPortal.FALADOR),
			"pohMountedItems", Set.of(PohMountedItem.GLORY)));
		assertEquals(base().pohNexusPortals(), effective.pohNexusPortals());
		assertEquals(base().pohMountedItems(), effective.pohMountedItems());
	}

	@Test
	public void backendKeyIsInert()
	{
		EffectiveConfig effective = effectiveWith(Map.of("pathfinderAlgorithm", PathfinderBackend.ASTAR));
		assertEquals(PathfinderBackend.LEGACY, effective.pathfinderBackend());
	}

	@Test
	public void keybindKeyIsInert()
	{
		EffectiveConfig effective = effectiveWith(Map.of("clearPathHotkey", new Keybind(KeyEvent.VK_C, KeyEvent.CTRL_DOWN_MASK)));
		assertEquals(Keybind.NOT_SET, effective.clearPathHotkey());
	}

	@Test
	public void unknownKeyIsInertButEchoed()
	{
		Settings settings = Settings.wrap(base());
		settings.applyOverrides(Map.of("notARealKey", 42));
		assertEquals(base().avoidWilderness(), settings.effective().avoidWilderness());
		assertEquals(base().currencyThreshold(), settings.effective().currencyThreshold());
		assertEquals(42, settings.rawOverrides().get("notARealKey"));
	}

	@Test
	public void emptyPayloadDoesNotClearOverrides()
	{
		Settings settings = Settings.wrap(base());
		settings.applyOverrides(Map.of("avoidWilderness", false));
		settings.applyOverrides(Map.of());
		assertFalse(settings.effective().avoidWilderness());
	}

	@Test
	public void clearOverridesRestoresBase()
	{
		Settings settings = Settings.wrap(base());
		settings.applyOverrides(Map.of("avoidWilderness", false));
		settings.clearOverrides();
		assertTrue(settings.effective().avoidWilderness());
		assertTrue(settings.rawOverrides().isEmpty());
	}

	@Test
	public void keyedCoerceIntUsesCallerSuppliedKey()
	{
		// The quetzal-whistle override key pairs with the shared costQuetzals
		// base getter — the caller supplies the key, not the decorator.
		ShortestPathConfig base = base();
		Settings settings = Settings.wrap(base);
		settings.applyOverrides(Map.of("costQuetzalWhistle", 7));
		assertEquals(7, settings.coerceInt("costQuetzalWhistle", base.costQuetzals()));
		assertEquals(base.costQuetzals(), settings.coerceInt("costQuetzals", base.costQuetzals()));
	}

	@Test
	public void effectiveConfigDeclaresEveryInterfaceMethod() throws Exception
	{
		// A missed method would compile silently — it would inherit the
		// interface default body and ignore the base config entirely.
		for (Method method : ShortestPathConfig.class.getDeclaredMethods())
		{
			Method declared = EffectiveConfig.class.getDeclaredMethod(method.getName(), method.getParameterTypes());
			assertEquals("not overridden by EffectiveConfig: " + method.getName(),
				EffectiveConfig.class, declared.getDeclaringClass());
		}
	}

	@Test
	public void wrapIsAPurePassthrough()
	{
		TestShortestPathConfig stub = new TestShortestPathConfig();
		Settings wrapped = Settings.wrap(stub);
		assertSame(stub, wrapped.configured());
		assertTrue(wrapped.rawOverrides().isEmpty());
		assertEquals(stub.avoidWilderness(), wrapped.effective().avoidWilderness());
		assertEquals(stub.currencyThreshold(), wrapped.effective().currencyThreshold());
		assertEquals(stub.useTeleportationItems(), wrapped.effective().useTeleportationItems());
		assertEquals(stub.unreachableText(), wrapped.effective().unreachableText());
		assertEquals(stub.colourText(), wrapped.effective().colourText());
		assertEquals(stub.drawTiles(), wrapped.display().drawTiles());
	}
}

package shortestpath.settings;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.io.IOException;
import java.lang.reflect.Method;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ArrayDeque;
import java.util.Arrays;
import java.util.Deque;
import java.util.List;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import java.util.SortedSet;
import java.util.TreeSet;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.junit.BeforeClass;
import org.junit.Test;

import net.runelite.client.config.ConfigItem;
import shortestpath.ShortestPathConfig;
import shortestpath.transport.TransportType;

/**
 * Source-scan parity between the routing-key table and the code it
 * describes: the set of config keys the refresh path actually reads must
 * equal the {@link ConfigKey} rows classified
 * {@link Effect#ROUTE_INVALIDATING}. The table and the read set are two
 * halves of one fact — a routing read without a route-invalidating row
 * silently leaves a running route stale, and a route-invalidating row no
 * refresh path reads is dead classification (or the read moved somewhere
 * the scan does not follow). Both directions are asserted, so drift on
 * either side fails the build.
 *
 * <p>The expected set is never hardcoded: it is derived by scanning the
 * refresh-path method bodies in {@code PathfinderConfig} and
 * {@code TransportTypeConfig} for {@code effective().<method>()},
 * {@code config.<method>()} and {@code settings.coerce<Kind>("<key>", ...)}
 * reads, expanding the per-{@link TransportType} driven reads
 * ({@code getEnabledGetter}/{@code getCostGetter} applied to config, keyed
 * by {@code getEnabledKey()}/{@code getCostKey()}) across every enum
 * constant, and following {@code ShortestPathConfig} default methods that
 * delegate to further config getters (e.g. {@code pohNexusPortals()} reads
 * {@code useTeleportationPortalsPoh()}). Method names map to key names
 * through the {@code @ConfigItem} annotations on
 * {@link ShortestPathConfig}.
 *
 * <p>Sources are resolved relative to the test working directory (the
 * Gradle project dir) — the same idiom as the package-boundary lints. A
 * missing file fails with an explicit message rather than an empty scan.
 */
public class RoutingKeyParityTest
{
	private static final Path PATHFINDER_CONFIG =
		Paths.get("src/main/java/shortestpath/pathfinder/PathfinderConfig.java");
	private static final Path TRANSPORT_TYPE_CONFIG =
		Paths.get("src/main/java/shortestpath/transport/TransportTypeConfig.java");
	private static final Path SHORTEST_PATH_CONFIG =
		Paths.get("src/main/java/shortestpath/ShortestPathConfig.java");

	/** Identifier call sites — {@code name(} — inside a method body. */
	private static final Pattern CALL = Pattern.compile("([A-Za-z_$][\\w$]*)\\s*\\(");
	/**
	 * {@code effective.<method>()} reads on the settings seam — both the
	 * {@code settings.effective().x()} call form and the captured
	 * {@code effective.x()} local form refresh uses for snapshot coherence.
	 */
	private static final Pattern EFFECTIVE_READ =
		Pattern.compile("(?:^|[^\\w$])effective\\s*(?:\\(\\s*\\))?\\s*\\.\\s*([A-Za-z_$][\\w$]*)\\s*\\(");
	/**
	 * {@code config.<method>()} bypass reads on the raw config proxy. A
	 * qualified receiver ({@code this.config.x()}) also matches — the
	 * excluded set drops {@code .} precisely so a dotted receiver still
	 * counts as a config read.
	 */
	private static final Pattern CONFIG_READ =
		Pattern.compile("(?:^|[^\\w$])config\\s*\\.\\s*([A-Za-z_$][\\w$]*)\\s*\\(");
	/** {@code settings.coerce<Kind>("<key>", ...)} override-aware reads. */
	private static final Pattern COERCE_READ =
		Pattern.compile("coerce\\w+\\s*\\(\\s*\"([^\"]+)\"");
	/** Keywords whose {@code name(} is never a method declaration. */
	private static final Set<String> CONTROL_TOKENS = Set.of(
		"if", "for", "while", "switch", "catch", "try", "do", "else",
		"synchronized", "return", "throw", "new", "assert", "super", "this",
		"case", "default");

	private static SortedSet<String> refreshReadKeys;

	@BeforeClass
	public static void deriveRefreshReadSet() throws IOException
	{
		refreshReadKeys = new TreeSet<>(routingReads());
	}

	/**
	 * The config keys the refresh path reads, derived entirely from source:
	 * every {@code effective()}/{@code config} getter invocation reachable
	 * from {@code refresh()} through same-file calls, the literal keys in
	 * {@code coerce*("key", ...)} calls, the per-transport-type driven keys,
	 * and keys read transitively through {@code ShortestPathConfig} default
	 * methods.
	 */
	static Set<String> routingReads() throws IOException
	{
		Map<String, String> methodToKey = configMethodToKey();
		Map<String, String> pathfinderBodies = methodBodies(readSource(PATHFINDER_CONFIG));
		Map<String, String> transportTypeBodies = methodBodies(readSource(TRANSPORT_TYPE_CONFIG));
		Map<String, String> configBodies = methodBodies(readSource(SHORTEST_PATH_CONFIG));

		Set<String> keys = new TreeSet<>();
		Set<String> readMethods = new HashSet<>();
		boolean enabledDriven = false;
		boolean costDriven = false;

		List<Map<String, String>> refreshSources =
			Arrays.asList(pathfinderBodies, transportTypeBodies);
		Set<String> scannedBodies = new HashSet<>();
		Deque<String> queue = new ArrayDeque<>();
		queue.add("refresh");
		while (!queue.isEmpty())
		{
			String name = queue.poll();
			for (Map<String, String> bodies : refreshSources)
			{
				String body = bodies.get(name);
				if (body == null || !scannedBodies.add(name + body))
				{
					continue;
				}
				Matcher effective = EFFECTIVE_READ.matcher(body);
				while (effective.find())
				{
					readMethods.add(effective.group(1));
				}
				Matcher config = CONFIG_READ.matcher(body);
				while (config.find())
				{
					readMethods.add(config.group(1));
				}
				Matcher coerce = COERCE_READ.matcher(body);
				while (coerce.find())
				{
					keys.add(coerce.group(1));
				}
				enabledDriven |= body.contains("getEnabledKey()")
					|| body.contains("getEnabledGetter()");
				costDriven |= body.contains("getCostKey()")
					|| body.contains("getCostGetter()");
				Matcher calls = CALL.matcher(body);
				while (calls.find())
				{
					String called = calls.group(1);
					if (!CONTROL_TOKENS.contains(called))
					{
						queue.add(called);
					}
				}
			}
		}

		// Resolve read method names to key names, following config default
		// methods that delegate to further config getters.
		Deque<String> methods = new ArrayDeque<>(readMethods);
		Set<String> seenMethods = new HashSet<>();
		while (!methods.isEmpty())
		{
			String method = methods.poll();
			if (!seenMethods.add(method))
			{
				continue;
			}
			String key = methodToKey.get(method);
			if (key != null)
			{
				keys.add(key);
			}
			String body = configBodies.get(method);
			if (body == null)
			{
				continue;
			}
			Matcher inner = CALL.matcher(body);
			while (inner.find())
			{
				String nested = inner.group(1);
				if (methodToKey.containsKey(nested))
				{
					methods.add(nested);
				}
			}
		}

		if (enabledDriven)
		{
			for (TransportType type : TransportType.values())
			{
				if (type.getEnabledKey() != null)
				{
					keys.add(type.getEnabledKey());
				}
			}
		}
		if (costDriven)
		{
			for (TransportType type : TransportType.values())
			{
				if (type.getCostKey() != null)
				{
					keys.add(type.getCostKey());
				}
			}
		}
		return keys;
	}

	/**
	 * Read a required source file; a missing file is a hard failure — an
	 * empty scan must never read as green.
	 */
	private static String readSource(Path path) throws IOException
	{
		assertTrue("source file not found (tests must run with the project "
			+ "dir as working directory): " + path.toAbsolutePath(),
			Files.isRegularFile(path));
		return new String(Files.readAllBytes(path));
	}

	/**
	 * {@code methodName -> @ConfigItem keyName} for every annotated
	 * {@link ShortestPathConfig} getter.
	 */
	private static Map<String, String> configMethodToKey()
	{
		Map<String, String> methodToKey = new HashMap<>();
		for (Method method : ShortestPathConfig.class.getMethods())
		{
			ConfigItem item = method.getAnnotation(ConfigItem.class);
			if (item != null && !item.keyName().isEmpty())
			{
				methodToKey.put(method.getName(), item.keyName());
			}
		}
		return methodToKey;
	}

	/**
	 * Extract {@code methodName -> body text} for every declaration in the
	 * source. Comments are stripped first so javadoc references cannot
	 * register as reads; overloads merge into one concatenated body.
	 */
	private static Map<String, String> methodBodies(String source)
	{
		String code = stripComments(source);
		Map<String, String> bodies = new HashMap<>();
		Matcher matcher = CALL.matcher(code);
		while (matcher.find())
		{
			String name = matcher.group(1);
			if (CONTROL_TOKENS.contains(name) || precededByNew(code, matcher.start()))
			{
				continue;
			}
			int closeParen = matchDelimiter(code, matcher.end() - 1, '(', ')');
			if (closeParen < 0)
			{
				continue;
			}
			int brace = skipToBrace(code, closeParen);
			if (brace < 0)
			{
				continue;
			}
			int closeBrace = matchDelimiter(code, brace, '{', '}');
			if (closeBrace < 0)
			{
				continue;
			}
			bodies.merge(name, code.substring(brace + 1, closeBrace), String::concat);
		}
		return bodies;
	}

	private static boolean precededByNew(String code, int index)
	{
		int end = index;
		while (end > 0 && Character.isWhitespace(code.charAt(end - 1)))
		{
			end--;
		}
		return end >= 3 && code.substring(end - 3, end).equals("new")
			&& (end == 3 || !Character.isJavaIdentifierPart(code.charAt(end - 4)));
	}

	/**
	 * After a call's closing paren at {@code from} (exclusive), a method
	 * declaration continues with whitespace, an optional {@code throws}
	 * clause, then the body brace. Returns the brace index or -1 when the
	 * site is a call rather than a declaration.
	 */
	private static int skipToBrace(String code, int from)
	{
		int i = from;
		while (i < code.length() && Character.isWhitespace(code.charAt(i)))
		{
			i++;
		}
		if (code.startsWith("throws", i))
		{
			int brace = code.indexOf('{', i);
			int semi = code.indexOf(';', i);
			return semi < 0 || brace < semi ? brace : -1;
		}
		return i < code.length() && code.charAt(i) == '{' ? i : -1;
	}

	/**
	 * Index just past the delimiter matching {@code open} at {@code openIndex},
	 * or -1 if unbalanced. Depth counts only; character/string literals are
	 * not special-cased because config sources carry no braces in literals.
	 */
	private static int matchDelimiter(String code, int openIndex, char open, char close)
	{
		int depth = 0;
		for (int i = openIndex; i < code.length(); i++)
		{
			char c = code.charAt(i);
			if (c == open)
			{
				depth++;
			}
			else if (c == close)
			{
				depth--;
				if (depth == 0)
				{
					return i + 1;
				}
			}
		}
		return -1;
	}

	private static String stripComments(String source)
	{
		String noBlock = source.replaceAll("(?s)/\\*.*?\\*/", " ");
		return noBlock.replaceAll("(?m)//.*$", " ");
	}

	/**
	 * The table's route-invalidating side: every {@link ConfigKey} row whose
	 * effect set contains {@link Effect#ROUTE_INVALIDATING}.
	 */
	private static SortedSet<String> routingTableKeys()
	{
		SortedSet<String> keys = new TreeSet<>();
		for (ConfigKey row : ConfigKey.values())
		{
			if (row.isRouteInvalidating())
			{
				keys.add(row.getKey());
			}
		}
		return keys;
	}

	@Test
	public void refreshReadsEqualRouteInvalidatingRows()
	{
		SortedSet<String> routingKeys = routingTableKeys();

		SortedSet<String> unread = new TreeSet<>(refreshReadKeys);
		unread.removeAll(routingKeys);
		SortedSet<String> stale = new TreeSet<>(routingKeys);
		stale.removeAll(refreshReadKeys);

		StringBuilder message = new StringBuilder();
		if (!unread.isEmpty())
		{
			message.append("config keys the refresh path reads that are not "
				+ "classified ROUTE_INVALIDATING — a change to them leaves a "
				+ "running route stale: ").append(unread).append(' ');
		}
		if (!stale.isEmpty())
		{
			message.append("ROUTE_INVALIDATING rows the refresh path never "
				+ "reads — stale rows, or a read the source scan does not "
				+ "follow: ").append(stale);
		}
		assertTrue(message.toString(), unread.isEmpty() && stale.isEmpty());
	}

	/**
	 * Vacuity guard: the scan must actually observe reads — an empty
	 * derived set would pass a degenerate comparison while meaning the
	 * scanner or the source layout broke.
	 */
	@Test
	public void scanHasReach() throws IOException
	{
		assertTrue("source file not found: " + PATHFINDER_CONFIG.toAbsolutePath(),
			Files.isRegularFile(PATHFINDER_CONFIG));
		assertTrue("source file not found: " + TRANSPORT_TYPE_CONFIG.toAbsolutePath(),
			Files.isRegularFile(TRANSPORT_TYPE_CONFIG));
		assertTrue("source file not found: " + SHORTEST_PATH_CONFIG.toAbsolutePath(),
			Files.isRegularFile(SHORTEST_PATH_CONFIG));
		assertFalse("refresh-path scan observed no config reads — the scanner "
			+ "or the refresh path is broken", refreshReadKeys.isEmpty());
	}
}

package shortestpath.settings;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;

import java.util.EnumSet;
import java.util.Map;
import java.util.Set;

import org.junit.Test;

import net.runelite.client.events.ConfigChanged;
import shortestpath.TestShortestPathConfig;
import shortestpath.requirement.RoutingPolicy;
import shortestpath.poh.JewelleryBoxTier;
import shortestpath.transport.TransportType;
import shortestpath.transport.TransportTypeConfig;

/**
 * Pins the two publication cadences on {@link Settings}: the view snapshots
 * (and the {@link EffectiveConfig} they derive from) are frozen between
 * republish events, while {@link #routing()} carries the refresh-built policy
 * on a separate slot that republishes never touch.
 */
public class RoutingSnapshotTest
{
	private static RoutingPolicy policy(boolean includeBankPath)
	{
		return new RoutingPolicy(
			EnumSet.of(TransportType.BOAT),
			TeleportationItem.NONE,
			false, false, false, false,
			Set.of(), Set.of(),
			JewelleryBoxTier.ORNATE,
			0, includeBankPath);
	}

	@Test
	public void routingIsNullUntilPublished()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());
		assertNull(settings.routing());
	}

	@Test
	public void republishDoesNotTouchTheRoutingSlot()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());
		RoutingPolicy policy = policy(true);
		settings.publishRouting(policy);

		settings.applyOverrides(Map.of("avoidWilderness", false));
		assertSame(policy, settings.routing());

		settings.clearOverrides();
		assertSame(policy, settings.routing());
	}

	@Test
	public void heldEffectiveConfigStaysFrozenAfterRepublish()
	{
		TestShortestPathConfig stub = new TestShortestPathConfig();
		Settings settings = Settings.wrap(stub);
		EffectiveConfig held = settings.effective();

		settings.applyOverrides(Map.of("avoidWilderness", false, "currencyThreshold", 50));

		assertTrue("the held decorator still reads the pre-apply map",
			held.avoidWilderness());
		assertFalse("the published decorator reads the new map",
			settings.effective().avoidWilderness());
		assertEquals(50, settings.effective().currencyThreshold());
		assertNotSame(held, settings.effective());
	}

	@Test
	public void viewSnapshotsFreezeUntilARepublishEvent()
	{
		TestShortestPathConfig stub = new TestShortestPathConfig();
		Settings settings = Settings.wrap(stub);
		Settings.BankView heldView = settings.bank();

		// Mutating the base config alone republishes nothing: a frozen view
		// keeps the captured value rather than tracking the live base.
		stub.setIncludeBankPathValue(true);
		assertFalse(heldView.includeBankPath());
		assertSame(heldView, settings.bank());

		// Any publication rebuilds the views off the current base + overrides.
		settings.applyOverrides(Map.of("avoidWilderness", false));
		assertTrue(settings.bank().includeBankPath());
		assertNotSame(heldView, settings.bank());
	}

	@Test
	public void configChangeEventRepublishesViews()
	{
		TestShortestPathConfig stub = new TestShortestPathConfig();
		Settings settings = Settings.wrap(stub);
		Settings.BankView heldView = settings.bank();

		stub.setIncludeBankPathValue(true);

		ConfigChanged event = new ConfigChanged();
		event.setGroup("shortestpath");
		event.setKey("includeBankPath");
		settings.onConfigChanged(event);

		assertNotSame(heldView, settings.bank());
		assertTrue(settings.bank().includeBankPath());
	}

	@Test
	public void foreignGroupEventIsIgnored()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());
		Settings.BankView heldView = settings.bank();

		ConfigChanged event = new ConfigChanged();
		event.setGroup("someOtherPlugin");
		event.setKey("includeBankPath");
		assertNull(settings.onConfigChanged(event));

		assertSame(heldView, settings.bank());
	}

	/**
	 * The service builds the routing policy itself: the built snapshot is
	 * published into the {@link #routing()} slot before the call returns, and
	 * the enabled-type set is frozen off the (post-disableUnless)
	 * transport-type view it was handed.
	 */
	@Test
	public void buildRoutingPolicyPublishesTheBuiltSnapshot()
	{
		TestShortestPathConfig config = new TestShortestPathConfig();
		Settings settings = Settings.wrap(config);
		TransportTypeConfig transportTypeConfig = new TransportTypeConfig(config, settings);
		transportTypeConfig.setEnabled(TransportType.BOAT, false);

		RoutingPolicy policy = settings.buildRoutingPolicy(transportTypeConfig,
			false, true, false, true, Set.of(), Set.of(),
			JewelleryBoxTier.ORNATE, 42, true);

		assertSame("the built policy is the published snapshot", policy, settings.routing());
		assertTrue(policy.isTransportTypeEnabled(TransportType.TRANSPORT));
		assertFalse("disableUnless-derived state is frozen into the build",
			policy.isTransportTypeEnabled(TransportType.BOAT));
		assertTrue(policy.usePohFairyRing());
		assertFalse(policy.usePoh());
		assertEquals(42, policy.currencyThreshold());
		assertTrue(policy.includeBankPath());
	}
}

package shortestpath.settings;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotSame;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertThrows;
import static org.junit.Assert.assertTrue;

import java.util.HashMap;
import java.util.Map;

import org.junit.Test;

import shortestpath.TestShortestPathConfig;

/**
 * Pins the {@link Settings} service-level payload contract: apply, clear, and
 * the raw echo. The override map is stored verbatim for the plugin-message
 * echo, copied defensively on apply, and every publication swaps the views
 * atomically with the map so a reader never sees a torn pair.
 */
public class SettingsPayloadTest
{
	@Test
	public void applyReachesViewsAtomically()
	{
		TestShortestPathConfig stub = new TestShortestPathConfig();
		Settings settings = Settings.wrap(stub);
		Settings.BankView before = settings.bank();

		settings.applyOverrides(Map.of("includeBankPath", true, "costBankVisit", 9));

		assertFalse("held view snapshot keeps the old value", before.includeBankPath());
		assertTrue(settings.bank().includeBankPath());
		assertEquals(9, settings.bank().costBankVisit());
		assertTrue(settings.effective().includeBankPath());
		assertNotSame(before, settings.bank());
	}

	@Test
	public void stringCoercionsApplyThroughTheService()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());
		settings.applyOverrides(Map.of("useTeleportationItems", "Inventory and Bank"));

		assertEquals(TeleportationItem.INVENTORY_AND_BANK, settings.effective().useTeleportationItems());
	}

	@Test
	public void clearRestoresConfiguredValuesEverywhere()
	{
		TestShortestPathConfig stub = new TestShortestPathConfig();
		Settings settings = Settings.wrap(stub);
		settings.applyOverrides(Map.of("includeBankPath", true, "avoidWilderness", false));

		settings.clearOverrides();

		assertTrue(settings.rawOverrides().isEmpty());
		assertFalse(settings.bank().includeBankPath());
		assertEquals(stub.avoidWilderness(), settings.effective().avoidWilderness());
	}

	@Test
	public void rawEchoIsVerbatimIncludingUnknownKeys()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());
		Map<String, Object> payload = Map.of(
			"avoidWilderness", false,
			"notARealKey", 42,
			"alsoNotReal", "text");
		settings.applyOverrides(payload);

		assertEquals(payload, settings.rawOverrides());
	}

	@Test
	public void rawEchoIsImmutable()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());
		settings.applyOverrides(Map.of("avoidWilderness", false));

		assertThrows(UnsupportedOperationException.class,
			() -> settings.rawOverrides().put("includeBankPath", true));
	}

	@Test
	public void applyCopiesThePayloadDefensively()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());
		Map<String, Object> payload = new HashMap<>();
		payload.put("avoidWilderness", false);
		settings.applyOverrides(payload);

		payload.put("includeBankPath", true);

		assertFalse("post-apply mutations of the caller map must not leak in",
			settings.effective().includeBankPath());
		assertFalse(settings.rawOverrides().containsKey("includeBankPath"));
	}

	@Test
	public void emptyPayloadIsANoOp()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());
		settings.applyOverrides(Map.of("avoidWilderness", false));
		Settings.DisplayView before = settings.display();

		settings.applyOverrides(Map.of());
		settings.applyOverrides(null);

		assertSame("empty payloads must not republish", before, settings.display());
		assertFalse(settings.effective().avoidWilderness());
		assertEquals(Map.of("avoidWilderness", false), settings.rawOverrides());
	}

	@Test
	public void unknownKeysAreInertOnEveryGetter()
	{
		TestShortestPathConfig stub = new TestShortestPathConfig();
		Settings settings = Settings.wrap(stub);
		settings.applyOverrides(Map.of("notARealKey", true));

		assertEquals(stub.avoidWilderness(), settings.effective().avoidWilderness());
		assertEquals(stub.includeBankPath(), settings.effective().includeBankPath());
		assertEquals(stub.currencyThreshold(), settings.effective().currencyThreshold());
		assertEquals(stub.useTeleportationItems(), settings.effective().useTeleportationItems());
	}
}

package shortestpath.settings;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.junit.Assert.assertTrue;
import static org.junit.Assert.fail;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.ArgumentMatchers.same;
import static org.mockito.Mockito.doAnswer;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

import java.util.EnumSet;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;

import javax.swing.SwingUtilities;

import org.junit.Test;

import net.runelite.client.config.ConfigManager;
import net.runelite.client.events.ConfigChanged;
import shortestpath.TestShortestPathConfig;
import shortestpath.poh.PohNexusPortal;

/**
 * Pins the panel write/listen/keyed-read contract on {@link Settings} —
 * the service surface the reworked panel consumes in place of its own
 * writeConfig/registerSync machinery.
 *
 * <p>The ordering contract mirrors the panel machinery it replaces:
 * {@code write()} is the sole mutation path (it delegates straight to
 * {@code ConfigManager.setConfiguration}), the {@link ConfigChanged} a write
 * produces is classified write-originated so it republishes views and yields
 * a normal {@link ConfigChange} fact but never triggers the external-delivery
 * path for that key, and same-key listeners fire synchronously inside
 * {@code write()}. External (non-write-originated) changes deliver their
 * listeners on the EDT via {@code SwingUtilities.invokeLater}.
 *
 * <p>Keyed reads return the configured value — the panel displays what is
 * stored, so payload overrides must not leak into these reads.
 */
public class SettingsWriteListenTest
{
	private static final String GROUP = "shortestpath";

	private static ConfigChanged event(String key)
	{
		ConfigChanged changed = new ConfigChanged();
		changed.setGroup(GROUP);
		changed.setKey(key);
		return changed;
	}

	/**
	 * Flushes the EDT so every invokeLater-delivered listener has run.
	 */
	private static void flushEdt() throws Exception
	{
		SwingUtilities.invokeAndWait(() ->
		{
		});
	}

	private static Settings service(ConfigManager configManager, TestShortestPathConfig config)
	{
		return new Settings(configManager, config);
	}

	@Test
	public void writeDelegatesToConfigManager()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());

		settings.write("avoidWilderness", false);

		verify(configManager).setConfiguration(GROUP, "avoidWilderness", false);
	}

	@Test
	public void unknownKeyWriteStillReachesConfigManager()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());

		settings.write("notARegistryKey", 7);

		verify(configManager).setConfiguration(GROUP, "notARegistryKey", 7);
	}

	@Test
	public void sameKeyListenerFiresSynchronouslyInsideWrite()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger fired = new AtomicInteger();

		settings.listen("avoidWilderness", fired::incrementAndGet);
		settings.write("avoidWilderness", false);

		assertEquals("same-key listener ran inside write()", 1, fired.get());
	}

	@Test
	public void multipleListenersPerKeyAllFire()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger first = new AtomicInteger();
		AtomicInteger second = new AtomicInteger();

		settings.listen("avoidWilderness", first::incrementAndGet);
		settings.listen("avoidWilderness", second::incrementAndGet);
		settings.write("avoidWilderness", false);

		assertEquals(1, first.get());
		assertEquals(1, second.get());
	}

	@Test
	public void differentKeyListenerDoesNotFireOnWrite() throws Exception
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger fired = new AtomicInteger();

		settings.listen("avoidWilderness", fired::incrementAndGet);
		settings.write("drawMap", true);
		flushEdt();

		assertEquals("a write to another key never touches this listener", 0, fired.get());
	}

	/**
	 * The echo a write produces must still republish views and classify, but
	 * the listener fires exactly once — from the synchronous in-write
	 * delivery, not again through the external path.
	 */
	@Test
	public void writeOriginatedEchoDoesNotDoubleDeliver()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		TestShortestPathConfig config = new TestShortestPathConfig();
		Settings settings = service(configManager, config);
		AtomicInteger fired = new AtomicInteger();
		AtomicReference<ConfigChange> classified = new AtomicReference<>();

		// any(Object.class) pins the (String, String, Object) overload —
		// bare any() would resolve to the (String, String, String) one.
		doAnswer(invocation ->
		{
			// Reproduce ConfigManager's synchronous dispatch: mutate the
			// configured value, then hand the event back to the service.
			config.setCalculationCutoffValue(9);
			ConfigChanged echo = event(invocation.getArgument(1));
			classified.set(settings.onConfigChanged(echo));
			return null;
		}).when(configManager).setConfiguration(anyString(), anyString(), any(Object.class));

		settings.listen("avoidWilderness", fired::incrementAndGet);
		settings.write("avoidWilderness", false);

		assertEquals("listener fired once, inside write()", 1, fired.get());
		ConfigChange fact = classified.get();
		assertNotNull("the write's echo still ran classification", fact);
		assertTrue("write-originated echo still classifies effects",
			fact.getEffects().contains(Effect.ROUTE_INVALIDATING));
		assertEquals("the echo still republished the views",
			9, settings.lifecycle().calculationCutoff());
	}

	/**
	 * Marshalling is pinned deterministically by consuming the event on the
	 * EDT itself: an invokeLater delivery cannot run before the current EDT
	 * task finishes, so the listener must still be pending when the event
	 * returns — an inline (unmarshalled) delivery would have already fired.
	 */
	@Test
	public void externalChangeDeliversOnEdtNotInline() throws Exception
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger fired = new AtomicInteger();

		settings.listen("avoidWilderness", fired::incrementAndGet);
		SwingUtilities.invokeAndWait(() ->
		{
			settings.onConfigChanged(event("avoidWilderness"));
			assertEquals("external delivery is marshalled, not inline", 0, fired.get());
		});
		flushEdt();
		assertEquals("listener ran on the EDT", 1, fired.get());
	}

	@Test
	public void externalChangeForOtherKeyStillDeliversDuringWrite() throws Exception
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger ownKey = new AtomicInteger();
		AtomicInteger otherKey = new AtomicInteger();

		doAnswer(invocation ->
		{
			settings.onConfigChanged(event(invocation.getArgument(1)));
			// An unrelated external event arriving mid-write is not
			// write-originated — its listeners still get EDT delivery.
			settings.onConfigChanged(event("drawMap"));
			return null;
		}).when(configManager).setConfiguration(anyString(), anyString(), any(Object.class));

		settings.listen("avoidWilderness", ownKey::incrementAndGet);
		settings.listen("drawMap", otherKey::incrementAndGet);
		settings.write("avoidWilderness", false);
		flushEdt();

		assertEquals("same-key listener fired once inside write()", 1, ownKey.get());
		assertEquals("external event for another key still delivered", 1, otherKey.get());
	}

	@Test
	public void foreignGroupEventDeliversNothing() throws Exception
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		AtomicInteger fired = new AtomicInteger();

		settings.listen("avoidWilderness", fired::incrementAndGet);
		ConfigChanged foreign = event("avoidWilderness");
		foreign.setGroup("someOtherPlugin");
		assertNull(settings.onConfigChanged(foreign));
		flushEdt();

		assertEquals(0, fired.get());
	}

	@Test
	public void keyedReadsReturnConfiguredNotEffective()
	{
		TestShortestPathConfig config = new TestShortestPathConfig();
		Settings settings = Settings.wrap(config);
		assertTrue("configured default", config.avoidWilderness());

		settings.applyOverrides(Map.of("avoidWilderness", false));
		assertFalse("effective read sees the override",
			settings.effective().avoidWilderness());

		assertEquals("keyed read returns the configured value",
			true, settings.configuredValue("avoidWilderness"));
		assertTrue(settings.configuredBool("avoidWilderness"));
	}

	@Test
	public void configuredBoolReadsTheConfiguredValue()
	{
		TestShortestPathConfig config = new TestShortestPathConfig();
		Settings settings = Settings.wrap(config);
		assertFalse(settings.configuredBool("includeBankPath"));

		config.setIncludeBankPathValue(true);
		assertTrue(settings.configuredBool("includeBankPath"));
	}

	@Test
	public void configuredSetPassesThroughRaw()
	{
		Set<PohNexusPortal> portals = EnumSet.of(PohNexusPortal.VARROCK);
		TestShortestPathConfig config = new TestShortestPathConfig()
		{
			@Override
			public Set<PohNexusPortal> pohNexusPortals()
			{
				return portals;
			}
		};
		Settings settings = Settings.wrap(config);

		assertSame("keyed read returns the stored set untouched",
			portals, settings.configuredValue("pohNexusPortals"));
		assertSame(portals, settings.configuredSet("pohNexusPortals"));
	}

	@Test
	public void writePassesSetValuesThroughUntouched()
	{
		ConfigManager configManager = mock(ConfigManager.class);
		Settings settings = service(configManager, new TestShortestPathConfig());
		Set<PohNexusPortal> portals = EnumSet.of(PohNexusPortal.VARROCK);

		settings.write("pohNexusPortals", portals);

		verify(configManager).setConfiguration(
			eq(GROUP), eq("pohNexusPortals"), same(portals));
	}

	/**
	 * The hidden built-* keys share a keyName between a read method and a
	 * void setter — the keyed read must resolve to the read method
	 * (parameterCount == 0, non-void return).
	 */
	@Test
	public void hiddenWritePairKeysResolveToReadMethod()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());

		assertEquals("", settings.configuredValue("builtTeleportationBoxes"));
		assertEquals("", settings.configuredValue("builtTeleportationPortalsPoh"));
	}

	@Test
	public void keyedReadOfUnknownKeyThrows()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());
		try
		{
			settings.configuredValue("notARegistryKey");
			fail("unknown keys must fail loudly");
		}
		catch (IllegalArgumentException expected)
		{
			assertTrue(expected.getMessage().contains("notARegistryKey"));
		}
	}

	@Test
	public void wrapSeamRejectsWrites()
	{
		Settings settings = Settings.wrap(new TestShortestPathConfig());
		try
		{
			settings.write("avoidWilderness", false);
			fail("a wrap-seam service has no config manager to write through");
		}
		catch (UnsupportedOperationException expected)
		{
		}
	}
}

package shortestpath.spirittree;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertThrows;
import java.util.HashSet;
import java.util.Set;
import org.junit.Test;

import shortestpath.settings.Effect;

/**
 * The spirit-tree change fact is the only hand-off between the service and
 * the plugin shell — pin its shape so a drifted value type breaks loudly
 * here rather than silently at the consumption site.
 */
public class TreeChangeTest
{
	@Test
	public void factCarriesKeyAndEffects()
	{
		TreeChange change = new TreeChange("varbit:Port Sarim", Set.of(Effect.ROUTE_INVALIDATING));

		assertEquals("varbit:Port Sarim", change.getKey());
		assertEquals(Set.of(Effect.ROUTE_INVALIDATING), change.getEffects());
	}

	@Test
	public void effectsAreImmutable()
	{
		Set<Effect> mutable = new HashSet<>();
		mutable.add(Effect.ROUTE_INVALIDATING);
		TreeChange change = new TreeChange("menu", mutable);

		mutable.add(Effect.ELIGIBILITY_STALE);
		assertEquals(Set.of(Effect.ROUTE_INVALIDATING), change.getEffects());
		assertThrows(UnsupportedOperationException.class,
			() -> change.getEffects().add(Effect.DISPLAY_ONLY));
	}

	@Test
	public void producersEmitRouteInvalidatingOnly()
	{
		// A changed tree set invalidates running paths but never item or
		// quest eligibility — the service must only ever declare
		// ROUTE_INVALIDATING. Drive every producer and assert the emitted
		// effect set carries it and nothing else.
		SpiritTreeService service = SpiritTreeService.forTesting();
		TreeChange profile = service.loadFromProfile();
		assertEquals(Set.of(Effect.ROUTE_INVALIDATING), profile.getEffects());

		TreeChange varbit = service.applyVarbitSample("Port Sarim", 20);
		assertEquals(Set.of(Effect.ROUTE_INVALIDATING), varbit.getEffects());

		TreeChange menu = service.applyMenuSnapshot(Set.of("Etceteria"), Set.of("Etceteria"));
		assertEquals(Set.of(Effect.ROUTE_INVALIDATING), menu.getEffects());
	}

	@Test
	public void unchangedObservationsEmitNullFacts()
	{
		SpiritTreeService service = SpiritTreeService.forTesting();
		service.applyVarbitSample("Port Sarim", 20);

		// An identical re-read is not a change — no fact is emitted.
		assertNull(service.applyVarbitSample("Port Sarim", 20));
		assertNull(service.applyMenuSnapshot(Set.of("Port Sarim"), Set.of("Port Sarim")));
	}
}

package shortestpath.transport;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.BitSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.junit.Assert;
import org.junit.BeforeClass;
import org.junit.Test;
import shortestpath.WorldPointUtil;
import shortestpath.pathfinder.CollisionMap;
import shortestpath.pathfinder.SplitFlagMap;

/**
 * The collision map leaves the open sea walkable (for Sailing), so a transport that starts or
 * lands on a sea tile joins the whole body of water to the map, and routes can then walk across
 * the ocean. Until Sailing is modelled, no transport may enter the open sea from outside it.
 */
public class SeaReachabilityTest
{
	/** One open-water tile in each walkable body of open sea on plane 0. */
	private static final int[][] SEA_SEEDS = {
		{2048, 2104}, // the sea around Karamja, Ape Atoll and the southern and western coasts
		{3072, 3968}, // the sea east of Morytania and north of the Wilderness
		{1024, 3040}, // the sea west of Kourend and Varlamore
		{1024, 2104}, // the south-western sea
	};

	private static CollisionMap map;
	private static Map<Integer, Set<Transport>> transports;

	@BeforeClass
	public static void load()
	{
		map = new CollisionMap(SplitFlagMap.fromResources());
		transports = TransportLoader.loadAllFromResources();
	}

	@Test
	public void testNoTransportEntersTheOpenSea()
	{
		List<String> leaks = new ArrayList<>();
		for (int[] seed : SEA_SEEDS)
		{
			BitSet sea = walkableComponent(seed[0], seed[1]);
			Assert.assertTrue("Sea seed " + seed[0] + "," + seed[1] + " should be open, walkable water",
				sea.cardinality() > 100_000);
			Assert.assertFalse("The sea at " + seed[0] + "," + seed[1] + " must not be walkable from Lumbridge",
				contains(sea, WorldPointUtil.packWorldPoint(3222, 3218, 0)));

			for (Map.Entry<Integer, Set<Transport>> entry : transports.entrySet())
			{
				for (Transport transport : entry.getValue())
				{
					if (contains(sea, transport.getDestination()) && !contains(sea, transport.getOrigin()))
					{
						leaks.add(describe(transport) + " lands in the sea at " + seed[0] + "," + seed[1]);
					}
				}
			}
		}
		Assert.assertTrue("Transports must not enter the open sea:\n" + String.join("\n", leaks), leaks.isEmpty());
	}

	private static BitSet walkableComponent(int seedX, int seedY)
	{
		BitSet seen = new BitSet(1 << 28);
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		seen.set(index(seedX, seedY));
		queue.add(index(seedX, seedY));
		while (!queue.isEmpty())
		{
			int tile = queue.poll();
			int x = tile >>> 14;
			int y = tile & 0x3fff;
			visit(seen, queue, map.n(x, y, 0), x, y + 1);
			visit(seen, queue, map.s(x, y, 0), x, y - 1);
			visit(seen, queue, map.e(x, y, 0), x + 1, y);
			visit(seen, queue, map.w(x, y, 0), x - 1, y);
		}
		return seen;
	}

	private static void visit(BitSet seen, ArrayDeque<Integer> queue, boolean open, int x, int y)
	{
		if (open && !seen.get(index(x, y)))
		{
			seen.set(index(x, y));
			queue.add(index(x, y));
		}
	}

	private static int index(int x, int y)
	{
		return x << 14 | y;
	}

	private static boolean contains(BitSet sea, int packedPoint)
	{
		if (packedPoint == Transport.UNDEFINED_ORIGIN || packedPoint == Transport.LOCATION_PERMUTATION
			|| WorldPointUtil.unpackWorldPlane(packedPoint) != 0)
		{
			return false;
		}
		int x = WorldPointUtil.unpackWorldX(packedPoint);
		int y = WorldPointUtil.unpackWorldY(packedPoint);
		return x >= 0 && x < 1 << 14 && y >= 0 && y < 1 << 14 && sea.get(index(x, y));
	}

	private static String describe(Transport transport)
	{
		return transport.getType() + " " + point(transport.getOrigin()) + " -> " + point(transport.getDestination())
			+ (transport.getDisplayInfo() != null ? " (" + transport.getDisplayInfo() + ")" : "");
	}

	private static String point(int packedPoint)
	{
		if (packedPoint == Transport.UNDEFINED_ORIGIN || packedPoint == Transport.LOCATION_PERMUTATION)
		{
			return "anywhere";
		}
		return WorldPointUtil.unpackWorldX(packedPoint) + "," + WorldPointUtil.unpackWorldY(packedPoint) + ","
			+ WorldPointUtil.unpackWorldPlane(packedPoint);
	}
}

