		long nowMinutes = 100000000L;
		values.put(5, 99999979); // stored timestamp 21 minutes ago

		VarRequirement v = VarRequirement.varbit(5, 20, VarCheckType.COOLDOWN_MINUTES);
		assertTrue(v.check(values, nowMinutes)); // 21 > 5

